	/**
	 * Save tour guide in the booking
	 *
	 * @param object $request
	 * @param int $id
	 * @return mixed
	 * 
	 * @version 1.0.0
	 */
	public function saveTourGuide(object $request, int $id)
	{
		try {
			if (empty($request->all())) {
				throw new Exception("Select tour guide to add in this booking.");
			}

			$guides = $request->guides;
			$assignedTourGuides = DB::table('booking_tour_guides')
				->where('booking_id', $id)
				->pluck('guide_id')
				->toArray();


			if (empty($request->guides)) {
				throw new Exception("Please select a tour guide to assign in this booking.");
			}
			DB::beginTransaction();
			$timeSlot =  DB::table('tour_bookings_master as tbm')
				->join('tour_packages AS tp', 'tp.id', '=', 'tbm.tour_package_id')
				->join('tour_slot_times as tst', 'tst.id', '=', 'tbm.tour_slot_id')
				->where('tbm.id', $id)
				->first(['tst.time_from', 'tst.date', 'tbm.tour_package_id', 'tp.include_in_operation_board']);
			$request->date = $timeSlot->date;
			$request->time_from = $timeSlot->time_from;

			if (!isset($guides[0]['is_deleted'])) {
				BoardService::validateGuideAssignment($request);
			}

			foreach ($guides as $guide) {
				$overBooked = $guide['over_booked'] ?? false;
				if (isset($guide['id']) && $guide['id'] > 0 && isset($guide['is_deleted']) && $guide['is_deleted'] == 1) {
					$tourGuide = BookingTourGuide::find($guide['id']);
					$guideAssignments = BookingTourGuide::where('station_id', $tourGuide->station_id)
						->where('guide_id', $tourGuide->guide_id)
						->where('time_from', $tourGuide->time_from)
						->where('date', $tourGuide->date)
						->get();

					$tourGuide = BookingTourGuide::where('id', $guide['id'])
						->first();

					$guide = Staff::findOrFail($tourGuide->guide_id);
					$guideName = "$guide->first_name $guide->last_name";

					// Remove or reset guide record
					if ($guideAssignments->count() > 1) {
						$tourGuide->delete();
					} else {
						$tourGuide->booking_id = null;
						$tourGuide->tourists = 0;
						$tourGuide->infants = 0;
						$tourGuide->save();
						if ($timeSlot->include_in_operation_board == 1) {
							BoardService::deleteBlockNextTimeSlot($tourGuide->date, $tourGuide->guide_id, $request->time_from, $tourGuide->station_id, $id);
						}
					}

					$note = "Tour guide $guideName has been successfully removed from the booking.";
					HistoryService::storeNoteInHistory($note, $id);
				} else {

					if (!in_array($guide['guide_id'], $assignedTourGuides)) {
						$checkGuide = BookingTourGuide::where('guide_id', $guide['guide_id'])->where('time_from', $request->time_from)->where('date', $request->date)
							->first();

						if ($checkGuide && $overBooked != 'true' && $checkGuide->booking_id == null) {

							$checkGuide->booking_id = $id;
							$checkGuide->tourists = $guide['tourists'];
							$checkGuide->infants = $guide['infants'];
							$checkGuide->save();
						} else {

							DB::table('booking_tour_guides')->Insert([
								'booking_id'    => $id,
								'guide_id'      => $guide['guide_id'],
								'station_id'    => $checkGuide->station_id ?? null,
								'tourists'      => $guide['tourists'],
								'infants'       => $guide['infants'],
								'time_from'     => $timeSlot->time_from,
								'date'          => $timeSlot->date,
								'created_at'    => mysqlDT(),
							]);
						}

						$tourBooking = TourBooking::find($id);
						if ($timeSlot->include_in_operation_board == 1) {
							BoardService::blockNextTimeSlot($tourBooking->tour_package_id, $timeSlot->date, $timeSlot->time_from, $guide['guide_id'], $checkGuide->station_id ?? null, $id);
						}

						$guide = Staff::findOrFail($guide['guide_id']);
						$guideName = "$guide->first_name $guide->last_name";

						$note = "Tour guide $guideName has been successfully assigned to the booking.";
						HistoryService::storeNoteInHistory($note, $id);
					} else {
						DB::table('booking_tour_guides')
							->where('booking_id', $id)
							->where('guide_id', $guide['guide_id'])->update([
								'tourists' => $guide['tourists'],
								'infants'  => $guide['infants'],
								'updated_at' => mysqlDT(),
							]);
					}
				}
			}

			// Update distribution amounts after saving tour guide
			TipService::updateDistributionAmounts($id);
			// Notify board: guide assigned/removed from booking info page
			BoardUpdated::dispatch(
				$timeSlot->date,
				$timeSlot->time_from,
				(string) tenancy()->tenant->id
			);
			DB::commit();

			return [
				'booking_id' => $id
			];
		} catch (Exception $exception) {
			Log::error($exception);
			DB::rollBack();
			throw new GeneralCoreException($exception);
		}
	}

	/**
	 * Send sms for booking
	 *
	 * @param int|string $bookingId
	 * @param mixed $info
	 *
	 * @return void
	 * 
	 * @version 1.0.0
	 */
	public function sendSMS($bookingId,  $info): void
	{
		// if $sms enabled send sms txt message
		if ($info->cust_phone && $info->is_affiliate == "No") {
			$props = (array)$info;
			$props['package_name'] = $info->packageName;

			$settings = Setting::where('key', 'BOOKING_ID_PREFIX')->first();
			$id = $settings->value . "" . $bookingId;

			$smsNotify = new SMSNotifications();
			$smsNotify->sendSMSLink($id, $props);
		}
	}

	/**
	 * Send email for booking
	 *
	 * @param object $request
	 * @param int $id
	 * @return mixed
	 * 
	 * @version 1.0.0
	 */
	public function sendEmail(object $request, int $bookingId)
	{
		try {
			$userType = userType();

			$qry = DB::table('tour_bookings_master AS tbm')
				->join('customers AS c', 'c.id', '=', 'tbm.customer_id')
				->join('tour_operators AS t_o', 't_o.id', '=', 'c.tour_operator_id')
				->join('tour_packages AS tp', 'tp.id', '=', 'tbm.tour_package_id')
				->join('cities AS ct', 'ct.id', '=', 't_o.city_id')
				->join('states AS st', 'st.id', '=', 'ct.state_id')
				->join('countries AS cn', 'cn.id', '=', 'st.country_id')
				->where('tbm.id', $bookingId)
				->select([
					't_o.name AS tour_operator',
					't_o.email AS t_o_email',
					't_o.phone_number AS t_o_phone',
					't_o.address AS t_o_address',
					't_o.postal_code AS t_o_postal_code',
					't_o.logo AS t_o_logo',
					't_o.tenant_id',
					'ct.name AS t_o_city',
					'st.name AS t_o_state',
					'cn.name AS t_o_country',
					'tbm.name AS customer',
					'tbm.name AS cust_name',
					'tbm.email AS cust_email',
					'tbm.phone_number AS cust_phone',
					'tbm.tour_package_id',
					'c.is_affiliate AS is_affiliate',
					'tp.name as packageName',
					'tp.email as packageEmail',
					'tp.from_name as packageFromName',
					'tp.from_email as packageFromEmail',
					'tp.api_key as packageApiKey',
				]);

			if ($userType == 'Tour Operator' || $userType == 'Affiliate')
				$qry = $qry->where('c.tour_operator_id', Auth::user()->tour_operator_id);

			$info = $qry->first();

			if (!$info) {
				throw new Exception("Unable to get the data of tour booking or customer.");
			}
			$tourOperatorLogo = '';
			if (!empty($info->t_o_logo)) {
				$tourOperatorLogo = tourOperatorLogo($info->tenant_id, $info->t_o_logo);
			}

			$arEmailData = [
				'bookingId' => $bookingId,
				'emailType' => config('constants.email_types.custom_email'),
				'emailContent' => $request->email_content,
				'tourOperator' => $info->tour_operator,
				'tourOpEmail' => $info->t_o_email,
				'tourOpPhone' => $info->t_o_phone,
				'tourOpAddress' => $info->t_o_address,
				'tourOpPostalCode' => $info->t_o_postal_code,
				'tourOpCity' => $info->t_o_city,
				'tourOpState' => $info->t_o_state,
				'tourOpCountry' => $info->t_o_country,
				'tourOpLogo' => $tourOperatorLogo,
				'tourPackageId' => $info->tour_package_id,
				'tourPackage' => $info->packageName,
				'packageEmail' => $info->packageEmail,
				'packageFromName' => $info->packageFromName,
				'packageFromEmail' => $info->packageFromEmail,
				'packageApiKey' => $info->packageApiKey,
				'operationBy' => Auth::id(),
				'operationByUserType' => $userType,
				'tenantId' => $info->tenant_id
			];

			if ($info->t_o_email) {
				$arEmailData['replyTo'] = [
					'name' => $info->tour_operator,
					'email' => $info->t_o_email,
				];
			}

			/** Send SMS message */
			// $this->sendSMS($bookingId, $info);

			sendEmail(
				$request->email_subject,
				[
					'name' => $info->customer,
					'email' => $info->cust_email,
				],
				'customer-booking-custom',
				$arEmailData
			);

			if (isset($request->api) && $request->api == 1) {
				return [];
			} else {
				return response()->json([]);
			}
		} catch (Exception $exception) {
			Log::error($exception);
			throw new GeneralCoreException($exception);
		}
	}

	/**
	 * Initialize the Calendar
	 *
	 * @param object $request
	 * @return array
	 * 
	 * @version 1.0.0
	 */
	public function calendar(object $request): array
	{
		try {
			$vars = [
				'page_title'      => 'Tour Bookings Calendar',
				'pageId'          => 'calendar',
				'tourOperatorId'  => 0,
				'currentDate'     => date('Y-m-d H:i:s'),
			];

			$userType = userType();

			if ($userType == 'Admin') {
				$vars['tourOperators'] = $this->tourOperator::where('status', 'Active')
					->orderBy('id')
					->get(['id', 'name']);

				$vars['tourOperatorId'] = Cookie::get('tourOpId', $vars['tourOperators']->first()->id);
			} else {
				$vars['tourOperatorId'] = $request->tourOperatorId ?? Auth::user()->tour_operator_id;
			}

			$yearMonth = $request->year . $request->month;

			if (isset($request->api) && $request->api == 1) {
				$date = substr($yearMonth, 0, 4) . '-' . str_pad(substr($yearMonth, 4, 2), 2, '0', STR_PAD_LEFT) . '-01';
			} else {
				$date = session('calendar_date') ?? date('Y-m-01');
			}

			$option    = session('calendar_option', 'month');
			$week      = session('calendar_week');
			$packageId = session()->get('package_id');

			if ($request->is('api/*')) {
				$option    = $request->get('option', 'month');
				$week      = $request->get('week');
				$packageId = $request->get('package_id');
			}

			$arYM = explode('-', $date);

			// Calendar week filter integration
			$currentMonth = Carbon::now()->month;
			$requestMonth = null !== session('calendar_month') ? (int)session('calendar_month') : (int)$arYM[1];
			$requestYear = session('calendar_year') ?? $arYM[0];
			$nowDate = Carbon::now();

			if ($week) {
				$weekNumber = (int)$week;
			} else {
				if ($requestMonth == $currentMonth) {
					$weekNumber = CalendarWeekFilterUtils::getWeeks($nowDate, "sunday", 1);
				} else {
					$weekNumber = CalendarWeekFilterUtils::getWeeks(Carbon::parse($date), "sunday", 0);
				}
			}

			$tourOpId = $vars['tourOperatorId'];

			$affiliateJoinQueries = CalendarQueryService::generateQueries($userType);

			$showAllPackageBookings = $affiliateJoinQueries['showAllPackageBookings'];

			$packageRelationSetting = hasSetting('PACKAGE_RELATION');

			// The calendar's package filter also scopes the SQL fetch of date-slots below.
			// When the filtered package belongs to a PACKAGE_RELATION family, the child/parent
			// availability math further down looks for a sibling row (is_parent == 1) inside
			// $dateSlots to know the group's shared capacity. If the fetch is left scoped to
			// only the filtered package, that sibling row never exists and availability always
			// computes as 0. Widen the fetch to the full family group here, then filter the
			// displayed rows back down to $requestedPackageId once $calData is built below.
			$requestedPackageId = $packageId;
			$hasPackageFilter = !empty($packageId) && !in_array(0, $packageId);

			if ($packageRelationSetting && $hasPackageFilter) {
				$filterIdsStr = implode(',', array_map('intval', $packageId));
				$familyPackageIds = DB::select("SELECT DISTINCT tour_package_id
                                        FROM tour_package_families
                                        WHERE relation_year = $requestYear
                                        AND parent_package_id IN (
                                                SELECT parent_package_id
                                                FROM tour_package_families
                                                WHERE tour_package_id IN ($filterIdsStr)
                                                        AND relation_year = $requestYear
                                        )");

				if (!empty($familyPackageIds)) {
					$packageId = array_values(array_unique(array_merge(
						$packageId,
						array_column($familyPackageIds, 'tour_package_id')
					)));
				}
			}

			$dateSlotsResult = CalendarQueryService::fetchDateSlots($userType, $option, $date, $tourOpId, $requestMonth, $requestYear, $weekNumber, $packageId);
			$dateSlots = $dateSlotsResult['data'];
			$vars['weekDates'] = $dateSlotsResult['weekDates'];

			$tourPackageFamilies = [];
			if ($packageRelationSetting && count($dateSlots)) {
				$packageIds = implode(',', array_unique(array_column((array) $dateSlots, 'tour_package_id')));

				$tourPackageFamilies = DB::select("SELECT *
                                        FROM tour_package_families
                                        WHERE relation_year = $requestYear
                                        AND parent_package_id IN (
                                                SELECT parent_package_id
                                                FROM tour_package_families
                                                WHERE tour_package_id IN (" . $packageIds . ")
                                                        AND relation_year = $requestYear
                                        )");
			}

			// A family member can still be entirely absent from $dateSlots even after the
			// widening above -- when $userType is Affiliate, fetchDateSlots() also applies
			// an INNER JOIN to package_affiliate_assignments, which excludes any package the
			// viewing affiliate isn't assigned to regardless of $packageId. If an affiliate is
			// assigned to a child package but not its parent (or another sibling), that
			// package's row never reaches $dateSlots. Fetch such missing members directly,
			// bypassing both the package filter and the affiliate-assignment join, so the
			// shared-capacity math below has real numbers instead of treating them as zero.
			$missingFamilyDataLookup = [];
			if ($packageRelationSetting && count($tourPackageFamilies)) {
				$fetchedPackageIds = array_unique(array_column((array) $dateSlots, 'tour_package_id'));
				$allFamilyPackageIds = array_unique(array_column($tourPackageFamilies, 'tour_package_id'));
				$missingPackageIds = array_values(array_diff($allFamilyPackageIds, $fetchedPackageIds));

				if (!empty($missingPackageIds)) {
					$missingPackageIdsStr = implode(',', array_map('intval', $missingPackageIds));
					$missingFamilyResults = DB::select("SELECT
                            tsd.tour_package_id,
                            tsd.date,
                            tst.time_from,
                            IFNULL(tst.time_slot_seats, 0) as seats,
                            COUNT(DISTINCT tst.id) AS available_slots,
                            IFNULL(SUM(tbm.tourists), 0) AS bookings
                        FROM tour_slot_dates AS tsd
                        INNER JOIN tour_slot_times AS tst ON tst.tour_slot_id = tsd.id
                        LEFT JOIN tour_bookings_master AS tbm ON tbm.tour_slot_id = tst.id
                            AND tbm.tour_package_id = tsd.tour_package_id
                            AND tbm.status != 'Cancelled'
                        WHERE " . $dateSlotsResult['dateRangeQuery'] . "
                            AND tsd.tour_package_id IN ($missingPackageIdsStr)
                            AND tsd.status = 'Active'
                            AND tsd.deleted_by = 0
                            AND tst.deleted_by = 0
                        GROUP BY tsd.tour_package_id, tsd.date, tst.time_from");

					foreach ($missingFamilyResults as $result) {
						$lookupKey = $result->date . '|' . $result->time_from . '|' . $result->tour_package_id;
						$missingFamilyDataLookup[$lookupKey] = [
							'seats' => $result->seats * $result->available_slots,
							'bookings' => (int) $result->bookings,
						];
					}
				}
			}

			// OPTIMIZATION: Batch affiliate queries before the loop to avoid N+1 queries
			$affiliateTouristsLookup = [];
			$affiliateSeatsLookup = [];
			$packageAssignmentsLookup = [];

			if ($userType == 'Affiliate') {
				$affiliateId = Auth::id();

				// Get all slot IDs and package IDs for batch queries
				$slotIds = array_column($dateSlots, 'time_slot_id');
				$packageIds = array_unique(array_column($dateSlots, 'tour_package_id'));

				// Batch query for package affiliate assignments
				if (!empty($packageIds)) {
					$packageAssignments = PackageAffiliateAssignment::where('affiliate_id', $affiliateId)
						->whereIn('package_id', $packageIds)
						->get(['package_id', 'show_all_package_bookings']);

					foreach ($packageAssignments as $assignment) {
						$packageAssignmentsLookup[$assignment->package_id] = $assignment;
					}
				}

				if (!empty($slotIds)) {
					// Batch query for affiliate tourists
					$slotIdsStr = implode(',', $slotIds);
					$packageIdsStr = implode(',', $packageIds);

					$affiliateTouristsData = DB::select("
						SELECT tbm.tour_slot_id, tbm.tour_package_id, IFNULL(SUM(tbm.tourists), 0) as afl_tourists
						FROM tour_bookings_master AS tbm
						JOIN customers AS c ON c.id = tbm.customer_id
						WHERE tbm.tour_slot_id IN ($slotIdsStr)
							AND c.is_affiliate = 'Yes'
							AND tbm.status != 'Cancelled'
							AND tbm.tour_package_id IN ($packageIdsStr)
							AND tbm.customer_id = $affiliateId
						GROUP BY tbm.tour_slot_id, tbm.tour_package_id
					");

					foreach ($affiliateTouristsData as $data) {
						$affiliateTouristsLookup[$data->tour_slot_id][$data->tour_package_id] = $data->afl_tourists;
					}

					// Batch query for affiliate seats - FIXED: Match package IDs correctly
					$affiliateSeatsData = DB::select("
						SELECT tst.id as tour_slot_id, tst.tour_package_id, tsta.tour_package_id as affiliate_package_id, IFNULL(ast.seat_limit, 0) as afl_seats
						FROM tour_slot_times tst
						JOIN tour_slot_times_affiliate tsta ON tsta.time_from = tst.time_from 
							AND tsta.time_to = tst.time_to 
							AND tsta.tour_package_id = tst.tour_package_id
						JOIN affiliate_slot_times ast ON ast.tour_slot_time_id = tsta.id
						WHERE tst.id IN ($slotIdsStr)
							AND ast.affiliate_id = $affiliateId
							AND ast.deleted_by = 0 
							AND tsta.deleted_by = 0
					");

					foreach ($affiliateSeatsData as $data) {
						$affiliateSeatsLookup[$data->tour_slot_id] = $data->afl_seats;
					}
				}
			}

			$calData = [];
			foreach ($dateSlots as $key => $dateSlot) {
				$relationPackage = [];
				$targetParent = [];
				$totalTourists = 0;
				/* START - mapping tour package and reducing the relational seats */
				if ($packageRelationSetting && count($tourPackageFamilies)) {
					$relationPackage = array_filter($tourPackageFamilies, function ($obj) use ($dateSlot) {
						return $obj->tour_package_id == $dateSlot->tour_package_id && $obj->group_index == $dateSlot->group_index;
					});

					$targetParent = array_filter($tourPackageFamilies, function ($obj) use ($dateSlot) {
						return $obj->is_parent == 1 && $obj->tour_package_id == $dateSlot->tour_package_id && $obj->group_index == $dateSlot->group_index;
					});

					// Calculate total tourists from actual bookings (optimized)
					$totalTourists = 0;
					if (!empty($relationPackage)) {
						$groupKey = $dateSlot->group_index;

						// Get the parent_package_id for this slot's family so we only sum
						// packages within the same parent group. Without this scope, two
						// independent family groups that happen to share the same group_index
						// ordinal (e.g. parent-1 group_index=1 and parent-2 group_index=1)
						// would cross-contaminate each other's tourist totals.
						$firstRelation = reset($relationPackage);
						$parentId = $firstRelation->parent_package_id;

						$groupPackageIds = array_column(
							array_filter($tourPackageFamilies, fn($f) => $f->group_index == $groupKey && $f->parent_package_id == $parentId),
							'tour_package_id'
						);

						$totalTourists = array_sum(
							array_column(
								array_filter(
									$dateSlots,
									fn($s) =>
									$s->date == $dateSlot->date &&
										$s->time_from == $dateSlot->time_from &&
										$s->group_index == $groupKey &&
										in_array($s->tour_package_id, $groupPackageIds)
								),
								'tourists'
							)
						);
					}

					// Fallback to original service method if no bookings found
					if ($totalTourists === 0) {
						$totalTourists = TouristService::getTotalTouristsForSlots($tourPackageFamilies, $dateSlots, $dateSlot);
					}
				}
				/* END */

				// For affiliates, check per-package whether to use affiliate-specific logic
				$useAffiliateLogicForPackage = false;
				if ($userType == 'Affiliate') {
					// Use pre-loaded package assignment data (OPTIMIZED - no more N+1 queries)
					$packageAssignment = $packageAssignmentsLookup[$dateSlot->tour_package_id] ?? null;
					$useAffiliateLogicForPackage = $packageAssignment && $packageAssignment->show_all_package_bookings == Constants::STATUS_ZERO;
				}

				if ($userType == 'Affiliate' && $useAffiliateLogicForPackage) {
					// Use pre-loaded data from batch queries (OPTIMIZED - no more N+1 queries)
					$affiliateTourists = $affiliateTouristsLookup[$dateSlot->time_slot_id][$dateSlot->tour_package_id] ?? 0;
					$affiliateSeats = $affiliateSeatsLookup[$dateSlot->time_slot_id] ?? 0;

					// FIXED: Manually calculate totalTourists for affiliates including all related packages
					if ($packageRelationSetting && count($tourPackageFamilies)) {
						// Find all related packages for this slot
						$relatedPackageIds = [];
						foreach ($tourPackageFamilies as $family) {
							if ($family->group_index == $dateSlot->group_index) {
								$relatedPackageIds[] = $family->tour_package_id;
							}
						}

						// Calculate total bookings from all related packages for this time slot
						$manualTotalTourists = 0;
						foreach ($dateSlots as $relatedSlot) {
							if (
								$relatedSlot->date == $dateSlot->date &&
								$relatedSlot->time_from == $dateSlot->time_from &&
								in_array($relatedSlot->tour_package_id, $relatedPackageIds)
							) {
								$manualTotalTourists += (int)$relatedSlot->tourists;
							}
						}

						$totalTourists = $manualTotalTourists > 0 ? $manualTotalTourists : $totalTourists;
					}

					// For affiliate calendar: calculate proper availability accounting for parent-child relationships
					if ($affiliateSeats > 0) {
						// For affiliates: Check if there are child package bookings
						// If child packages have bookings, we need to account for them to prevent overbooking
						$childBookings = 0;
						if ($packageRelationSetting && count($tourPackageFamilies) && !empty($relationPackage)) {
							// Calculate child bookings for this specific time slot
							$presentGroupPackageIds = [];
							foreach ($dateSlots as $relatedSlot) {
								if (
									$relatedSlot->date == $dateSlot->date &&
									$relatedSlot->time_from == $dateSlot->time_from &&
									$relatedSlot->group_index == $dateSlot->group_index &&
									$relatedSlot->tour_package_id != $dateSlot->tour_package_id
								) {
									$childBookings += (int)$relatedSlot->tourists;
									$presentGroupPackageIds[] = $relatedSlot->tour_package_id;
								}
							}

							// Siblings/parent the affiliate isn't assigned to never reach
							// $dateSlots -- pull their real bookings from the direct lookup
							// so they still count against the shared capacity.
							$groupMemberIds = array_column(
								array_filter($tourPackageFamilies, fn($f) => $f->group_index == $dateSlot->group_index),
								'tour_package_id'
							);
							$missingGroupPackageIds = array_diff(
								$groupMemberIds,
								array_merge([$dateSlot->tour_package_id], $presentGroupPackageIds)
							);
							foreach ($missingGroupPackageIds as $missingId) {
								$lookupKey = $dateSlot->date . '|' . $dateSlot->time_from . '|' . $missingId;
								$childBookings += $missingFamilyDataLookup[$lookupKey]['bookings'] ?? 0;
							}
						}

						// Use parent capacity, but include child bookings to prevent showing availability when overbooked
						$globalBookings = (int)$dateSlot->tourists + $childBookings;
						$globalRemaining = max(0, $dateSlot->seats - $globalBookings);
						$affiliateRemaining = max(0, $affiliateSeats - $affiliateTourists);
						$actualAvailableSeats = min($globalRemaining, $affiliateRemaining);

						$tourists = (int) $affiliateTourists;
						// Overbooking only if affiliate exceeded their own assigned seat limit
						$overBooking = max(0, $affiliateTourists - $affiliateSeats);
						$availableSeats = $actualAvailableSeats;
						$bookedSeats = $affiliateTourists; // Use affiliate tourists for consistency
						$seats = $affiliateSeats; // Use affiliate seat allocation
					} else {
						// No affiliate seat allocation - cannot book
						$tourists = 0;
						$overBooking = 0;
						$availableSeats = 0;
						$bookedSeats = 0;
						$seats = 0;
					}
				} else {
					// Apply parent-child logic: parent shows total, child shows only child bookings
					if (!empty($relationPackage)) {
						$isParentPackage = count($targetParent) > 0;

						if ($isParentPackage) {
							// Parent package: show total tourists (parent + child)
							$tourists = ($totalTourists > 0) ? (int) $totalTourists : (int) $dateSlot->tourists;
							$bookedSeats = $tourists;
							$seats = $dateSlot->seats * $dateSlot->available_slots;
							$overBooking = max(0, $tourists - $seats);
							$availableSeats = max(0, $seats - $tourists);
						} else {
							// Child package: show only child bookings but availability constrained by parent
							$tourists = (int) $dateSlot->tourists;
							$bookedSeats = $tourists;
							$childSeats = $dateSlot->seats * $dateSlot->available_slots;

							// For child packages, available seats should be constrained by parent's remaining capacity
							// Find parent package seats and calculate remaining capacity
							$parentTotalSeats = 0;
							foreach ($dateSlots as $relatedSlot) {
								if (
									$relatedSlot->date == $dateSlot->date &&
									$relatedSlot->time_from == $dateSlot->time_from &&
									$relatedSlot->group_index == $dateSlot->group_index &&
									$relatedSlot->is_parent == 1
								) {
									$parentTotalSeats += $relatedSlot->seats * $relatedSlot->available_slots;
								}
							}

							// Child availability is constrained by both child capacity and parent's remaining capacity
							$childOwnAvailability = max(0, $childSeats - $tourists);
							$parentRemainingCapacity = max(0, $parentTotalSeats - ($totalTourists > 0 ? $totalTourists : 0));
							$availableSeats = min($childOwnAvailability, $parentRemainingCapacity);
							$seats = $childSeats;

							// Child overbooking is based on child's own capacity
							$overBooking = max(0, $tourists - $childSeats);
						}
					} else {
						// Non-related packages: use original logic
						$tourists = (int) $dateSlot->tourists;
						$bookedSeats = $tourists;
						$seats = $dateSlot->seats * $dateSlot->available_slots;
						$overBooking = max(0, $tourists - $seats);
						$availableSeats = max(0, $seats - $tourists);
					}
				}

				// Group by date and package, with special handling for affiliate parent-child relationships
				$calKey = $dateSlot->date . '_' . $dateSlot->tour_package_id;

				// For affiliates: aggregate child bookings to parent ONLY if affiliate is NOT assigned to child package directly
				if ($userType == 'Affiliate' && $useAffiliateLogicForPackage && !empty($relationPackage) && count($targetParent) == 0) {
					// Check if affiliate is assigned to this child package directly
					$childPackageAssignment = $packageAssignmentsLookup[$dateSlot->tour_package_id] ?? null;

					// Only aggregate to parent if affiliate is NOT assigned to child package
					if (!$childPackageAssignment) {
						// Find parent package ID for this child package
						foreach ($dateSlots as $relatedSlot) {
							if (
								$relatedSlot->date == $dateSlot->date &&
								$relatedSlot->time_from == $dateSlot->time_from &&
								$relatedSlot->group_index == $dateSlot->group_index &&
								$relatedSlot->is_parent == 1
							) {
								$calKey = $dateSlot->date . '_' . $relatedSlot->tour_package_id;
								break;
							}
						}
					}
					// If affiliate IS assigned to child package, keep original calKey (show child package separately)
				}

				if (!isset($calData[$calKey])) {
					$calData[$calKey] = [
						'id' => $dateSlot->id,
						'date' => $dateSlot->date,
						'pkg_id' => $dateSlot->tour_package_id,
						'pkg_name' => $dateSlot->pkg_name,
						'tourists' => 0,
						'seats' => 0,
						'over_booking' => 0,
						'available_seats' => 0,
						'booked_seats' => 0,
					];
				}

				$calData[$calKey]['tourists'] += $tourists;
				$calData[$calKey]['seats'] += $seats;
				$calData[$calKey]['available_seats'] += $availableSeats;

				// For affiliate calendar: handle overbooking and booked_seats differently
				if ($userType == 'Affiliate' && $useAffiliateLogicForPackage) {
					$calData[$calKey]['booked_seats'] = $calData[$calKey]['tourists']; // Use affiliate tourists total
					// Overbooking: sum individual slot overbookings (same as calendarAHR)
					$calData[$calKey]['over_booking'] += $overBooking;
				} else {
					$calData[$calKey]['over_booking'] += $overBooking;
					$calData[$calKey]['booked_seats'] += $bookedSeats;
				}
			}

			// Add available_tourists field for frontend compatibility after all calculations
			foreach ($calData as &$calItem) {
				$calItem['available_tourists'] = $calItem['available_seats'];
			}

			$vars['tourSlots'] = array_values($calData);

			// Drop the sibling/parent rows that were only fetched above for capacity math —
			// the admin filtered the calendar to $requestedPackageId and shouldn't see extras.
			if ($hasPackageFilter) {
				$requestedPackageIdInts = array_map('intval', $requestedPackageId);
				$vars['tourSlots'] = array_values(array_filter(
					$vars['tourSlots'],
					fn($slot) => in_array((int) $slot['pkg_id'], $requestedPackageIdInts)
				));
			}

			$vars['year'] = session('calendar_year') ?? $arYM[0];
			$vars['month'] = session('calendar_month') ?? $arYM[1];
			$vars['week'] = session('calendar_week') ?? $weekNumber;

			// Get selected filter option
			$vars['option'] = session('calendar_option') ?? 'month';
			if ($request->is('api/*')) {
				$vars['option'] = $request->option ?? 'month';
			}
			$vars['date'] = $date;

			$vars['affiliates'] = BookingUtils::getActiveAffiliates($vars['tourOperatorId'], $userType);

			$bookings = CalendarQueryService::fetchBookings($userType, $showAllPackageBookings);

			$bookingPrefix = bookingPrefixSetting();

			// OPTIMIZATION: Batch load payment links and history to eliminate N+1 queries
			$groupIds = collect($bookings)->pluck('group_id')->unique()->filter()->toArray();
			$bookingIds = collect($bookings)->pluck('id')->toArray();

			// Batch load payment links
			$paymentLinks = [];
			if (!empty($groupIds)) {
				$paymentLinksData = TourBookingPaymentLink::whereIn('order_id', $groupIds)
					->where('status', 'Unpaid')
					->get(['order_id'])
					->keyBy('order_id');
				$paymentLinks = $paymentLinksData->toArray();
			}

			// Batch load booking history
			$bookingHistories = [];
			if (!empty($bookingIds)) {
				$historiesData = TourBookingHistory::whereIn('tour_booking_id', $bookingIds)
					->get(['id', 'tour_booking_id', 'details', 'operation'])
					->groupBy('tour_booking_id');

				// Keep as objects since the code expects $historyData->details
				foreach ($historiesData as $bookingId => $histories) {
					$bookingHistories[$bookingId] = $histories->all(); // Keep as objects
				}
			}

			foreach ($bookings as $key => $bookingData) {
				// Use pre-loaded payment link data
				if (isset($paymentLinks[$bookingData->group_id])) {
					$bookings[$key]->payment_method = 'Payment Link';
				}

				$bookings[$key]->is_tripadvisor_booking = $bookingData->tripadvisor_id ? 1 : 0;
				$bookings[$key]->is_get_your_guide_booking = $bookingData->get_your_guide_booking_id ? 1 : 0;
				$bookings[$key]->is_ota_booking = $bookingData->ota_booking_id ? 1 : 0;
				$bookings[$key]->invoiceStatus = $bookingData->invoice_status ?? 0;
				$bookings[$key]->prefixedId = ($bookingPrefix != '') ? $bookingPrefix . $bookingData->id : $bookingData->id;

				if (!empty($bookingData->timezone)) {
					$bookings[$key]->booking_d_t = Carbon::createFromFormat('Y-m-d H:i:s', $bookingData->booking_d_t, config('app.timezone'))
						->setTimezone($bookingData->timezone)
						->format('Y-m-d H:i:s');
				}

				// Use pre-loaded history data
				$history = $bookingHistories[$bookingData->id] ?? [];
				if ($bookingData->is_group_booking == '1') {
					$tGroupsChanged = ["P:" . $bookingData->tourists];
				} else {
					$tGroupsChanged = CalendarService::touristGroups($bookingData->t_groups);
				}
				$bookings[$key]->t_groups = isset($tGroupsChanged) ? implode(" |", $tGroupsChanged) : '';
				$bookings[$key]->BookingTotal = $bookingData->total;
				$bookings[$key]->RefundAmount = 0;

				foreach ($history as $his => $historyData) {
					$details = json_decode($historyData->details);

					if ($historyData->operation == 'Update') {
						$bookings[$key]->BookingTotal = $bookingData->total;
					}

					if ($historyData->operation == 'Payment') {
						$bookings[$key]->BookingTotal = round((float) $details->amount, 2);
					}

					if ($historyData->operation == 'Refund' && $bookingData->id == $historyData->tour_booking_id) {
						$bookings[$key]->RefundAmount += (float) $details->amount;
					}

					if ($historyData->operation == 'Cancelled' && isset($details->refund_type) && $details->refund_type != "Don't Refund") {
						$bookings[$key]->RefundAmount += $details->amount;
					}
				}

				$bookings[$key]->RefundAmount = round($bookings[$key]->RefundAmount, 2);
				$bookings[$key]->totalF = round($bookings[$key]->total);
				$bookings[$key]->PaymentTotal = max(0, $bookings[$key]->BookingTotal - $bookings[$key]->RefundAmount);

				$bookings[$key]->background_colour_class = BookingService::backgroundColourClass($bookings[$key]);
				$otaTitle = BokunUtils::getOTAChannelNameByBookingId($bookings[$key]->id);
				$bookings[$key]->ota_title = strtolower($otaTitle);
				$bookings[$key]->ota_logo  = BokunUtils::getOTALogoByTitle($otaTitle);
			}

			$vars['tourBookings'] = $bookings;

			$vars['tourPackages'] = CalendarService::getActivePackages($userType);

			if ($request->is('api/*')) {
				$settings =  DB::table('settings')
					->select(['key', 'value'])->get();

				if (!empty($settings)) {
					foreach ($settings as $setting) {
						if ($setting->key == 'API_VERSION') {
							$vars['apiVersion'] = (string) $setting->value;
						}

						if ($setting->key == 'IS_NO_HIDE') {
							$vars['isNoHide'] = ($setting->value == '1') ? true : false;
						}
					}
				}
			}

			$vars['partnerships'] = CalendarService::getPartnersData($userType);
			$vars['showAllPackageBookings'] = $showAllPackageBookings;
			$vars['otaPlatforms'] = BokunUtils::getAllOtaTitles();

			if (count($vars['tourBookings']) != 0 || count($vars['affiliates']) != 0 || count($vars) != 0) {
				return $vars;
			}

			throw new Exception("Calendar details not available.");
		} catch (Exception $exception) {
			Log::error($exception);
			throw new GeneralCoreException($exception);
		}
	}

	public function getTimeSlotsByDate($date, $pkg_id)
	{
		try {
			$overbooked_seats = 0;
			$overbooked_seats_arr = array();
			$timeSlots = DB::select("SELECT `tst`.`id`, `tst`.`time_from`, `tst`.`time_to`, `tst`.`time_slot_seats` AS `seats`, `tst`.`bookable_status`, 
                                IFNULL((SELECT SUM(`tbm`.`tourists`)
                                        FROM `tour_bookings_master` AS `tbm`
                                        WHERE `tbm`.`tour_slot_id` = `tst`.`id`
                                                AND `tbm`.`status` != 'Cancelled'
                                                AND `tbm`.`tour_package_id` = " . $pkg_id . "
                                        GROUP BY `tbm`.`tour_slot_id`, `tbm`.`tour_package_id`), 0) AS tourists,
                                IFNULL((SELECT SUM(`tbm`.`tourists`)
                                        FROM `tour_bookings_master` AS `tbm`
                                        JOIN `customers` AS `c` ON `c`.`id` = `tbm`.`customer_id`
                                        WHERE `tbm`.`tour_slot_id` = `tst`.`id`
                                                AND `c`.`is_affiliate` = 'Yes'
                                                AND tbm.`status` != 'Cancelled'
                                                AND `tbm`.`tour_package_id` = " . $pkg_id . "
                                        GROUP BY `tbm`.`tour_slot_id`, `tbm`.`tour_package_id`), 0) AS afl_tourists
                                FROM `tour_slot_dates` as `tsd`
                                JOIN `tour_slot_times` as `tst` on `tst`.`tour_slot_id` = `tsd`.`id` 
                                        WHERE `tsd`.`date` = '" . $date . "'
                                                AND `tsd`.`status` = 'Active' 
                                                AND `tst`.`deleted_by` = 0 
                                                AND `tsd`.`tour_package_id` = " . $pkg_id . "");

			foreach ($timeSlots as $key => $timeSlot) {
				if ((int)$timeSlot->tourists > $timeSlot->seats) {
					$overbooked_seats_arr[$key]['date'] = $date;
					$overbooked_seats += ((int)$timeSlot->tourists - $timeSlot->seats);
					$overbooked_seats_arr[$key]['over_booking'] = $overbooked_seats;
				}
			}

			$overbooked_seats_arr = array_values($overbooked_seats_arr);

			return $overbooked_seats_arr;
		} catch (Exception $exception) {
			Log::error($exception);
			throw new GeneralCoreException($exception);
		}
	}

	/**
	 * Edit booking (Delete and Edit)
	 *
	 * @param object $request
	 * @return mixed
	 * 
	 * @version 1.0.0
	 */
	public function editBooking(object $request)
	{
		try {
			$oldBookingId = oldBookingId();
			$isCashFees = cashFees();

			$check = $request->input('check', []);

			$modalUrl = '';
			if (!$request->is('api/*')) {
				if ($request->has('parent_url') && $request->parent_url != '') {
					if (Str::contains($request->parent_url, 'calendar') || Str::contains($request->parent_url, 'modal=1')) {
						$modalUrl = '?modal=1';
					}
				} else {
					$modalUrl = '?modal=1';
				}
			}
			$transP = $this->transaction::where('tour_booking_id', $request->bookingID)
				->where('status', 'Completed')
				->whereNull('charge_type')
				->orderBy('id', 'ASC')
				->first();

			$tourBooking = $this->tourBooking::find($request->bookingID);
			$packageHasContacts = $this->tourPackage::find($tourBooking->tour_package_id);
			$isPartnerBooking = $tourBooking->is_partner_booking;
			$paymentTransCountForBooking = $this->transaction::where('tour_booking_id', $request->bookingID)->where('status', 'Completed')->whereNull('charge_type')->count();
			$isImportedBooking = false;
			if (!empty($transP) && $transP->via == 'Card' && $transP->transaction_number === "" && $request->action_type == "update" && $paymentTransCountForBooking == 1) {
				$isImportedBooking = true;
			}

			if ($request->payment_type == "Card" && $request->is_cash == "" && $request->action_type == "delete") {
				if ($isImportedBooking == true) {
					if (isset($request->api) && $request->api == 1) {
						throw new Exception('This booking is imported. Kindly use here Cash or Check/Wire option');
					} else {
						$message = 'This booking is imported. Kindly use here Cash or Check/Wire option.';
						return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
					}
				}
			}

			if (count($check) == 0) {
				if (isset($request->api) && $request->api == 1) {
					throw new Exception('Your are not selected any check box in action option.');
				} else {
					$message = 'Your are not selected any check box in action option.';
					return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
				}
			}

			$createdByWithName = BookingService::createdUserInfo();

			$tourBookingTransaction = $this->bookingTransact::where('tour_booking_id', $request->bookingID)->where('deleted_by', 0)->first();

			$array = array_count_values($check);

			$checkPermitfee = $request->input('permitF', []);
			if ($request->action_type == "update") {
				$paymentTransCountForBooking = $this->transaction::where('tour_booking_id', $request->bookingID)->where('status', 'Completed')->whereNull('charge_type')->count();
				//calculate refund value
				$refundOnly = $this->tourBookingHistory::where('tour_booking_id', $request->bookingID)
					->where('operation', 'Refund')
					->where('payment_method', '!=', "Don't Refund")
					->get([
						'id',
						'details'
					]);
				$refundOnlyCheck = 0;
				foreach ($refundOnly as $value) {
					$details = json_decode($value->details, true);
					$refundOnlyCheck += $details['amount'];
				}
				if ($refundOnlyCheck == (float)$tourBooking->booking_total) {
					$message = 'Unable to update permit fee as transaction already refunded.';
					if (isset($request->api) && $request->api == 1) {
						throw new Exception($message);
					} else {
						return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
					}
				}
				if ($request->payment_type == 'Card' && $paymentTransCountForBooking > 1 && $request->checked_transactions == '') {
					if (isset($request->api) && $request->api == 1) {
						throw new Exception("You must need to select payment transaction to update.");
					} else {
						$message = 'You must need to select payment transaction to update permit fees.';
						return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
					}
				}

				$refundpermitarray = array();
				$oldpermitfeesarray = array();
				$newprocessingfees = array();
				$tourbooking = $this->tourBooking::where('id', $request->bookingID)->first();
				$totalTouristtriedtoincreasepermitfeesarray = array();
				$totalTouristswithoutpermitfeesarray = array();
				$unpaidPermitFeeDelta        = 0;   // net permit-fee change for unpaid pax (no Stripe refund needed)
				$unpaidTransactDeltaByRate   = [];  // per-rate-group delta, used to update transact total
				$unpaidPaxCountByRateFor     = [];  // rate_for => count of changed unpaid pax, used for history "deleted" field

				// Fallback: build transact_id → unpaid pax count from payment link items so we can
				// detect unpaid pax even when is_pax_added was never stamped into refund_permitfee_status
				// (covers bookings created before the saveNonCardPermitFeeJson fix was applied).
				$unpaidPaxCountByTransact = [];
				$remainingLinkForFallback = TourBookingPaymentLink::where('order_id', $tourbooking->group_id)
					->where('status', 'Unpaid')
					->where('section', 'remaining_payment')
					->first();
				if ($remainingLinkForFallback) {
					$fallbackLinkItems = TourBookingPaymentLinkItem::where('payment_link_id', $remainingLinkForFallback->id)
						->where('type', 'change_people')
						->where('status', 'Unpaid')
						->where(function ($q) use ($request) {
							$q->whereRaw("JSON_UNQUOTE(JSON_EXTRACT(details, '$.tour_booking_id')) = ?", [(string)$request->bookingID])
							  ->orWhereRaw("JSON_EXTRACT(details, '$.tour_booking_id') IS NULL");
						})
						->get();
					foreach ($fallbackLinkItems as $fallbackItem) {
						$fDetails = is_array($fallbackItem->details)
							? $fallbackItem->details
							: (json_decode($fallbackItem->details ?? '[]', true) ?? []);
						if (!empty($fDetails['added_transact_data'])) {
							foreach ($fDetails['added_transact_data'] as $fTd) {
								$fTid = $fTd['transact_id'] ?? null;
								$fCnt = $fTd['added_count']  ?? 0;
								if ($fTid) {
									$unpaidPaxCountByTransact[$fTid] = ($unpaidPaxCountByTransact[$fTid] ?? 0) + $fCnt;
								}
							}
						}
					}
				}

				foreach ($check as $key => $value) {
					$btset = $this->bookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $value)->where('deleted_by', 0)->first();
					$isInfantRate = $btset->is_infant_rate;
					$touristsCount = ($isInfantRate == 1) ? $btset->infants : $btset->tourists;
					$customerCheck = $this->tourBooking::where('id', $request->bookingID)->first();
					$customer = $this->customer::where('id', $customerCheck->customer_id)->first();
					$oldpermitfeesarray[$value] = $btset->permit_fee;
					$tourpackagerate = $this->tourPackageRate::withTrashed()->find($value);
					if ($btset->refund_permitfee_status == '') {
						$statusInfo = [];
					} else {
						$statusInfo = json_decode($btset->refund_permitfee_status);
					}

					$oldpermitfees = $btset->permit_fee * $touristsCount;
					$totalTouristswithoutpermitfees = 0;
					$totalTouristtriedtoincreasepermitfees = 0;
					for ($b = 0; $b < $touristsCount; $b++) {
						$totalold = $btset->total;

						if (!isset($statusInfo[$b]) || (!isset($statusInfo[$b]) && $checkPermitfee[$tourpackagerate->rate_for . "." . $b] > 0)) {
							$statusInfo[$b] = new \stdClass;
							$statusInfo[$b]->status = 'N';
						}
						// Handle both full and partial permit fee refunds
						// Allow subsequent refunds: check if new permit fee is less than current effective permit fee
						$currentEffectivePermitFee = $btset->permit_fee;
						if (isset($statusInfo[$b]) && $statusInfo[$b]->status == 'Y' && isset($statusInfo[$b]->new_permit_fee)) {
							// If there was a previous refund, use the new_permit_fee as the current effective fee
							$currentEffectivePermitFee = $statusInfo[$b]->new_permit_fee;
						}

						$isPaxAdded = isset($statusInfo[$b]->is_pax_added) && $statusInfo[$b]->is_pax_added == true;

						// Fallback: use payment link item data to detect unpaid pax when is_pax_added
						// is absent from the JSON. Stamps the flag now so subsequent edits skip this lookup.
						if (!$isPaxAdded && isset($unpaidPaxCountByTransact[$btset->id])) {
							$fallbackUnpaidCount  = $unpaidPaxCountByTransact[$btset->id];
							$fallbackUnpaidStart  = $touristsCount - $fallbackUnpaidCount;
							if ($b >= $fallbackUnpaidStart) {
								$isPaxAdded = true;
								$statusInfo[$b]->is_pax_added = true;
							}
						}

						// For unpaid pax a prior permit_fee_override supersedes the transact row value
						if ($isPaxAdded && isset($statusInfo[$b]->permit_fee_override)) {
							$currentEffectivePermitFee = (float)$statusInfo[$b]->permit_fee_override;
						}

						$newPermitFeeForSlot = (float)$checkPermitfee[$tourpackagerate->rate_for . "." . $b];

						if ($isPaxAdded) {
							// Unpaid pax: no Stripe refund; track delta so the remaining_payment link
							// and transact total can be updated. Both increases and decreases are allowed.
							if ($newPermitFeeForSlot != $currentEffectivePermitFee) {
								$slotDelta = $newPermitFeeForSlot - $currentEffectivePermitFee;
								$unpaidPermitFeeDelta += $slotDelta;
								$unpaidTransactDeltaByRate[$value] = ($unpaidTransactDeltaByRate[$value] ?? 0.0) + $slotDelta;
								$statusInfo[$b]->permit_fee_override = $newPermitFeeForSlot;
								$unpaidPaxCountByRateFor[$tourpackagerate->rate_for] = ($unpaidPaxCountByRateFor[$tourpackagerate->rate_for] ?? 0) + 1;
							}
						} elseif ($oldpermitfees > 0 && $newPermitFeeForSlot < $currentEffectivePermitFee) {
							$totalTouristswithoutpermitfees++;

							// Calculate refund amount (difference between current effective and new permit fee)
							$refundAmount = $currentEffectivePermitFee - $newPermitFeeForSlot;
							$newPermitFee = $newPermitFeeForSlot;

							if ($customer->is_affiliate === 'Yes' && $btset->additional_tax_percentage) {
								$oldrt = ($btset->rate + $btset->additional_charge + $currentEffectivePermitFee + $btset->partner_fees_amount) * ($btset->additional_tax_percentage) / 100;
								$rt = ($btset->rate + $btset->additional_charge + $newPermitFee + $btset->partner_fees_amount) * ($btset->additional_tax_percentage) / 100;
							} else {
								$oldrt = ($btset->rate + $btset->additional_charge + $currentEffectivePermitFee + $btset->partner_fees_amount) * ($btset->additional_tax_percentage + $btset->processing_charge_percentage) / 100;
								$rt = ($btset->rate + $btset->additional_charge + $newPermitFee + $btset->partner_fees_amount) * ($btset->additional_tax_percentage + $btset->processing_charge_percentage) / 100;
							}
							$refundpermitarray[$value] = $totalTouristswithoutpermitfees;
							$newprocessingfees[$value] = number_format((float)($oldrt - $rt), 2);

							// Store refund information (partial or full)
							$statusInfo[$b]->amount = $refundAmount;
							if (!isset($statusInfo[$b]->original_permit_fee)) {
								$statusInfo[$b]->original_permit_fee = $btset->permit_fee;
							}
							$statusInfo[$b]->new_permit_fee = $newPermitFee;
							$statusInfo[$b]->processing_fees = ($request->bookingID < $oldBookingId) ? number_format((float)($oldrt - $rt), 2) : 0;
							$statusInfo[$b]->status = 'Y';
							$statusInfo[$b]->is_partial_refund = ($newPermitFee > 0);
							$statusInfo[$b]->dateTime = mysqlDT();
							if (isset($statusInfo[$b]->is_pax_added) && $statusInfo[$b]->is_pax_added == true) {
								unset($statusInfo[$b]->is_pax_added);
							}
						}

						// Check for actual permit fee increases for PAID pax only (unpaid pax may freely increase)
						if (!$isPaxAdded) {
							$originalPermitFee = $btset->permit_fee;
							$newPermitFee      = $newPermitFeeForSlot;
							if ($newPermitFee > $originalPermitFee) {
								$totalTouristtriedtoincreasepermitfees++;
							}
						}
					}

					$totalTouristtriedtoincreasepermitfeesarray[$value] = $totalTouristtriedtoincreasepermitfees;
					$totalTouristswithoutpermitfeesarray[$value] = $totalTouristswithoutpermitfees;

					$subtotal = $total = $totalold;
					$total = $subtotal;
					$bt = $this->bookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $value)->where('deleted_by', 0)->first();
					if ($request->payment_type == 'Card' && $request->bookingID > 14000 && $customer->is_affiliate == 'No') {
						$transaction = $this->transaction::where('tour_booking_id', $request->bookingID)->whereNull('charge_type')->first();
						$fee = ($bt->nat_fees_percentage * $subtotal) / 100;
						$total = $fee + $total;
					}


					// Check if any permit fee changed for this rate group
					$hasPermitFeeChange = false;
					for ($b = 0; $b < $touristsCount; $b++) {
						if ($bt->permit_fee != $checkPermitfee[$tourpackagerate->rate_for . "." . $b]) {
							$hasPermitFeeChange = true;
							break;
						}
					}

					if ($hasPermitFeeChange) {
						$transactUpdates = ['refund_permitfee_status' => json_encode($statusInfo)];

						// For unpaid pax, adjust the transact total in place (no Stripe refund path).
						// Only update rows where at least one unpaid pax's fee actually changed.
						if (isset($unpaidTransactDeltaByRate[$value]) && $unpaidTransactDeltaByRate[$value] != 0) {
							$transactUpdates['total'] = DB::raw('total + ' . $unpaidTransactDeltaByRate[$value]);

							// Only update the permit_fee column when every pax in this rate group
							// is unpaid. In mixed bookings (paid + unpaid share the same rate), the
							// column must stay at the original rate's fee — only the per-pax
							// permit_fee_override in refund_permitfee_status carries the override.
							$allPaxUnpaid = true;
							for ($b = 0; $b < $touristsCount; $b++) {
								if (!isset($statusInfo[$b]->is_pax_added) || !$statusInfo[$b]->is_pax_added) {
									$allPaxUnpaid = false;
									break;
								}
							}
							if ($allPaxUnpaid) {
								$lastUnpaidNewFee = (float)$bt->permit_fee;
								for ($b = 0; $b < $touristsCount; $b++) {
									if (isset($statusInfo[$b]->is_pax_added) && $statusInfo[$b]->is_pax_added) {
										$lastUnpaidNewFee = (float)($checkPermitfee[$tourpackagerate->rate_for . '.' . $b] ?? $bt->permit_fee);
									}
								}
								$transactUpdates['permit_fee'] = $lastUnpaidNewFee;
							}
						}

						$this->bookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $value)->where('deleted_by', 0)
							->update($transactUpdates);
					}
				}

				if (array_sum($totalTouristtriedtoincreasepermitfeesarray) > 0 && array_sum($totalTouristswithoutpermitfeesarray) == 0) {
					if (isset($request->api) && $request->api == 1) {
						throw new Exception("Your are not allowed to increase permit fees.");
					} else {
						$message = 'Your are not allowed to increase permit fees.';
						return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
					}
				}

				if (!empty($refundpermitarray)) {
					$amountTotal = 0;
					$amountTotalrefundpermitfees = 0;
					$amountTotalrefundprocessingfees = 0;
					$textfordeleted = '';
					$i = 0;
					foreach ($refundpermitarray as $key => $value) {
						$btset = $this->bookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $key)->where('deleted_by', 0)->first();
						$tourpackagerate = $this->tourPackageRate::withTrashed()->find($key);

						$textfordeleted .= ($i == 0) ? $tourpackagerate->rate_for . " person " . $value : "  , " . $tourpackagerate->rate_for . " person " . $value;
						$totalrefundpermitfeesamount = 0;
						$totalrefundprocessingfeesamount = 0;

						// Calculate actual refund amount from status info for mixed refunds
						$statusInfo = json_decode($btset->refund_permitfee_status);
						$totalRefundAmount = 0;
						$newPermitFeePerPerson = $btset->permit_fee; // Default to current permit fee

						if (!empty($statusInfo)) {
							// Find the most recent refunds by checking dateTime
							// Group refunds by dateTime to identify the current operation
							$refundsByTime = [];
							foreach ($statusInfo as $index => $status) {
								if (isset($status->status) && $status->status == 'Y' && isset($status->amount) && isset($status->dateTime)) {
									$refundsByTime[$status->dateTime][] = $status->amount;
								}
							}

							// Get the most recent refund operation (latest dateTime)
							if (!empty($refundsByTime)) {
								$latestTime = max(array_keys($refundsByTime));
								$currentOperationRefunds = $refundsByTime[$latestTime];
								$totalRefundAmount = array_sum($currentOperationRefunds);
							}

							// For permit fee update, use the most recent refund status
							foreach ($statusInfo as $status) {
								if (isset($status->status) && $status->status == 'Y') {
									if (isset($status->new_permit_fee)) {
										$newPermitFeePerPerson = $status->new_permit_fee;
									} else {
										$newPermitFeePerPerson = 0; // Full refund case
									}
								}
							}
						}

						$totalrefundpermitfeesamount = $totalRefundAmount;
						if (($request->bookingID < $oldBookingId)) {
							$totalrefundprocessingfeesamount = (isset($newprocessingfees[$key])) ? $newprocessingfees[$key] * $value : 0;
						}
						$amountTotalrefundprocessingfees += $totalrefundprocessingfeesamount;
						$amountTotalrefundpermitfees += $totalRefundAmount;
						$bookingtotal = $btset->total - $totalrefundpermitfeesamount - $totalrefundprocessingfeesamount;

						// Update permit fee to new amount
						$permitfee = ($btset->tourists == $value) ? $newPermitFeePerPerson : $btset->permit_fee;
						$this->bookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $key)->where('deleted_by', 0)
							->update(
								[
									'total' => number_format((float)$bookingtotal, 2, '.', ''),
									'permit_fee' => $permitfee,
								]
							);
						$i++;
					}

					$amountTotal = $tourbooking->total - $amountTotalrefundpermitfees - $amountTotalrefundprocessingfees;
					$TS = $this->transaction::where('tour_booking_id', $request->bookingID)->where('status', 'Completed')->whereNull('charge_type')->latest('id')->first();

					$permitFee = 0;
					if (!empty($TS) && ($TS->via == "Card" || ($isCashFees == '1' && $TS->via == "Cash"))) {
						$permitFee = $tourbooking->service_commission;
					}

					$tourBooking = $this->tourBooking::where('id', $request->bookingID)->update(['total' => $amountTotal, 'service_commission' => $permitFee]);
					if ($isImportedBooking == true) {

						if ($request->is_cash == '') {
							if (isset($request->api) && $request->api == 1) {
								throw new Exception("Your must need to select Cash/Wire payment method.");
							} else {
								$message = 'Your must need to select Cash/Wire payment method.';
								return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
							}
						}

						if ($request->is_cash == 'Cash') {
							$paymentType = 'Cash';
						} elseif ($request->is_cash == 'Wire Transfer') {
							$paymentType = 'Check/Wire';
						}
					} else {
						$paymentType = $request->payment_type;
					}

					$details = json_encode([], JSON_NUMERIC_CHECK);

					$data = [
						'amount' => $amountTotal,
						'permit_fees' => $amountTotalrefundpermitfees + $amountTotalrefundprocessingfees,
						'payment_type' => $paymentType,
					];
					$tourBooking = $this->tourBooking::find($request->bookingID);
					HistoryService::updateTouristInHistory($request->bookingID, $data, $tourBooking, $createdByWithName);

					$cardNumber = '';
					if (!empty($TS) && $request->payment_type == 'Card') {
						if ($request->has('checked_transactions') && $request->checked_transactions != '') {
							$cardDetails = BookingService::cardLastFourDigit($request->bookingID, $request->checked_transactions);
						} else {
							$cardDetails = BookingService::cardLastFourDigit($request->bookingID, $TS->transaction_number);
						}
						$cardNumber = $cardDetails['card_last_4_digit'];
					}
					if (!empty($TS)) {
						if ($isImportedBooking == true && $request->payment_type == 'Card') {
							if ($request->is_cash == 'Cash') {
								$paymentType = 'Cash';
							} elseif ($request->is_cash == 'Wire Transfer') {
								$paymentType = 'Check/Wire';
							}
						} else {
							$paymentType = $request->payment_type;
						}

						$data = [
							'amount' => $amountTotalrefundpermitfees + $amountTotalrefundprocessingfees,
							'refund_keep_us' => 0,
							'payment_type' => $paymentType,
							'card_number' => $cardNumber,
							'deleted' => $textfordeleted,
							'refund_type' => 'Permitfees Refund',
							'comment' => null
						];
					} else {
						$data = [
							'amount' => $amountTotalrefundpermitfees + $amountTotalrefundprocessingfees,
							'refund_keep_us' => 0,
							'payment_type' => $paymentType,
							'card_number' => null,
							'deleted' => $textfordeleted,
							'refund_type' => 'Permitfees Refund',
							'comment' => null
						];
					}

					$bookingInfo = $this->tourBooking::find($request->bookingID);

					$historyId = HistoryService::storeRefundDataInHistory(
						$request->bookingID,
						$bookingInfo->tourists + $bookingInfo->infants,
						$createdByWithName,
						$data['comment'],
						$data['refund_type'],
						null, /* $transaction */
						$data['amount'],
						$data['card_number'],
						[], /* $cardsArray */
						[], /* $partialAmountArray */
						$data['payment_type'],
						null, /* $paymentTotal */
						null, /* $refundTotal */
						$data['refund_keep_us'],
						$data['deleted']
					);

					if (!empty($TS) && $request->payment_type == 'Card' && !$isImportedBooking) {
						try {
							if ($request->has('checked_transactions') && $request->checked_transactions != '') {
								$TSDetails = $this->transaction::where('tour_booking_id', $request->bookingID)->where('transaction_number', $request->checked_transactions)->where('status', 'Completed')->where(function ($query) {
									// A priced add-on charged on its OWN PaymentIntent (no accompanying tour-side
									// charge) is a valid, admin-selectable "Tour Transaction" option in the Delete
									// Booking modal — its card genuinely holds refundable money, Stripe doesn't care
									// what the charge was originally FOR, so it must resolve here too instead of
									// only matching a charge_type-null (tour-side) transaction.
									$query->whereNull('charge_type')->orWhere('charge_type', 'addons');
								})->first(['id', 'amount', 'application_fee_id', 'payment_mode']);
								$transId = $TSDetails->id;
								//Below line is to reverse transfer of permit fees from partner connected account
								if ($tourBooking->is_partner_booking == 1 && $amountTotalrefundpermitfees > 0) {
									ThreeWayPaymentService::reverseTransfer($request->bookingID, $TSDetails->id, $amountTotalrefundpermitfees);
								}
								$refundParams = [
									'payment_intent' => $request->checked_transactions,
									'amount' => ($amountTotalrefundpermitfees + $amountTotalrefundprocessingfees) * 100,
									'reverse_transfer' => true,
								];
								$refund = app(PaymentGatewayInterface::class)->refundPayment($refundParams, $TSDetails->payment_mode);

								$TS_number = $request->checked_transactions;
								$application_fee_id = $TSDetails->application_fee_id;
								$piMode = $TSDetails->payment_mode;
							} else {
								if ($tourBooking->is_partner_booking == 1 && $amountTotalrefundpermitfees > 0) {
									ThreeWayPaymentService::reverseTransfer($request->bookingID, $TS->id, $amountTotalrefundpermitfees);
								}
								$refundParams = [
									'payment_intent' => $TS->transaction_number,
									'amount' => ($amountTotalrefundpermitfees + $amountTotalrefundprocessingfees) * 100,
									'reverse_transfer' => true,
								];
								$refund = app(PaymentGatewayInterface::class)->refundPayment($refundParams, $TS->payment_mode);
								$TS_number = $TS->transaction_number;
								$application_fee_id = $TS->application_fee_id;
								$transId = $TS->id;
								$piMode = $TS->payment_mode;
							}
							$refundAmount = $amountTotalrefundpermitfees + $amountTotalrefundprocessingfees;
							$refundTransId = TransactionService::storeRefundInTransaction($request->bookingID, $refundAmount, 0, 'Card', $TS_number, $application_fee_id, mode: $piMode);
							//Below line is for to store reverse tranfer for permit fees from partner connnected account
							if ($tourBooking->is_partner_booking == 1 && $amountTotalrefundpermitfees > 0) {
								ThreeWayPaymentService::storeReverseTransferInPayout($request->bookingID, $transId, $refundTransId, $amountTotalrefundpermitfees);
							}
						} catch (Exception $e) {
							Log::error('Permit fee Stripe refund failed', [
								'booking_id' => $request->bookingID,
								'error'      => $e->getMessage(),
							]);
							throw $e;
						}
					} else if (!empty($TS) && $request->payment_type == 'Card' && $isImportedBooking) {
						if ($request->is_cash == 'Cash') {
							$paymentType = 'Cash';
						} elseif ($request->is_cash == 'Wire Transfer') {
							$paymentType = 'Check/Wire';
						}
						$refundAmount = $amountTotalrefundpermitfees + $amountTotalrefundprocessingfees;
						$refundTransId = TransactionService::storeRefundInTransaction($request->bookingID, $refundAmount, 0, $paymentType, null, null, mode: $TS->payment_mode);
						//Below line is for to store reverse tranfer for permit fees from partner connnected account
						if ($tourBooking->is_partner_booking == 1 && $amountTotalrefundpermitfees > 0) {
							ThreeWayPaymentService::storeReverseTransferInPayout($request->bookingID, $TS->id, $refundTransId, $amountTotalrefundpermitfees, 0, 0, $paymentType);
						}
					} elseif (!empty($TS) && $request->payment_type == 'Cash') {
						$refundAmount = $amountTotalrefundpermitfees + $amountTotalrefundprocessingfees;
						$refundTransId = TransactionService::storeRefundInTransaction($request->bookingID, $refundAmount, 0, 'Cash', null, null);
						if ($tourBooking->is_partner_booking == 1 && $amountTotalrefundpermitfees > 0) {
							ThreeWayPaymentService::storeReverseTransferInPayout($request->bookingID, $TS->id, $refundTransId, $amountTotalrefundpermitfees, 0, 0, 'Cash');
						}
					} elseif ($amountTotalrefundpermitfees > 0 && !empty($TS)) {
						// Non-Card/Cash payment type (e.g. Headout, Viator, Wire Transfer, Invoiced)
						// — a real Completed transaction backs this booking, just via a channel that
						// didn't match the Card/Cash branches above; still worth recording as a real
						// refund. Requires $TS itself (NOT just falling back to $request->payment_type)
						// — a genuinely never-paid Pay Later booking has ZERO transaction rows at all
						// (same convention as TourBookingAddonRepository::resolveBookingPaymentMethodLabel()),
						// so writing a "Refund" transaction here for it fabricated a refund of money
						// that was never actually collected by anyone.
						$refundAmount = $amountTotalrefundpermitfees + $amountTotalrefundprocessingfees;
						$refundVia = $TS->via;
						$refundTransId = TransactionService::storeRefundInTransaction($request->bookingID, $refundAmount, 0, $refundVia, null, null);
					}

					// Permit fee refund queue job dispatch
					PermitFeeRefundBookingService::run($tourbooking, $refundTransId ?? null, $historyId, $request->all(), $request->payment_type);
				}

				// Payment link query start — remaining_payment links are managed separately
				$tourBookingPaymentLink = TourBookingPaymentLink::where('order_id', $tourBooking->group_id)
					->where('status', 'Unpaid')
					->where(function ($q) { $q->whereNull('section')->orWhere('section', '!=', 'remaining_payment'); })
					->first();

				if ($tourBookingPaymentLink) {
					$infoDetails = BookingUtils::getBookingDetails($tourBooking->id);
					$data = [
						'amount' => $amountTotalrefundpermitfees,
						'natFeesPercentage' => $tourBookingTransaction->nat_fees_percentage
					];
					PaymentLinkService::paymentLinkUpdate($data, $infoDetails, $tourBooking, $tourBookingPaymentLink, 'Permit Fee Remove');
				}
				// Payment link query end

				// Update remaining_payment link and write history when permit fee changed for unpaid pax
				if ($unpaidPermitFeeDelta != 0) {
					PaymentLinkService::processUnpaidPermitFeeDelta(
						$request,
						$unpaidPermitFeeDelta,
						(float)($tourBookingTransaction->nat_fees_percentage ?? 0),
						$tourbooking,
						$createdByWithName,
						$unpaidPaxCountByRateFor
					);
				}

				if (!isset($request->api)) {
					$message = 'Permit fee updated successfully.';
					return BookingService::refundRouteWithSuccess($request->bookingID, $modalUrl, $message);
				} else {
					return [
						'booking_id' => $request->bookingID,
						'history' => isset($TourBookingHistory) ? $TourBookingHistory : null,
						'message' => 'Permit fee updated successfully.'
					];
				}
			}

			$total = 0;
			$checkTotalTourists = count($check);
			$transK = Transaction::where('status', 'Completed')->where('tour_booking_id', $request->bookingID)->first();
			if ($request->total_tourist == $checkTotalTourists) {
				if (isset($request->api) && $request->api == 1) {
					throw new Exception("You can not delete all records. Please use cancel booking option.");
				} else {
					$message = 'You can not delete all records. Please use cancel booking option.';
					return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
				}
			}

			$oldBookingID = $oldBookingId;
			if ($tourBooking->is_group_booking == '1' && $request->action_type == "delete") {
				$res = EditBookingService::deletePaxFromGroupBooking($request, $modalUrl, $paymentTransCountForBooking);
				// deletePaxFromGroupBooking() only ever returns a plain array on success; any other
				// return (a redirect on the classic web submit, or a JSON error response on an
				// AJAX/JSON submit) is already a complete response and must be returned as-is,
				// not fallen through into the single-booking logic below. Not gated on a specific
				// status code (previously ===302 only) so a JSON error response — which is never
				// a 302 — still short-circuits here instead of silently continuing.
				if (getType($res) != "array") {
					return $res;
				}
				// Read by the shared "Payment link query" below — the single-booking branch sets
				// this itself, but the group path skips that branch entirely, so without this an
				// Unpaid booking payment link crashed with "Undefined variable".
				$tourBookingTotalForPayLater = $res['tourBookingTotalForPayLater'] ?? 0;
			} else {
				if ($request->action_type == "delete") {
					// Must count add-ons-only PaymentIntents (charge_type = 'addons') too, not just
					// whereNull('charge_type') ticket PIs — otherwise a booking with exactly ONE
					// ticket PaymentIntent plus one-or-more add-ons-only PaymentIntents (e.g. a
					// later "upgrade a free add-on" charge that landed on its own PI) is treated as
					// having only 1 payment transaction, even though the "Update Booking" modal's own
					// Tour Transaction picker renders and lets the admin select any of them. That
					// mismatch used to skip BOTH the "must select a transaction" guard below AND the
					// balance-sufficiency validation further down (paymentTransCountForBooking > 1
					// gates both), letting an admin pick an add-ons-only PaymentIntent that can't
					// cover the ticket refund with no error at all — see the 100_refund Stripe-refund
					// branch's own comment further below for what happened next.
					$paymentTransCountForBooking = $this->transaction::where('tour_booking_id', $request->bookingID)->where('status', 'Completed')->where(function ($query) {
						$query->whereNull('charge_type')->orWhere('charge_type', 'addons');
					})->count();
					if ($request->payment_type == 'Card' && $request->refund_Type != "fareharbor" && $request->is_cash == '' && $paymentTransCountForBooking > 1 && ($request->has('checked_transactions') && $request->checked_transactions == '' && $request->refund_Type != 'dont_refund')) {
						if (isset($request->api) && $request->api == 1) {
							throw new Exception("You must need to select payment transaction to delete person.");
						} else {
							$message = 'You must need to select payment transaction to delete person.';
							return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
						}
					}
					if ($request->refund_Type == "partial_refund") {
						if ($request->partial_Refund_value == '') {
							if (isset($request->api) && $request->api == 1) {
								throw new Exception("Please enter partial refund amount value.");
							} else {
								$message = 'Please enter partial refund amount value.';
								return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
							}
						}
					}
					$refundedpermitarray = array();

					$checkarrays = array();
					$checkinstatusarray = array();
					$redeemTicketArray = array();
					$refundedpermitfeearray = array();

					foreach ($check as $key => $value) {
						$btset = $this->bookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $value)->where('deleted_by', 0)->first();

						$explode = explode('.', $key);

						$checkarrays[$value][] = $explode[1];
						$checkinstatusarray[$value] = $btset->check_in_status;
						$redeemTicketArray[$value] = $btset->redeem_ticket;
						$refundedpermitfeearray[$value] = $btset->refund_permitfee_status;
					}
					$updatedCheckIns = array();
					$updatedRedeemTickets = array();
					$updatedRefundedPermitFees = array();

					if (!empty($checkarrays)) {
						foreach ($checkarrays as $k => $checkarray) {
							if (isset($checkinstatusarray[$k]) && $checkinstatusarray[$k] != '')
								$checkinstatusInfo = json_decode($checkinstatusarray[$k]);
							else
								$checkinstatusInfo = [];

							if (isset($redeemTicketArray[$k]) && $redeemTicketArray[$k] != '')
								$redeemTicketInfo = json_decode($redeemTicketArray[$k], TRUE);
							else
								$redeemTicketInfo = [];

							if (isset($refundedpermitfeearray[$k]) && $refundedpermitfeearray[$k] != '')
								$refundpermitfeesstatusInfo = json_decode($refundedpermitfeearray[$k]);
							else
								$refundpermitfeesstatusInfo = [];

							foreach ($checkarray as $l => $m) {
								if (isset($checkinstatusInfo[$m]) && !empty($checkinstatusInfo[$m])) {
									unset($checkinstatusInfo[$m]);
								}
								if (!empty($redeemTicketInfo)) {
									for ($y = 0; $y < count($redeemTicketInfo); $y++) {
										if (isset($redeemTicketInfo[$y]['data'][$m]) && !empty($redeemTicketInfo[$y]['data'][$m])) {
											unset($redeemTicketInfo[$y]['data'][$m]);
										}
										if (isset($redeemTicketInfo[$y]['data'])) {
											$redeemTicketInfo[$y]['data'] = array_values($redeemTicketInfo[$y]['data']);
										}
									}
								}
								if (isset($refundpermitfeesstatusInfo[$m]) && !empty($refundpermitfeesstatusInfo[$m])) {

									if (isset($refundpermitfeesstatusInfo[$m]->status) && $refundpermitfeesstatusInfo[$m]->status == 'Y' && isset($refundpermitfeesstatusInfo[$m]->amount) && $refundpermitfeesstatusInfo[$m]->amount > 0) {
										$refundedpermitarray[$k][] = $m;
									}

									unset($refundpermitfeesstatusInfo[$m]);
								}
							}
							$updatedCheckIns[$k] = $checkinstatusInfo;
							$updatedRedeemTickets[$k] = $redeemTicketInfo;
							$updatedRefundedPermitFees[$k] = $refundpermitfeesstatusInfo;
						}
					}

					//Check validations with calculations for multiple payments using card
					if ($request->payment_type == 'Card' && $request->refund_Type != "fareharbor" && $request->is_cash == '' && $paymentTransCountForBooking > 1 && ($request->has('checked_transactions') && $request->checked_transactions != '')) {
						$refundTrans = $this->transaction::where('tour_booking_id', $request->bookingID)->where('transaction_number', $request->checked_transactions)->where('status', 'Refund')->where(function ($query) {
							$query->whereNull('charge_type')->orWhere('charge_type', 'addons');
						})->get(['id', 'amount']);
						$paymentTrans = $this->transaction::where('tour_booking_id', $request->bookingID)->where('transaction_number', $request->checked_transactions)->where('status', 'Completed')->where(function ($query) {
							$query->whereNull('charge_type')->orWhere('charge_type', 'addons');
						})->first(['id', 'amount']);
						$totalrefundedamount = 0;
						foreach ($refundTrans as $ky => $val) {
							$totalrefundedamount += $val->amount;
						}
						$amountCapturedStripe = 0;
						$amountRefundedStripe = 0;
						$paymentIntent = app(PaymentGatewayInterface::class)->retrievePayment($request->checked_transactions);
						if (!empty($paymentIntent) && isset($paymentIntent->charges) && isset($paymentIntent->charges->data[0]) && !empty($paymentIntent->charges->data[0])) {
							$amountCapturedStripe = $paymentIntent->charges->data[0]->amount_captured;
							$amountRefundedStripe = ($paymentIntent->charges->data[0]->amount_refunded != '') ? $paymentIntent->charges->data[0]->amount_refunded : 0;
						}

						//Validation check if payment transactions fully refunded or not
						if ($paymentTrans->amount - $totalrefundedamount <= 0) {
							if (isset($request->api) && $request->api == 1) {
								throw new Exception('Unable to refund booking. Selected transaction already fully refunded.Please select different one.');
							} else {
								$message = 'Unable to refund booking. Selected transaction already fully refunded. Please select different one.';
								return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
							}
						}

						$totalAmountForValidation = 0;
						$totalFeeForValidation = 0;
						$totalPartnerFeesForValidation = 0;
						foreach ($array as $key => $value) {
							$tourBooking = $this->tourBooking::find($request->bookingID);
							$customer = $this->customer::find($tourBooking->customer_id);

							$rateCheck = $this->bookingTransact::where('tour_package_rate_id', $key)->where('tour_booking_id', $request->bookingID)->where('deleted_by', 0)->first();
							$serviceCommissionPercentage = $rateCheck->nat_fees_percentage;
							// Check if this rate group has any permit fee refund status (partial or full)
							if ($request->action_type == "delete" && $rateCheck->refund_permitfee_status != '') {
								// Get the rate group type from the tour package rate
								$tourPackageRate = $this->tourPackageRate::withTrashed()->find($key);
								$rateGroupType = $tourPackageRate->rate_for;

								// Get people being deleted for this rate group from checkarrays
								$peopleToDelete = [];
								if (isset($checkarrays[$key])) {
									$peopleToDelete = $checkarrays[$key];
								}

								$totalSubtotal = 0;
								$totalFee = 0;

								// Calculate cost for each person being deleted individually
								foreach ($peopleToDelete as $personIndex) {
									// Get current permit fee for this specific person from permitF array
									$permitKey = $rateGroupType . '.' . $personIndex;
									$currentPermitFee = isset($checkPermitfee[$permitKey]) ? floatval($checkPermitfee[$permitKey]) : $rateCheck->permit_fee;

									// Calculate rate with individual permit fee
									$rate = $rateCheck->rate + $rateCheck->additional_charge + $currentPermitFee + $rateCheck->partner_fees_amount;

									if ($request->payment_type === 'Card') {
										$per = $rate * ($rateCheck->additional_tax_percentage + $rateCheck->processing_charge_percentage) / 100;
									} else {
										$per = $rate * $rateCheck->additional_tax_percentage / 100;
									}

									$personSubtotal = $rate + $per;
									$personFee = roundout($personSubtotal * $serviceCommissionPercentage / 100);

									$totalSubtotal += $personSubtotal;
									$totalFee += $personFee;
								}

								// Format final values
								$subtotal = round($totalSubtotal, 2);
								$feeSize = round($totalFee, 2);
							} else {
								$rate = $rateCheck->rate + $rateCheck->additional_charge + $rateCheck->permit_fee + $rateCheck->partner_fees_amount;
								if ($request->payment_type === 'Card') {
									$per = $rate * ($rateCheck->additional_tax_percentage + $rateCheck->processing_charge_percentage) / 100;
								} else {
									$per = $rate * $rateCheck->additional_tax_percentage / 100;
								}
								$subtotal = ($rate + $per);
								$feeSize = roundout($subtotal * $serviceCommissionPercentage / 100) * $value;
								$subtotal = number_format((float)$subtotal * $value, 2, '.', '');
							}
							$totalAmountForValidation += $subtotal;
							$totalFeeForValidation += $feeSize;
							$totalPartnerFeesForValidation += $rateCheck->partner_fees_amount * $value;
						}

						// Subtract unpaid pax (pending payment link) amounts — they were never captured
						// by Stripe, so including them causes false "exceeds unrefunded" validation errors.
						if (!in_array($request->refund_Type, ['dont_refund', 'partial_refund'])) {
							$unpaidMapForValidation = $this->buildUnpaidPaxCountByTransactId($request);
							$deduction = PaymentLinkService::computeUnpaidPaxValidationDeduction(
								$array, (int)$request->bookingID, $unpaidMapForValidation
							);
							$totalAmountForValidation = max(0.0, round($totalAmountForValidation - $deduction['amount'], 2));
							$totalFeeForValidation    = max(0.0, round($totalFeeForValidation - $deduction['fee'], 2));
						}

						if ($request->refund_Type == "partial_refund") {
							//We added fees calculations because we need to refund platoform fees as well in partial refund.
							$feeAmount = 0;
							if ($request->payment_type == 'Card' || ($isCashFees == '1' && $request->payment_type == 'Cash')) {
								$feeAmount = ($totalAmountForValidation * $serviceCommissionPercentage) / 100;
							}
							$netAmountForValidationPartialRefund = round($totalAmountForValidation + $feeAmount, 2);
							if ($request->partial_Refund_value > $netAmountForValidationPartialRefund) {
								if (isset($request->api) && $request->api == 1) {
									throw new Exception('Unable to refund booking. Please enter amount less than total.');
								} else {
									$message = 'Unable to refund booking. Please enter amount less than total.';
									return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
								}
							}
							if ($amountCapturedStripe > 0) {
								$remainingAmountStripe = $amountCapturedStripe / 100 - $amountRefundedStripe / 100;
								if ($request->partial_Refund_value > $remainingAmountStripe) {
									if (isset($request->api) && $request->api == 1) {
										throw new Exception('Unable to refund booking. For the chosen transaction, the refund amount is greater than the unrefunded amount. Please choose another transaction.');
									} else {
										$message = 'Unable to refund booking. For the chosen transaction, the refund amount is greater than the unrefunded amount. Please choose another transaction.';
										return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
									}
								}
							}
						}
						if ($request->refund_Type != "dont_refund" && $request->refund_Type != "partial_refund"  && $amountCapturedStripe > 0) {
							$remainingAmountStripe = $amountCapturedStripe / 100 - $amountRefundedStripe / 100;
							if ($totalAmountForValidation > $remainingAmountStripe) {
								if (isset($request->api) && $request->api == 1) {
									throw new Exception('Unable to refund booking. For the chosen transaction, the refund amount is greater than the unrefunded amount. Please choose another transaction.');
								} else {
									$message = 'Unable to refund booking. For the chosen transaction, the refund amount is greater than the unrefunded amount. Please choose another transaction.';
									return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
								}
							}
						}
						//Validation check for 100% refund when deleting persons
						if ($request->refund_Type == "100_refund" && ($totalAmountForValidation > 0)) {
							$setFeeAmount = $totalFeeForValidation;
							$refund100 = round($totalAmountForValidation + $totalFeeForValidation, 2);
							$rounded = round($paymentTrans->amount - $totalrefundedamount - $refund100, 2);
							$refund100 = round($totalAmountForValidation + $setFeeAmount, 2);
							$rounded = round($paymentTrans->amount - $totalrefundedamount - $refund100, 2);
							if ($rounded < -0.05) {
								if (isset($request->api) && $request->api == 1) {
									throw new Exception('Unable to refund booking. Please choose a valid transaction or person to refund.');
								} else {
									$message = 'Unable to refund booking. Please choose a valid transaction or person to refund.';
									return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
								}
							}
						}
						//Validation check for full refund minus fees when deleting persons
						if ($request->refund_Type == "full_refund" && ($totalAmountForValidation > 0)) {

							$ticketCost = round($totalAmountForValidation, 2);

							if (($paymentTrans->amount - $totalrefundedamount - $ticketCost) < -0.05) {
								if (isset($request->api) && $request->api == 1) {
									throw new Exception('Unable to refund booking. Please choose a valid transaction or person to refund.');
								} else {
									$message = 'Unable to refund booking. Please choose a valid transaction or person to refund.';
									return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
								}
							}
						}
					}

					//Check validations cash
					if ($request->payment_type == 'Cash' && $request->refund_Type != "dont_refund") {
						if ($request->refund_Type == "partial_refund") {
							if ($request->partial_Refund_value == "NaN") {
								$message = 'Please enter partial refund amount.';
								if (isset($request->api) && $request->api == 1) {
									throw new Exception($message);
								} else {
									return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
								}
							}
						}
						$checkTotalTourist = count($check);
						foreach ($array as $key => $value) {
							$rateCheck = BookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $key)->first();
							$subtotal = $rateCheck->rate + $rateCheck->additional_charge + $rateCheck->permit_fee + $rateCheck->partner_fees_amount;
						}
						//calculate refund value
						$refundOnly = $this->tourBookingHistory::where('tour_booking_id', $request->bookingID)
							->where('operation', 'Refund')
							->where('payment_method', '!=', "Don't Refund")
							->get([
								'id',
								'details'
							]);
						$refundOnlyCheck = 0;
						foreach ($refundOnly as $value) {
							$details = json_decode($value->details, true);
							$refundOnlyCheck += $details['amount'];
						}
						if ($request->refund_Type == "partial_refund") {
							if ($request->partial_Refund_value > ((float)$tourBooking->booking_total - $refundOnlyCheck)) {
								$message = 'Unable to refund booking. Refund amount is greater than the unrefunded amount.';
								if (isset($request->api) && $request->api == 1) {
									throw new Exception($message);
								} else {
									return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
								}
							}
						}
						$calculatedRefund = $subtotal * $checkTotalTourist;
						$availableAmount = (float)$tourBooking->booking_total - $refundOnlyCheck;
						$tolerance = 0.01;
						if (abs($calculatedRefund - $availableAmount) > $tolerance) {
							if ($calculatedRefund > $availableAmount) {
								$message = 'Unable to refund booking. Refund amount is greater than the unrefunded amount.';
								if (isset($request->api) && $request->api == 1) {
									throw new Exception($message);
								} else {
									return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
								}
							}
						}
					}

					// validation cash end
					$tourBooking = $this->tourBooking::find($request->bookingID);
					//Update waiver, checkins and permit fees details for rate groups
					EditBookingService::updateWaiverAndPermitFees($request, $updatedCheckIns, $updatedRedeemTickets, $updatedRefundedPermitFees);
				}
				$total = 0;
				$totalFees = 0;
				$totalTicketCost = 0;
				foreach ($array as $keyl => $value) {
					$transaction = $this->transaction::where('tour_booking_id', $request->bookingID)->where('status', 'Completed')->whereNull('charge_type')->first();
					$tourBooking = $this->tourBooking::find($request->bookingID);
					$customer = $this->customer::find($tourBooking->customer_id);
					$rateCheckname = $this->tourPackageRate::where('id', $keyl)->withTrashed()->first();
					$rateCheck = $this->bookingTransact::where('tour_package_rate_id', $keyl)->where('tour_booking_id', $request->bookingID)->where('deleted_by', 0)->first();
					$stripe_fees_percentage = $rateCheck->stripe_fees_percentage;
					$serviceCommissionPercentage = $rateCheck->nat_fees_percentage;

					// Check if this rate group has any permit fee refund status (partial or full)
					if ($request->action_type == "delete" && $rateCheck->refund_permitfee_status != '') {
						// Get the rate group type from the tour package rate
						$tourPackageRate = $this->tourPackageRate::withTrashed()->find($keyl);
						$rateGroupType = $tourPackageRate->rate_for;

						// Get people being deleted for this rate group from checkarrays
						$peopleToDelete = [];
						if (isset($checkarrays[$keyl])) {
							$peopleToDelete = $checkarrays[$keyl];
						}

						$totalSubtotal = 0;
						$totalFee = 0;

						// Calculate cost for each person being deleted individually
						foreach ($peopleToDelete as $personIndex) {
							// Get current permit fee for this specific person from permitF array
							$permitKey = $rateGroupType . '.' . $personIndex;
							$currentPermitFee = isset($checkPermitfee[$permitKey]) ? floatval($checkPermitfee[$permitKey]) : $rateCheck->permit_fee;

							// Calculate rate with individual permit fee
							$rate = $rateCheck->rate + $rateCheck->additional_charge + $currentPermitFee + $rateCheck->partner_fees_amount;

							if ($request->payment_type === 'Card' || ($isCashFees == '1' && $request->payment_type === 'Cash')) {
								$per = $rate * ($rateCheck->additional_tax_percentage + $rateCheck->processing_charge_percentage) / 100;
							} else {
								$per = $rate * $rateCheck->additional_tax_percentage / 100;
							}

							$personSubtotal = $rate + $per;
							$personFee = roundout($personSubtotal * $serviceCommissionPercentage / 100);

							$totalSubtotal += $personSubtotal;
							$totalFee += $personFee;
						}

						// Format final values
						$subtotal = round($totalSubtotal, 2);
						$feeSize = round($totalFee, 2);
					} else {
						$rate = $rateCheck->rate + $rateCheck->additional_charge + $rateCheck->permit_fee + $rateCheck->partner_fees_amount;

						if ($request->payment_type === 'Card' || ($isCashFees == '1' && $request->payment_type === 'Cash')) {
							$per = $rate * ($rateCheck->additional_tax_percentage + $rateCheck->processing_charge_percentage) / 100;
						} else {
							$per = $rate * $rateCheck->additional_tax_percentage / 100;
						}

						$subtotal = ($rate + $per);
						$feeSize = roundout($subtotal * $serviceCommissionPercentage / 100) * $value;
						$subtotal = number_format((float)$subtotal * $value, 2, '.', '');
					}

					$total += $subtotal;
					$totalFees += $feeSize;
				}
				$totalTicketCost = $total;
				$btvtotal = 0;
				$btv = $this->tourBooking::find($request->bookingID);
				$btvtotal = $btv->total;
				$btvtotal = (float)$btvtotal;
				$total = (float)$total;
				$nan = 0;

				$tsm = $this->transaction::where('tour_booking_id', $request->bookingID)->where('status', 'Completed')->whereNull('charge_type')->orderBy('id', 'DESC')->first();

				if (!empty($tsm) && $tsm->payment_type == 1 && $request->refund_Type == "dont_refund") {
					$paymentOnlyCheck = 0;
					$paymentOnly = $this->tourBookingHistory::where('tour_booking_id', $request->bookingID)->where('operation', 'Payment')->get();

					foreach ($paymentOnly as $value) {
						$details = json_decode($value->details);
						$paymentOnlyCheck += $details->amount;
					}

					$pendingAmount = $btv->total - $paymentOnlyCheck;
					$pendingAmount = round($pendingAmount);
					$deleteRequestAmount = 0;

					$deleteRequestAmount = $this->splitPaymentCheckBeforeDelete($array, $request->bookingID, $request->payment_type);

					$deleteRequestAmount = round($deleteRequestAmount);

					if ($deleteRequestAmount > $pendingAmount) {
						if (isset($request->api) && $request->api == 1) {
							throw new Exception('Unable to delete booking. Please delete unpaid pax first.');
						} else {
							$message = 'Unable to delete booking. Please delete unpaid pax first.';
							return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
						}
					}
				}

				if ($request->partial_Refund_value == "NaN") {
					$nan = 0;
				} else {
					$nan = $request->partial_Refund_value;
				}

				// validation for payemnt total less than refund total 
				$transactionData = $this->transaction::where('tour_booking_id', $request->bookingID)->where('status', 'Completed')->whereNull('charge_type')->get();
				$transactionRefundData = $this->transaction::where('tour_booking_id', $request->bookingID)->where('status', 'Refund')->whereNull('charge_type')->get();
				$totalAmt = 0;
				$totalRefundAmt = 0;
				if ($transactionData->count() > 1) {
					foreach ($transactionData as $transaData) {
						$totalAmt += $transaData->amount;
					}
				} else {
					if (!empty($transaction)) {
						$totalAmt =  $transaction->amount;
					}
				}

				if ($transactionRefundData->count() > 1) {
					foreach ($transactionRefundData as $transaRefundData) {
						$totalRefundAmt += $transaRefundData->amount;
					}
				} else {
					$transactionRefundData = $this->transaction::where('tour_booking_id', $request->bookingID)->where('status', 'Refund')->whereNull('charge_type')->first();
					if (!empty($transactionRefundData)) {
						$totalRefundAmt = $transactionRefundData->amount;
					}
				}
				$totalAmt = round($totalAmt - $totalRefundAmt, 2);
				if (!empty($transP)) { // if no pay later
					EditBookingService::validateRefundRequestDeletePax($request, $nan, $totalAmt, $modalUrl);
				}
				// vaidation end 
				//Validation modified because now refunding fees as well in partial refunds
				if ($request->refund_Type == "partial_refund") {
					$feeAmount = 0;
					if ($request->payment_type == 'Card' || ($isCashFees == '1' && $request->payment_type == 'Cash')) {
						$feeAmount = ($total * $serviceCommissionPercentage) / 100;
					}
					$netAmountForValidationPartialRefund = round($total + $feeAmount, 2);
					if (($nan > $netAmountForValidationPartialRefund) || ($nan > $btvtotal)) {
						$message = 'Unable to refund booking. Please enter amount less than total.';
						if (isset($request->api) && $request->api == 1) {
							throw new Exception($message);
						} else {
							return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
						}
					}
				}

				if (($total > $btvtotal) && ($request->partial_Refund_value == "NaN") && ($request->refund_Type != "dont_refund")) {
					$message = 'Unable to refund booking. Please enter amount less than total.';
					if (isset($request->api) && $request->api == 1) {
						throw new Exception($message);
					} else {
						return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
					}
				}

				$rateChecknameForPartialRefund = [];
				$partnerFeesRefundForPartialRefund = 0;
				$tourBookingTotalForPayLater = 0;
				$transaction = $this->transaction::where('tour_booking_id', $request->bookingID)->where('status', 'Completed')->whereNull('charge_type')->first();
				$customer = $this->customer::find($tourBooking->customer_id);

				// Build transact_id → unpaid-pax-count map so the loop below can scale
				// Stripe refund amounts and refund_keep_us to paid pax only in mixed (paid + unpaid) deletes.
				// Excluded for partial_refund only — partial_refund handles its own amount calculations.
				// dont_refund is now included so refund_keep_us can be correctly zeroed for unpaid pax.
				$unpaidCountByTransactId = ($request->refund_Type !== 'partial_refund')
					? $this->buildUnpaidPaxCountByTransactId($request)
					: [];

				$totalDeletedPax = 0;
				foreach ($array as $key => $value) {
					$tourBooking = $this->tourBooking::find($request->bookingID);
					$rateCheckname = $this->tourPackageRate::where('id', $key)->withTrashed()->first();
					$rateChecknameForPartialRefund[] = $rateCheckname->rate_for . ' person ' . $value;
					$rateCheck = $this->bookingTransact::where('tour_package_rate_id', $key)->where('tour_booking_id', $request->bookingID)->where('deleted_by', 0)->first();
					$totalDeletedPax += ($rateCheck->infants == 0) ? $value : 0;

					// How many of the pax being deleted have a pending (unpaid) payment link
					$unpaidPaxCount = min((int)$value, $unpaidCountByTransactId[$rateCheck->id] ?? 0);
					$paidPaxValue   = (int)$value - $unpaidPaxCount;

					$serviceCommissionPercentage = $rateCheck->nat_fees_percentage;

					$partnerFees = ($isPartnerBooking == 1) ? $rateCheck->partner_fees_amount * $value : 0;
					// Check if this rate group has any permit fee refund status (partial or full)
					if ($rateCheck->refund_permitfee_status != '') {
						// Get the rate group type from the tour package rate
						$tourPackageRate = $this->tourPackageRate::withTrashed()->find($key);
						$rateGroupType = $tourPackageRate->rate_for;

						// Get people being deleted for this rate group from checkarrays
						$peopleToDelete = [];
						if (isset($checkarrays[$key])) {
							$peopleToDelete = $checkarrays[$key];
						}

						$totalSubtotal = 0;
						$totalFee = 0;

						// Calculate cost for each person being deleted individually
						foreach ($peopleToDelete as $personIndex) {
							// Get current permit fee for this specific person from permitF array
							$permitKey = $rateGroupType . '.' . $personIndex;
							$currentPermitFee = isset($checkPermitfee[$permitKey]) ? floatval($checkPermitfee[$permitKey]) : $rateCheck->permit_fee;

							// Calculate rate with individual permit fee
							$rate = $rateCheck->rate + $rateCheck->additional_charge + $currentPermitFee + $rateCheck->partner_fees_amount;

							if ($request->payment_type === 'Card' || ($isCashFees == '1' && $request->payment_type === 'Cash')) {
								$per = $rate * ($rateCheck->additional_tax_percentage + $rateCheck->processing_charge_percentage) / 100;
							} else {
								$per = $rate * $rateCheck->additional_tax_percentage / 100;
							}

							$personSubtotal = $rate + $per;
							$personFee = roundout($personSubtotal * $serviceCommissionPercentage / 100);

							$totalSubtotal += $personSubtotal;
							$totalFee += $personFee;
						}

						// Format final values
						$subtotal = round($totalSubtotal, 2);
						$feeSize = round($totalFee, 2);
					} else {
						$rate = $rateCheck->rate + $rateCheck->additional_charge + $rateCheck->permit_fee + $rateCheck->partner_fees_amount;
						if ($request->payment_type === 'Card' || ($isCashFees == '1' && $request->payment_type === 'Cash')) {
							$per = $rate * ($rateCheck->additional_tax_percentage + $rateCheck->processing_charge_percentage) / 100;
						} else {
							$per = $rate * $rateCheck->additional_tax_percentage / 100;
						}

						$subtotal = ($rate + $per);
						$feeSize = roundout($subtotal * $serviceCommissionPercentage / 100) * $value;
						$subtotal = number_format((float)$subtotal * $value, 2, '.', '');
					}
					//calculate ticket cost to reverse transfer from partner package payments
					$ticketCost = $subtotal - $partnerFees;
					//Check partial amount is less than ticket cost for partner package

					$total = $subtotal;
					$totalFees = $feeSize;

					$bt = $this->bookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $key)->where('deleted_by', 0)->first();

					$setTotal = $bt->total - $total;
					$setTourist = ($bt->is_infant_rate != 1) ? $bt->tourists - $value : $bt->tourists;
					$setInfant = ($bt->is_infant_rate == 1) ? $bt->infants - $value : $bt->infants;

					$totalFeeAmount = 0;
					if (!empty($transaction) && ($transaction->via == "Card" || ($isCashFees == '1' && $transaction->via == 'Cash'))) {
						$totalFeeAmount = $totalFees;
					}

					$totalFeeAmount = roundout((float)$totalFeeAmount, 2);

					$setFeeAmount = 0;
					$partnerFeesAmount = 0;
					if ($transaction) {
						$setFeeAmount = $tourBooking->service_commission - (float)$totalFeeAmount;
						$setFeeAmount = number_format((float)$setFeeAmount, 2, '.', '');
					}

					DB::beginTransaction();
					if ($setTourist == 0 && $setInfant == 0) {
						$this->bookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $key)->where('deleted_by', 0)
							->update([
								'total' => $setTotal,
								'tourists' => $setTourist,
								'infants' => $setInfant,
								'check_in_status' => '',
								'redeem_ticket' => null,
								'refund_permitfee_status' => ''
							]);
					} else {
						$this->bookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $key)->where('deleted_by', 0)
							->update([
								'total' => $setTotal,
								'tourists' => $setTourist,
								'infants' => $setInfant
							]);
					}

					// Scale to paid-pax-only for the master total update.
					// cancelPendingChangePeopleItems will separately reverse the unpaid-pax
					// contribution from total, booking_total, and service_commission.
					$masterTotalDelta = $total;
					$masterFeesDelta  = roundout((float)$totalFees, 2);
					if (
						!in_array($request->refund_Type, ['dont_refund', 'partial_refund', 'fareharbor']) &&
						isset($unpaidPaxCount) && $unpaidPaxCount > 0 && (int)$value > 0
					) {
						$paidFrac = $paidPaxValue / (int)$value;
						$masterTotalDelta = round($total * $paidFrac, 2);
						$masterFeesDelta  = round($totalFees * $paidFrac, 2);
					}

					if (!empty($transaction)) {

						$tourBookingSetTotal = $tourBooking->total - $masterTotalDelta;
						$tourBookingSetTourist = ($bt->is_infant_rate != 1) ? $tourBooking->tourists - $value : $tourBooking->tourists;
						$tourBookingSetInfant = ($bt->is_infant_rate == 1) ? $tourBooking->infants - $value : $tourBooking->infants;
						if (($transaction->via == "Card" || ($isCashFees == '1' && $transaction->via == 'Cash')) && $request->refund_Type != "fareharbor") {
							$setFeeAmount = $totalFees;
							$setFeeAmount = roundout((float)$setFeeAmount, 2);
							$setFeeAmount = (float)$setFeeAmount;
							if ($request->refund_Type == "dont_refund") {

								$tourBookingSetTotal = $tourBooking->total - ($masterTotalDelta + $masterFeesDelta);

								$permitFeeUpdate = ($tourBookingSetTotal * $stripe_fees_percentage) / 100;
								$permitFeeUpdate = number_format((float)$permitFeeUpdate, 2, '.', '');

								if ($transK->payment_type == 1) {
									$tourBooking->update([
										'booking_total' => $tourBookingSetTotal,
										'service_commission' => $permitFeeUpdate,
									]);
									DB::commit();
								}
							}

							if ($request->refund_Type == "100_refund") {
								// Ticket cost + fees both refunded back to customer — reduce total by paid-pax-only amount
								$tourBookingSetTotal = $tourBooking->total - ($masterTotalDelta + $masterFeesDelta);
							}

							if ($request->refund_Type == "full_refund") {
								// Fees are kept (not refunded) — reduce total by paid-pax ticket cost only
								$tourBookingSetTotal = $tourBooking->total - $masterTotalDelta;
							}

							$tourBookingSetTotal = number_format((float)$tourBookingSetTotal, 2, '.', '');
							if ($request->refund_Type != "partial_refund") {
								$masterUpdateData = [
									'total'    => $tourBookingSetTotal,
									'tourists' => $tourBookingSetTourist,
									'infants'  => $tourBookingSetInfant,
								];
								// For 100% refund the fees go back to the customer, so remove paid-pax fees from service_commission
								if ($request->refund_Type == "100_refund") {
									$masterUpdateData['service_commission'] = max(0, round($tourBooking->service_commission - $masterFeesDelta, 2));
								}
								$tourBooking->update($masterUpdateData);
								DB::commit();
							}
						} else {
							if ($request->refund_Type != "partial_refund") {
								$tourBooking->update([
									'total'    => $tourBookingSetTotal,
									'tourists' => $tourBookingSetTourist,
									'infants'  => $tourBookingSetInfant
								]);
								DB::commit();
							}
						}
					} else {
						// booking_total holds the original booking amount and must not change.
						if (isset($request->payment_type) && $request->payment_type === 'Card') {
							$tourBookingSetTotal = $tourBooking->total - ($masterTotalDelta + $masterFeesDelta);
						} else {
							$tourBookingSetTotal = $tourBooking->total - $masterTotalDelta;
						}
						$tourBookingTotalForPayLater += $total;
						$tourBookingSetTourist = ($bt->is_infant_rate != 1) ? $tourBooking->tourists - $value : $tourBooking->tourists;
						$tourBookingSetInfant = ($bt->is_infant_rate == 1) ? $tourBooking->infants - $value : $tourBooking->infants;
						if ($request->refund_Type != "partial_refund") {
							$tourBooking->update([
								'total'    => $tourBookingSetTotal,
								'tourists' => $tourBookingSetTourist,
								'infants'  => $tourBookingSetInfant
							]);
							DB::commit();
						}
					}

					// Scale $total/$totalFees/$ticketCost to paid-pax-only for Stripe refund operations below.
					if (
						!in_array($request->refund_Type, ['dont_refund', 'partial_refund', 'fareharbor']) &&
						isset($unpaidPaxCount) && $unpaidPaxCount > 0 && (int)$value > 0
					) {
						$paidFraction = $paidPaxValue / (int)$value;
						$total        = round((float)$total * $paidFraction, 2);
						$totalFees    = round((float)$totalFees * $paidFraction, 2);
						$ticketCost   = round((float)$ticketCost * $paidFraction, 2);
					}

					// No tour payment yet (e.g. a soft block or unpaid Card booking) means there is no
					// charge to refund or transfer to reverse, unless a specific transaction was picked.
					$hasCheckedTransaction = $request->has('checked_transactions') && $request->checked_transactions != '';
					if ($request->payment_type == 'Card' && $request->refund_Type != "fareharbor" && ($request->is_cash == '') && (!empty($transaction) || $hasCheckedTransaction)) {
						//Fetching transaction id for transfer reversal in stripe
						if ($hasCheckedTransaction) {
							$checkedTrans = $this->transaction::where('tour_booking_id', $request->bookingID)->where('transaction_number', $request->checked_transactions)->where('status', 'Completed')->first(['id']);
							$transId = $checkedTrans->id;
						} else {
							$transId = $transaction->id;
						}
						//Reverse transfer for partner package (ticket cost)
						if ($isPartnerBooking == 1 && $ticketCost > 0 && $request->refund_Type != "dont_refund" && $request->refund_Type != "partial_refund") {
							ThreeWayPaymentService::reverseTransfer($request->bookingID, $transId, $ticketCost);
						}
						if ($request->refund_Type == "full_refund" && ($total > 0)) {
							if ($request->has('checked_transactions') && $request->checked_transactions != '') {
								// Same balance-sufficiency guard the 100_refund branch below already
								// applies -- without it, a Ticket Refund pointed at an insufficiently
								// funded transaction (e.g. a small add-ons-only PaymentIntent selected
								// by mistake) sent the full ticket amount to Stripe with no local check
								// at all, relying purely on Stripe itself to reject the over-refund --
								// which this code has no guarantee of (gateway/API-version dependent),
								// and even when Stripe does reject it, that happens AFTER the tour
								// booking's tourist count/total have already been updated and committed
								// above, leaving pax removed with no refund at all. Fail loudly first.
								$refundTransForValidation = $this->transaction::where('tour_booking_id', $request->bookingID)
									->where('transaction_number', $request->checked_transactions)
									->where('status', 'Refund')
									->where(function ($query) {
										$query->whereNull('charge_type')->orWhere('charge_type', 'addons');
									})
									->get(['id', 'amount']);
								$paymentTransForValidation = $this->transaction::where('tour_booking_id', $request->bookingID)
									->where('transaction_number', $request->checked_transactions)
									->where('status', 'Completed')
									->where(function ($query) {
										$query->whereNull('charge_type')->orWhere('charge_type', 'addons');
									})
									->first(['id', 'amount', 'payment_mode']);
								$totalRefundedForValidation = 0;
								foreach ($refundTransForValidation as $val) {
									$totalRefundedForValidation += $val->amount;
								}
								$availableOnSelectedTransaction = ($paymentTransForValidation->amount ?? 0) - $totalRefundedForValidation;
								if (round($availableOnSelectedTransaction - $total, 2) < -0.01) {
									$message = 'Unable to refund booking. For the chosen transaction, the refund amount is greater than the unrefunded amount. Please choose another transaction.';
									if (isset($request->api) && $request->api == 1) {
										throw new Exception($message);
									} else {
										return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
									}
								}
								$refundParams = [
									'payment_intent' => $request->checked_transactions,
									'amount' => $total * 100,
									'reverse_transfer' => true,
								];
								app(PaymentGatewayInterface::class)->refundPayment($refundParams, $paymentTransForValidation->payment_mode);
							} else {
								$refundParams = [
									'payment_intent' => $transaction->transaction_number,
									'amount' => $total * 100,
									'reverse_transfer' => true,
								];
								app(PaymentGatewayInterface::class)->refundPayment($refundParams, $transaction->payment_mode);
							}
							DB::commit();
						}
						if ($request->refund_Type == "100_refund" && ($total > 0)) {
							$setFeeAmount = $totalFees;
							$refund100 = $total + $setFeeAmount;
							$refund100 = round($refund100, 2);


							$setFeeAmount = round($setFeeAmount, 2);
							if ($request->has('checked_transactions') && $request->checked_transactions != '') {
								$refundTrans = $this->transaction::where('tour_booking_id', $request->bookingID)
									->where('transaction_number', $request->checked_transactions)
									->where('status', 'Refund')
									->where(function ($query) {
										$query->whereNull('charge_type')
											->orWhere('charge_type', 'discount')
											->orWhere('charge_type', 'addons');
									})
									->get(['id', 'amount']);

								$paymentTrans = $this->transaction::where('tour_booking_id', $request->bookingID)
									->where('transaction_number', $request->checked_transactions)
									->where('status', 'Completed')
									->where(function ($query) {
										$query->whereNull('charge_type')
											->orWhere('charge_type', 'discount')
											->orWhere('charge_type', 'addons');
									})
									->first(['id', 'amount', 'payment_mode']);

								$totalrefundedamount = 0;
								foreach ($refundTrans as $ky => $val) {
									$totalrefundedamount += $val->amount;
								}

								$rounded = round($paymentTrans->amount - $totalrefundedamount - $refund100, 2);
								if ($rounded <= -0.01) {
									// The selected transaction (checked_transactions) doesn't have enough
									// remaining balance to cover this 100%-refund — this used to silently
									// shrink the actual Stripe refund to whatever balance was left on that
									// PaymentIntent (draining it, e.g. an add-ons-only PI picked by mistake
									// for the tour refund) while the history/ledger below still recorded the
									// FULL originally-requested $total, so the system believed more was
									// refunded than Stripe ever actually returned to the customer — and
									// because that PaymentIntent was now drained, the add-ons refund
									// further below (which targets this same transaction) silently had
									// nothing left to draw from either, with no error and no history entry.
									// Fail loudly instead — same message/convention the upfront
									// $paymentTransCountForBooking > 1 balance check above already uses, in
									// case that check doesn't end up catching this first.
									$message = 'Unable to refund booking. For the chosen transaction, the refund amount is greater than the unrefunded amount. Please choose another transaction.';
									if (isset($request->api) && $request->api == 1) {
										throw new Exception($message);
									} else {
										return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
									}
								} else {
									$refundParams = [
										'payment_intent' => $request->checked_transactions,
										'amount' => $refund100 * 100,
										'reverse_transfer' => true,
										'refund_application_fee' => true,
									];
									app(PaymentGatewayInterface::class)->refundPayment($refundParams, $paymentTrans->payment_mode);
									DB::commit();
								}
							} else {
								$refundParams = [
									'payment_intent' => $transaction->transaction_number,
									'amount' => $refund100 * 100,
									'reverse_transfer' => true,
									'refund_application_fee' => true,
								];
								app(PaymentGatewayInterface::class)->refundPayment($refundParams, $transaction->payment_mode);

								DB::commit();
							}
						}
					}

					$deletedPeople = $value;
					if ($request->refund_Type == "dont_refund") {
						if (($request->payment_type == 'Card' || ($isCashFees == '1' && $request->payment_type == 'Cash')) && $request->refund_Type != "fareharbor") {
							$feeAmount = 0;
							if ($request->bookingID < $oldBookingID) {
								if ($customer->is_affiliate === "No") {
									$feeAmount = ($total * 6) / 100;
								}
							} else {
								$feeAmount = ($total * $serviceCommissionPercentage) / 100;
							}

							$feeAmount = number_format((float)$feeAmount, 2, '.', '');
							$total = $total + $feeAmount;
							$refundKeepUs = $total;
						} else {
							$refundKeepUs = $total;
						}
						$refundPartnerFeesKeepUs = $partnerFees;
						// Nothing paid yet: the removed pax were never charged, so nothing is kept.
						if (empty($transaction)) {
							$total = 0;
							$refundKeepUs = 0;
							$refundPartnerFeesKeepUs = 0;
						}
						// Unpaid pax were never charged — NAT keeps nothing for them.
						// Scale refundKeepUs to the paid-pax fraction only.
						if (isset($unpaidPaxCount) && $unpaidPaxCount > 0 && (int)$value > 0) {
							$paidFrac     = $paidPaxValue / (int)$value;
							$refundKeepUs = round($refundKeepUs * $paidFrac, 2);
						}

						// $fee_amount = 0;
						$refundType = "Don't Refund";
					}

					if ($request->refund_Type == "partial_refund") {
						//Below line is to check ticket cost is less than partial refund amount for partner package
						if (!empty($transaction) && $isPartnerBooking == 1 && $request->refund_Type == "partial_refund" && $request->partial_Refund_value != "NaN") {

							//Below line is to check ticket cost is less than partial refund amount for partner package
							if ($request->partial_Refund_value < $totalTicketCost) {
								$total = $subtotal - $partnerFees;
								$ticketCost = $total;
							} else {
								$total = $subtotal;
								$partnerFeesRefundForPartialRefund += $partnerFees;
							}
						}
						if (($request->payment_type == 'Card' || ($isCashFees == '1' && $request->payment_type == 'Cash')) && $request->refund_Type != "fareharbor") {
							$feeAmount = 0;
							if ($request->bookingID < $oldBookingID) {
								if ($customer->is_affiliate === "No") {
									$feeAmount = ($total * 6) / 100;
								}
							} else {
								$feeAmount = ($total * $serviceCommissionPercentage) / 100;
							}

							$feeAmount = number_format((float)$feeAmount, 2, '.', '');
							$total = $total + $feeAmount;
							$refundKeepUs = $total - (float)$request->partial_Refund_value;
							$refundKeepUs = number_format((float)$refundKeepUs, 2, '.', '');
							$feeAmount = 0;
						} else {
							$refundKeepUs = $total - (float)$request->partial_Refund_value;
							$refundKeepUs = number_format((float)$refundKeepUs, 2, '.', '');
						}

						if (empty($transaction)) {
							$total = 0;
						}

						$total = number_format((float)$request->partial_Refund_value, 2, '.', '');
						$refundType = "Partial Refund";
					}

					if ($request->refund_Type == "full_refund") {
						if (($request->payment_type == 'Card' || ($isCashFees == '1' && $request->payment_type == 'Cash')) && $request->refund_Type != "fareharbor") {
							$feeAmount = 0;
							if ($request->bookingID < $oldBookingID) {
								if ($customer->is_affiliate === "No") {
									$feeAmount = ($total * 6) / 100;
								}
							} else {
								$feeAmount = ($total * $serviceCommissionPercentage) / 100;
							}

							$feeAmount = number_format((float)$feeAmount, 2, '.', '');
							$refundKeepUs = $feeAmount;
							$feeAmount = 0;
						} else {
							$refundKeepUs = 0;
						}

						if (empty($transaction)) {
							$total = 0;
						}
						$partnerFeesAmount = (!empty($transaction)) ? $partnerFees : 0;
						$refundType = "Full Refund minus Fees";
					}


					if ($request->refund_Type == "fareharbor") {
						$refundKeepUs = $total;
						$refundType = "Fareharbor";
					}

					if ($request->refund_Type == "100_refund") {
						if (($request->payment_type == 'Card' || ($isCashFees == '1' && $request->payment_type == 'Cash')) && $request->refund_Type != "fareharbor") {
							$feeAmount = $totalFees;
							$feeAmount = roundout($feeAmount, 2);
							$total = $total + $feeAmount;
							$refundKeepUs = 0;
						} else {
							$refundKeepUs = 0;
						}

						if (empty($transaction)) {
							$total = 0;
						}

						$partnerFeesAmount = (!empty($transaction)) ? $partnerFees : 0;
						$refundType = "100 % Refund";
					}


					if (isset($request->is_cash) && $request->is_cash != '') {
						if ($request->is_cash == 'Cash') {
							$refundVia = 'Cash';
						} elseif ($request->is_cash == 'Wire Transfer') {
							$refundVia = 'Check/Wire';
						}
					} else {
						$refundVia = $request->payment_type;
					}

					$data = [
						'amount' => $total,
						'refund_keep_us' => $refundKeepUs,
						'payment_type' => $refundVia,
						'deleted' => $rateCheckname->rate_for . ' person ' . $value,
						'created_by_with_name' => $createdByWithName,
						'refund_type' => $refundType,
						'comment' => null
					];

					if ($request->refund_Type != "partial_refund") {
						$historyId = HistoryService::storeRefundDataInHistory(
							$request->bookingID,
							$tourBooking->tourists + $tourBooking->infants,
							$createdByWithName,
							$data['comment'],
							$data['refund_type'],
							null, /* $transaction */
							$data['amount'],
							null, /* $cardNumber */
							[], /* $cardsArray */
							[], /* $partialAmountArray */
							$data['payment_type'],
							null, /* $paymentTotal */
							null, /* $refundTotal */
							$data['refund_keep_us'],
							$data['deleted'],
							isset($feeAmount) ? $feeAmount : 0,
							null,
							$partnerFeesAmount,
							$refundPartnerFeesKeepUs ?? 0
						);

						// Remove contacts if booking package has contacts
						if ($packageHasContacts->has_contacts == 1) {
							if (isset($request->contacts) && $request->contacts != null) {
								try {
									PackageHasContactsService::deleteContacts($request->contacts);
								} catch (Exception $ex) {
									Log::error($ex->getMessage());
								}
							}
						}
					}

					$paymentOnly = $this->tourBookingHistory::where('tour_booking_id', $request->bookingID)->where('operation', 'Payment')->get();
					$paymentOnlyCheck = 0;
					foreach ($paymentOnly as $value) {
						$details = json_decode($value->details);
						$paymentOnlyCheck += $details->amount;
					}

					$bok = round($tourBooking->booking_total);
					$pay = round($paymentOnlyCheck);
					$firstTransaction = $this->transaction::where('tour_booking_id', $request->bookingID)->where('status', 'Completed')->whereNull('charge_type')->orderBy('id', 'DESC')->first();
					if (!empty($transaction) && $request->payment_type == 'Card' && $request->refund_Type != "fareharbor" && $request->refund_Type != "partial_refund") {
						if (isset($request->is_cash) && $request->is_cash != '') {
							if ($request->is_cash == 'Cash') {
								$refundVia = 'Cash';
							} elseif ($request->is_cash == 'Wire Transfer') {
								$refundVia = 'Check/Wire';
							}
						} else {
							$refundVia = $request->payment_type;
						}

						if ($firstTransaction->payment_type == 0) {
							if ($request->has('checked_transactions') && $request->checked_transactions != '') {
								$selectedTransaction = $this->transaction::where('tour_booking_id', $request->bookingID)->where('transaction_number', $request->checked_transactions)->where('status', 'Completed')->where(function ($query) {
									$query->whereNull('charge_type')->orWhere('charge_type', 'addons');
								})->first();
								$refundAmount = $request->refund_Type == "dont_refund" ? 0.00 : $total;
								$refundFeesAmount = $request->refund_Type == "100_refund" ? round($totalFees, 2) : 0.00;
								// $refundVia is 'Cash'/'Check/Wire' when is_cash overrode a Card
								// booking to a manual reimbursement — no real Stripe operation backs
								// this refund row, so it must not carry a real PaymentIntent/fee id
								// (same "no transaction_number for a non-Card refund" rule the Partial
								// Refund branch below already applies).
								$refundTransId = TransactionService::storeRefundInTransaction($request->bookingID, $refundAmount, $refundFeesAmount, $refundVia, ($refundVia == "Card") ? $selectedTransaction->transaction_number : null, ($refundVia == "Card") ? $selectedTransaction->application_fee_id : null, mode: $selectedTransaction->payment_mode);
							} else {
								$refundAmount = $request->refund_Type == "dont_refund" ? 0.00 : $total;
								$refundFeesAmount = $request->refund_Type == "100_refund" ? round($totalFees, 2) : 0.00;
								$refundTransId = TransactionService::storeRefundInTransaction($request->bookingID, $refundAmount, $refundFeesAmount, $refundVia, ($refundVia == "Card") ? $firstTransaction->transaction_number : null, ($refundVia == "Card") ? $firstTransaction->application_fee_id : null, mode: $firstTransaction->payment_mode);
							}
							//Store reverse transfer in payout for partner package
							if ($isPartnerBooking == 1 && $ticketCost > 0  && $request->refund_Type != "dont_refund") {
								$transactionId = ($request->has('checked_transactions') && $request->checked_transactions != '') ? $selectedTransaction->id :  $firstTransaction->id;
								ThreeWayPaymentService::storeReverseTransferInPayout($request->bookingID, $transactionId, $refundTransId ?? null, $ticketCost, $partnerFeesAmount);
							}
						}

						if ($pay >= $bok) {
							$firstTransaction->payment_type = 0;
							$firstTransaction->save();
						}
					} elseif (!empty($transaction) && $request->payment_type == 'Cash' && $request->refund_Type != "partial_refund") {
						if (isset($request->is_cash) && $request->is_cash != '') {
							if ($request->is_cash == 'Cash') {
								$refundVia = 'Cash';
							} elseif ($request->is_cash == 'Wire Transfer') {
								$refundVia = 'Check/Wire';
							}
						} else {
							$refundVia = $request->payment_type;
						}
						$refundAmount = $request->refund_Type == "dont_refund" ? 0.00 : $total;
						if ($isCashFees == '1') {
							$refundFeesAmount = $request->refund_Type == "dont_refund" ? 0.00 : round($total * $tourBookingTransaction->stripe_fees_percentage / 100, 2);
						} else {
							$refundFeesAmount = 0;
						}

						$refundTransId = TransactionService::storeRefundInTransaction($request->bookingID, $refundAmount, $refundFeesAmount, $refundVia, null, null);

						//Store reverse transfer in payout for partner package
						if ($isPartnerBooking == 1 && $ticketCost > 0 && $request->refund_Type != "dont_refund") {
							ThreeWayPaymentService::storeReverseTransferInPayout($request->bookingID, $firstTransaction->id, $refundTransId ?? null, $ticketCost, $partnerFeesAmount);
						}

						DB::commit();
					} elseif (!empty($transaction) && $request->refund_Type == "fareharbor" && $request->refund_Type != "partial_refund") {
						if (isset($request->is_cash) && $request->is_cash != '') {
							if ($request->is_cash == 'Cash') {
								$refundVia = 'Cash';
							} elseif ($request->is_cash == 'Wire Transfer') {
								$refundVia = 'Check/Wire';
							}
						} else {
							$refundVia = $request->payment_type;
						}
						$refundAmount = $request->refund_Type == "dont_refund" ? 0.00 : $total;
						$refundTransId = TransactionService::storeRefundInTransaction($request->bookingID, $refundAmount, 0, $refundVia, null, null, mode: $transaction->payment_mode);
						DB::commit();
					} elseif (!empty($transaction) && $request->refund_Type != "partial_refund") {
						// Handle third-party platforms (TripAdvisor, GetYourGuide, Headout, etc.)
						if (isset($request->is_cash) && $request->is_cash != '') {
							if ($request->is_cash == 'Cash') {
								$refundVia = 'Cash';
							} elseif ($request->is_cash == 'Wire Transfer') {
								$refundVia = 'Check/Wire';
							}
						} else {
							$refundVia = $request->payment_type;
						}
						$refundAmount = $request->refund_Type == "dont_refund" ? 0.00 : $total;
						$refundTransId = TransactionService::storeRefundInTransaction($request->bookingID, $refundAmount, 0, $refundVia, null, null, mode: $transaction->payment_mode);
						DB::commit();
					}

					// Below line is for to update tour booking history table
					if ($request->refund_Type != "partial_refund") {
						$this->handleDeletePersonHistoryUpdateJobs($tourBooking, $historyId, $request->all(), $refundVia, $refundTransId ?? null);

						// Remove pax-addons if exists for the booking and selected from edit booking
						// delete people. Runs AFTER the tour-side refund transaction is stored above
						// (not before it, as previously) so the `transactions` table always records
						// the pax refund first and the add-ons refund second — matching the order
						// the Change People feature already uses.
						//
						// Also runs when neither request field is filled but this rate group actually
						// had people checked for deletion ($checkarrays[$key]) — a Pay Later / no-
						// transaction booking never renders the "Update Booking" modal's add-ons block
						// at all (it's gated on an existing $trans in _update-booking-modal.blade.php),
						// so delete_booking_addon_scope_ids is never submitted for it. Without this
						// fallback the removed pax's own add-on field rows silently survive the delete.
						if ($request->filled('pax_addons_ids') || $request->filled('delete_booking_addon_scope_ids') || !empty($checkarrays[$key])) {
							try {
								$addonRefundType = match ($request->refund_Type ?? 'dont_refund') {
									'full_refund'    => Constants::ADDONS_TICKET_REFUND,
									'100_refund'     => Constants::ADDONS_FULL_REFUND,
									default          => Constants::ADDONS_DONT_REFUND,
								};
								// Admin's per-add-on refund selection from the "Update Booking" modal
								// (null when not submitted — deletePaxAddons() then refunds every
								// field in scope, matching pre-existing behavior).
								$selectedAddonFieldIds = null;
								if ($request->has('selected_addon_field_ids') && $request->selected_addon_field_ids !== null) {
									$decoded = is_array($request->selected_addon_field_ids)
										? $request->selected_addon_field_ids
										: json_decode($request->selected_addon_field_ids, true);
									$selectedAddonFieldIds = array_map('intval', $decoded ?? []);
								}
								// The direct "Edit Booking" delete flow no longer routes through the
								// "Passenger Add-ons" selection modal — the "Update Booking" modal's
								// own add-ons block already knows the exact field ids in scope for
								// the person(s) checked for deletion (same position-derivation it
								// displays with), so it submits them directly here instead.
								//
								// This whole block sits inside the per-rate-group `foreach ($array as
								// $key => $value)` loop — $request->delete_booking_addon_scope_ids is
								// the FULL submitted list across every rate group being deleted from,
								// so it must be narrowed to just THIS iteration's rate group
								// (tour_bookings_transact.id === tour_booking_addon_fields.pax_id,
								// via $rateCheck above). Without this, the first rate group processed
								// would refund every group's add-ons at once (later iterations become
								// no-ops since those fields are already soft-deleted by then) — the
								// history would then show both add-on refunds bunched next to the
								// FIRST rate group's tour refund instead of each rate group's own tour
								// refund being immediately followed by its own add-ons refund.
								$explicitFieldIds = null;
								if ($request->filled('delete_booking_addon_scope_ids')) {
									$decodedScope = json_decode($request->delete_booking_addon_scope_ids, true);
									$submittedFieldIds = array_map('intval', $decodedScope ?? []);
									$explicitFieldIds = empty($submittedFieldIds) ? [] : TourBookingAddonField::whereIn('id', $submittedFieldIds)
										->where('pax_id', $rateCheck->id)
										->pluck('id')
										->all();
								} elseif (!$request->filled('pax_addons_ids') && !empty($checkarrays[$key])) {
									// No scope submitted at all (Pay Later — see comment above) — resolve
									// this rate group's removed pax's own add-on fields straight from the
									// DB using the exact person-position(s) actually checked for deletion.
									// tour_booking_addon_fields.pax_index is an OPAQUE string (not simply
									// "0"/"1" matching .ads_Checkbox's position), so position -> real
									// pax_index must be resolved the same way getIndividualPaxAddons() does
									// — see resolveFieldIdsByPaxPositions()'s own docblock.
									$explicitFieldIds = $this->tourBookingAddonRepository->resolveFieldIdsByPaxPositions(
										$rateCheck->id,
										array_map('intval', $checkarrays[$key])
									);
								}
								// Admin's explicit "Tour Transaction" pick (checked_transactions) should draw
								// BOTH the tour refund and every removed add-on's refund from that ONE
								// PaymentIntent, not each add-on's own historical origin PI.
								$targetTransactionNumber = ($request->has('checked_transactions') && $request->checked_transactions != '') ? $request->checked_transactions : null;
								// Same "reimburse by hand instead of a real Stripe refund" override the
								// tour-side refund above already applies — a Card-paid booking's add-on
								// must follow the SAME Cash/Check-Wire choice, not always refund to the card.
								$addonManualRefundVia = null;
								if (isset($request->is_cash) && $request->is_cash != '') {
									if ($request->is_cash == 'Cash') {
										$addonManualRefundVia = 'Cash';
									} elseif ($request->is_cash == 'Wire Transfer') {
										$addonManualRefundVia = 'Check/Wire';
									}
								}
								$this->tourBookingAddonRepository->deletePaxAddons($request->bookingID, $request->pax_addons_ids ?? '[]', $addonRefundType, null, $selectedAddonFieldIds, $explicitFieldIds, $targetTransactionNumber, $addonManualRefundVia);
							} catch (Exception $ex) {
								Log::error($ex->getMessage());
							}
						}
					}
				}

				// Cancel pending payment-link items for removed unpaid pax.
				// For dont_refund / fareharbor the loop above already applied the full pax cost
				// (paid + unpaid) to tour_bookings_master.total, so skip the total decrement here
				// to avoid double-counting. booking_total is always corrected here (4th arg false)
				// because the no-transaction loop above never touches it, for any refund_Type.
				$skipTotalForCancel = in_array($request->refund_Type ?? '', ['dont_refund', 'fareharbor']);
				PaymentLinkService::cancelPendingChangePeopleItems(
					$request->filled('pending_item_ids') ? $request->pending_item_ids : null,
					$request->filled('pending_history_ids') ? $request->pending_history_ids : null,
					$skipTotalForCancel,
					false
				);
				// Also cancel any pending addon payment-link items for the same booking.
				PaymentLinkService::cancelPendingAddonLinkItemsForBooking((int) $request->bookingID);

				// Partial Refund edit booking
				if ($request->refund_Type == "partial_refund") {
					$tourBooking = $this->tourBooking::find($request->bookingID);

					if ($request->has('checked_transactions') && $request->checked_transactions != '') {
						$transac = $this->transaction::where('tour_booking_id', $request->bookingID)->where('transaction_number', $request->checked_transactions)->where('status', 'Completed')->where(function ($query) {
							$query->whereNull('charge_type')->orWhere('charge_type', 'addons');
						})->first();
					} else {
						$transac = $this->transaction::where('tour_booking_id', $request->bookingID)->where('status', 'Completed')->whereNull('charge_type')->first();
					}

					if ($request->partial_Refund_value == "NaN") {
						$message = 'Please enter partial refund amount.';
						if (isset($request->api) && $request->api == 1) {
							throw new Exception($message);
						} else {
							return BookingService::refundRouteWithError($request->bookingID, $modalUrl, $message);
						}
					}
					$transactionFirst = $this->transaction::where('tour_booking_id', $request->bookingID)->whereNull('charge_type')->first();
					$refundAmountFromConnectedAccountForTrans = 0;

					// Everything below is Stripe-facing and was previously unguarded — a null $transac
					// (e.g. the admin picked an "Add-ons only" PaymentIntent as the Tour Transaction, or
					// the lookup above simply found no match) or a gateway error (amount too large for
					// that specific PI, etc.) used to throw straight out of editBooking() uncaught. That
					// aborted the request before ever reaching the tour-total update/addon-removal code
					// further down, so the pax's add-ons (and the tour total itself) silently never got
					// touched even though the admin saw the delete submit with no visible error — a plain
					// synchronous form POST doesn't surface a raw JSON 500 the way an AJAX call would.
					// Catch and log here instead, matching the same "log and keep going" convention this
					// function already uses for deletePaxAddons()/deleteContacts() below.
					if ($refundVia == "Card") {
						try {
							if (empty($transac)) {
								throw new Exception('Unable to locate the selected payment transaction to refund.');
							}
							$netPartnerAmountsForTrans = ($isPartnerBooking == 1) ? ThreeWayPaymentService::getNetPartnerAmountsForTransaction($request->bookingID, $transac->transaction_number) : 0;  //Get net ticket cost without partner fees
							$netTicketCostForTrans = $netPartnerAmountsForTrans['netTicketCost'] ?? 0;

							//Below line is for to check if the partial refund value is greater than net ticket cost and refund from partner fees amount for selected transaction
							$refundAmountFromConnectedAccountForTrans = 0;
							if ($isPartnerBooking == 1 && $netTicketCostForTrans > 0) {
								if ($netTicketCostForTrans < $request->partial_Refund_value) {
									$refundAmountFromConnectedAccountForTrans = $netTicketCostForTrans;
								} else {
									$refundAmountFromConnectedAccountForTrans = $request->partial_Refund_value;
								}
							}
							if ($request->partial_Refund_value > 0) {
								//Reverse transfer for partner package (ticket cost)
								if ($isPartnerBooking == 1 && $refundAmountFromConnectedAccountForTrans > 0) {
									ThreeWayPaymentService::reverseTransfer($request->bookingID, $transac->id, $refundAmountFromConnectedAccountForTrans);
								}
								$refundParams = [
									'payment_intent' => $transac->transaction_number,
									'amount' => $request->partial_Refund_value * 100,
									'reverse_transfer' => true,
									'refund_application_fee' => true
								];
								app(PaymentGatewayInterface::class)->refundPayment($refundParams, $transac->payment_mode);
							}
						} catch (Exception $ex) {
							Log::error('Partial refund Stripe call failed for booking ' . $request->bookingID . ': ' . $ex->getMessage());
						}
					}

					$btp = $this->bookingTransact::where('tour_booking_id', $request->bookingID)->where('deleted_by', 0)->get();

					$tcount = 0;
					$infantCount = 0;
					foreach ($btp as $value) {
						$tcount += $value->tourists;
						$infantCount += $value->infants;
					}

					if (!empty($transactionFirst)) {
						$ptotal = $tourBooking->total - $request->partial_Refund_value;
						$tourBooking->update([
							'total' => $ptotal,
							'tourists' => $tcount,
							'infants' => $infantCount
						]);
					} else {
						$tourBooking->update([
							'total' => $tourBooking->total - $tourBookingTotalForPayLater,
							'booking_total' => $tourBooking->booking_total - $tourBookingTotalForPayLater,
							'tourists' => $tcount,
							'infants' => $infantCount
						]);
					}
					DB::commit();
					if (!empty($transactionFirst)) {
						$partialValue = $request->partial_Refund_value;
					} else {
						$partialValue = 0;
						$refundKeepUs = 0;
					}

					$data = [
						'amount' => $partialValue,
						'refund_keep_us' => $refundKeepUs,
						'payment_type' => $refundVia,
						'deleted' => $rateChecknameForPartialRefund,
						'created_by_with_name' => $createdByWithName,
						'refund_type' => $refundType,
						'comment' => null
					];

					$historyId = HistoryService::storeRefundDataInHistory(
						$request->bookingID,
						$tcount + $infantCount,
						$createdByWithName,
						$data['comment'],
						$data['refund_type'],
						null, /* $transaction */
						$data['amount'],
						null, /* $cardNumber */
						[], /* $cardsArray */
						[], /* $partialAmountArray */
						$data['payment_type'],
						null, /* $paymentTotal */
						null, /* $refundTotal */
						$data['refund_keep_us'],
						$data['deleted'],
						0,
						null,
						$partnerFeesRefundForPartialRefund
					);

					// Remove contacts if booking package has contacts
					if ($packageHasContacts->has_contacts == 1) {
						if (isset($request->contacts) && $request->contacts != null) {
							try {
								PackageHasContactsService::deleteContacts($request->contacts);
							} catch (Exception $ex) {
								Log::error($ex->getMessage());
							}
						}
					}

					if (!empty($transactionFirst)) {
						$refundAmount = $request->partial_Refund_value;
						$refundTransId = TransactionService::storeRefundInTransaction($request->bookingID, $refundAmount, 0, $refundVia, ($refundVia == "Card") ? $transac->transaction_number : null, null, mode: ($refundVia == "Card") ? $transac->payment_mode : PaymentModeResolver::DESTINATION);
						if ($refundVia != "Card") {
							$refundAmountFromConnectedAccountForTrans = $refundAmount;
						}
						//Store reverse transfer in payout for partner package
						if ($isPartnerBooking == 1 && $refundAmountFromConnectedAccountForTrans > 0) {
							ThreeWayPaymentService::storeReverseTransferInPayout($request->bookingID, $transac->id, $refundTransId ?? null, $refundAmountFromConnectedAccountForTrans, $partnerFeesRefundForPartialRefund, 'partial_refund');
						}
						$this->handleDeletePersonHistoryUpdateJobs($tourBooking, $historyId, $request->all(), $refundVia, $refundTransId ?? null);
					}

					// Remove pax-addons if exists for the booking and selected from edit booking
					// delete people. Runs AFTER the tour-side refund transaction is stored above (not
					// before it, as previously) so the `transactions` table always records the pax
					// refund first and the add-ons refund second — matching the order the Change
					// People feature already uses.
					//
					// Also runs when neither request field is filled but this rate group actually had
					// people checked for deletion ($checkarrays[$key]) — see the same fallback and its
					// full explanation in the non-partial-refund branch above (Pay Later / no-
					// transaction bookings never render the "Update Booking" modal's add-ons block, so
					// delete_booking_addon_scope_ids is never submitted for them).
					if ($request->filled('pax_addons_ids') || $request->filled('delete_booking_addon_scope_ids') || !empty($checkarrays[$key])) {
						try {
							// Admin's per-add-on refund selection from the "Update Booking" modal
							// (null when not submitted — deletePaxAddons() then refunds every field
							// in scope, matching pre-existing behavior).
							$selectedAddonFieldIds = null;
							if ($request->has('selected_addon_field_ids') && !empty($request->selected_addon_field_ids)) {
								$decoded = is_array($request->selected_addon_field_ids)
									? $request->selected_addon_field_ids
									: json_decode($request->selected_addon_field_ids, true);
								$selectedAddonFieldIds = array_map('intval', $decoded ?? []);
							}
							// See the "dont_refund" branch above — the direct delete flow now
							// submits explicit field ids instead of routing through the
							// "Passenger Add-ons" modal.
							$explicitFieldIds = null;
							if ($request->filled('delete_booking_addon_scope_ids')) {
								$decodedScope = json_decode($request->delete_booking_addon_scope_ids, true);
								$explicitFieldIds = array_map('intval', $decodedScope ?? []);
							} elseif (!$request->filled('pax_addons_ids') && !empty($checkarrays[$key])) {
								// No scope submitted at all (Pay Later — see comment above) — resolve
								// this rate group's removed pax's own add-on fields straight from the
								// DB using the exact person-position(s) actually checked for deletion —
								// see resolveFieldIdsByPaxPositions()'s own docblock for why a plain
								// pax_index match on the checkbox position doesn't work.
								$explicitFieldIds = $this->tourBookingAddonRepository->resolveFieldIdsByPaxPositions(
									$rateCheck->id,
									array_map('intval', $checkarrays[$key])
								);
							}
							$targetTransactionNumber = ($request->has('checked_transactions') && $request->checked_transactions != '') ? $request->checked_transactions : null;
							// $refundVia was already resolved above (from $request->is_cash, same as
							// the tour-side partial refund just recorded) — reuse it verbatim so a
							// Card-paid booking's add-on follows the SAME manual Cash/Check-Wire choice
							// instead of always refunding to the card.
							$addonManualRefundVia = in_array($refundVia, ['Cash', 'Check/Wire'], true) ? $refundVia : null;
							// Partial Refund only ever moves money on the tour side (the admin's
							// manually-typed amount above) — the "Update Booking" modal disables every
							// add-on checkbox under this refund type and says so explicitly ("Partial
							// refunds only apply to the tour amount — add-ons aren't refunded
							// automatically for this type"). ADDONS_TICKET_REFUND would actually refund
							// the removed pax's add-on price despite that, contradicting the UI. Use
							// ADDONS_DONT_REFUND so the field is still removed/recorded but no money
							// moves — matching every other addon-only-affecting refund type's default.
							$this->tourBookingAddonRepository->deletePaxAddons($request->bookingID, $request->pax_addons_ids ?? '[]', Constants::ADDONS_DONT_REFUND, null, $selectedAddonFieldIds, $explicitFieldIds, $targetTransactionNumber, $addonManualRefundVia);
						} catch (Exception $ex) {
							Log::error($ex->getMessage());
						}
					}
					DB::commit();
				}
			}
			if ($tourBooking->is_group_booking != 1) {
				// Update slot summary
				$seatsDiff = - ($totalDeletedPax);
				TimeSlotAvailabilityService::updateSlotSummary($tourBooking->tour_slot_id, $seatsDiff);
				DB::commit();
			}
			$info = DB::table('tour_slot_times AS tst')
				->join('tour_bookings_master as bm', 'bm.tour_slot_id', '=', 'tst.id')
				->join('tour_slot_dates AS tsd', 'tsd.id', '=', 'tst.tour_slot_id')
				->join('tour_packages AS tp', 'tp.id', '=', 'tsd.tour_package_id')
				->join('tour_operators AS t_o', 't_o.id', '=', 'tp.tour_operator_id')
				->join('cities AS ct', 'ct.id', '=', 't_o.city_id')
				->join('states AS st', 'st.id', '=', 'ct.state_id')
				->where('bm.id', $request->bookingID)
				->select([
					'tst.time_from',
					'tsd.date',
					'tst.time_slot_seats as seats',
					'tp.tour_operator_id',
					'tsd.tour_package_id',
					'tp.name AS package_name',
					'tp.important_notes',
					'tp.things_to_bring',
					'ct.state_id',
					'st.permit_fee',
					't_o.name AS tour_operator',
					't_o.email AS tour_op_email',
					't_o.phone_number AS tour_op_phone',
					't_o.website AS tour_op_website',
					't_o.logo AS tour_op_logo',
					't_o.cancellation_policy',
					'tp.service_commission_percentage',
					'tp.stripe_commission_percentage',
					't_o.tenant_id',
					'bm.name As custname',
					'bm.email As custemail',
					'bm.phone_number As phone_number',
					'tp.email as packageEmail',
					'tp.from_name as packageFromName',
					'tp.from_email as packageFromEmail',
					'tp.api_key as packageApiKey',
					DB::raw("(SELECT SUM(tbm.tourists)
                            FROM tour_bookings_master AS tbm
                            WHERE tbm.tour_slot_id = tst.id
                                AND tbm.status != 'Cancelled'
                            GROUP BY tbm.tour_slot_id) AS booked_seats")
				])->first();

			// Payment link query start — remaining_payment links are managed separately
			$tourBookingPaymentLink = TourBookingPaymentLink::where('order_id', $tourBooking->group_id)
				->where('status', 'Unpaid')
				->where(function ($q) { $q->whereNull('section')->orWhere('section', '!=', 'remaining_payment'); })
				->first();

			if ($tourBookingPaymentLink) {
				$data = [
					'amount' => $tourBookingTotalForPayLater,
					'natFeesPercentage' => $tourBookingTransaction->nat_fees_percentage
				];
				PaymentLinkService::paymentLinkUpdate($data, $info, $tourBooking, $tourBookingPaymentLink, 'Delete People');
			}
			// Payment link query end               

			$deletedPeople = $this->tourBookingHistory::where('tour_booking_id', $request->bookingID)->where('operation', 'Refund')->get();

			//Unassign booking from board station
			BoardService::boardBookingUpdate($tourBooking->id);
			$arEmailData = [
				'tour_d_t' => $info->date . ' ' . $info->time_from,
				'bookingId' => $request->bookingID,
				'custName' => $info->custname,
				'custEmail' => $info->custemail,
				'custPhone' => $info->phone_number ?? '',
				'deletedPeople' => $deletedPeople
			];

			if (in_array(Auth::user()->email, config('constants.prevent_sending_emails')) == false) {
				EmailService::sendPeopleRemovedEmail($info, $arEmailData);
			}

			if (isset($request->api) && $request->api == 1) {
				return [
					'booking_id' => $request->bookingID,
					'message' => 'Booking has been updated' . ($request->refund_Type != "dont_refund" ? ' and refund has been initiated.' : '.')
				];
			} else {
				$message = 'Booking has been updated' . ($request->refund_Type != "dont_refund" ? ' and refund has been initiated.' : '.');
				return BookingService::refundRouteWithSuccess($request->bookingID, $modalUrl, $message);
			}
		} catch (Exception $exception) {
			Log::error($exception);
			DB::rollBack();
			throw new GeneralCoreException($exception);
		}
	}

	/**
	 * Change people in the existing booking
	 *
	 * @param object $request
	 * @return mixed
	 * 
	 * @version 1.0.0
	 */
	public function splitPeopleBooking($request)
	{
		try {
			$tourBooking = $this->tourBooking::find($request->bookingID);
			$isPartnerBooking = $tourBooking->is_partner_booking;
			$check = $request->input('check', []);
			$checkTotalTourist = count($check);
			$isCashFees = cashFees();

			if (count($check) == 0) {
				throw new Exception('You have not selected any checkbox in the action option.');
			}

			if ($tourBooking->tourists + $tourBooking->infants == $checkTotalTourist) {
				throw new Exception("You cannot split all tourists.");
			}

			if ($tourBooking->tourists + $tourBooking->infants < $checkTotalTourist) {
				throw new Exception("Something went wrong.Please try after sometimes.");
			}

			$totalTourists = 0;
			$totalInfants = 0;
			$check = $request->input('check', []);
			$checkPermitfee = $request->input('permitF', []);
			$array = array_count_values($check);

			// Build checkarrays for individual permit fee calculations
			$checkarrays = array();
			foreach ($check as $key => $value) {
				$explode = explode('.', $key);
				$checkarrays[$value][] = $explode[1];
			}

			foreach ($array as $key => $value) {
				$rateCheck = BookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $key)->first();

				// Calculate individual permit fees for people being split
				$totalPermitFeeForRateGroup = 0;
				if ($rateCheck->refund_permitfee_status != '' && isset($checkarrays[$key])) {
					// Get the rate group type from the tour package rate
					$tourPackageRate = TourPackageRate::withTrashed()->find($key);
					$rateGroupType = $tourPackageRate->rate_for;

					// Calculate permit fees individually for each person being split
					foreach ($checkarrays[$key] as $personIndex) {
						$permitKey = $rateGroupType . '.' . $personIndex;
						$currentPermitFee = isset($checkPermitfee[$permitKey]) ? floatval($checkPermitfee[$permitKey]) : $rateCheck->permit_fee;
						$totalPermitFeeForRateGroup += $currentPermitFee;
					}
				} else {
					// No refund status, use original permit fee for all people
					$totalPermitFeeForRateGroup = $rateCheck->permit_fee * $value;
				}

				$averagePermitFee = $totalPermitFeeForRateGroup / $value;
				$subtotal = $rateCheck->rate + $rateCheck->additional_charge + $averagePermitFee + ($isPartnerBooking == 1 ? $rateCheck->partner_fees_amount : 0);

				$isInfantRate = $rateCheck->is_infant_rate;
				if ($isInfantRate == 1) {
					$totalInfants += $value;
				} else {
					$totalTourists += $value;
				}
			}

			//validation for infants only
			if ($totalTourists == 0 && $totalInfants > 0) {
				throw new Exception("You cannot split only infants.");
			}
			//calculate refund value
			$refundOnly = $this->tourBookingHistory::where('tour_booking_id', $request->bookingID)
				->where('operation', 'Refund')
				->where('payment_method', '!=', "Don't Refund")
				->whereNull('charge_type')
				->where('payment_type', '!=', "")
				->get([ 
					'id',
					'details'
				]);

			$refundOnlyCheck = 0;
			foreach ($refundOnly as $value) {
				$details = json_decode($value->details, true);
				$refundOnlyCheck += $details['amount'];
			}

			$trans = $this->transaction::where('tour_booking_id', $request->bookingID)
				->where('status', 'Completed')
				->whereNull('charge_type')
				->orderBy('id', 'DESC')
				->first();

			// Detect all-unpaid split and mixed (paid + unpaid) split.
			$splitIsAllUnpaid    = $request->input('split_is_all_unpaid') === '1';
			$splitPendingItemIds = array_values(array_filter(explode(',', $request->input('split_pending_item_ids', ''))));
			$unpaidCountsRaw     = $request->input('split_unpaid_check_counts', '');
			$unpaidCheckCounts   = !empty($unpaidCountsRaw) ? (json_decode($unpaidCountsRaw, true) ?? []) : [];
			$hasMixedSplit       = !$splitIsAllUnpaid && !empty($splitPendingItemIds) && !empty($unpaidCheckCounts);

			// Build the per-rate unpaid map for use below.
			$unpaidArray = [];
			if ($hasMixedSplit) {
				foreach ($array as $rateId => $count) {
					$uc = (int) ($unpaidCheckCounts[$rateId] ?? 0);
					if ($uc > 0) { $unpaidArray[$rateId] = min($uc, $count); }
				}
			}

			if (!$splitIsAllUnpaid) {
				// For mixed split validate only against the paid pax subtotal so
				// the unpaid portion (never charged) does not cause a false error.
				if ($hasMixedSplit) {
					$paidPaxSubtotal = 0;
					foreach ($array as $rateId => $count) {
						$paidCount = $count - (int) ($unpaidCheckCounts[$rateId] ?? 0);
						if ($paidCount <= 0) continue;
						$rateRow = BookingTransact::where('tour_booking_id', $request->bookingID)
							->where('tour_package_rate_id', $rateId)->first();
						if (!$rateRow) continue;
						$perPerson = $rateRow->rate + $rateRow->additional_charge + $rateRow->permit_fee
							+ ($isPartnerBooking == 1 ? $rateRow->partner_fees_amount : 0);
						$paidPaxSubtotal += $perPerson * $paidCount;
					}
					$calculatedRefund = $paidPaxSubtotal;
				} else {
					$calculatedRefund = $subtotal * $checkTotalTourist;
				}
				$availableAmount = (float) $tourBooking->booking_total - $refundOnlyCheck;
				$tolerance       = 0.01;
				if ($trans && abs($calculatedRefund - $availableAmount) > $tolerance) {
					if ($calculatedRefund > $availableAmount) {
						throw new Exception("The paid amount is too low to split among the selected people.");
					}
				}
			}

			if ($splitIsAllUnpaid) {
				$extendBooking = $this->splitUnpaidPaxBooking($request, $tourBooking);
			} else {
				$unpaidCheck = [];
				if ($hasMixedSplit) {
					// Filter original check[] to paid pax only, preserving "RateType.N"
					// string keys so forMultiplePayments() can do explode('.', $key)[1].
					// The complement ($unpaidCheck) keeps the same keys for the unpaid pax, so
					// attachUnpaidPaxToSplitBooking() can resolve their add-on fields the same way.
					$remaining = $unpaidCheckCounts;
					$paidCheck = [];
					foreach ($check as $key => $value) {
						$toRemove = (int)($remaining[$value] ?? 0);
						if ($toRemove > 0) {
							$remaining[$value] = $toRemove - 1;
							$unpaidCheck[$key] = $value;
						} else {
							$paidCheck[$key] = $value;
						}
					}
					$request->merge(['check' => $paidCheck]);
				}

				$paymentMethod = isset($trans->via) ? $trans->via : '';
				if ($isCashFees == '1' && $paymentMethod == 'Cash') { $paymentMethod = 'Card'; }
				switch ($paymentMethod) {
					case 'Cash':     $extendBooking = ExtendBookingCashService::run($request);     break;
					case 'Invoiced': $extendBooking = ExtendBookingInvoicedService::run($request); break;
					case 'Card':     $extendBooking = ExtendBookingCardService::run($request);     break;
					default:         $extendBooking = ExtendBookingPayLaterService::run($request); break;
				}

				// For mixed split: move unpaid pax to the new booking and send payment link.
				if ($hasMixedSplit && !empty($extendBooking['bookingId'])) {
					$this->attachUnpaidPaxToSplitBooking(
						(int) $extendBooking['bookingId'],
						(int) $request->bookingID,
						$unpaidArray,
						$splitPendingItemIds,
						(int) $isPartnerBooking,
						$unpaidCheck
					);
				}
			}
			//update booking on board station
			BoardService::boardBookingUpdate($tourBooking->id);

			return $extendBooking;
		} catch (Exception $exception) {
			Log::error($exception);
			throw new GeneralCoreException($exception);
		}
	}

	/**
	 * Post-split hook for mixed (paid + unpaid) pax selection.
	 * The extend service has already created the new booking for the paid pax.
	 * This method moves the unpaid pax transact rows to that same new booking,
	 * adjusts both booking masters, cancels the old pending payment link items,
	 * and creates a new remaining_payment link for the unpaid pax cost.
	 *
	 * @param int   $newBookingId        ID returned by the extend service
	 * @param int   $oldBookingId        Original booking being split
	 * @param array $unpaidArray         [tour_package_rate_id => count] for unpaid pax
	 * @param array $splitPendingItemIds IDs from tour_booking_payment_link_items to cancel
	 * @param int   $isPartnerBooking
	 * @param array $unpaidCheck         The unpaid subset of the original "check" selection
	 *                                   (same "RateType.N" => tour_package_rate_id shape), used to
	 *                                   resolve and move these pax's own add-on fields, if any.
	 */
	private function attachUnpaidPaxToSplitBooking(
		int $newBookingId,
		int $oldBookingId,
		array $unpaidArray,
		array $splitPendingItemIds,
		int $isPartnerBooking,
		array $unpaidCheck = []
	): void {
		DB::beginTransaction();
		try {
			$newTourBooking    = TourBooking::find($newBookingId);
			$userType          = userType();
			$createdByWithName = BookingService::createdUserInfo();

			// Resolve the unpaid pax's own add-on fields BEFORE the loop below decrements the old
			// booking's transact row(s) — resolveSplitAddonFieldIds() re-slots ordinal positions
			// against that row's CURRENT headcount, so it must run while the headcount still
			// reflects the pax being split off, not after they've already been removed from it.
			// Resolved per rate group (rather than one merged call) so each field's original rate
			// group is known below — needed to re-point pax_id at the CORRECT new transact row when
			// the new booking ends up with more than one transact row for the same rate group (its
			// own paid-pax row plus the one this method creates for the unpaid pax).
			$unpaidAddonFieldIdsByRate = [];
			$unpaidAddonFieldToRateId  = [];
			if (!empty($unpaidCheck)) {
				$unpaidCheckarrays = [];
				foreach ($unpaidCheck as $key => $value) {
					$explode = explode('.', $key);
					$unpaidCheckarrays[$value][] = $explode[1];
				}
				foreach ($unpaidCheckarrays as $rateId => $positions) {
					$fieldIds = AddonBookingService::resolveSplitAddonFieldIds($oldBookingId, [$rateId => $positions]);
					if (!empty($fieldIds)) {
						$unpaidAddonFieldIdsByRate[$rateId] = $fieldIds;
						foreach ($fieldIds as $fieldId) {
							$unpaidAddonFieldToRateId[$fieldId] = $rateId;
						}
					}
				}
			}
			$unpaidAddonFieldIds = array_keys($unpaidAddonFieldToRateId);

			$natFeePct = (float) (
				DB::table('tour_bookings_transact')->where('tour_booking_id', $newBookingId)->value('nat_fees_percentage')
				?? DB::table('tour_bookings_transact')->where('tour_booking_id', $oldBookingId)->value('nat_fees_percentage')
				?? 0
			);

			$totalUnpaidTicketCost = 0.0;
			$totalUnpaidNatFees    = 0.0;
			$totalUnpaidTourists   = 0;
			$totalUnpaidInfants    = 0;
			// Maps the new booking's own transact rows to their unpaid pax count, so
			// downstream unpaid-pax lookups (PaymentLinkService::unpaidCountByRateGroupFromFormIds(),
			// cancelPendingChangePeopleItems(), etc.) can still resolve this item after the split —
			// they all key off added_transact_data[].transact_id.
			$addedTransactData     = [];
			$newTransactIdByRateId = [];

			foreach ($unpaidArray as $rateId => $unpaidCount) {
				$rateCheck     = BookingTransact::where('tour_booking_id', $oldBookingId)->where('tour_package_rate_id', $rateId)->first();
				$rateCheckname = TourPackageRate::where('id', $rateId)->first();
				if (!$rateCheck || !$rateCheckname) continue;

				$isInfantRate = $rateCheck->is_infant_rate;
				$perPerson    = $rateCheck->rate + $rateCheck->additional_charge + $rateCheck->permit_fee
					+ ($isPartnerBooking ? $rateCheck->partner_fees_amount : 0);
				$subtotal     = $perPerson * $unpaidCount;
				$natFee       = roundout($subtotal * $natFeePct / 100, 2);

				$totalUnpaidTicketCost += $subtotal;
				$totalUnpaidNatFees    += $natFee;
				if ($isInfantRate == 1) { $totalUnpaidInfants += $unpaidCount; } else { $totalUnpaidTourists += $unpaidCount; }

				// ── Add new transact row for unpaid pax on new booking ────────────────
				// Pre-build refund_permitfee_status so editBooking() can detect these
				// as unpaid/added pax (is_pax_added = true) when permit fee is edited.
				$unpaidPermitFeeSlots = [];
				for ($i = 0; $i < $unpaidCount; $i++) {
					$paxSlot = new \stdClass;
					$paxSlot->status = 'N';
					$paxSlot->is_pax_added = true;
					$unpaidPermitFeeSlots[] = $paxSlot;
				}
				$unpaidPermitFeeStatusJson = !empty($unpaidPermitFeeSlots) ? json_encode($unpaidPermitFeeSlots) : '';

				$newTransactId = DB::table('tour_bookings_transact')->insertGetId([
					'tour_booking_id'              => $newBookingId,
					'tour_package_rate_id'         => $rateId,
					'tourists'                     => $isInfantRate == 1 ? 0 : $unpaidCount,
					'infants'                      => $isInfantRate == 1 ? $unpaidCount : 0,
					'processing_charge_percentage' => 0,
					'nat_fees_percentage'          => $rateCheck->nat_fees_percentage,
					'stripe_fees_percentage'       => $rateCheck->stripe_fees_percentage,
					'partner_fees_type'            => $rateCheck->partner_fees_amount > 0 ? $rateCheck->partner_fees_type : null,
					'partner_fees_percentage'      => $rateCheck->partner_fees_percentage,
					'partner_fees_amount'          => $rateCheck->partner_fees_amount,
					'refund_permitfee_status'      => $unpaidPermitFeeStatusJson,
					'check_in_status'              => '',
					'is_infant_rate'               => $isInfantRate,
					'redeem_ticket'                => null,
					'additional_tax_percentage'    => $rateCheck->additional_tax_percentage,
					'additional_charge'            => $rateCheck->additional_charge,
					'permit_fee'                   => $rateCheckname->permit_fee,
					'rate'                         => $rateCheck->rate,
					'total'                        => $subtotal,
					'created_by'                   => Auth::id(),
					'created_by_user_type'         => $userType,
					'created_at'                   => Carbon::now(),
				]);
				$addedTransactData[] = ['transact_id' => $newTransactId, 'added_count' => $unpaidCount];
				$newTransactIdByRateId[$rateId] = $newTransactId;
				DB::commit();

				// ── Update old transact row (remove unpaid pax) ──────────────────────
				$setTotal    = $rateCheck->total - $subtotal;
				$setTourists = $isInfantRate == 1 ? $rateCheck->tourists         : $rateCheck->tourists - $unpaidCount;
				$setInfants  = $isInfantRate == 1 ? $rateCheck->infants - $unpaidCount : $rateCheck->infants;
				$updateFields = ['total' => $setTotal, 'tourists' => $setTourists, 'infants' => $setInfants];
				if ($setTourists <= 0 && $setInfants <= 0) {
					$updateFields = array_merge($updateFields, ['check_in_status' => '', 'redeem_ticket' => null, 'refund_permitfee_status' => '']);
				}
				BookingTransact::where('tour_booking_id', $oldBookingId)->where('tour_package_rate_id', $rateId)->update($updateFields);
				DB::commit();

				// ── Decrement old booking master for unpaid pax ──────────────────────
				$freshOld = TourBooking::find($oldBookingId);
				TourBooking::where('id', $oldBookingId)->update([
					'total'         => $freshOld->total - ($subtotal + $natFee),
					'booking_total' => $freshOld->booking_total - ($subtotal + $natFee),
					'tourists'      => $isInfantRate == 1 ? $freshOld->tourists         : $freshOld->tourists - $unpaidCount,
					'infants'       => $isInfantRate == 1 ? $freshOld->infants - $unpaidCount : $freshOld->infants,
				]);
				DB::commit();
			}

			// ── Move add-ons belonging to the unpaid pax onto the new booking ─────
			// The extend service above already moved add-ons for the PAID pax (via its own
			// resolveSplitAddonFieldIds()/splitBookingPaxAddons() call on the paid-only $request);
			// this covers the unpaid remainder, now that the new booking's own transact rows
			// (created in the loop above) exist for splitBookingPaxAddons() to re-point pax_id to.
			if (!empty($unpaidAddonFieldIds)) {
				try {
					AddonBookingService::splitBookingPaxAddons($oldBookingId, $newBookingId, $unpaidAddonFieldIds);

					// Correct pax_id where the new booking has MORE THAN ONE transact row for the
					// same rate group (its own paid-pax row plus the one this method just created for
					// the unpaid pax) — splitBookingPaxAddons() just grabs the first matching row on
					// the new booking, which isn't necessarily the unpaid pax's own row. Re-point each
					// moved field at the exact transact row created above for its rate group.
					foreach ($unpaidAddonFieldIdsByRate as $rateId => $fieldIds) {
						if (isset($newTransactIdByRateId[$rateId])) {
							TourBookingAddonField::where('tour_booking_id', $newBookingId)
								->whereIn('id', $fieldIds)
								->update(['pax_id' => $newTransactIdByRateId[$rateId]]);
						}
					}
				} catch (Exception $ex) {
					Log::error($ex->getMessage());
				}
			}

			// ── Update new booking master to include unpaid pax ──────────────────
			$unpaidPayLinkAmount = round($totalUnpaidTicketCost + $totalUnpaidNatFees, 2);
			if ($unpaidPayLinkAmount > 0) {
				$freshNew = TourBooking::find($newBookingId);
				TourBooking::where('id', $newBookingId)->update([
					'total'              => $freshNew->total + $unpaidPayLinkAmount,
					'booking_total'      => $freshNew->booking_total + $unpaidPayLinkAmount,
					'service_commission' => $freshNew->service_commission + $totalUnpaidNatFees,
					'tourists'           => $freshNew->tourists + $totalUnpaidTourists,
					'infants'            => $freshNew->infants + $totalUnpaidInfants,
				]);
				DB::commit();
			}

			// ── Cancel old pending payment link items ────────────────────────────
			// Both total AND booking_total already decremented together for the old booking
			// above (this method's own loop) — skip both here to avoid double-decrementing.
			if (!empty($splitPendingItemIds)) {
				PaymentLinkService::cancelPendingChangePeopleItems(implode(',', $splitPendingItemIds), null, true, true);
			}

			// ── Create remaining_payment link for unpaid pax on new booking ──────
			if ($unpaidPayLinkAmount > 0) {
				$slotInfo = DB::table('tour_slot_times AS tst')
					->join('tour_slot_dates AS tsd', 'tsd.id', '=', 'tst.tour_slot_id')
					->join('tour_packages AS tp',    'tp.id',  '=', 'tsd.tour_package_id')
					->join('tour_operators AS t_o',  't_o.id', '=', 'tp.tour_operator_id')
					->join('cities AS ct',           'ct.id',  '=', 't_o.city_id')
					->join('states AS st',           'st.id',  '=', 'ct.state_id')
					->where('tst.id', $newTourBooking->tour_slot_id)
					->select([
						'tst.time_from', 'tst.time_to', 'tsd.date',
						'tp.tour_operator_id', 'tsd.tour_package_id',
						'tp.name AS package_name', 'tp.important_notes',
						'tp.things_to_bring', 'tp.arrival_time_duration',
						'ct.state_id', 'st.permit_fee',
						't_o.name AS tour_operator', 't_o.email AS tour_op_email',
						't_o.phone_number AS tour_op_phone', 't_o.website AS tour_op_website',
						't_o.logo AS tour_op_logo', 't_o.cancellation_policy',
						'tp.service_commission_percentage', 'tp.stripe_commission_percentage',
						't_o.tenant_id', 'tp.stripe_destination_id', 't_o.id as tour_operator_id',
						't_o.statement_descriptor', 't_o.card_reader_prefix',
						'tp.email as packageEmail', 'tp.from_name as packageFromName',
						'tp.from_email as packageFromEmail', 'tp.api_key as packageApiKey',
						'tp.attach_waiver_pdf', 'tp.waiver_pdf', 'tp.has_contacts',
					])->first();

				$slotDateTime = Carbon::parse($slotInfo->date . ' ' . $slotInfo->time_from);
				PaymentLinkService::upsertRemainingPaymentLink(
					$newTourBooking->group_id,
					[
						'type'         => 'change_people',
						'reference_id' => null,
						'amount'       => $unpaidPayLinkAmount,
						'reason'       => 'Payment for your booking',
						'details'      => [
							'tour_booking_id'      => $newBookingId,
							'tourists'             => $totalUnpaidTourists + $totalUnpaidInfants,
							'ticket_cost'          => $totalUnpaidTicketCost,
							'platform_fees'        => $totalUnpaidNatFees,
							'added_transact_data'  => $addedTransactData,
							'created_by_with_name' => $createdByWithName,
						],
					],
					$newTourBooking,
					$slotDateTime,
					$slotInfo
				);
			}

			// Move the unpaid pax's own pending add-on payment (a separate remaining_payment
			// link item, type='addon') onto the new booking too — otherwise the add-on field
			// itself moves (above) but its unpaid charge stays stuck on the old booking's link.
			PaymentLinkService::movePendingAddonPaymentLinkItems($oldBookingId, $newBookingId, $unpaidAddonFieldIds);

			DB::commit();
		} catch (Exception $exception) {
			DB::rollBack();
			Log::error($exception);
			throw new GeneralCoreException($exception);
		}
	}


	/**
	 * Split an unpaid pax (on a pending payment link) to a new booking.
	 * Unlike the paid-split paths, this never touches booking_total on the old
	 * booking, sets booking_total=0 on the new booking, and creates a new
	 * remaining_payment link for the new booking instead of processing a refund.
	 */
	private function splitUnpaidPaxBooking($request, $tourBooking): array
	{
		DB::beginTransaction();
		try {
			$check             = $request->input('check', []);
			$array             = array_count_values($check);
			$userType          = userType();
			$createdByWithName = BookingService::createdUserInfo();
			$isPartnerBooking  = $tourBooking->is_partner_booking;
			$tourists          = $tourBooking->tourists + $tourBooking->infants;

			// ── Slot / package info ──────────────────────────────────────────
			$info = DB::table('tour_slot_times AS tst')
				->join('tour_slot_dates AS tsd', 'tsd.id', '=', 'tst.tour_slot_id')
				->join('tour_packages AS tp',    'tp.id',  '=', 'tsd.tour_package_id')
				->join('tour_operators AS t_o',  't_o.id', '=', 'tp.tour_operator_id')
				->join('cities AS ct',           'ct.id',  '=', 't_o.city_id')
				->join('states AS st',           'st.id',  '=', 'ct.state_id')
				->where('tst.id', $tourBooking->tour_slot_id)
				->select([
					'tst.time_from', 'tst.time_to', 'tsd.date',
					'tst.time_slot_seats as seats',
					'tp.tour_operator_id', 'tsd.tour_package_id',
					'tp.name AS package_name', 'tp.important_notes',
					'tp.things_to_bring', 'tp.arrival_time_duration',
					'ct.state_id', 'st.permit_fee',
					't_o.name AS tour_operator', 't_o.email AS tour_op_email',
					't_o.phone_number AS tour_op_phone', 't_o.website AS tour_op_website',
					't_o.logo AS tour_op_logo', 't_o.cancellation_policy',
					'tp.service_commission_percentage', 'tp.stripe_commission_percentage',
					't_o.tenant_id', 'tp.stripe_destination_id', 't_o.id as tour_operator_id',
					't_o.statement_descriptor', 't_o.card_reader_prefix',
					'tp.email as packageEmail', 'tp.from_name as packageFromName',
					'tp.from_email as packageFromEmail', 'tp.api_key as packageApiKey',
					'tp.attach_waiver_pdf', 'tp.waiver_pdf', 'tp.has_contacts',
					DB::raw("(SELECT SUM(tbm.tourists) FROM tour_bookings_master AS tbm
						WHERE tbm.tour_slot_id = tst.id AND tbm.status != 'Cancelled'
						GROUP BY tbm.tour_slot_id) AS booked_seats"),
				])->first();
			if (!$info) throw new Exception('Unable to split booking.');

			$customer = Customer::where('id', $tourBooking->customer_id)->first();

			// ── Build check-in / redeem / permit arrays ──────────────────────
			$checkarrays            = [];
			$checkinstatusarray     = [];
			$redeemTicketArray      = [];
			$refundedpermitfeearray = [];
			foreach ($check as $key => $value) {
				$btset = BookingTransact::where('tour_booking_id', $request->bookingID)
					->where('tour_package_rate_id', $value)->first();
				$explode                        = explode('.', $key);
				$checkarrays[$value][]          = $explode[1];
				$checkinstatusarray[$value]     = $btset->check_in_status;
				$redeemTicketArray[$value]      = $btset->redeem_ticket;
				$refundedpermitfeearray[$value] = $btset->refund_permitfee_status;
			}
			$explicitAddonFieldIds = AddonBookingService::resolveSplitAddonFieldIds($request->bookingID, $checkarrays);

			$updatedCheckIns = $updatedRedeemTickets = $updatedRefundedPermitfees = [];
			$updatedRefundedPermitfeesForSplitBooking = $updatedCheckInsForSplitBooking = $updatedRedeemTicketsForSplitBooking = [];
			foreach ($checkarrays as $k => $checkarray) {
				$checkinstatusInfo          = ($checkinstatusarray[$k] ?? '') !== '' ? json_decode($checkinstatusarray[$k]) : [];
				$redeemTicketInfo           = ($redeemTicketArray[$k] ?? '') !== '' ? json_decode($redeemTicketArray[$k], true) : [];
				$refundpermitfeesstatusInfo = ($refundedpermitfeearray[$k] ?? '') !== '' ? json_decode($refundedpermitfeearray[$k]) : [];
				$updatedRefundedPermitfeesStatusInfo = $updatedCheckInsStatusInfo = $updatedRedeemTicketInfo = [];
				$count = $cnt = $redeemCount = 0;
				$newRedeemTicketArr = [];
				foreach ($checkarray as $m) {
					if (isset($checkinstatusInfo[$m]) && !empty($checkinstatusInfo[$m])) {
						$updatedCheckInsStatusInfo[$cnt] = $checkinstatusInfo[$m];
						unset($checkinstatusInfo[$m]); $cnt++;
					}
					if (!empty($redeemTicketInfo)) {
						for ($y = 0; $y < count($redeemTicketInfo); $y++) {
							if (isset($redeemTicketInfo[$y]['data'][$m]) && !empty($redeemTicketInfo[$y]['data'][$m])) {
								$updatedRedeemTicketInfo[$y]['id']   = $redeemTicketInfo[$y]['id'];
								$updatedRedeemTicketInfo[$y]['name'] = $redeemTicketInfo[$y]['name'];
								$updatedRedeemTicketInfo[$y]['data'][$redeemCount] = [
									'status'   => $redeemTicketInfo[$y]['data'][$m]['status'],
									'dateTime' => $redeemTicketInfo[$y]['data'][$m]['dateTime'],
								];
								unset($redeemTicketInfo[$y]['data'][$m]); $redeemCount++;
							}
							if (isset($redeemTicketInfo[$y]['data'])) {
								$newRedeemTicketArr = $redeemTicketInfo;
								$newRedeemTicketArr[$y]['data'] = array_values($newRedeemTicketArr[$y]['data']);
							}
							$updatedRedeemTicketInfo[$y]['data'] = array_values($updatedRedeemTicketInfo[$y]['data'] ?? []);
						}
					}
					if (isset($refundpermitfeesstatusInfo[$m]) && !empty($refundpermitfeesstatusInfo[$m])) {
						$updatedRefundedPermitfeesStatusInfo[$count] = $refundpermitfeesstatusInfo[$m];
						$count++;
						unset($refundpermitfeesstatusInfo[$m]);
					}
				}
				$redeemTicketInfo = $newRedeemTicketArr;
				$updatedCheckIns[$k]                          = $checkinstatusInfo;
				$updatedRedeemTickets[$k]                     = $redeemTicketInfo;
				$updatedRefundedPermitfees[$k]                = $refundpermitfeesstatusInfo;
				$updatedRefundedPermitfeesForSplitBooking[$k] = $updatedRefundedPermitfeesStatusInfo;
				$updatedCheckInsForSplitBooking[$k]           = $updatedCheckInsStatusInfo;
				$updatedRedeemTicketsForSplitBooking[$k]      = $updatedRedeemTicketInfo;
			}

			// ── Liability waiver ─────────────────────────────────────────────
			$liabilityWaiverSigningSplitBooking = [];
			$liability_waiver_signing           = $tourBooking->liability_waiver_signing;
			$touristsNumbers                    = $request->input('tourits_numbers', '');
			if ($liability_waiver_signing !== '' && $touristsNumbers !== '') {
				$liability_waiver_signing = json_decode($liability_waiver_signing);
				$touristsCount = 0;
				foreach (explode(',', $touristsNumbers) as $v) {
					if (isset($liability_waiver_signing[$v])) {
						$liabilityWaiverSigningSplitBooking[$touristsCount] = $liability_waiver_signing[$v];
						unset($liability_waiver_signing[$v]); $touristsCount++;
					}
				}
				TourBooking::where('id', $request->bookingID)->update([
					'liability_waiver_signing' => !empty($liability_waiver_signing) ? json_encode(array_values($liability_waiver_signing)) : '',
				]);
			}

			// ── Update old booking transact status arrays ────────────────────
			foreach ($updatedCheckIns as $key => $value) {
				BookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $key)
					->update(['check_in_status' => !empty($value) ? json_encode(array_values($value)) : '']);
			}
			foreach ($updatedRedeemTickets as $key => $value) {
				BookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $key)
					->update(['redeem_ticket' => !empty($value) ? json_encode(array_values($value)) : '']);
			}
			foreach ($updatedRefundedPermitfees as $key => $value) {
				if (!empty($value)) {
					BookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $key)
						->update(['refund_permitfee_status' => json_encode(array_values($value))]);
				}
			}

			// ── Move pax to new booking ──────────────────────────────────────
			$totalForNewBooking = 0;
			$totalTourists      = 0;
			$totalInfants       = 0;
			$touristGroups      = [];
			$tbTransact         = [];
			$tbTransaction      = [];
			foreach ($array as $key => $value) {
				$rateCheck     = BookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $key)->first();
				$rateCheckname = TourPackageRate::where('id', $key)->first();
				$isInfantRate  = $rateCheck->is_infant_rate;
				$subtotal      = $rateCheck->rate + $rateCheck->additional_charge + $rateCheck->permit_fee
				               + ($isPartnerBooking ? $rateCheck->partner_fees_amount : 0);

				$totalRefundedPermitFees = 0;
				foreach ($updatedRefundedPermitfeesForSplitBooking[$key] ?? [] as $v) {
					if (isset($v->status) && $v->status === 'Y' && isset($v->amount) && $v->amount > 0) {
						$totalRefundedPermitFees += $v->amount;
					}
				}
				$subtotal = $rateCheck->permit_fee > 0
					? ($subtotal * $value) - $totalRefundedPermitFees
					: $subtotal * $value;

				$totalForNewBooking += $subtotal;
				if ($isInfantRate == 1) { $totalInfants += $value; } else { $totalTourists += $value; }

				$refundedPermitFeesDetails = !empty($updatedRefundedPermitfeesForSplitBooking[$key]) ? json_encode(array_values($updatedRefundedPermitfeesForSplitBooking[$key])) : '';
				$checkInsDetails           = !empty($updatedCheckInsForSplitBooking[$key])           ? json_encode(array_values($updatedCheckInsForSplitBooking[$key]))           : '';
				$redeemTicketDetails       = !empty($updatedRedeemTicketsForSplitBooking[$key])      ? json_encode(array_values($updatedRedeemTicketsForSplitBooking[$key]))      : '';

				$touristGroups[] = $rateCheckname->rate_for[0] . ':' . $value;
				$tbTransact[]    = [
					'tour_package_rate_id'         => $key,
					'tourists'                     => $isInfantRate == 1 ? 0 : $value,
					'infants'                      => $isInfantRate == 1 ? $value : 0,
					'processing_charge_percentage' => 0,
					'nat_fees_percentage'          => $rateCheck->nat_fees_percentage,
					'stripe_fees_percentage'       => $rateCheck->stripe_fees_percentage,
					'partner_fees_type'            => $rateCheck->partner_fees_amount > 0 ? $rateCheck->partner_fees_type : null,
					'partner_fees_percentage'      => $rateCheck->partner_fees_percentage,
					'partner_fees_amount'          => $rateCheck->partner_fees_amount,
					'refund_permitfee_status'      => $refundedPermitFeesDetails,
					'check_in_status'              => $checkInsDetails,
					'is_infant_rate'               => $isInfantRate,
					'redeem_ticket'                => $redeemTicketDetails,
					'additional_tax_percentage'    => $rateCheck->additional_tax_percentage,
					'additional_charge'            => $rateCheck->additional_charge,
					'permit_fee'                   => $rateCheckname->permit_fee,
					'rate'                         => $rateCheck->rate,
					'total'                        => $subtotal,
					'created_by'                   => Auth::id(),
					'created_by_user_type'         => $userType,
					'created_at'                   => Carbon::now(),
				];
				$tbTransaction[] = ['tour_package_rate_id' => $key, 'tourists' => $value, 'rate_for' => $rateCheckname->rate_for];

				// Update old booking transact row
				$setTotal    = $rateCheck->total - $subtotal;
				$setTourists = $isInfantRate == 1 ? $rateCheck->tourists         : $rateCheck->tourists - $value;
				$setInfants  = $isInfantRate == 1 ? $rateCheck->infants - $value : $rateCheck->infants;
				$updateFields = ['total' => $setTotal, 'tourists' => $setTourists, 'infants' => $setInfants];
				if ($setTourists == 0 && $setInfants == 0) {
					$updateFields = array_merge($updateFields, ['check_in_status' => '', 'redeem_ticket' => null, 'refund_permitfee_status' => '']);
				}
				BookingTransact::where('tour_booking_id', $request->bookingID)->where('tour_package_rate_id', $key)->update($updateFields);
				DB::commit();

				// Update old booking master: decrement total (the payable-today figure) so the old
				// booking reflects only the remaining pax after the split. booking_total is NOT
				// decremented here — per this method's own docblock, it's the gross lifetime total
				// and this pax was never actually charged against it (nothing was ever collected).
				$fresh = TourBooking::find($request->bookingID);
				TourBooking::where('id', $request->bookingID)->update([
					'total'         => $fresh->total - $subtotal,
					'tourists'      => $isInfantRate == 1 ? $fresh->tourists         : $fresh->tourists - $value,
					'infants'       => $isInfantRate == 1 ? $fresh->infants - $value : $fresh->infants,
				]);
				DB::commit();

				// NO refund history, NO DeletePersonFullRefundService — nothing was ever charged.
			}

			// ── Create new booking ───────────────────────────────────────────
			// NAT fee is a package-level rate; all transact rows share the same percentage.
			// service_commission must be pre-set here: ChangePeopleItemHandler::finalize()
			// relies on it already being correct and never updates it after payment.
			// total and booking_total are both set to ticket+fee so the master record
			// reflects the full payable amount from the moment the booking is created.
			$natFeePct     = !empty($tbTransact) ? (float) $tbTransact[0]['nat_fees_percentage'] : 0.0;
			$payLinkFees   = roundout($totalForNewBooking * $natFeePct / 100, 2);
			$payLinkAmount = round($totalForNewBooking + $payLinkFees, 2);

			$newTourBooking = TourBooking::create([
				'tour_package_id'          => $tourBooking->tour_package_id,
				'tour_slot_id'             => $tourBooking->tour_slot_id,
				'customer_id'              => $tourBooking->customer_id,
				'tourists'                 => $totalTourists,
				'infants'                  => $totalInfants,
				'name'                     => $tourBooking->name,
				'email'                    => $tourBooking->email,
				'phone_number'             => $tourBooking->phone_number,
				'mask_required'            => 'Yes',
				'service_commission'       => $payLinkFees,
				'total'                    => $payLinkAmount,
				'booking_total'            => $payLinkAmount,
				'liability_waiver_signing' => !empty($liabilityWaiverSigningSplitBooking) ? json_encode(array_values($liabilityWaiverSigningSplitBooking)) : '',
				'status'                   => 'Booked',
				'is_partner_booking'       => $isPartnerBooking,
				'visitor'                  => $request->getClientIp(),
				'request_from'             => $request->is('api/*') ? Constants::API : Constants::BACKEND,
				'expire_at'                => $tourBooking->expire_at,
				'created_by'               => Auth::id(),
				'created_by_user_type'     => $userType,
				'updated_at'               => null,
			]);
			DB::commit();

			// ── Insert transact rows for new booking ─────────────────────────
			for ($a = 0, $ac = count($tbTransact); $a < $ac; $a++) {
				$tbTransact[$a]['tour_booking_id'] = $newTourBooking->id;
			}
			DB::table('tour_bookings_transact')->insert($tbTransact);
			DB::commit();

			// Map each rate group to its new transact row id, so the remaining_payment link
			// item created below can carry a resolvable added_transact_data — downstream unpaid-pax
			// lookups (PaymentLinkService::unpaidCountByRateGroupFromFormIds(),
			// cancelPendingChangePeopleItems(), etc.) all key off added_transact_data[].transact_id.
			$newTransactIdByRateId = DB::table('tour_bookings_transact')
				->where('tour_booking_id', $newTourBooking->id)
				->pluck('id', 'tour_package_rate_id');
			$addedTransactData = [];
			foreach ($array as $key => $value) {
				if (isset($newTransactIdByRateId[$key])) {
					$addedTransactData[] = ['transact_id' => $newTransactIdByRateId[$key], 'added_count' => $value];
				}
			}

			// ── Transfer contacts ─────────────────────────────────────────────
			if ($info->has_contacts == 1 && isset($request->contacts) && $request->contacts !== null) {
				try {
					$contactIds = json_decode($request->contacts, true);
					if (!empty($contactIds)) {
						$bookingTransact = BookingTransact::where('tour_booking_id', $request->bookingID)->get();
						foreach ($contactIds as $contactId) {
							$tourBookingContact = TourBookingContact::findOrFail($contactId);
							foreach ($bookingTransact as $transact) {
								$newBT = BookingTransact::where('tour_booking_id', $newTourBooking->id)
									->where('tour_package_rate_id', $transact->tour_package_rate_id)->first();
								if ($transact->id == $tourBookingContact->tour_booking_transact_id) {
									$tourBookingContact->update([
										'tour_booking_id'          => $newTourBooking->id,
										'tour_booking_transact_id' => $newBT->id,
										'updated_at'               => mysqlDT(),
									]);
								}
							}
						}
					}
				} catch (Exception $ex) {
					Log::error($ex->getMessage());
				}
			}

			// ── Tourist history on new booking ────────────────────────────────
			$addedPeoplesText = array_map(fn($t) => $t['rate_for'] . ' person ' . $t['tourists'], $tbTransaction);
			HistoryService::storeTouristInHistory($request, $newTourBooking, 0, $addedPeoplesText, $newTourBooking->tourists + $newTourBooking->infants, $createdByWithName);
			DB::commit();

			// ── Move pax add-ons ──────────────────────────────────────────────
			if (!empty($explicitAddonFieldIds)) {
				try {
					AddonBookingService::splitBookingPaxAddons($request->bookingID, $newTourBooking->id, $explicitAddonFieldIds);
				} catch (Exception $ex) {
					Log::error($ex->getMessage());
				}
			}

			// ── Split history on both bookings ────────────────────────────────
			HistoryService::storeSplitBookingInHistory($tourBooking->id, $newTourBooking->id, $tourists, $totalTourists + $totalInfants, 'Payment Link', $createdByWithName, []);
			DB::commit();

			// ── Cancel old pending payment link items ─────────────────────────
			// skipTotalUpdate=true: master.total already decremented in the loop above.
			// booking_total is NOT skipped (4th arg omitted/false): per this method's own
			// old-booking update above, booking_total is deliberately left untouched there
			// (an unpaid pax was never actually charged against it), so it must be corrected here.
			$splitPendingItemIds = $request->input('split_pending_item_ids', '');
			if (!empty($splitPendingItemIds)) {
				PaymentLinkService::cancelPendingChangePeopleItems($splitPendingItemIds, null, true);
			}

			// ── Create remaining_payment link for the new booking ─────────────
			$slotDateTime = Carbon::parse($info->date . ' ' . $info->time_from);
			if ($payLinkAmount > 0) {
				PaymentLinkService::upsertRemainingPaymentLink(
					$newTourBooking->group_id,
					[
						'type'         => 'change_people',
						'reference_id' => null,
						'amount'       => $payLinkAmount,
						'reason'       => 'Payment for your booking',
						'details'      => [
							'tour_booking_id'      => $newTourBooking->id,
							'tourists'             => $totalTourists + $totalInfants,
							'ticket_cost'          => $totalForNewBooking,
							'platform_fees'        => $payLinkFees,
							'added_transact_data'  => $addedTransactData,
							'created_by_with_name' => $createdByWithName,
						],
					],
					$newTourBooking,
					$slotDateTime,
					$info
				);
			}

			// Move the split-off pax's own pending add-on payment (a separate remaining_payment
			// link item, type='addon') onto the new booking too — splitBookingPaxAddons() above
			// already re-points the TourBookingAddonField row itself, but its unpaid charge would
			// otherwise stay stuck on the old booking's link.
			PaymentLinkService::movePendingAddonPaymentLinkItems($request->bookingID, $newTourBooking->id, $explicitAddonFieldIds);

			// ── Broadcast new booking ─────────────────────────────────────────
			$slotInfo = DB::table('tour_slot_times AS tst')
				->join('tour_slot_dates AS tsd', 'tsd.id', '=', 'tst.tour_slot_id')
				->join('tour_packages AS tp',    'tp.id',  '=', 'tsd.tour_package_id')
				->where('tst.id', $tourBooking->tour_slot_id)
				->select([DB::raw("(SELECT SUM(tbm.tourists) FROM tour_bookings_master AS tbm
					WHERE tbm.tour_slot_id = tst.id AND tbm.status != 'Cancelled'
					GROUP BY tbm.tour_slot_id) AS booked_seats")])->first();
			$booking = [
				'id'               => $newTourBooking->id,
				'group_id'         => $newTourBooking->group_id,
				'prefixedId'       => bookingPrefix($newTourBooking->id),
				'cust_name'        => $newTourBooking->name,
				'pkg_id'           => $info->tour_package_id,
				'pkg_name'         => $info->package_name,
				'paid'             => '',
				'total'            => $totalForNewBooking,
				'tour_slot_id'     => $newTourBooking->tour_slot_id,
				'tour_d_t'         => $info->date . ' ' . $info->time_from,
				'booking_d_t'      => $newTourBooking->created_at,
				't_groups'         => implode(' | ', $touristGroups),
				'tour_operator_id' => $info->tour_operator_id,
				'tourists'         => $totalTourists,
				'infants'          => $totalInfants,
				'is_affiliate'     => 'No',
				'notif_for'        => 'admin',
				'date'             => $info->date,
				'time_from'        => $info->time_from,
				'time_to'          => $info->time_to,
				'seats'            => $info->seats,
				'payment_method'   => 'Payment Link',
				'booked_seats'     => $slotInfo->booked_seats ?? 0,
				'broadcaster_user_id' => Auth::id(),
				'env'              => config('app.env'),
				'invoiceStatus'    => 0,
				'BookingTotal'     => 0,
				'RefundAmount'     => 0,
				'PaymentTotal'     => 0,
				'paid_split'       => null,
				'domain'           => url('/'),
				'background_colour_class' => $customer->is_affiliate == 'Yes' ? 'affiliate-catch' : 'normal-booking',
			];
			BookingNew::dispatch($booking);
			$booking['notif_for'] = 'Tour Operator';
			BookingNew::dispatch($booking);

			$arEmailData = [
				'tour_d_t'       => $booking['tour_d_t'],
				'bookingId'      => $newTourBooking->id,
				'bookingGroupId' => $newTourBooking->group_id,
				'custName'       => $newTourBooking->name,
				'custEmail'      => $newTourBooking->email,
				'custPhone'      => $newTourBooking->phone_number,
			];
			if (in_array(Auth::user()->email, config('constants.prevent_sending_emails')) === false) {
				EmailService::sendAcknowledgementEmail($info, $arEmailData);
			}

			DB::commit();
			return [
				'bookingId'    => $newTourBooking->id,
				'bookingToken' => Crypt::encryptString($newTourBooking->id),
			];
		} catch (Exception $exception) {
			DB::rollBack();
			Log::error($exception);
			throw new GeneralCoreException($exception);
		}
	}

	/**
	 * Change people in the existing booking
	 *
	 * @param object $request
	 * @return mixed
	 *
	 * @version 1.0.0
	 */
	public function changePeopleBooking($request)
	{
		DB::beginTransaction();
		try {
			$isValidationCheckForBookingChangePeople = $request->get('validation_check') === 'true';
			if (isset($request->api) && $request->api == 1) {
				$this->transformer->transformRequestData($request);
			}

			$oldBookingID = oldBookingId();
			$isCashFees = cashFees();
			$tourBooking = $this->tourBooking::find($request->bookingID);

			$isGroupBooking = $tourBooking->is_group_booking;
			$isPartnerBooking = $tourBooking->is_partner_booking;
			$cashPriceEnabled = cashPriceEnabled();
			$bookingT = DB::table('tour_bookings_transact AS tbt')
				->join('tour_package_rates AS tpr', 'tpr.id', '=', 'tbt.tour_package_rate_id')
				->where('tbt.tour_booking_id', $request->bookingID)
				->where('tbt.deleted_by', 0)
				->orderBy('tpr.orderby', 'asc')
				->get(['tpr.rate_for', 'tbt.tour_package_rate_id', 'tbt.tourists', 'tbt.infants', 'tbt.is_infant_rate', 'tbt.rate', 'tbt.additional_charge', 'tbt.partner_fees_type', 'tbt.partner_fees_percentage', 'tbt.partner_fees_amount', 'tbt.total', 'tbt.stripe_fees_percentage', 'tbt.nat_fees_percentage']);

			$rateGroupWiseTourists = array();
			$rateGroupWiseIsInfantRate = array();
			$totalTouristsOfBooking = 0;
			$oldGroupRateId = 0;
			$oldGroupTourists = 0;
			$oldGroupRate = 0;
			foreach ($bookingT as $value) {
				$rateGroupWiseTourists[$value->tour_package_rate_id] = ($value->infants > 0) ? $value->infants : $value->tourists;
				$rateGroupWiseIsInfantRate[$value->tour_package_rate_id] = $value->is_infant_rate;
				$totalTouristsOfBooking += $value->tourists + $value->infants;
				if ($isGroupBooking == '1') {
					$oldGroupRateId = $value->tour_package_rate_id;
					$oldGroupTourists += $value->tourists;
					$oldGroupRate = $value->total;
				}
			}

			// For Payment Link: include pax from any active pending change_people items in
			// the baseline so the admin's desired-total (paid + pending + new) maps cleanly
			// to delta = new-only. Only fills in rate groups that are absent from transact
			// (soft-deleted or not yet written); rate groups already in rateGroupWiseTourists
			// already have the pending count because the payment-link creation inserted/updated
			// their transact row at the time the link was made.
			$pendingLinkPaxAdded = [];
			if ($request->payment_method === 'Payment Link') {
				$pendingCpDetails = DB::table('tour_booking_payment_link_items AS tbpli')
					->join('tour_booking_payment_links AS tbpl', 'tbpl.id', '=', 'tbpli.payment_link_id')
					->where('tbpl.order_id', $tourBooking->group_id)
					->where('tbpli.type', 'change_people')
					->where('tbpl.status', 'Unpaid')
					->pluck('tbpli.details');
				foreach ($pendingCpDetails as $detailsRaw) {
					$pendingDetails = is_array($detailsRaw) ? $detailsRaw : json_decode($detailsRaw, true);
					foreach ($pendingDetails['added_transact_data'] ?? [] as $entry) {
						if (empty($entry['transact_id'])) {
							continue;
						}
						$pendingRateGroupId = DB::table('tour_bookings_transact')
							->where('id', $entry['transact_id'])
							->where('tour_booking_id', $tourBooking->id)
							->value('tour_package_rate_id');
						if ($pendingRateGroupId && !isset($rateGroupWiseTourists[$pendingRateGroupId])) {
							$count = (int)($entry['added_count'] ?? 0);
							$rateGroupWiseTourists[$pendingRateGroupId] = $count;
							$pendingLinkPaxAdded[$pendingRateGroupId] = $count;
						}
					}
				}
			}

			//calculate refund value
			$refundOnly = $this->tourBookingHistory::where('tour_booking_id', $request->bookingID)
				->where('operation', 'Refund')
				->get([
					'id',
					'details'
				]);
			$refundOnlyCheck = 0;
			foreach ($refundOnly as $value) {
				$details = json_decode($value->details, true);
				// Skip split-booking reallocations — accounting artifacts, not actual customer refunds
				if (isset($details['from']) && $details['from'] === 'Extend Booking') {
					continue;
				}
				$refundOnlyCheck += $details['amount'];
			}
			$totalBooking = (float)$tourBooking->booking_total;
			$tolerance = 0.00001;
			if (request()->is('api/*')) {
				if (isset($request->refund_Type) && !empty($request->refund_Type) && $request->refund_Type != "dont_refund") {
					if ((!$isGroupBooking && (abs($refundOnlyCheck - $totalBooking) < $tolerance) || ($refundOnlyCheck == $totalBooking)) && ((string)$request->tourists[0] < (string)$totalTouristsOfBooking)) {
						throw new Exception('Unable to change people as transaction already refunded.');
					}
				}
			} else {
				if (isset($request->refund_Type) && !empty($request->refund_Type) && $request->refund_Type != "dont_refund") {
					if (!$isGroupBooking && ((abs($refundOnlyCheck - $totalBooking) < $tolerance) || ($refundOnlyCheck == $totalBooking)) && ((int)$request->tourists[0] < (int)$totalTouristsOfBooking)) {
						throw new Exception('Unable to change people as transaction already refunded.');
					}
				}
			}

			if (empty($rateGroupWiseTourists)) {
				throw new Exception('Please select at least one tourist.');
			}

			//Validations to restrict user to perform only delete peoples
			$result = BookingUtils::calculateChangedTouristsData($request, $tourBooking, $isGroupBooking, $rateGroupWiseTourists, $rateGroupWiseIsInfantRate);

			$addedPeopleCount = $result['addedPeopleCount'];
			$deletedPeopleCount = $result['deletedPeopleCount'];
			$addedInfantsCount = $result['addedInfantsCount'];
			$deletedInfantsCount = $result['deletedInfantsCount'];
			$rateGroupWiseAddedPeople = $result['rateGroupWiseAddedPeople'];
			$rateGroupWiseDeletedPeople = $result['rateGroupWiseDeletedPeople'];
			$rateGroupWiseAddedPeopleArray = $result['rateGroupWiseAddedPeopleArray'];
			$rateGroupWiseDeletedPeopleArray = $result['rateGroupWiseDeletedPeopleArray'];
			$rateGrpIds = $result['rateGrpIds'];
			$permitfeeAr = $result['permitfeeAr'];

			// Check if there are addon changes even when tourist count hasn't changed
			$hasAddonChanges = ($request->has('addons_payload') && !empty($request->addons_payload)) ||
				($request->has('addons_added') && !empty($request->addons_added)) ||
				($request->has('addons_updated') && !empty($request->addons_updated)) ||
				($request->has('addons_removed') && !empty($request->addons_removed));

			if ($addedPeopleCount == 0 && $deletedPeopleCount == 0 && $addedInfantsCount == 0 && $deletedInfantsCount == 0 && !$hasAddonChanges) {
				throw new Exception('You must need to select tourists to change.');
			}

			if ($addedPeopleCount == 0 && $deletedPeopleCount > 0 && $deletedPeopleCount == $totalTouristsOfBooking) {
				throw new Exception('You can not delete all pax from the booking.');
			}

			$userType = userType();

			$info = TourPackageService::getTourSlotInfo($request->slot_time, $userType);
			if (!$info) {
				throw new Exception('Unable to change people to tour package');
			}

			/* Validation for booking has contacts or not */
			if ($info->has_contacts == 1) {
				PackageHasContactsService::contactList($request->bookingID);
			}

			$createdByWithName = BookingService::createdUserInfo();
			$customer = $this->customer::where('id', $tourBooking->customer_id)->withTrashed()->first();

			$commissionRates = TourPackageService::getCommissionFeesPercentage($request, $customer, $info);

			// Assign the returned values to respective variables
			$natFeesPercentage = $commissionRates['nat_fees_percentage'];
			$stripeFeesPercentage = $commissionRates['stripe_fees_percentage'];

			$rateGroups = BookingUtils::getRateGroups($rateGrpIds, $isPartnerBooking, $cashPriceEnabled);

			$rateGroupWiseRate = $bookingT->pluck('rate', 'tour_package_rate_id')->toArray();
			$rateGroupWiseAdditionalCharge = $bookingT->pluck('additional_charge', 'tour_package_rate_id')->toArray();
			$rateGroupWisePartnerFees = $bookingT->pluck('partner_fees_amount', 'tour_package_rate_id')->toArray();
			$rateGroupWisePartnerFeesValue = $bookingT->pluck('partner_fees_percentage', 'tour_package_rate_id')->toArray();
			$rateGroupWisePartnerFeesType = $bookingT->pluck('partner_fee_type', 'tour_package_rate_id')->toArray();

			foreach ($rateGroups as $rateGroup) {
				if (isset($rateGroupWiseRate[$rateGroup->id])) {
					$rateGroup->rate = $rateGroupWiseRate[$rateGroup->id];
				}

				if (isset($rateGroupWiseAdditionalCharge[$rateGroup->id])) {
					$rateGroup->additional_charge = $rateGroupWiseAdditionalCharge[$rateGroup->id];
				}

				if ($isPartnerBooking == 1 && isset($rateGroupWisePartnerFees[$rateGroup->id])) {
					$rateGroup->partner_fee_amount = $rateGroupWisePartnerFees[$rateGroup->id];
				}

				if ($isPartnerBooking == 1 && isset($rateGroupWisePartnerFeesValue[$rateGroup->id])) {
					$rateGroup->partner_fee_percentage = $rateGroupWisePartnerFeesValue[$rateGroup->id];
				}
				if ($isPartnerBooking == 1 && isset($rateGroupWisePartnerFeesType[$rateGroup->id])) {
					$rateGroup->partner_fee_type = $rateGroupWisePartnerFeesType[$rateGroup->id];
				}
			}

			$trans = $this->transaction::where('tour_booking_id', $request->bookingID)->where('status', 'Completed')->whereNull('charge_type')->orderBy('id', 'DESC')->first();
			$payAmount = $request->payment_amount;
			$refundAmount = $request->refund_amount;
			$infantsorchilds = $request->infantorchilds;

			// This is for Pay Later bookings and infants and payment and refund amounts are same
			if (
				(
					($trans == null)        // Pay Later / no transaction
					|| ($payAmount == 0 && $refundAmount == 0 && $infantsorchilds > 0)    // Zero-pay with infants
					|| (                                                                   // Balanced payment + people added
						($payAmount == $refundAmount
							|| round($refundAmount - $payAmount, 2) == -0.01
							|| round($payAmount - $refundAmount, 2) == 0.01)
						&& (($addedPeopleCount > 0 || $addedInfantsCount > 0) || ($isGroupBooking && $deletedPeopleCount > 0))
					)
					|| ($addedInfantsCount > 0 && $addedPeopleCount == 0)    // Infants added — free pax, bypass payment check
					|| ($deletedInfantsCount > 0 && $deletedPeopleCount == $deletedInfantsCount && $addedPeopleCount == 0 && $addedInfantsCount == 0)    // Only infants deleted, nothing added — free pax, bypass payment check
				)
				&& !(
					!$isGroupBooking
					&& $addedPeopleCount == 0
					&& $addedInfantsCount == 0
					&& $deletedPeopleCount > $deletedInfantsCount  // Exclude when any non-infant adult was deleted (with or without infants), non-group bookings only
				)
			) {
				$discountAmt = 0;
				$result = EditBookingService::processCalculationsChangePeople($request, $rateGroups, $rateGroupWiseAddedPeople, $rateGroupWiseDeletedPeople, $rateGroupWiseTourists, $permitfeeAr, $natFeesPercentage, $oldGroupRateId, $oldGroupRate, $isGroupBooking, $stripeFeesPercentage, $isPartnerBooking);
				$total = $result['total'];
				$paymentTotal = $result['paymentTotal'];
				$refundTotal = $result['refundTotal'];
				$newlyAddedTotal = $result['newlyAddedTotal'];
				$newGroupRateId = $result['newGroupRateId'];
				$tbTransact = $result['tbTransact'];

				// Merge priced price_per_pax add-on deltas into the SAME combined total used for
				// the charge/refund sign decision, so Change People produces one net charge/refund.
				$addonDelta = ChangePeopleAddonService::calculatePricedAddonDelta(
					$request->addons_added ?? [],
					$request->addons_updated ?? [],
					$request->addons_removed ?? [],
					$natFeesPercentage,
					($request->payment_method == 'Card' || ($isCashFees == '1' && $request->payment_method == 'Cash'))
				);
				if ($addonDelta['net_price'] != 0) {
					$total += $addonDelta['net_price'];
					if ($addonDelta['net_price'] > 0) {
						$paymentTotal += $addonDelta['net_price'];
					} else {
						$refundTotal += abs($addonDelta['net_price']);
					}
				}
				$subtt = $total;

				//This is for refund process
				$refundProcess = false;
				if ($total < 0) {
					$refundProcess = true;
				}

				if (!$refundProcess) {
					if ($request->has('discount_type') && $total > 0) {
						$discountAmt = match ($request->discount_type) {
							'Percentage' => round(($total * ($request->discount_percentage ?? 0)) / 100, 2),
							'Fixed Money' => round($request->discount_fixed_money ?? 0, 2),
							default => 0,
						};
					}
				}

				$tt = $total = round($total, 2);
				//This is to exclude infants count from total tourists
				$addedPeopleCount = $addedPeopleCount - $addedInfantsCount;
				$deletedPeopleCount = $deletedPeopleCount - $deletedInfantsCount;

				$totalTourists = $tourBooking->tourists + $addedPeopleCount - $deletedPeopleCount;
				$totalInfants = $tourBooking->infants + $addedInfantsCount - $deletedInfantsCount;

				$tourBookingUpdate = false;
				if ($tourBooking) {
					$updates = [
						'tourists' => $totalTourists,
						'infants' => $totalInfants,
						'discount2_value' => DB::raw('discount2_value+' . $discountAmt),
						'updated_at' => mysqlDT(),
						'updated_by' => Auth::id(),
						'updated_by_user_type' => $userType,
					];

					// Add totals only if it's not a group booking or a new group rate exists
					if (!$isGroupBooking || !empty($newGroupRateId)) {
						// $subtt includes the addon net_price delta merged in above (to get one
						// combined charge/refund sign for Stripe/cash) — but tour_bookings_master
						// .total/.booking_total must stay the TOUR-ONLY total; add-ons are tracked
						// separately via BookingService::fetchAddonsWithPrice()/
						// fetchPayLaterAddonsWithPrice() (addons_gross_total, payLaterAddons, etc.),
						// exactly like the already-paid branch below already does via
						// $subttForPersist = round($subtt - $addonDelta['net_price'], 2). Without
						// this exclusion here too, an addon-only Change People edit on a Pay Later
						// booking permanently bakes the addon's price into .total, corrupting every
						// later "Total Cost" display by that amount (confirmed on booking 90517: an
						// addon removal wrongly persisted a -$15 into .total).
						$subttForPersistPayLater = round($subtt - $addonDelta['net_price'], 2);
						$updates['total'] = DB::raw('total+' . $subttForPersistPayLater);
						$updates['booking_total'] = DB::raw('booking_total+' . $subttForPersistPayLater);
					}

					if (
						!empty($request->discount_percentage) ||
						(!empty($tourBooking->discount2_percentage) && $tourBooking->discount2_percentage > 0)
					) {
						$discountAmountArray = DiscountService::adjustDiscountPercentage($tourBooking, $discountAmt, $total);
						$newDiscountPercent = $discountAmountArray['newDiscountPercent'];
						$newDiscountValue = $discountAmountArray['newDiscountValue'] ?? 0;
						$updatedTotal = $discountAmountArray['updatedTotal'] ?? 0;
						$updates['discount2_percentage'] = $newDiscountPercent;
						if ($updatedTotal > 0) {
							$updates['discount2_value'] = $newDiscountValue;
							$updates['total'] = $updatedTotal;
							$updates['booking_total'] = $updatedTotal;
						}
					}
					$tourBookingUpdate = $tourBooking->update($updates);
				}

				if (!$tourBookingUpdate) {
					throw new Exception('Unable to change people to tour package.');
				}

				for ($a = 0, $ac = count($tbTransact); $a < $ac; $a++) {
					$tbTransact[$a]['tour_booking_id'] = $tourBooking->id;
				}

				$addedPeoplesTexts = array();
				$deletedPeoplesTexts = array();
				$paxIndexToTransactMap = [];
				$rateGroupPaxCounts = [];

				if (!empty($tbTransact)) {
					foreach ($tbTransact as $tbltrans) {
						$rateGroupId = $tbltrans['tour_package_rate_id'];
						if (!isset($rateGroupPaxCounts[$rateGroupId])) {
							$existingCount = $this->bookingTransact::where('tour_package_rate_id', $rateGroupId)
								->where('tour_booking_id', $request->bookingID)
								->where('deleted_by', 0)
								->count();
							$rateGroupPaxCounts[$rateGroupId] = $existingCount;
						}

						$tbTransactexist = $this->bookingTransact::where('tour_package_rate_id', $tbltrans['tour_package_rate_id'])->where('tour_booking_id', $request->bookingID)->where('deleted_by', 0)->first();
						$tourPackageRateGroup = $this->tourPackageRate::find($tbltrans['tour_package_rate_id']);
						if (!empty($tbTransactexist) && isset($tbTransactexist->id)) {

							$updatesTransact = [];
							if ($tbltrans['added'] == true) {
								$addedPeoplesTexts[] = BookingUtils::getPeopleText($isGroupBooking, $tbltrans);
								$updatesTransact = BookingUtils::getTransactionUpdatesChangePeople($tbltrans, $tbTransactexist, $isGroupBooking, $userType);
							} else if ($tbltrans['deleted'] == true) {
								$deletedPeoplesTexts[] = BookingUtils::getPeopleText($isGroupBooking, $tbltrans);
								$updatesTransact = BookingUtils::getTransactionUpdatesChangePeople($tbltrans, $tbTransactexist, $isGroupBooking, $userType);
							}
							unset($tbltrans['rate_for']);
							if ($tbTransactexist->check_in_status != '') {
								$updatesTransact['check_in_status'] = BookingUtils::updateCheckInStatusChangePeople($tbltrans, $tbTransactexist);
							}

							if ($tbTransactexist->redeem_ticket != '') {
								$updatesTransact['redeem_ticket'] = BookingUtils::updateRedeemTicketInfoChangePeople($tbltrans, $tbTransactexist);
							}

							if (isset($updatesTransact) && !empty($updatesTransact)) {
								if ($isGroupBooking != '1') {
									if ($request->payment_method == "Card") {
										$updatesTransact = static::saveCardPermitFeeJson($updatesTransact, $tbTransactexist, $tbltrans, $tourPackageRateGroup);
									} else {
										$updatesTransact = static::saveNonCardPermitFeeJson($updatesTransact, $tbTransactexist, $tbltrans);
									}
								}
							}

							if (isset($updatesTransact) && !empty($updatesTransact)) {
								$this->bookingTransact::where('id', $tbTransactexist->id)->update($updatesTransact);
							}
						} else {
							if ($isGroupBooking == '1' && $newGroupRateId > 0 && $oldGroupRateId != $newGroupRateId) {
								$tbTransactexist = $this->bookingTransact::where('tour_package_rate_id', $oldGroupRateId)->where('tour_booking_id', $request->bookingID)->where('deleted_by', 0)->first();
								if (!empty($tbTransactexist) && isset($tbTransactexist->id)) {
									if (($tbltrans['added'] == true || $tbltrans['deleted'] == true)) {
										$updatesTransact = [];
										if ($tbltrans['added'] == true) {
											$addedPeoplesTexts[] = BookingUtils::getPeopleText($isGroupBooking, $tbltrans);
										} else if ($tbltrans['deleted'] == true) {
											$deletedPeoplesTexts[] = BookingUtils::getPeopleText($isGroupBooking, $tbltrans);
										}
										$updatesTransact = BookingUtils::getTransactionUpdatesChangePeopleGroupBooking($tbltrans, $newGroupRateId, $userType);

										if ($tbTransactexist->check_in_status != '') {
											$updatesTransact['check_in_status'] = BookingUtils::updateCheckInStatusChangePeople($tbltrans, $tbTransactexist);
										}

										if ($tbTransactexist->redeem_ticket != '') {
											$updatesTransact['redeem_ticket'] = BookingUtils::updateRedeemTicketInfoChangePeople($tbltrans, $tbTransactexist);
										}

										if (isset($updatesTransact) && !empty($updatesTransact)) {
											$this->bookingTransact::where('id', $tbTransactexist->id)->update($updatesTransact);
										}
									}
								}
							} else {
								$addedPeoplesTexts[] = $tbltrans['rate_for'] . " person " . ($tbltrans['is_infant_rate'] == 1 ? $tbltrans['infants'] : $tbltrans['tourists']);
								$rateGroupIdForInsert = $tbltrans['tour_package_rate_id'];
								unset($tbltrans['rate_for'], $tbltrans['added'], $tbltrans['deleted']);
								$newTransactId = DB::table('tour_bookings_transact')->insertGetId($tbltrans);

								$paxIndex = $rateGroupPaxCounts[$rateGroupIdForInsert];
								$mapKey = $rateGroupIdForInsert . '_' . $paxIndex;
								$paxIndexToTransactMap[$mapKey] = $newTransactId;
								$rateGroupPaxCounts[$rateGroupIdForInsert]++;
							}
						}
					}
				}

				/* Execute contacts only if booking package has contacts feature enabled */
				$packageHasContacts = $this->tourPackage::find($tourBooking->tour_package_id);

				if ($packageHasContacts->has_contacts == 1) {
					/* Remove Contacts */
					if ($deletedPeopleCount > 0) {
						if (isset($request->contacts)) {
							try {
								PackageHasContactsService::deleteContacts($request->contacts);
							} catch (Exception $ex) {
								Log::error($ex->getMessage());
							}
						}
					}

					/* Add Contacts */
					if ($addedPeopleCount > 0) {
						if (isset($request->new_contacts) && $request->new_contacts != "") {
							try {
								PackageHasContactsService::storeTourBookingPeople($tourBooking->id, $request->new_contacts);
							} catch (Exception $ex) {
								Log::error($ex->getMessage());
							}
						}
					}
				}

				// This branch bypasses real Stripe charge/refund (balanced pay/refund amounts,
				// free-infant-only changes, or — per $trans == null above — a booking with no
				// transaction recorded at all yet). A priced add-on here has no tour-side payment
				// to piggyback on.
				//
				// True "Pay Later" means nothing is owed yet at all — settling the add-on here
				// (and recording a Payment/"Add-ons" history entry for it) would incorrectly show
				// it as already paid/Billable when no money has moved. Leave its field rows
				// exactly as processAddons() below wrote them — genuinely open/unsettled — the
				// same "no transaction row yet" state AddonBookingService::
				// createAddonTransactionsFromFields() already knows how to pick up and settle
				// once a real "Make Payment" happens later.
				//
				// An actual Invoiced/Billable booking (this same $trans === null branch, but
				// $request->payment_method === 'Invoiced' rather than 'Pay Later') DOES settle
				// here — it's a real billing arrangement, not a deferred "nothing yet."
				/* Process pax add-ons changes */
				$addonProcessResult = ['addon_delta' => [], 'field_db_id_map' => []];
				try {
					$addonProcessResult = ChangePeopleAddonService::processAddons($request, $tourBooking->id, $paxIndexToTransactMap, ['precomputed_delta' => $addonDelta]);
					// Nothing collected yet: keep any never-collected 'open' charge of an edited
					// field in step with its new selection, so a later payment settles $18, not $16.
					ChangePeopleAddonService::refreshOpenChargesForUpdatedFields($request->addons_updated ?? []);
				} catch (Exception $ex) {
					Log::error('ChangePeopleAddonService error: ' . $ex->getMessage());
				}

				// See the identical call further down this method (the "real settlement" branch)
				// for why this must run regardless of $request->payment_method — a removed/
				// downgraded field can already be covered by an existing pending remaining_payment
				// 'addon' item from an earlier edit, which nothing else here knows to shrink/cancel.
				if (!empty($addonProcessResult['addon_delta']['refundItems'])) {
					try {
						$this->reduceChangePeopleAddonPaymentLink($addonProcessResult['addon_delta']['refundItems'], $tourBooking);
					} catch (Exception $ex) {
						Log::error('reduceChangePeopleAddonPaymentLink error: ' . $ex->getMessage());
					}
				}

				if ($request->payment_method !== 'Pay Later'
					&& (!empty($addonProcessResult['addon_delta']['chargeItems']) || !empty($addonProcessResult['addon_delta']['refundItems']))) {
					try {
						// Same admin-chosen refund type mapping as the "real" refund branch further
						// down (Update Booking modal's Refund Type radios, via #refund_Type) — only
						// meaningful when net_price < 0 (a removal); ignored for a charge.
						$addonRefundType = match ($request->refund_Type ?? 'dont_refund') {
							'full_refund' => Constants::ADDONS_TICKET_REFUND,
							'100_refund'  => Constants::ADDONS_FULL_REFUND,
							default       => Constants::ADDONS_DONT_REFUND,
						};
						// Mirrors the CHARGE-side equivalent of reduceChangePeopleAddonPaymentLink()
						// just above (which only ever handled the REFUND/downgrade side): an upgraded
						// field whose OLD selection was never actually paid (still sitting on a
						// pending remaining_payment link item — calculatePricedAddonDelta()'s
						// 'supersedes_pending_link' flag) is about to be charged its FULL new price
						// here, via a real Invoiced billing arrangement. Drop the stale pending line
						// now — recalculate=true (no companion finalizeItems() call exists for a
						// non-Card settlement to do this for free, unlike the Card branch further
						// down this method) so the link's amount/token/email reflect the reduced
						// balance immediately, matching TourBookingAddonRepository::
						// syncPendingAddonLinkForEditedFields()'s own non-card branch.
						$supersededFieldIds = array_column(
							array_filter($addonProcessResult['addon_delta']['chargeItems'] ?? [], fn ($item) => !empty($item['supersedes_pending_link'])),
							'db_id'
						);
						if (!empty($supersededFieldIds)) {
							PaymentLinkService::syncPendingAddonLinkItemsForUpdatedFields(
								$tourBooking->id,
								$supersededFieldIds,
								$supersededFieldIds,
								true
							);
						}
						ChangePeopleAddonService::settleFromDelta(
							$addonProcessResult['addon_delta'],
							[
								'action' => $addonDelta['net_price'] < 0 ? 'refund' : 'charge',
								'payment_method' => 'Invoiced',
								'refund_type' => $addonRefundType,
							],
							$tourBooking->id,
							$addonProcessResult['field_db_id_map'] ?? []
						);
					} catch (Exception $ex) {
						Log::error('ChangePeopleAddonService::settleFromDelta error in no-payment bypass branch: ' . $ex->getMessage());
					}
				} elseif ($request->payment_method === 'Pay Later'
					&& (!empty($addonProcessResult['addon_delta']['refundItems']) || !empty($addonProcessResult['addon_delta']['chargeItems']))) {
					// True Pay Later: nothing was ever charged, so settleFromDelta() above is
					// correctly skipped — there's no real money moving either way yet. But
					// processAddons() already wrote/deleted the field rows, so without a history
					// entry the change would be silently invisible in tour_booking_history.
					// Record a $0, blank-payment-method entry per side — same convention used by
					// TourBookingAddonRepository's equivalent Pay Later add/remove cases (and the
					// net-$0 reassignment branch further below).
					if (!empty($addonProcessResult['addon_delta']['refundItems'])) {
						try {
							$removedHistoryItems = array_map(function ($item) {
								return [
									'name' => $item['label'] ?? 'Add-on',
									'price' => $item['price'] ?? 0,
									'fee' => $item['fee'] ?? 0,
									'payment_method' => '',
									'status' => "Don't Refund",
								];
							}, $addonProcessResult['addon_delta']['refundItems']);

							HistoryService::storeAddonsRefundInHistory(
								$tourBooking,
								(object) ['payment_method' => ''],
								['price' => 0, 'fee' => 0, 'transaction_id' => null, 'application_fee_id' => null],
								$removedHistoryItems,
								'removed',
								Constants::ADDONS_DONT_REFUND,
								null,
								(object) ['description' => null]
							);
						} catch (Exception $ex) {
							Log::error('ChangePeopleAddonService error (Pay Later addon-removal history): ' . $ex->getMessage());
						}
					}

					if (!empty($addonProcessResult['addon_delta']['chargeItems'])) {
						try {
							// Mirrors TourBookingAddonRepository::processAddonFinancialTransactions()'s
							// Pay Later/'open' charge branch: no real transactions-ledger row (that
							// stays reserved for a genuine payment — AddonBookingService::
							// createAddonTransactionsFromFields() settles this for real, with its own
							// 'paid' history entry, once an actual "Make Payment" happens later), just
							// a $0/blank-payment-method history entry now so the addition is visible.
							$addedHistoryItems = array_map(function ($item) {
								return [
									'name' => $item['label'] ?? 'Add-on',
									'price' => $item['price'] ?? 0,
									'fee' => $item['fee'] ?? 0,
									'payment_method' => '',
									'status' => 'open',
								];
							}, $addonProcessResult['addon_delta']['chargeItems']);

							HistoryService::storeAddonsPaymentInHistory(
								$tourBooking,
								$addedHistoryItems,
								'added',
								null,
								null,
								'open',
								0,
								0
							);
						} catch (Exception $ex) {
							Log::error('ChangePeopleAddonService error (Pay Later addon-addition history): ' . $ex->getMessage());
						}
					}
				}

				$data = [
					'tourists' => $totalTourists + $totalInfants,
					'sub_operation' => 'Tourists Changed',
					'discount_percentage' => $request->discount_percentage ?: 0,
					'discount2_value' => $discountAmt,
					'addedpeoplesetexts' => $addedPeoplesTexts,
					'deletedpeoplestexts' => $deletedPeoplesTexts,
					'addedtourists' => $addedPeopleCount + $addedInfantsCount,
					'deletedtourits' => $deletedPeopleCount + $deletedInfantsCount,
					'addedinfants' => $addedInfantsCount,
					'deletedinfants' => $deletedInfantsCount,
					'paymenttotal' => $paymentTotal,
					'refundtotal' => $refundTotal
				];

				// Payment link query start — remaining_payment links are managed separately
				$tourBookingPaymentLink = TourBookingPaymentLink::where('order_id', $tourBooking->group_id)
					->where('status', 'Unpaid')
					->where(function ($q) { $q->whereNull('section')->orWhere('section', '!=', 'remaining_payment'); })
					->first();

				if ($tourBookingPaymentLink) {

					// $data['paymenttotal']/['refundtotal'] are pax-ticket-only (calculateChangedTouristsData()
					// never looks at add-ons) — fold in the add-on price delta too (net_price only, NOT
					// net_total: paymentLinkUpdate() computes its own fee on the combined base amount via
					// natFeesPercentage below, so including net_fee here would double-count it), or a
					// pax removal/addition that also drops/adds priced add-ons left the link overstated/
					// understated by exactly the add-on's own worth.
					// $paymentTotal/$refundTotal ALREADY had $addonDelta['net_price'] merged in above
					// (one combined charge/refund sign), so back it out before adding the processed
					// add-on delta — adding it on top counted it twice: a $16 → $18 dropdown change on
					// the same pax moved the link by $4 + fee instead of $2 + fee.
					$addonNetPriceForPayLink = (float) ($addonProcessResult['addon_delta']['net_price'] ?? 0);
					$payLinkSubTotal = $data['paymenttotal'] - $data['refundtotal'] - (float) $addonDelta['net_price'] + $addonNetPriceForPayLink;
					$dataPaymentLink = [
						'amount' => $payLinkSubTotal,
						'natFeesPercentage' => $bookingT[0]->nat_fees_percentage
					];
					PaymentLinkService::paymentLinkUpdate($dataPaymentLink, $info, $tourBooking, $tourBookingPaymentLink, 'Charge People');
				} else {
					// No lump-sum link, but a pending ITEMIZED one (e.g. created by Split Booking):
					// it isn't touched above, so the pax added here would never reach the customer's
					// link. Append the added pax's ticket + fee to it as a pending change_people item.
					$addedPaxTicketCost = round($subtt - $addonDelta['net_price'], 2);
					$hasItemizedLink = TourBookingPaymentLink::where('order_id', $tourBooking->group_id)
						->where('status', 'Unpaid')
						->where('section', 'remaining_payment')
						->exists();

					if ($hasItemizedLink && $addedPaxTicketCost > 0) {
						// Same fee rules as the main path below: the helper's per-pax-rounded sum when
						// pax were only added, a total-based figure otherwise; 6% for pre-oldBookingID
						// non-affiliate bookings; affiliates only pay a fee on newer bookings.
						$addedPaxFees = ($result['serviceCommissionTotal'] > 0 && $deletedPeopleCount == 0)
							? round($result['serviceCommissionTotal'], 2)
							: roundout($addedPaxTicketCost * $natFeesPercentage / 100, 2);

						$itemizedLinkCustomer = $tourBooking->customer_id != 0 ? $this->customer::where('id', $tourBooking->customer_id)->first() : null;

						// Which transact row(s) the added pax landed on — same lookup as the main
						// path's Payment Link branch. Without it the item carried an empty
						// added_transact_data, so the booking page couldn't mark the added pax
						// "Unpaid", and removing them later couldn't find this pending item.
						$addedTransactData = [];
						foreach ($tbTransact as $tbltrans) {
							if (!empty($tbltrans['added']) && $tbltrans['tourists'] > 0) {
								$transactId = DB::table('tour_bookings_transact')
									->where('tour_booking_id', $tourBooking->id)
									->where('tour_package_rate_id', $tbltrans['tour_package_rate_id'])
									->where('deleted_by', 0)
									->value('id');
								if ($transactId) {
									$addedTransactData[] = [
										'transact_id' => $transactId,
										'added_count' => $tbltrans['tourists'],
									];
								}
							}
						}

						PaymentLinkService::upsertRemainingPaymentLink(
							$tourBooking->group_id,
							[
								'type'         => 'change_people',
								'reference_id' => null,
								'amount'       => round($addedPaxTicketCost + $addedPaxFees, 2),
								'reason'       => 'Payment for added guests to your booking',
								'details'      => [
									'tour_booking_id'      => $tourBooking->id,
									'tourists'             => $totalTourists + $totalInfants,
									'ticket_cost'          => $addedPaxTicketCost,
									'platform_fees'        => $addedPaxFees,
									'fee_deferred'         => true,
									'added_transact_data'  => $addedTransactData,
									'created_by_with_name' => $createdByWithName,
								],
							],
							$tourBooking,
							Carbon::parse($info->date . ' ' . $info->time_from),
							$info
						);
					}
				}
				// Payment link query end

				// No pax count changed at all — this edit only touched add-ons, already settled
				// above with its own correct "Add-ons" Payment/Refund history entry. Skip the
				// spurious "Update Pax" / "Edit Booking" entry entirely rather than recording a
				// no-op pax change.
				if ($addedPeopleCount != 0 || $deletedPeopleCount != 0 || $addedInfantsCount != 0 || $deletedInfantsCount != 0) {
					HistoryService::changeTouristInHistory($tourBooking->id, $data, $createdByWithName);
				}
				$seatsDiff = $addedPeopleCount - $deletedPeopleCount;
				TimeSlotAvailabilityService::updateSlotSummary($request->slot_time, $seatsDiff);
				$errors = [];
				$paymentIntentInfo = [
					'clientSecret' => '',
					'transactionId' => '',
				];

				try {
					$arEmailData = [
						'tour_d_t' => $info->date . ' ' . $info->time_from,
						'bookingId' => $request->bookingID,
						'bookingGroupId' => $tourBooking->group_id,
						'custName' => $tourBooking->name,
						'custEmail' => $tourBooking->email,
						'custPhone' => $tourBooking->phone_number
					];

					if (in_array(Auth::user()->email, config('constants.prevent_sending_emails')) == false) {
						EmailService::sendAcknowledgementEmail($info, $arEmailData);
					}
				} catch (Exception $exception) {
					Log::error($exception);
					$errors[] = 'email';
				}
				//Unassign booking from board station
				BoardService::boardBookingUpdate($tourBooking->id);
				DB::commit();
				return [
					'bookingId' => $tourBooking->id,
					'bookingToken' => Crypt::encryptString($tourBooking->id), // for security purpose
					'stripeId' => $paymentIntentInfo['clientSecret'],
					'transactionId' => Crypt::encryptString($paymentIntentInfo['transactionId']),
					'errors' => $errors,
					'errors_message' => !empty($errors_message) ? $errors_message : '',
				];
			}
			if (!$request->is('api/*')) {
				if ($isValidationCheckForBookingChangePeople) {
					// This case is only for pax add-ons Add/Edit no change in PAX Add/Edit/Delete
					if ($addedPeopleCount == 0 && $deletedPeopleCount == 0 && $addedInfantsCount == 0 && $deletedInfantsCount == 0 && $hasAddonChanges) {
						$addonOnlyDelta = ChangePeopleAddonService::calculatePricedAddonDelta(
							$request->addons_added ?? [],
							$request->addons_updated ?? [],
							$request->addons_removed ?? [],
							$natFeesPercentage,
							($request->payment_method == 'Card' || ($isCashFees == '1' && $request->payment_method == 'Cash'))
						);
						// A FREE add-on-only edit can commit in this single preflight round-trip
						// (no payment ever needed, matching today's behavior). A PRICED delta needs
						// the same charge/refund round-trip a pax-count change gets — defer the field
						// writes + financial settlement to the real (validation_check=false) submission
						// below so add-on rows are never written twice and are settled against the
						// actual PaymentIntent/refund for this edit.
						if ($addonOnlyDelta['net_price'] == 0) {
							try {
								// No 'action' here on purpose — processAddons() only writes the
								// tour_booking_addon_fields rows, it does NOT run
								// settleAddonTransactions(). That settlement path prices charge/refund
								// items independently (a same-priced reassignment has a real $15
								// chargeItem AND a real $15 refundItem even though they net to $0) and
								// writes them as TWO separate ledger rows/history entries with their
								// GROSS (not net) amounts — for Pay Later that's correctly left open,
								// but for an already-paid Cash/Card/Invoiced booking it would falsely
								// record a $15 "Payment" and a $15 "Refund" against the real payment
								// method, i.e. phantom money movement for an edit that owes nothing.
								ChangePeopleAddonService::processAddons($request, $tourBooking->id, [], ['precomputed_delta' => $addonOnlyDelta]);

								// Still record ONE plain, $0-money history entry so the reassignment
								// itself isn't silently invisible in tour_booking_history — same
								// convention TourBookingAddonRepository::savePaxAddons() already uses
								// for the identical "add-on moved, net $0" case in the other (non-Change
								// People) pax add-ons editor: one 'Refund' row, zero transaction value,
								// ADDONS_DONT_REFUND, both sides listed via removed/added_addons.
								$reassignedPaymentMethod = $request->payment_method ?: 'Cash';
								$reassignHistoryItem = function ($item) use ($reassignedPaymentMethod) {
									return [
										'name' => $item['label'] ?? 'Add-on',
										'price' => $item['price'] ?? 0,
										'fee' => $item['fee'] ?? 0,
										'payment_method' => $reassignedPaymentMethod,
										'status' => 'Reassigned',
									];
								};
								$removedHistoryItems = array_map($reassignHistoryItem, $addonOnlyDelta['refundItems'] ?? []);
								$addedHistoryItems = array_map($reassignHistoryItem, $addonOnlyDelta['chargeItems'] ?? []);

								if (!empty($removedHistoryItems) || !empty($addedHistoryItems)) {
									HistoryService::storeAddonsRefundInHistory(
										$tourBooking,
										(object) ['payment_method' => $reassignedPaymentMethod],
										['price' => 0, 'fee' => 0, 'transaction_id' => null, 'application_fee_id' => null],
										$removedHistoryItems,
										'removed',
										Constants::ADDONS_DONT_REFUND,
										null,
										(object) ['description' => null],
										$addedHistoryItems
									);
								}
							} catch (Exception $ex) {
								Log::error('ChangePeopleAddonService error: ' . $ex->getMessage());
							}
						}
					}
					DB::commit();
					return response()->json([
						'message' => 'All validation checks were successful!'
					]);
				}
			}
			if (($addedPeopleCount == 0 && $addedInfantsCount == 0 && ($deletedPeopleCount > 0 || $deletedInfantsCount > 0))) {
				$formData = $request->all();
				$formData['clientIp'] =  $request->getClientIp();
				$formData['requestFrom'] = $request->is('api/*') ? Constants::API : Constants::BACKEND;

				/* Process pax add-ons changes for delete-only case — field rows are removed here;
				   deletePeopleChangePeople() below uses this SAME priced delta to also refund the
				   add-on money for the deleted pax, per rate group, alongside its own tour refund. */
				$deleteOnlyAddonDelta = [];
				$deleteOnlyAddonProcessResult = ['field_db_id_map' => []];
				try {
					$deleteOnlyAddonDelta = ChangePeopleAddonService::calculatePricedAddonDelta(
						$request->addons_added ?? [],
						$request->addons_updated ?? [],
						$request->addons_removed ?? [],
						$natFeesPercentage,
						($request->payment_method == 'Card' || ($isCashFees == '1' && $request->payment_method == 'Cash'))
					);
					$deleteOnlyAddonProcessResult = ChangePeopleAddonService::processAddons($request, $request->bookingID, [], ['precomputed_delta' => $deleteOnlyAddonDelta]);
				} catch (Exception $ex) {
					Log::error('ChangePeopleAddonService error: ' . $ex->getMessage());
				}

				// Charge any priced add-ons ADDED for a pax who is NOT being removed in this same
				// edit (e.g. deleting one Adult while also adding a Photography Package to a
				// surviving Children pax). deletePeopleChangePeople() below only ever settles this
				// same delta's refundItems, scoped per rate group to the pax being deleted —
				// chargeItems for a surviving pax are never looked at anywhere in that function.
				// Without this, processAddons() above still writes the tour_booking_addon_fields
				// row, but nothing ever creates a TourBookingAddonTransaction charge row or an
				// "Add-ons" Payment history entry for it — the addition silently never shows up in
				// History & Notes and no money is ever recorded for it.
				if (!empty($deleteOnlyAddonDelta['chargeItems'])) {
					$existingTransactionForAddonCharge = $this->transaction::where('tour_booking_id', $request->bookingID)
						->where('status', 'Completed')
						->whereNull('charge_type')
						->orderBy('id', 'DESC')
						->first();

					if (empty($existingTransactionForAddonCharge)) {
						// True Pay Later: nothing has ever been captured, so there's no combined
						// payment to book this charge against — mirror the identical Pay Later
						// addon-addition bypass used a few hundred lines above in this same method
						// (a plain $0/open history entry, no ledger row) instead of fabricating a
						// "paid" charge for money that was never actually collected.
						try {
							$deleteOnlyAddedHistoryItems = array_map(function ($item) {
								return [
									'name' => $item['label'] ?? 'Add-on',
									'price' => $item['price'] ?? 0,
									'fee' => $item['fee'] ?? 0,
									'payment_method' => '',
									'status' => 'open',
								];
							}, $deleteOnlyAddonDelta['chargeItems']);

							HistoryService::storeAddonsPaymentInHistory(
								$tourBooking, $deleteOnlyAddedHistoryItems, 'added', null, null, 'open', 0, 0
							);
						} catch (Exception $ex) {
							Log::error('ChangePeopleAddonService error (Pay Later addon-addition history, delete-only branch): ' . $ex->getMessage());
						}
					} else {
						try {
							ChangePeopleAddonService::settleFromDelta(
								['chargeItems' => $deleteOnlyAddonDelta['chargeItems'], 'refundItems' => []],
								[
									'action' => 'charge',
									'payment_method' => $request->payment_method,
									'transaction_id' => $existingTransactionForAddonCharge->transaction_number ?? null,
								],
								$request->bookingID,
								$deleteOnlyAddonProcessResult['field_db_id_map'] ?? []
							);
						} catch (Exception $ex) {
							Log::error('ChangePeopleAddonService: addon charge settlement failed in delete-only branch: ' . $ex->getMessage());
						}
					}
				}

				if ($isGroupBooking == '1') {
					$paymentTransCountForBooking = $this->transaction::where('tour_booking_id', $request->bookingID)->where('status', 'Completed')->whereNull('charge_type')->count();
					$res = EditBookingService::deletePaxFromGroupBooking($request, '', $paymentTransCountForBooking, true, $deleteOnlyAddonDelta);
				} else {
					$res = $this->deletePeopleChangePeople($formData, $deleteOnlyAddonDelta);
				}
				if (!empty($res) && isset($res['success']) && $res['success'] == true) {
					// cancelPendingChangePeopleItems is already called inside
					// deletePeopleChangePeople (end of function) — no duplicate call here.
					//update booking on board station
					BoardService::boardBookingUpdate($request->bookingID);
					DB::commit();
					return [
						'bookingId' => $request->bookingID,
						'bookingToken' => Crypt::encryptString($request->bookingID), // for security purpose
					];
				} else {
					throw new Exception('Something went wrong.Unable to change people to tour package.');
				}
			}

			$transactionFirst = $this->transaction::where('status', 'Completed')->where('tour_booking_id', $request->bookingID)->whereNull('charge_type')->first();
			$paymentMethod = (!empty($transactionFirst)) ? $transactionFirst->via : '';
			$isCashPriceApply = ($paymentMethod == 'Cash' && $cashPriceEnabled == 1) ? true : false;

			$discountAmt = 0;
			$tt = 0;
			$serviceCommission = 0;
			$serviceCommissionTotal = 0;
			$serviceCommissionNewlyAddedTotal = 0;
			$newGroupRateId = 0;

			$result = EditBookingService::processCalculationsChangePeople($request, $rateGroups, $rateGroupWiseAddedPeople, $rateGroupWiseDeletedPeople, $rateGroupWiseTourists, $permitfeeAr, $natFeesPercentage, $oldGroupRateId, $oldGroupRate, $isGroupBooking, $stripeFeesPercentage, $isPartnerBooking, $isCashPriceApply);
			$total = $result['total'];

			$paymentTotal = $result['paymentTotal'];
			$refundTotal = $result['refundTotal'];
			$newlyAddedTotal = $result['newlyAddedTotal'];
			$newGroupRateId = $result['newGroupRateId'];
			$touristGroups  = $result['touristGroups'];
			$tbTransact = $result['tbTransact'];
			$partnerFeesTotal = $result['partnerFeesTotal'];
			$refundPartnerFeesTotal = $result['refundPartnerFeesTotal'];
			$netPartnerFeesTotal = ($isPartnerBooking == 1) ? ($partnerFeesTotal - $refundPartnerFeesTotal) : 0;
			$isFeeApplicable = ($request->payment_method == 'Card' || $paymentMethod == 'Card' || ($isCashFees == '1' && ($request->payment_method == 'Cash' || $paymentMethod == 'Cash')) || $request->payment_method == 'Payment Link');
			if ($isFeeApplicable) {
				$serviceCommissionTotal = $result['serviceCommissionTotal'];
			}

			// Merge priced price_per_pax add-on deltas into the SAME combined total used for
			// the charge/refund sign decision, so Change People produces one net charge/refund.
			$addonDelta = ChangePeopleAddonService::calculatePricedAddonDelta(
				$request->addons_added ?? [],
				$request->addons_updated ?? [],
				$request->addons_removed ?? [],
				$natFeesPercentage,
				$isFeeApplicable
			);
			if ($addonDelta['net_price'] != 0) {
				$total += $addonDelta['net_price'];
				if ($addonDelta['net_price'] > 0) {
					$paymentTotal += $addonDelta['net_price'];
				} else {
					$refundTotal += abs($addonDelta['net_price']);
				}
			}
			// $serviceCommissionTotal feeds the "people only added" fast path below (it's used
			// AS-IS instead of recomputing `$total * natFeesPercentage / 100` in that case) — the
			// add-on's own commission must be folded in here too, or it silently drops out of the
			// actual Stripe charge amount even though the add-on PRICE was merged into $total above.
			if ($isFeeApplicable && $addonDelta['net_fee'] != 0) {
				$serviceCommissionTotal += $addonDelta['net_fee'];
			}

			// Add back cost of deleted unpaid pax — Stripe was never charged for them
			$effectiveCpPendingItemIds = $request->cp_pending_item_ids ?? null;

			$unpaidCountByRateGroupIdForMix = PaymentLinkService::unpaidCountByRateGroupFromFormIds(
				$effectiveCpPendingItemIds,
				$request->cp_pending_history_ids ?? null
			);
			$unpaidCostCorrection = PaymentLinkService::computeMixedPathUnpaidCostCorrection(
				$unpaidCountByRateGroupIdForMix,
				$rateGroupWiseDeletedPeopleArray,
				$request->bookingID
			);
			// Capture $total before the correction so that $totalBeforeUnpaidCorrection is
			// available for any code that still needs it. $total itself is then corrected
			// upward by the unpaid-pax cost so that the Stripe charge / refund decision uses
			// the right amount. After the correction we also capture $totalAfterUnpaidCorrection
			// — this is the correct base for the payment-link ticket_cost and for the
			// tour_bookings_master delta: cancelPendingChangePeopleItems already reverses the
			// old cancelled item's contribution, so only the new-pax cost (+correction) belongs
			// in the DB delta, not the net of added minus ALL deleted.
			$totalBeforeUnpaidCorrection = $total;
			if ($unpaidCostCorrection > 0) {
				$total       += $unpaidCostCorrection;
				$refundTotal  = max(0.0, $refundTotal - $unpaidCostCorrection);
			}
			$totalAfterUnpaidCorrection = $total;

			//This is for refund process
			$refundProcess = false;
			if ($total < 0) {
				$refundProcess = true;
			}

			//This is for partner fees refund payout
			$refundPartnerFees = false;
			if ($netPartnerFeesTotal < 0) {
				$refundPartnerFees = true;
				$netPartnerFeesTotal = abs($netPartnerFeesTotal);
			}

			//This is to exclude infants count from total tourists
			$addedPeopleCount = $addedPeopleCount - $addedInfantsCount;
			$deletedPeopleCount = $deletedPeopleCount - $deletedInfantsCount;

			$totalTourists = $tourBooking->tourists + $addedPeopleCount - $deletedPeopleCount;
			$totalInfants = $tourBooking->infants + $addedInfantsCount - $deletedInfantsCount;
			$subtt = $totalAfterUnpaidCorrection;
			if (!$refundProcess) {
				if ($request->has('discount_type')) {
					$discountAmt = match (true) {
						$request->discount_type === 'Percentage' && !empty($request->discount_percentage) =>
						round(($total * $request->discount_percentage) / 100, 2),

						$request->discount_type === 'Fixed Money' && !empty($request->discount_fixed_money) =>
						round($request->discount_fixed_money, 2),

						default => 0,
					};
					$total -= $discountAmt;
					$subtt -= $discountAmt;
				}
			}

			$checkaffiliate = null;
			if ($tourBooking->customer_id != 0) {
				$checkaffiliate = $this->customer::where('id', $tourBooking->customer_id)->first();
			}

			if (!$refundProcess) {
				if (($request->payment_method == "Card" || $request->payment_method == 'Payment Link' || ($isCashFees == '1' && $request->payment_method == 'Cash')) && $checkaffiliate->is_affiliate == 'No') {
					//This is for old bookings
					if ($request->bookingID < $oldBookingID) {
						$serviceCommission = $total * 6 / 100;
						$total += $serviceCommission;
						if ($newlyAddedTotal > 0) {
							$newlyAddedTotal += $newlyAddedTotal * 6 / 100;
						}
					} else {
						if ($serviceCommissionTotal > 0 && $deletedPeopleCount == 0) { //This is the calculations if people only added
							$serviceCommission = $serviceCommissionTotal;
						} else {
							$serviceCommission = roundout(($total * $natFeesPercentage / 100), 2); //This is the calculations if people only added and deleted both
						}
						$total += $serviceCommission;
						if ($newlyAddedTotal > 0) {
							if ($serviceCommissionNewlyAddedTotal > 0 && $deletedPeopleCount == 0) { //This is the calculations if people only added
								$newlyAddedTotal += $serviceCommissionNewlyAddedTotal;
							} else {
								$newlyAddedTotal += roundout(($newlyAddedTotal * $natFeesPercentage / 100), 2); //This is the calculations if people only added and deleted both
							}
						}
					}
				}

				if (($request->payment_method == "Card" || $request->payment_method == 'Payment Link' || ($isCashFees == 1 && $request->payment_method == 'Cash')) && $checkaffiliate->is_affiliate == 'Yes') {
					if ($request->bookingID > $oldBookingID) {
						if ($serviceCommissionTotal > 0 && $deletedPeopleCount == 0) {
							$serviceCommission = $serviceCommissionTotal;
						} else {
							$serviceCommission = roundout(($total * $natFeesPercentage / 100), 2);
						}
						$total += $serviceCommission;
						if ($newlyAddedTotal > 0) {
							if ($serviceCommissionNewlyAddedTotal > 0 && $deletedPeopleCount == 0) {
								$newlyAddedTotal += $serviceCommissionNewlyAddedTotal;
							} else {
								$newlyAddedTotal += roundout(($newlyAddedTotal * $natFeesPercentage / 100), 2);
							}
						}
					}
				}
			}

			$tt = $total = round($total, 2);
			$serviceCommission = round($serviceCommission, 2);

			// $serviceCommission includes this request's own add-on fee (folded in above so the
			// ACTUAL STRIPE CHARGE — $total — comes out correct). tour_bookings_master.service_commission
			// is a running total that feeds the "Booking Fees" line on the booking page
			// (tour-booking-info.blade.php), which separately adds pricedAddons['addons_final_fee']
			// freshly computed from every currently-active add-on — persisting $serviceCommission
			// as-is here would double-count this add-on's fee in that display every time people are
			// added alongside a priced add-on. Persist the ticket-only portion instead — the same
			// subtraction already used for the tour-only ledger row's own serviceCommission field
			// further down ($tourOnlyServiceCommission).
			$serviceCommissionForPersist = round($serviceCommission - $addonDelta['net_fee'], 2);

			// Same double-counting risk as above, for the running total itself: $total/$subtt both
			// include this request's own add-on price+fee (needed for the ACTUAL STRIPE CHARGE
			// amount). tour_bookings_master.total/booking_total feed the "Booking Total" line,
			// which separately adds pricedAddons['addons_payment_total'] freshly computed from
			// every currently-active add-on — persisting the addon-inclusive total here would
			// double-count this add-on's price+fee in that display. Persist the tour-only portion
			// instead — the same subtraction already used for the tour-only ledger row's own total
			// fields further down ($tourOnlyTotal / $tourOnlySubtt).
			// Use $totalAfterUnpaidCorrection (= $total after restoring unpaid-pax cost) so that
			// the DB delta for tour_bookings_master reflects only the newly-added pax cost.
			// cancelPendingChangePeopleItems reverses the old cancelled item's contribution
			// separately, so we must NOT re-subtract the deleted unpaid pax cost here.
			// NOTE: only subtract net_price here. $addonDelta['net_fee'] was folded into
			// $serviceCommissionTotal (line above), not into $total — so $totalAfterUnpaidCorrection
			// never contains it. The fee is already stripped from $serviceCommissionForPersist via
			// ($serviceCommission - $addonDelta['net_fee']). Subtracting it here too would
			// double-subtract it, causing master.total to be short by the addon fee amount.
			$totalForPersist = round($totalAfterUnpaidCorrection - $addonDelta['net_price'], 2);
			$subttForPersist = round($subtt - $addonDelta['net_price'], 2);

			$paymentOnly = $this->tourBookingHistory::where('tour_booking_id', $request->bookingID)
				->where('operation', 'Payment')
				->get([
					'id',
					'ticket_cost',
					'processing_fees',
					'platform_fees'
				]);

			$paymentOnlyCheck = 0;
			foreach ($paymentOnly as $value) {
				$paymentOnlyCheck += $value->ticket_cost + $value->processing_fees + $value->platform_fees;
			}

			$splitPendingAmount = 0;
			$splitPendingAmount = round($tourBooking->total - $paymentOnlyCheck, 2);

			$transP = $this->transaction::where('status', 'Completed')->where('tour_booking_id', $request->bookingID)->whereNull('charge_type')->first();
			$doNotRefund = 0;
			if ($refundProcess && !empty($transP) && ($transP->via == 'Card' || ($isCashFees == 1 && $transP->via == 'Cash'))) {
				$trans = $this->transaction::where('tour_booking_id', $request->bookingID)
					->where('status', 'Completed')
					->whereNull('charge_type')
					->orderBy('id', 'DESC')
					->first();

				if (!empty($trans) && ($transP->via == "Card" || ($isCashFees == 1 && $transP->via == 'Cash')) && $trans->payment_type == 1) {
					$doNotRefund = 1;
				}
			}

			$tourBookingUpdate = false;
			if ($tourBooking) {
				$partialRefunds = $this->tourBookingHistory::where('tour_booking_id', $request->bookingID)->where('operation', 'Refund')->whereIn('payment_method', ['Partial Refund', '100 % Refund', 'Full Refund minus Fees', 'Permitfees Refund', "Don't Refund"])->get();

				$bookingT = $this->bookingTransact::with('packageRate')
					->where('tour_booking_id', $request->bookingID)
					->where('deleted_by', 0)
					->get();

				// Calculate the booking amount because old bookings data have booking_total in tour_booking_master table is 0
				$calculatedAmounts = BookingService::calculateBookingAmountChangePeople($request, $bookingT, $natFeesPercentage, $oldBookingID, $rateGroupWiseAddedPeopleArray, $rateGroupWiseDeletedPeopleArray, $isCashFees, $paymentMethod, $isGroupBooking);
				$bookingTotal = $calculatedAmounts['bookingTotal'];
				$refundedPermitFeesTotalAmount = $calculatedAmounts['refundedPermitFeesTotalAmount'];
				$refundedProcessingFeesTotal = $calculatedAmounts['refundedProcessingFeesTotal'];
				$serviceCommissionOldTotal = $calculatedAmounts['serviceCommissionOldTotal'];

				if ($tourBooking->discount2_value > 0 && $bookingTotal > 0) {
					$bookingTotal -= $tourBooking->discount2_value;
				}

				$serviceCommissionOld = 0;
				if (($request->payment_method == "Card" || ($isCashFees == 1 && $request->payment_method == 'Cash')) && $checkaffiliate->is_affiliate == 'No') {
					if ($request->bookingID < $oldBookingID) {
						$serviceCommissionOld = ($bookingTotal + $refundedPermitFeesTotalAmount + $refundedProcessingFeesTotal) * 6 / 100;
						$bookingTotal += $serviceCommissionOld;
					} else {
						if ($serviceCommissionOldTotal > 0) {
							$serviceCommissionOld = $serviceCommissionOldTotal;
						} else {
							$serviceCommissionOld = round((($bookingTotal + $refundedPermitFeesTotalAmount + $refundedProcessingFeesTotal) * $natFeesPercentage / 100), 2);
						}
						$bookingTotal += $serviceCommissionOld;
					}
				}

				if (($request->payment_method == "Card" || ($isCashFees == 1 && $request->payment_method == 'Cash')) && $checkaffiliate->is_affiliate == 'Yes' && $natFeesPercentage > 0 && $request->bookingID > $oldBookingID) {
					if ($serviceCommissionOldTotal > 0) {
						$serviceCommissionOld = $serviceCommissionOldTotal;
					} else {
						$serviceCommissionOld = round((($bookingTotal + $refundedPermitFeesTotalAmount + $refundedProcessingFeesTotal) * $natFeesPercentage / 100), 2);
					}
					$bookingTotal += $serviceCommissionOld;
				}

				//This is for adjust calculation of booking total on booking info page if partial refunds done
				if ($refundProcess) {
					$bookingTotal += abs($total);
				}

				$partialRefundAmount = BookingService::calculatePartialRefundAmount($partialRefunds);
				$bookingTotal += $partialRefundAmount;

				$bookingTotal = round($bookingTotal, 2);
				$transactionFirst = $this->transaction::where('status', 'Completed')->where('tour_booking_id', $tourBooking->id)->whereNull('charge_type')->first();
				// Never reachable with a null $transactionFirst before the Split Booking payment-link
				// fix (a $trans == null booking was always intercepted by the "Pay Later" fast path
				// earlier in this method) — now that an explicit Card/Payment Link choice on such a
				// booking falls through to here, this must tolerate no prior transaction existing at
				// all, same as the earlier assignment of this same variable a few hundred lines above.
				$paymentMethod = !empty($transactionFirst) ? $transactionFirst->via : '';

				if ($refundProcess && ($paymentMethod == 'Card' || ($isCashFees == 1 && $paymentMethod == 'Cash'))) {
					if ($doNotRefund == 1) {
						$rateCheck = $this->bookingTransact::where('tour_booking_id', $tourBooking->id)->where('deleted_by', 0)->first();
						$stripeFeesPercentage = $rateCheck->stripe_fees_percentage;
						$serviceCommissionPercentage = $rateCheck->nat_fees_percentage;
						if ($request->bookingID < $oldBookingID) {
							if ($customer->is_affiliate === "No") {
								$setFeeAmount = (abs($total) * 6) / 100;
							}
						} else {
							$setFeeAmount = (abs($total) * $serviceCommissionPercentage) / 100;
						}

						$setFeeAmount = number_format((float)$setFeeAmount, 2, '.', '');
						$setFeeAmount = (float)$setFeeAmount;
						$tourBookingSetTotal = $tourBooking->total - (abs($total) + $setFeeAmount);
						$permitFeeUpdate = ($tourBookingSetTotal * $stripeFeesPercentage) / 100;
						$updates = [
							'tourists' => $totalTourists,
							'infants' => $totalInfants,
							'discount2_value' => DB::raw('discount2_value+' . $discountAmt),
							'service_commission' => $permitFeeUpdate,
							'booking_total' => $tourBookingSetTotal,
							'total' => $tourBookingSetTotal,
							'updated_at' => mysqlDT(),
							'updated_by' => Auth::id(),
							'updated_by_user_type' => $userType,
						];
					} else {
						$updates = [
							'tourists' => $totalTourists,
							'infants' => $totalInfants,
							'discount2_value' => DB::raw('discount2_value+' . $discountAmt),
							'service_commission' => DB::raw('service_commission+' . (($request->payment_method == "Card" || ($isCashFees == '1' && $request->payment_method == 'Cash')) ? $serviceCommissionForPersist : 0)),
							'total' => DB::raw('total+' . (($request->payment_method == "Card" || ($isCashFees == '1' && $request->payment_method == 'Cash')) ? ($totalForPersist + $serviceCommissionForPersist) : $subttForPersist)),
							'booking_total' => DB::raw('booking_total+' . (($request->payment_method == "Card" || ($isCashFees == '1' && $request->payment_method == 'Cash')) ? ($totalForPersist + $serviceCommissionForPersist) : $subttForPersist)),
							'updated_at' => mysqlDT(),
							'updated_by' => Auth::id(),
							'updated_by_user_type' => $userType,
						];
					}
				} else if ($refundProcess && $paymentMethod == 'Cash' && $isCashFees != 1) {
					$updates = [
						'tourists' => $totalTourists,
						'infants' => $totalInfants,
						'discount2_value' => DB::raw('discount2_value+' . $discountAmt),
						'service_commission' => DB::raw('service_commission+' . ($request->payment_method == "Card" ? $serviceCommissionForPersist : 0)),
						'total' => DB::raw('total+' . ($totalForPersist + $serviceCommissionForPersist)),
						'booking_total' => DB::raw('booking_total+' . ($totalForPersist + $serviceCommissionForPersist)),
						'updated_at' => mysqlDT(),
						'updated_by' => Auth::id(),
						'updated_by_user_type' => $userType,
					];
				} else {
					// 'Payment Link' deliberately excluded from the fee component of every column
					// below (unlike Card/cash-fee-Cash): those two collect money in THIS same
					// request, so the fee is genuinely already collected/owed. A Payment Link is
					// only sent here, not paid — baking its fee into total/booking_total/
					// service_commission immediately made a booking whose OWN established baseline
					// is fee-free (e.g. a booking created via Payment Link, confirmed total/
					// booking_total/service_commission all start at pure ticket cost, no fee at
					// all) silently pick up a partial fee mid-edit, before any money moved. For the
					// lump-sum shape (no tour_booking_payment_link_items), the real fee gets correctly
					// (re)computed fresh from live transact rows once the link is actually paid, via
					// PaymentLinkService::bookingUpdate() -> CartService::calculateTotalAmount(), so
					// nothing is lost by not writing it here. For the itemized (remaining_payment)
					// shape, ChangePeopleItemHandler::finalize() now writes it at actual payment time
					// instead (see its own comment) — this is the other half of that same fix.
					$feeCollectedNow = ($request->payment_method == "Card" || ($isCashFees == '1' && $request->payment_method == 'Cash'));
					$updates = [
						'tourists' => $totalTourists,
						'infants' => $totalInfants,
						'discount2_value' => DB::raw('discount2_value+' . $discountAmt),
						'service_commission' => DB::raw('service_commission+' . ($feeCollectedNow ? $serviceCommissionForPersist : 0)),
						'total' => DB::raw('total+' . ($totalForPersist + ($feeCollectedNow ? $serviceCommissionForPersist : 0))),
						'booking_total' => DB::raw('booking_total+' . ($totalForPersist + ($feeCollectedNow ? $serviceCommissionForPersist : 0))),
						'updated_at' => mysqlDT(),
						'updated_by' => Auth::id(),
						'updated_by_user_type' => $userType,
					];
				}

				if (!empty($request->discount_percentage) || (!empty($tourBooking->discount2_percentage) && $tourBooking->discount2_percentage > 0)) {
					$oldDiscountedTotalWithoutServiceCharge = $tourBooking->total - $tourBooking->service_commission;
					$originalTotalOld = $oldDiscountedTotalWithoutServiceCharge + $tourBooking->discount2_value;

					$newDiscountedTotalWithoutServiceCharge = $total - $serviceCommission;
					$originalTotalNew = $newDiscountedTotalWithoutServiceCharge + $discountAmt;

					$newDiscountPercent = round(100 - (
						($oldDiscountedTotalWithoutServiceCharge + $newDiscountedTotalWithoutServiceCharge) * 100 /
						($originalTotalOld + $originalTotalNew)
					), 2);

					$updates['discount2_percentage'] = $newDiscountPercent;
				}

				$tourBookingUpdate = $tourBooking->update($updates);
			}

			for ($a = 0, $ac = count($tbTransact); $a < $ac; $a++) {
				$tbTransact[$a]['tour_booking_id'] = $tourBooking->id;
			}

			$addedPeoplesTexts = array();
			$deletedPeoplesTexts = array();
			$paxIndexToTransactMap = [];
			$rateGroupPaxCounts = [];
			if (!empty($tbTransact)) {
				foreach ($tbTransact as $tbltrans) {
					$rateGroupId = $tbltrans['tour_package_rate_id'];
					if (!isset($rateGroupPaxCounts[$rateGroupId])) {
						$existingCount = $this->bookingTransact::where('tour_package_rate_id', $rateGroupId)
							->where('tour_booking_id', $request->bookingID)
							->where('deleted_by', 0)
							->count();
						$rateGroupPaxCounts[$rateGroupId] = $existingCount;
					}
					$tbTransactexist = $this->bookingTransact::where('tour_package_rate_id', $tbltrans['tour_package_rate_id'])->where('tour_booking_id', $request->bookingID)->where('deleted_by', 0)->first();
					$tourPackageRateGroup = $this->tourPackageRate::find($tbltrans['tour_package_rate_id']);

					if (!empty($tbTransactexist) && isset($tbTransactexist->id)) {
						if ($tbltrans['added'] == true) {
							$addedPeoplesTexts[] = BookingUtils::getPeopleText($isGroupBooking, $tbltrans);
						} else if ($tbltrans['deleted'] == true) {
							$deletedPeoplesTexts[] = BookingUtils::getPeopleText($isGroupBooking, $tbltrans);
						}
						EditBookingService::updateTblTransactChangePeople($tbltrans, $tbTransactexist, $request->payment_method, $isGroupBooking, $userType);
					} else {
						if ($isGroupBooking == '1' && $newGroupRateId > 0 && $oldGroupRateId != $newGroupRateId) {
							$tbTransactexist = $this->bookingTransact::where('tour_package_rate_id', $oldGroupRateId)->where('tour_booking_id', $request->bookingID)->where('deleted_by', 0)->first();
							if (!empty($tbTransactexist) && isset($tbTransactexist->id)) {
								EditBookingService::updateTblTransactChangeGroupPeople($tbltrans, $tbTransactexist, $newGroupRateId, $userType);
								if ($tbltrans['added'] == true) {
									$addedPeoplesTexts[] = BookingUtils::getPeopleText($isGroupBooking, $tbltrans);
								} else if ($tbltrans['deleted'] == true) {
									$deletedPeoplesTexts[] = BookingUtils::getPeopleText($isGroupBooking, $tbltrans);
								}
							}
						} else {
							$addedPeoplesTexts[] = $tbltrans['rate_for'] . " person " . ($tbltrans['is_infant_rate'] == 1 ? $tbltrans['infants'] : $tbltrans['tourists']);
							$rateGroupIdForInsert = $tbltrans['tour_package_rate_id'];
							unset($tbltrans['rate_for'], $tbltrans['added'], $tbltrans['deleted']);
							$newTransactId = DB::table('tour_bookings_transact')->insertGetId($tbltrans);

							$paxIndex = $rateGroupPaxCounts[$rateGroupIdForInsert];
							$mapKey = $rateGroupIdForInsert . '_' . $paxIndex;
							$paxIndexToTransactMap[$mapKey] = $newTransactId;
							$rateGroupPaxCounts[$rateGroupIdForInsert]++;
						}
					}
				}
			}

			// No pre-read needed: cancelled pending items were UNPAID (never charged),
			// so their cost is not a credit against the new pax. The new payment link
			// is always for the full cost of the newly added pax.

			// Cancel pending payment-link items for any deleted unpaid pax (mixed path).
			// Uses $effectiveCpPendingItemIds which includes auto-detected items when the
			// form did not supply cp_pending_item_ids explicitly.
			PaymentLinkService::cancelPendingChangePeopleItems(
				$effectiveCpPendingItemIds ?? null,
				$request->cp_pending_history_ids ?? null
			);
			// For Card payment, the combined PI already includes the pending addon amount —
			// leave the items in place so createPaymentIntent()/createBookingCard() can
			// finalize them via RemainingPaymentService::finalizeItems(), which writes the
			// proper history + transaction records. For other methods, cancel them now.
			if (strtolower((string) ($request->payment_method ?? '')) !== 'card') {
				PaymentLinkService::cancelPendingAddonLinkItemsForBooking((int) $tourBooking->id);
			}
			/* Execute only when booking package has contacts feature enabled */
			$packageHasContacts = $this->tourPackage::find($tourBooking->tour_package_id);

			if ($packageHasContacts->has_contacts == 1) {
				/* Remove contacts */
				if ($deletedPeopleCount > 0) {
					if (isset($request->contacts)) {
						try {
							PackageHasContactsService::deleteContacts($request->contacts);
						} catch (Exception $ex) {
							Log::error($ex->getMessage());
						}
					}
				}

				/* Add contacts */
				if ($addedPeopleCount > 0) {
					if (isset($request->new_contacts) && $request->new_contacts != "") {
						try {
							PackageHasContactsService::storeTourBookingPeople($tourBooking->id, $request->new_contacts);
						} catch (Exception $ex) {
							Log::error($ex->getMessage());
						}
					}
				}
			}

			/* Process pax add-ons changes (field rows only — financial settlement happens below
			   once the real combined charge/refund for this edit has actually resolved) */
			$addonProcessResult = ['addon_delta' => [], 'field_db_id_map' => []];
			try {
				$addonProcessResult = ChangePeopleAddonService::processAddons($request, $tourBooking->id, $paxIndexToTransactMap, ['precomputed_delta' => $addonDelta]);
			} catch (Exception $ex) {
				Log::error('ChangePeopleAddonService error: ' . $ex->getMessage());
			}

			// A removed/downgraded field can already be covered by an EXISTING pending
			// remaining_payment 'addon' item from an earlier edit made via "Pay with Link" —
			// this edit's own settlement below runs against whatever payment_method THIS submission
			// picked (Card/Cash/Invoiced), which has no idea that separate pending item exists, so
			// without this it's left stuck at its old, now-too-high amount forever. Unconditional
			// (not gated on $request->payment_method) and safe to call even when no such link
			// exists — reduceChangePeopleAddonPaymentLink() no-ops in that case.
			if (!empty($addonProcessResult['addon_delta']['refundItems'])) {
				try {
					$this->reduceChangePeopleAddonPaymentLink($addonProcessResult['addon_delta']['refundItems'], $tourBooking);
				} catch (Exception $ex) {
					Log::error('reduceChangePeopleAddonPaymentLink error: ' . $ex->getMessage());
				}
			}

			$createdByWithName = BookingService::createdUserInfo();

			$paymentTotal = round($paymentTotal, 2);
			$refundTotal = round($refundTotal, 2);

			// Add-ons get their OWN separate "Payment"/"Refund" history entry (see
			// ChangePeopleAddonService::settleFromDelta()) — keep the "Update Pax" / tour-side
			// Payment/Refund entries showing ONLY the tour amount so the two aren't double-counted.
			if ($addonDelta['net_price'] > 0) {
				$paymentTotal = round($paymentTotal - $addonDelta['net_price'], 2);
			} elseif ($addonDelta['net_price'] < 0) {
				$refundTotal = round($refundTotal - abs($addonDelta['net_price']), 2);
			}

			$data = [
				'tourists' => $totalTourists + $totalInfants,
				'sub_operation' => 'Tourists Changed',
				'discount_percentage' => $request->discount_percentage ?: 0,
				'discount2_value' => $discountAmt,
				'addedpeoplesetexts' => $addedPeoplesTexts,
				'deletedpeoplestexts' => $deletedPeoplesTexts,
				'addedtourists' => $addedPeopleCount + $addedInfantsCount,
				'deletedtourits' => $deletedPeopleCount + $deletedInfantsCount,
				'addedinfants' => $addedInfantsCount,
				'deletedinfants' => $deletedInfantsCount,
				'paymenttotal' => $paymentTotal,
				'refundtotal' => $refundTotal
			];

			//This is for refund process
			if ($refundProcess) {
				$transactionFirst = $this->transaction::where('status', 'Completed')->where('tour_booking_id', $tourBooking->id)->whereNull('charge_type')->first();
				// $transactionFirst can be null here — same guard as the earlier assignment of
				// this variable (a Card/Payment Link edit on a never-paid booking with a pending
				// remaining-payment link can reach this refund branch too, e.g. a net downgrade).
				$paymentMethod = !empty($transactionFirst) ? $transactionFirst->via : '';

				// The admin's chosen refund type for this whole edit (the "Update Booking"
				// modal's Refund Type radios, mirrored into the hidden #refund_Type field) — same
				// field + mapping editBooking()'s direct delete-pax flow already uses for the
				// identical add-on settlement. One admin choice governs BOTH the tour-side refund
				// and the add-on's own refund settlement below (settleFromDelta()); "Partial
				// Refund" is a manually-typed TOUR-ONLY amount, so — matching that same existing
				// convention — it maps to "don't touch add-ons" here, same as no selection at all.
				$addonRefundType = match ($request->refund_Type ?? 'dont_refund') {
					'full_refund' => Constants::ADDONS_TICKET_REFUND,
					'100_refund'  => Constants::ADDONS_FULL_REFUND,
					default       => Constants::ADDONS_DONT_REFUND,
				};

				// Stripe must actually move the add-on's own fee delta too when the admin's
				// refund type calls for it (Weather/100% Refund) — the charge-side equivalent
				// already folds the add-on's fee into $total via $serviceCommissionTotal (a few
				// hundred lines up), but that merge lives entirely inside the `if (!$refundProcess)`
				// block and never runs here. Without this, the fee got recorded as refunded in the
				// ledger below (settleFromDelta(), driven by this SAME $addonRefundType) but was
				// never actually included in the real Stripe refund amount.
				$addonFeeToRefund = $addonRefundType === Constants::ADDONS_FULL_REFUND ? $addonDelta['net_fee'] : 0;
				$total += $addonFeeToRefund;

				if ($paymentMethod == 'Cash' || $paymentMethod == 'Invoiced') {
					$total = abs($total);
					// Add-ons get their OWN separate refund ledger/history row (settleFromDelta()
					// below) — this row must show ONLY the tour-side refund amount. $total now
					// carries the addon's fee delta too (folded in above), so it must be backed out
					// here as well or it leaks into this tour-only figure.
					$tourOnlyRefundAmount = round($total + $addonDelta['net_price'] + $addonFeeToRefund, 2);

					// No pax count changed AND nothing owed on the tour side — this edit only
					// touched add-ons. Skip the tour-side Refund/history write entirely (it would
					// otherwise still record a spurious "$0.00 Update Pax Refund" history entry
					// and an empty tour-side `transactions` row) — the add-on's own refund gets
					// its OWN correct "Refund" Payment history entry via settleFromDelta() below.
					$skipTourSideLedger = $addedPeopleCount == 0 && $deletedPeopleCount == 0
						&& $addedInfantsCount == 0 && $deletedInfantsCount == 0
						&& $tourOnlyRefundAmount == 0;

					$transactionId = null;
					$historyId = null;
					if (!$skipTourSideLedger) {
						$transactionId = TransactionService::storeRefundInTransaction($tourBooking->id, $tourOnlyRefundAmount, '', $paymentMethod, null, null);

						if ($isPartnerBooking == 1 && $transactionFirst->id != '') {
							if ($total > 0) {
								ThreeWayPaymentService::storeReverseTransferInPayout($tourBooking->id, $transactionFirst->id, $transactionId ?? null, $total - $netPartnerFeesTotal, $netPartnerFeesTotal, 'partial_refund', $paymentMethod);
							}
						}
						$historyId = HistoryService::storeRefundDataInHistory(
							$tourBooking->id,
							$totalTourists + $totalInfants,
							$createdByWithName,
							null, /* $comment */
							'Partial Refund', /* $refundType */
							null, /* $transaction */
							$tourOnlyRefundAmount,
							null, /* $cardNumber */
							[], /* $cardsArray */
							[], /* $partialAmountArray */
							$paymentMethod,
							$paymentTotal,
							$refundTotal,
							0,
							null,
							0,
							null,
							$netPartnerFeesTotal
						);

						$data['txnhistoryid'] = $historyId;
						HistoryService::changeTouristInHistory($tourBooking->id, $data, $createdByWithName);
					}
				} else if ($paymentMethod == 'Card') {
					$total = abs($total);
					// Add-ons get their OWN separate refund ledger/history row (settleFromDelta()
					// below) — the tour-side row/history must show ONLY the tour-side refund
					// amount. The actual Stripe refund call below stays on the combined $total
					// (it's one real refund covering both). $total now carries the addon's fee
					// delta too (folded in above), so it must be backed out here as well or it
					// leaks into this tour-only figure.
					$tourOnlyRefundAmount = round($total + $addonDelta['net_price'] + $addonFeeToRefund, 2);

					// Same "nothing on the tour side" check as the Cash/Invoiced branch above —
					// but here it ONLY skips the ledger-anchor + "Update Pax Refund" history write.
					// The Stripe refund call and partner-transfer reversal below stay unconditional
					// (guarded solely by $total > 0, unrelated to this flag): $total can be > 0
					// purely from the add-on's own money even when nothing tour-side changed, and
					// that money still has to actually move via Stripe regardless.
					$skipTourSideLedger = $addedPeopleCount == 0 && $deletedPeopleCount == 0
						&& $addedInfantsCount == 0 && $deletedInfantsCount == 0
						&& $tourOnlyRefundAmount == 0;

					// When this edit only touched add-ons ($skipTourSideLedger) and the admin
					// picked "Don't Refund," $total is ENTIRELY the add-on's own money — there is
					// no tour-side amount mixed in to justify still moving it. Skip the Stripe
					// refund (and everything that depends on it: partner-fee reversal, card-number
					// lookup, the tour-side ledger/history write) entirely; settleFromDelta() below
					// still records the add-on's own $0.00 "Don't Refund" history entry regardless.
					$skipStripeRefundForAddonOnly = $skipTourSideLedger && $addonRefundType === Constants::ADDONS_DONT_REFUND;

					$transactionId = null;
					$historyId = null;
					if ($total > 0 && !$skipStripeRefundForAddonOnly) {
						//This is for to reverse ticket cost from partner account if partner package
						$transId = ($request->has('checked_transactions') && $request->checked_transactions != '') ? $request->checked_transactions : $transactionFirst->transaction_number;
						$trans = $this->transaction::where('transaction_number', $transId)->where('status', 'Completed')->whereNull('charge_type')->first();
						$piMode = $transactionFirst->payment_mode;
						$netPartnerAmountsForTrans = ($isPartnerBooking == 1 && $doNotRefund == 0) ? ThreeWayPaymentService::getNetPartnerAmountsForTransaction($tourBooking->id, $trans->transaction_number) : 0;  //Get net ticket cost without partner fees
						$netTicketCostForTrans = $netPartnerAmountsForTrans['netTicketCost'] ?? 0;

						//Below line is for to check if the partial refund value is greater than net ticket cost and refund from partner fees amount for selected transaction
						$refundAmountFromConnectedAccountForTrans = 0;
						if ($isPartnerBooking == 1 && $netTicketCostForTrans > 0) {
							if ($netTicketCostForTrans < $total) {
								$refundAmountFromConnectedAccountForTrans = $netTicketCostForTrans;
							} else {
								$refundAmountFromConnectedAccountForTrans = $total;
							}
						}

						if ($isPartnerBooking == 1 && $doNotRefund == 0 && $refundAmountFromConnectedAccountForTrans > 0) {
							ThreeWayPaymentService::reverseTransfer($tourBooking->id, $trans->id, $refundAmountFromConnectedAccountForTrans);
						}
						if ($request->has('checked_transactions') && $request->checked_transactions != '') {
							$transID = $request->checked_transactions;
							// The admin explicitly picked this transaction, which is not necessarily
							// $transactionFirst — look up its own persisted payment_mode rather than
							// assuming it matches whichever transaction happened to be "first". No
							// fallback if it's missing: a checked_transactions value with no matching
							// row is a genuine data problem that should surface loudly, not be papered
							// over with an assumed mode.
							$checkedTransaction = Transaction::where('transaction_number', $transID)->firstOrFail();
							$piMode = $checkedTransaction->payment_mode;
							StripeService::processStripeRefund($transID, $total, $checkedTransaction->payment_mode);
						} else {
							if (!empty($transactionFirst->transaction_number) && $doNotRefund == 0) {
								$transID = $transactionFirst->transaction_number;
								StripeService::processStripeRefund($transID, $total, $transactionFirst->payment_mode);
							}
						}

						// No pax count changed AND nothing owed on the tour side — this edit only
						// touched add-ons, so skip the ledger-anchor + "Update Pax Refund" history
						// write (the Stripe refund above already moved the add-on's own money; its
						// own correct "Refund" Payment history entry comes from settleFromDelta()
						// below). $doNotRefund's card-number resolution stays unconditional — it's
						// needed either way if some OTHER caller ever reads $cardNumber from scope.
						if ($doNotRefund == 0) {
							$cardDetails = BookingService::cardLastFourDigit($tourBooking->id, $transID);
							$cardNumber = (!empty($cardDetails)) ? $cardDetails['card_last_4_digit'] : '';
						} else {
							$cardNumber = '';
						}

						if (!$skipTourSideLedger) {
							if ($doNotRefund == 0) {
								$transactionId = TransactionService::storeRefundInTransaction($tourBooking->id, $tourOnlyRefundAmount, '', $paymentMethod, ($doNotRefund == 1) ? null : $transID, null, mode: $piMode);
								//This is to store reverse transfer for partner package
								if ($isPartnerBooking == 1 && $transID != '') {
									if ($refundAmountFromConnectedAccountForTrans > 0) {
										ThreeWayPaymentService::storeReverseTransferInPayout($tourBooking->id, $trans->id, $transactionId ?? null, $refundAmountFromConnectedAccountForTrans, $netPartnerFeesTotal, 'partial_refund', 'Card');
									}
								}
							}

							$historyId = HistoryService::storeRefundDataInHistory(
								$tourBooking->id,
								$totalTourists + $totalInfants,
								$createdByWithName,
								null, /* $comment */
								($doNotRefund == 1) ? "Don't Refund" : 'Partial Refund', /* $refundType */
								null, /* $transaction */
								$tourOnlyRefundAmount,
								$cardNumber,
								[], /* $cardsArray */
								[], /* $partialAmountArray */
								$paymentMethod,
								$paymentTotal,
								$refundTotal,
								$tourOnlyRefundAmount,
								null,
								0,
								null,
								($doNotRefund == 0) ? $netPartnerFeesTotal : 0
							);

							$data['txnhistoryid'] = $historyId;
							HistoryService::changeTouristInHistory($tourBooking->id, $data, $createdByWithName);
						}
					}
				}

				if ($doNotRefund == 0) {
					RefundBookingService::run($transactionId ?? null, $historyId, $paymentMethod);
				}

				// Settle priced add-on refunds against this SAME combined Stripe refund — no
				// second Stripe call, and reuse the tour-side ledger row (ledger_transaction_id)
				// instead of creating a second `transactions` row for the same money.
				if (!empty($addonProcessResult['addon_delta']['chargeItems']) || !empty($addonProcessResult['addon_delta']['refundItems'])) {
					ChangePeopleAddonService::settleFromDelta(
						$addonProcessResult['addon_delta'],
						[
							'action' => 'refund',
							'payment_method' => $paymentMethod,
							'transaction_id' => $transID ?? ($transactionFirst->transaction_number ?? null),
							'ledger_transaction_id' => $transactionId ?? null,
							'refund_type' => $addonRefundType,
						],
						$tourBooking->id,
						$addonProcessResult['field_db_id_map'] ?? []
					);
				}

				$seatsDiff = $addedPeopleCount - $deletedPeopleCount;
				TimeSlotAvailabilityService::updateSlotSummary($request->slot_time, $seatsDiff);
				//Unassign booking from board station
				BoardService::boardBookingUpdate($tourBooking->id);
				DB::commit();

				return [
					'bookingId' => $tourBooking->id,
					'bookingToken' => Crypt::encryptString($tourBooking->id), // for security purpose
				];
			} else {
				// When the unpaid-pax correction brings $tt to exactly $0 with no add-on charges,
				// no Stripe or Payment Link action is needed (a $0 PI / $0 link is rejected by Stripe).
				// Pax counts and booking_total are already written above; delegate history + commit.
				// Payment Link path handles $tt=0 itself (cancel old link, no new link) — skip here.
				if ($request->payment_method !== 'Payment Link' && ChangePeopleZeroNetService::applies((float) $tt, (float) $addonDelta['net_price'], (float) $addonDelta['net_fee'])) {
					$zeroNetHistData = [
						'tourists'            => $totalTourists + $totalInfants,
						'addedpeoplesetexts'  => $addedPeoplesTexts,
						'deletedpeoplestexts' => $deletedPeoplesTexts,
						'addedtourists'       => $addedPeopleCount + $addedInfantsCount,
						'deletedtourits'      => $deletedPeopleCount + $deletedInfantsCount,
						'addedinfants'        => $addedInfantsCount,
						'deletedinfants'      => $deletedInfantsCount,
						'paymenttotal'        => $paymentTotal,
						'refundtotal'         => $refundTotal,
					];
					return ChangePeopleZeroNetService::commit(
						$tourBooking,
						$zeroNetHistData,
						$addedPeopleCount,
						$deletedPeopleCount,
						$request->slot_time,
						$createdByWithName
					);
				}
				if ($request->payment_method == 'Cash' || $request->payment_method == 'Pay Later' || $request->payment_method == 'Invoiced') {
					$paymentMethod = ($request->payment_method == 'Pay Later' || $request->payment_method == 'Invoiced') ? 'Invoiced' : 'Cash';
					$changeAmount = 0;

					if ($request->payment_method === "Cash") {
						$cashPaidAmount = $request->has('cash_paid_amount') && $request->cash_paid_amount !== ''
							? $request->cash_paid_amount
							: '';

						$paymentAmountCash = !empty($request->split_value)
							? $request->split_value
							: ($isCashFees == 1 ? $tt : $subtt);

						// Calculate change amount if cash paid is more than required amount
						if (!empty($cashPaidAmount) && $cashPaidAmount > $paymentAmountCash) {
							$changeAmount = round($cashPaidAmount - $paymentAmountCash, 2);
						}

						// Ensure change is 0 if no cash amount is provided
						if (empty($cashPaidAmount)) {
							$changeAmount = 0;
						}
					}

					if ($isCashFees == 1 && $request->payment_method == "Cash") {
						$totalAmount = !empty($request->split_value) ? $request->split_value : $tt;

						if ($tourBooking->id < $oldBookingID) {
							if ($customer->is_affiliate === 'Yes') {
								$feesAmount = ($totalAmount - ($totalAmount * 2.9 / 100));
							} else {
								$feesAmount = ($totalAmount - ($totalAmount * 8.9 / 100));
							}
						} else {
							$tourBookingTransaction = $this->bookingTransact::where('tour_booking_id', $tourBooking->id)->where('deleted_by', 0)->first();
							$feesAmount = ($totalAmount - ($totalAmount * $tourBookingTransaction->stripe_fees_percentage / 100));
						}
						if (!empty($request->split_value)) {
							$feesAmount = $totalAmount - $feesAmount;
							$feesAmount = roundout($feesAmount, 2);
						} else {
							$feesAmount = $serviceCommission;
						}
					} else {
						$totalAmount = !empty($request->split_value) ? $request->split_value : $subtt;
						$feesAmount = 0;
					}

					// Add-ons get their OWN separate "Payment" ledger/history row
					// (settleFromDelta() below) — keep this tour-side row/history showing ONLY
					// the tour amount. Split payments are a manually-entered partial amount, not
					// derived from $tt/$subtt, so there's nothing to net out in that case.
					if (empty($request->split_value)) {
						$totalAmount = round($totalAmount - $addonDelta['net_price'] - $addonDelta['net_fee'], 2);
						if ($isCashFees == 1 && $request->payment_method == 'Cash') {
							$feesAmount = round($feesAmount - $addonDelta['net_fee'], 2);
						}
					}

					// No pax count changed AND nothing owed on the tour side — this edit only
					// touched add-ons. Skip the tour-side Payment/history write entirely (it would
					// otherwise still record a spurious "$0.00 Update Pax Payment" history entry
					// and an empty tour-side `transactions` row) — the add-on's own charge gets its
					// OWN correct "Add-ons" Payment history entry via settleFromDelta() below.
					$skipTourSideLedger = $addedPeopleCount == 0 && $deletedPeopleCount == 0
						&& $addedInfantsCount == 0 && $deletedInfantsCount == 0
						&& $totalAmount == 0;

					$transactionId = null;
					$historyId = null;
					if (!$skipTourSideLedger) {
						$paymentType = (!empty($request->split_value) || $splitPendingAmount > 0) ? 1 : 0;
						$transactionId = TransactionService::storePaymentInTransaction($tourBooking->id, $totalAmount, $feesAmount, $paymentMethod, $paymentType, null, null);

						$data = [
							'tourists' => $totalTourists + $totalInfants,
							'amount' => $totalAmount,
							'payment_type' => $paymentMethod,
							'payment_method' => (!empty($request->split_value) || $splitPendingAmount > 0) ? 'Split Payment' : 'Full Payment',
							'paymenttotal' => $paymentTotal,
							'refundtotal' => $refundTotal,
						];

						$historyId = HistoryService::storeCashPaymentInHistory($tourBooking->id, $totalTourists + $totalInfants, $data, $changeAmount, $createdByWithName);

						//Below line is for to store payout for partner package
						if ($isPartnerBooking == 1) {
							$payoutData = [
								'amount' => $totalAmount,
								'platform_fees' => $feesAmount,
								'partner_fees' => $netPartnerFeesTotal,
								'booking_id' => $tourBooking->id,
								'transaction_id' => $transactionId,
								'package_id' => $tourBooking->tour_package_id,
								'payment_method' => $paymentMethod
							];
							ThreeWayPaymentService::transferToPartner($payoutData);
						}
						// Below line is for to update tour booking history table
						$isSplitOrFull = (!empty($request->split_value) || $splitPendingAmount > 0) ? 'Split Payment' : 'Full Payment';
						if ($paymentMethod == 'Cash') {
							if ($isCashFees == 1) {
								$tourBookingData = [
									'booking_id' => $request->bookingID,
									'customer_id' => $tourBooking->customer_id,
									'is_pax_added' => true,
								];
								CardBookingService::run($tourBookingData, $transactionId, $historyId, $isSplitOrFull, $request->all() + ['is_pax_added' => true]);
							} else {
								CashBookingService::run($tourBooking, $transactionId, $historyId, $isSplitOrFull, $request->all() + ['is_pax_added' => true]);
							}
						} elseif ($paymentMethod === 'Invoiced') {
							InvoicedBookingService::run($tourBooking, $transactionId, $historyId, $isSplitOrFull, $request->all() + ['is_pax_added' => true]);
						}
						//Below line is for to update tour booking history table for change people
						$changePeopleData = [
							'tourists' => $totalTourists + $totalInfants,
							'discount_percentage' => $request->discount_percentage ? $request->discount_percentage : 0,
							'discount2_value' => $discountAmt,
							'addedpeoplesetexts' => $addedPeoplesTexts,
							'deletedpeoplestexts' => $deletedPeoplesTexts,
							'addedtourists' => $addedPeopleCount + $addedInfantsCount,
							'deletedtourits' => $deletedPeopleCount + $deletedInfantsCount,
							'addedinfants' => $addedInfantsCount,
							'deletedinfants' => $deletedInfantsCount,
							'paymenttotal' => $paymentTotal,
							'refundtotal' => $refundTotal,
							'txnhistoryid' => $historyId
						];

						HistoryService::changeTouristInHistory($tourBooking->id, $changePeopleData, $createdByWithName);
					}

					// Settle priced add-on charges against this SAME cash/invoiced payment — no
					// separate charge, and reuse the tour-side ledger row instead of creating a
					// second `transactions` row for the same money.
					//
					// This edit never showed the "Update Booking" refund-type modal (that only
					// appears for an actual pax DELETION, handled separately by
					// deletePeopleChangePeople()) — this branch is reached whenever the overall
					// tour-side amount is a CHARGE, e.g. adding a person while also reassigning/
					// removing an add-on elsewhere. Without an explicit 'refund_type' here,
					// settleAddonTransactions() defaulted to 'ticket_refund' (fee kept) for any
					// embedded refundItems — silently recording the item's fee as "kept" even
					// though nothing was ever actually collected for it beyond the tour amount
					// (net_price/net_fee are folded into the SAME PaymentIntent above, and a true
					// reassignment nets those to $0). 'full_refund' makes the add-on side of the
					// ledger/history net to the same $0 the real payment actually moved, instead
					// of a phantom kept fee no admin ever chose.
					if (!empty($addonProcessResult['addon_delta']['chargeItems']) || !empty($addonProcessResult['addon_delta']['refundItems'])) {
						// See the identical drop below (the Card branch) and in the earlier
						// no-payment-bypass branch above for why this must also run here: an upgraded
						// field whose OLD selection was never actually paid (still sitting on a
						// pending remaining_payment link item) is about to be charged its FULL new
						// price via this real Cash/Invoiced payment. recalculate=true since no
						// companion finalizeItems() call exists for a non-Card settlement to
						// recompute the link's amount/token/email afterward.
						$supersededFieldIds = array_column(
							array_filter($addonProcessResult['addon_delta']['chargeItems'] ?? [], fn ($item) => !empty($item['supersedes_pending_link'])),
							'db_id'
						);
						if (!empty($supersededFieldIds)) {
							PaymentLinkService::syncPendingAddonLinkItemsForUpdatedFields(
								$tourBooking->id,
								$supersededFieldIds,
								$supersededFieldIds,
								true
							);
						}
						ChangePeopleAddonService::settleFromDelta(
							$addonProcessResult['addon_delta'],
							[
								'action' => 'charge',
								'payment_method' => $paymentMethod,
								'ledger_transaction_id' => $transactionId,
								'refund_type' => 'full_refund',
							],
							$tourBooking->id,
							$addonProcessResult['field_db_id_map'] ?? []
						);
					}

					$seatsDiff = $addedPeopleCount - $deletedPeopleCount;
					TimeSlotAvailabilityService::updateSlotSummary($request->slot_time, $seatsDiff);
				} elseif ($request->payment_method == 'Payment Link') {
					// Pax change applied immediately; record a pending payment entry and send a payment link.
					$addedTransactData = [];
					foreach ($tbTransact as $tbltrans) {
						if (!empty($tbltrans['added']) && $tbltrans['tourists'] > 0) {
							$transactId = DB::table('tour_bookings_transact')
								->where('tour_booking_id', $tourBooking->id)
								->where('tour_package_rate_id', $tbltrans['tour_package_rate_id'])
								->where('deleted_by', 0)
								->value('id');
							if ($transactId) {
								$addedTransactData[] = [
									'transact_id' => $transactId,
									'added_count' => $tbltrans['tourists'],
								];
							}
						}
					}
					// No pending history record is created when the payment link is sent.
					// All relevant data is stored on the payment link item (details column)
					// so finalize() can insert the real history entry when payment is received.
					$changePeopleData = [
						'tourists'            => $totalTourists + $totalInfants,
						'addedpeoplesetexts'  => $addedPeoplesTexts,
						'deletedpeoplestexts' => $deletedPeoplesTexts,
						'addedtourists'       => $addedPeopleCount + $addedInfantsCount,
						'deletedtourits'      => $deletedPeopleCount + $deletedInfantsCount,
						'addedinfants'        => $addedInfantsCount,
						'deletedinfants'      => $deletedInfantsCount,
						'paymenttotal'        => $paymentTotal,
						'refundtotal'         => $refundTotal,
					];
					HistoryService::changeTouristInHistory($tourBooking->id, $changePeopleData, $createdByWithName);

					$seatsDiff = $addedPeopleCount - $deletedPeopleCount;
					TimeSlotAvailabilityService::updateSlotSummary($request->slot_time, $seatsDiff);

					// $subttForPersist already excludes priced add-on price ($addonDelta['net_price'])
					// so it represents only the pax ticket cost for this change.
					// Cancelled pending items were unpaid (never charged), so their cost is NOT
					// a credit — the new payment link always covers the full new-pax cost.
					$paymentLinkTicketCost = $subttForPersist;

					// Always compute fees as a percentage of the final ticket cost.
					// $serviceCommission can fold in add-on fees or cover more pax than
					// $paymentLinkTicketCost reflects, so using it directly would overcharge.
					if ($checkaffiliate->is_affiliate === 'No') {
						$paymentLinkFees = ($request->bookingID < $oldBookingID)
							? roundout($paymentLinkTicketCost * 6 / 100, 2)
							: roundout($paymentLinkTicketCost * $natFeesPercentage / 100, 2);
					} elseif ($checkaffiliate->is_affiliate === 'Yes' && $request->bookingID > $oldBookingID) {
						$paymentLinkFees = roundout($paymentLinkTicketCost * $natFeesPercentage / 100, 2);
					} else {
						$paymentLinkFees = 0;
					}

					$paymentLinkAmount = round($paymentLinkTicketCost + $paymentLinkFees, 2);

					$slotDateTime = Carbon::parse($info->date . ' ' . $info->time_from);

					// When $tt=0 or the link amount works out to zero (all form pax were
					// covered by the cancelled cp_pending items — no truly new pax to charge),
					// skip upsertRemainingPaymentLink — Stripe rejects $0-amount links.
					if ($paymentLinkAmount > 0) {
						PaymentLinkService::upsertRemainingPaymentLink(
							$tourBooking->group_id,
							[
								'type'         => 'change_people',
								'reference_id' => null,
								'amount'       => $paymentLinkAmount,
								'reason'       => 'Payment for added guests to your booking',
								'details'      => [
									'tour_booking_id'      => $tourBooking->id,
									'tourists'             => $totalTourists + $totalInfants,
									'ticket_cost'          => $paymentLinkTicketCost,
									'platform_fees'        => $paymentLinkFees,
									// The fee is NOT on service_commission yet (see the $updates above):
									// finalize() records it once paid; cancelling must not subtract it.
									'fee_deferred'         => true,
									'added_transact_data'  => $addedTransactData,
									'created_by_with_name' => $createdByWithName,
								],
							],
							$tourBooking,
							$slotDateTime,
							$info
						);
					}

					// If this change-people edit also added priced add-ons, create a separate
					// 'addon' payment link item so AddonItemHandler::finalize() can settle
					// the addon transactions when the customer pays.
					$this->upsertChangePeopleAddonPaymentLink(
						$addonDelta,
						$checkaffiliate,
						$oldBookingID,
						$request,
						$natFeesPercentage,
						$tourBooking,
						$addonProcessResult,
						$createdByWithName,
						$slotDateTime,
						$info
					);

				}
			}
			if ($refundProcess || (!$refundProcess && ($request->payment_method == 'Cash' || $request->payment_method == 'Pay Later' || $request->payment_method == 'Invoiced' || $request->payment_method == 'Payment Link'))) {
				DB::commit();
			}
			//Unassign booking from board station
			BoardService::boardBookingUpdate($tourBooking->id);
		} catch (\Throwable $exception) {
			DB::rollBack();
			Log::error($exception);
			// GeneralCoreException only accepts ?Exception — wrap \Error instances.
			$wrapped = $exception instanceof Exception
				? $exception
				: new Exception($exception->getMessage(), (int) $exception->getCode(), $exception);
			throw new GeneralCoreException($wrapped);
		}

		$errors = [];

		$paymentIntentInfo = [
			'clientSecret' => '',
			'transactionId' => '',
		];

		try {
			$arEmailData = [
				'tour_d_t' => $info->date . ' ' . $info->time_from,
				'bookingId' => $request->bookingID,
				'bookingGroupId' => $tourBooking->group_id,
				'custName' => $tourBooking->name,
				'custEmail' => $tourBooking->email,
				'custPhone' => $tourBooking->phone_number
			];

			if ($request->payment_method == 'Cash' || $request->payment_method == 'Pay Later' || $paymentMethod == 'Cash' || $paymentMethod == 'Invoiced') {
				if (in_array(Auth::user()->email, config('constants.prevent_sending_emails')) == false) {
					EmailService::sendAcknowledgementEmail($info, $arEmailData);
				}
			}
		} catch (Exception $exception) {
			Log::error($exception);
			$errors[] = 'email';
		}

		if ($request->payment_method == 'Pay Later' || $request->payment_method == 'Payment Link') {
			DB::commit();

			return [
				'bookingId' => $tourBooking->id,
				'bookingToken' => Crypt::encryptString($tourBooking->id), // for security purpose
				'stripeId' => $paymentIntentInfo['clientSecret'],
				'transactionId' => Crypt::encryptString($paymentIntentInfo['transactionId']),
				'errors' => $errors,
				'message' => $request->payment_method === 'Payment Link' ? 'Payment link sent successfully.' : null,
			];
		}
		if ($request->payment_method == 'Card') {
			// Add-ons get their OWN separate "Payment" ledger/history row (settleFromDelta()
			// below, matching the one_time/price_per_unit convention at booking creation) — this
			// $data array drives the tour-side `transactions` row + "Payment" history entry via
			// createPaymentIntent()/createBookingCard(), so it must show ONLY the tour amount.
			$tourOnlyTotal = round($tt - $addonDelta['net_price'] - $addonDelta['net_fee'], 2);
			$tourOnlySubtt = round($subtt - $addonDelta['net_price'], 2);
			$tourOnlyServiceCommission = round($serviceCommission - $addonDelta['net_fee'], 2);

			// Nothing changed on the tour side at all (no pax added/removed, no infants
			// added/removed, and the recomputed tour-only amount is genuinely $0) — this edit only
			// touched add-ons. createPaymentIntent()/createBookingCard() below would otherwise
			// still write a spurious $0.00 tour-side `transactions` row + "Update Pax Payment"
			// history entry even though only the add-on's own money (its own separate "Add-ons"
			// history entry, via ChangePeopleAddonService::settleFromDelta() further down) actually
			// changed hands.
			$data = [
				'skip_tour_side_ledger' => ($addedPeopleCount == 0 && $deletedPeopleCount == 0
					&& $addedInfantsCount == 0 && $deletedInfantsCount == 0
					&& $tourOnlyTotal == 0),
				'total' => $tourOnlyTotal,
				'customer_id' => $tourBooking->customer_id,
				'customer_name' => $tourBooking->name,
				'customer_email' => $tourBooking->email,
				'customer_phone' => $tourBooking->phone_number,
				'tourists' => $totalTourists + $totalInfants,
				'booking_id' => $tourBooking->id,
				'group_id' => $tourBooking->group_id,
				'partnerFees' => $netPartnerFeesTotal,
				'isPartnerPackage' => $isPartnerBooking,
				'partner_destination_id' => $info->packageDestinationId,
				'tour_package' => $info->package_name,
				'date' => $info->date,
				'time_from' => $info->time_from,
				'subtotal' => $tourOnlySubtt,
				'serviceCommission' => $tourOnlyServiceCommission,
				'destination' => $info->tourOperatorDestinationId,
				'slot_time' => $request->slot_time,
				'tour_operator_id' => $info->tour_operator_id,
				'statement_descriptor' => $info->statement_descriptor,
				'card_reader_prefix' => $info->card_reader_prefix,
				'note' => $request->tour_operator_note,
				'booked_by_staff' => $request->booked_by_staff,
				'split_value' => $request->split_value,
				'split_pending_amount' => $splitPendingAmount,
				'api' => $request->api,
				'change_people' => 1,
				'discount_percentage' => $request->discount_percentage ? $request->discount_percentage : 0,
				'discount2_value' => $discountAmt,
				'addedpeoplesetexts' => $addedPeoplesTexts,
				'deletedpeoplestexts' => $deletedPeoplesTexts,
				'addedtourists' => $addedPeopleCount,
				'deletedtourits' => $deletedPeopleCount,
				'paymenttotal' => $paymentTotal,
				'refundtotal' => $refundTotal,
				'is_pax_added' => true,
				'webhook' => !empty($request->webhook) ? 1 : 0,
				'tour_package_id' => $info->tour_package_id,
				'custom_charge' => [],
				'custom_charge_amount' => 0, // Check if custom charge is applied
				'custom_charge_fees' => 0,
				'addon_price' => $addonDelta['net_price'],
				'addon_fee' => $addonDelta['net_fee'],
				'addon_total' => round($addonDelta['net_price'] + $addonDelta['net_fee'], 2),
				'payment_intent_id' => ($request->has('payment_intent_id') && $request->payment_intent_id != '') ? $request->payment_intent_id : ''
			];
			$paymentIntentId = ($request->has('payment_intent_id') && $request->payment_intent_id != '') ? $request->payment_intent_id : '';

			// Save the card details
			HistoryService::getSavedCardFromPaymentIntent($paymentIntentId, $data['booking_id'], "BACKEND");
			if ($request->has('feature') && $request->feature == 'change_people') {
				$data['from'] = 'Web Manual Card';
			}

			// Drop any pending remaining_payment link line whose field's FULL new price this same
			// PaymentIntent is about to charge (calculatePricedAddonDelta()'s 'supersedes_pending_link'
			// flag) — BEFORE createBookingCard()/createPaymentIntent() below, which finalizes the
			// pending link's remaining Unpaid items via RemainingPaymentService::finalizeItems().
			// Doing this after that call (as an earlier version of this fix did) is too late:
			// finalizeItems() would already have settled the old, stale pending amount as a SEPARATE
			// paid entry before settleFromDelta() ever ran, producing two ledger entries for the
			// same add-on instead of one. Mirrors
			// TourBookingAddonRepository::syncPendingAddonLinkForEditedFields()'s identical ordering
			// for the single-passenger addon-edit flow (sync/drop, THEN finalize).
			$supersededFieldIds = array_column(
				array_filter($addonProcessResult['addon_delta']['chargeItems'] ?? [], fn ($item) => !empty($item['supersedes_pending_link'])),
				'db_id'
			);
			if (!empty($supersededFieldIds)) {
				PaymentLinkService::syncPendingAddonLinkItemsForUpdatedFields(
					$tourBooking->id,
					$supersededFieldIds,
					$supersededFieldIds,
					false
				);
			}

			if ($request->has('api') && $request->api == 1) {

				if ($paymentIntentId == '') {
					throw new Exception('Card payment could not be processed. Please refresh the page and try again.');
				}
				$data['payment_intent_id'] = $paymentIntentId;
				$paymentIntentInfo = $this->createBookingCard($data);
			} else {
				$paymentIntentInfo = $this->createPaymentIntent($data);
			}

			// Settle priced add-on charges against this SAME confirmed PaymentIntent — no
			// separate charge, and reuse the tour-side ledger row (ledger_transaction_id) instead
			// of creating a second `transactions` row for the same money.
			//
			// This edit never showed the "Update Booking" refund-type modal (that only appears
			// for an actual pax DELETION, handled separately by deletePeopleChangePeople()) —
			// this branch is reached whenever the overall tour-side amount is a CHARGE, e.g.
			// adding a person while also reassigning/removing an add-on elsewhere (same PaymentIntent
			// as the tour charge; addon_price/addon_total folded into $tourOnlyTotal above are the
			// NET delta, so a true reassignment charges/collects $0 extra for the add-on side).
			// Without an explicit 'refund_type' here, settleAddonTransactions() defaulted to
			// 'ticket_refund' (fee kept) for any embedded refundItems — recording the removed
			// item's fee as "kept" in `transactions`/`tour_booking_history` even though nothing
			// beyond the tour amount was ever actually charged via Stripe for it. 'full_refund'
			// makes the add-on side of the ledger/history net to the same $0 the real payment
			// actually moved, instead of a phantom kept fee no admin ever chose.
			if (empty($paymentIntentInfo['ex']) && (!empty($addonProcessResult['addon_delta']['chargeItems']) || !empty($addonProcessResult['addon_delta']['refundItems']))) {
				ChangePeopleAddonService::settleFromDelta(
					$addonProcessResult['addon_delta'],
					[
						'action' => 'charge',
						'payment_method' => 'Card',
						'transaction_id' => $paymentIntentId,
						'ledger_transaction_id' => $paymentIntentInfo['transactionId'] ?? null,
						'refund_type' => 'full_refund',
					],
					$tourBooking->id,
					$addonProcessResult['field_db_id_map'] ?? []
				);
			}

			if (isset($paymentIntentInfo['nextAction'])) {
				$tourBooking->stripe_paymentintent_id = $paymentIntentInfo['clientSecret'];
				$tourBooking->save();
				DB::commit();

				return [
					'bookingId' => $tourBooking->id,
					'bookingToken' => Crypt::encryptString($tourBooking->id), // for security purpose
					'stripeId' => $paymentIntentInfo['clientSecret'],
					'require3ds' => 1,
					'nextAction' => $paymentIntentInfo['nextAction'],
					'errors' => $errors,
					'errors_message' => !empty($errors_message) ? $errors_message : ''
				];
			}

			if ($paymentIntentInfo['clientSecret'] == '') {
				$errors[] = 'payment';
			}

			if (!empty($paymentIntentInfo['ex'])) {
				$errors_message = $paymentIntentInfo['ex']->getError()->message;
				DB::rollBack();
			}
		}
		if ($request->payment_method == 'Card' && isset($paymentIntentInfo['clientSecret']) && $paymentIntentInfo['clientSecret'] == '' && isset($paymentIntentInfo['ex']) && !empty($paymentIntentInfo['ex'])) {
			DB::rollBack();
		} else {
			DB::commit();
		}

		return [
			'bookingId' => $tourBooking->id,
			'bookingToken' => Crypt::encryptString($tourBooking->id), // for security purpose
			'stripeId' => $paymentIntentInfo['clientSecret'],
			'transactionId' => Crypt::encryptString($paymentIntentInfo['transactionId']),
			'errors' => $errors,
			'errors_message' => !empty($errors_message) ? $errors_message : '',
			'operation_at' => mysqlDT()
		];
	}

	/**
	 * Remove the people from booking
	 *
	 * @param array $data
	 */
	private function deletePeopleChangePeople($data, array $addonRefundDelta = [])
	{
		DB::beginTransaction();
		try {
			if (isset($data['api']) && $data['api'] == 1) {
				if (isset($data['permit_fee'][0])) {
					$data['permit_fee'] = explode(",", $data['permit_fee'][0]);
				}

				if (isset($data['rate_group'][0])) {
					$data['rate_group'] = explode(",", $data['rate_group'][0]);
				}

				if (isset($data['tourists'][0])) {
					$data['tourists'] = explode(",", $data['tourists'][0]);
				}
			}

			$bookingID = $data['bookingID'];
			$isCashFees = cashFees();

			$tourBooking = $this->tourBooking::find($bookingID);
			$packageHasContacts = $this->tourPackage::find($tourBooking->tour_package_id);
			$isPartnerBooking = $tourBooking->is_partner_booking;

			$bookingT = DB::table('tour_bookings_transact AS tbt')
				->join('tour_package_rates AS tpr', 'tpr.id', '=', 'tbt.tour_package_rate_id')
				->where('tbt.tour_booking_id', $data['bookingID'])
				->where('tbt.deleted_by', 0)
				->orderByDesc('tpr.age_from')
				->orderByDesc('tpr.age_to')
				->get(['tpr.rate_for', 'tbt.tour_package_rate_id', 'tbt.tourists', 'tbt.infants', 'tbt.total']);

			$rateGroupWiseTourists = array();
			$totalTouristsOfBooking = 0;
			foreach ($bookingT as $value) {
				$rateGroupWiseTourists[$value->tour_package_rate_id] = ($value->infants > 0) ? $value->infants : $value->tourists;
				$totalTouristsOfBooking += $value->tourists + $value->infants;
			}

			$deletedPeopleCount = 0;
			$rateGroupWisedeletedPeople = array();
			$rateGroupWisedeletedPeopleArray = array();
			for ($a = 0, $ac = count($data['tourists']); $a < $ac; $a++) {
				$rateGroupWisedeletedPeople[$a] = 0;

				if (isset($data['rate_group'][$a]) && isset($rateGroupWiseTourists[$data['rate_group'][$a]]) && $data['tourists'][$a] < $rateGroupWiseTourists[$data['rate_group'][$a]]) {
					$deletedPeopleCount += $rateGroupWiseTourists[$data['rate_group'][$a]] - $data['tourists'][$a];
					$rateGroupWisedeletedPeople[$a] = (int)$rateGroupWiseTourists[$data['rate_group'][$a]] - $data['tourists'][$a];
					$rateGroupWisedeletedPeopleArray[$data['rate_group'][$a]] = $rateGroupWisedeletedPeople[$a];
				}
			}

			//Validations
			if ($deletedPeopleCount == $totalTouristsOfBooking) {
				throw new Exception("You can not delete all records. Please use cancel booking option.");
			}

			// Build unpaid-pax-by-rate-group map — Stripe must NOT be charged for these pax
			$unpaidCountByRateGroupId = PaymentLinkService::unpaidCountByRateGroupFromFormIds(
				$data['pending_item_ids'] ?? null,
				$data['pending_history_ids'] ?? null
			);

			$paymentTransCountForBooking = $this->transaction::where('tour_booking_id', $data['bookingID'])->where('status', 'Completed')->whereNull('charge_type')->count();

			if (isset($data['payment_type']) && $data['payment_type'] == 'Card' && $data['refund_Type'] != "fareharbor" && $data['is_cash'] == '' && $paymentTransCountForBooking > 1 && (isset($data['checked_transactions']) && $data['checked_transactions'] == '') && $data['refund_Type'] != 'dont_refund') {
				throw new Exception("You must need to select payment transaction to delete person.");
			}

			$created_by_with_name = BookingService::createdUserInfo();

			$refundedpermitarray = array();
			$checkarrays = array();
			$checkinstatusarray = array();
			$redeemTicketArray = array();
			$refundedpermitfeearray = array();

			foreach ($rateGroupWisedeletedPeopleArray as $key => $value) {
				$btset = $this->bookingTransact::where('tour_booking_id', $bookingID)->where('tour_package_rate_id', $key)->where('deleted_by', 0)->first();
				$touristsCount = ($btset->infants > 0) ? $btset->infants - $value : $btset->tourists - $value;
				$touristsBt = ($btset->infants > 0) ? $btset->infants : $btset->tourists;
				//This is for removing indexes from the end
				for ($a = $touristsCount, $ac = $touristsBt; $a < $ac; $a++) {
					$checkarrays[$key][] = $a;
				}
				$checkinstatusarray[$key] = $btset->check_in_status;
				$redeemTicketArray[$key] = $btset->redeem_ticket;
				$refundedpermitfeearray[$key] = $btset->refund_permitfee_status;
			}

			$updatedCheckIns = array();
			$updatedRedeemTickets = array();
			$updatedRefundedPermitfees = array();

			if (!empty($checkarrays)) {
				foreach ($checkarrays as $k => $checkarray) {
					if (isset($checkinstatusarray[$k]) && $checkinstatusarray[$k] != '')
						$checkinstatusInfo = json_decode($checkinstatusarray[$k]);
					else
						$checkinstatusInfo = [];

					if (isset($redeemTicketArray[$k]) && $redeemTicketArray[$k] != '')
						$redeemTicketInfo = json_decode($redeemTicketArray[$k], TRUE);
					else
						$redeemTicketInfo = [];

					if (isset($refundedpermitfeearray[$k]) && $refundedpermitfeearray[$k] != '')
						$refundpermitfeesstatusInfo = json_decode($refundedpermitfeearray[$k]);
					else
						$refundpermitfeesstatusInfo = [];

					foreach ($checkarray as $m) {
						if (isset($checkinstatusInfo[$m]) && !empty($checkinstatusInfo[$m])) {
							unset($checkinstatusInfo[$m]);
						}

						if (!empty($redeemTicketInfo)) {
							for ($y = 0; $y < count($redeemTicketInfo); $y++) {
								if (isset($redeemTicketInfo[$y]['data'][$m]) && !empty($redeemTicketInfo[$y]['data'][$m])) {
									unset($redeemTicketInfo[$y]['data'][$m]);
								}
								if (isset($redeemTicketInfo[$y]['data'])) {
									$redeemTicketInfo[$y]['data'] = array_values($redeemTicketInfo[$y]['data']);
								}
							}
						}

						if (isset($refundpermitfeesstatusInfo[$m]) && !empty($refundpermitfeesstatusInfo[$m])) {
							if (isset($refundpermitfeesstatusInfo[$m]->status) && $refundpermitfeesstatusInfo[$m]->status == 'Y' && isset($refundpermitfeesstatusInfo[$m]->amount) && $refundpermitfeesstatusInfo[$m]->amount > 0) {
								$refundedpermitarray[$k][] = $m;
							}

							unset($refundpermitfeesstatusInfo[$m]);
						}
					}

					$updatedCheckIns[$k] = $checkinstatusInfo;
					$updatedRedeemTickets[$k] = $redeemTicketInfo;
					$updatedRefundedPermitfees[$k] = $refundpermitfeesstatusInfo;
				}
			}

			//Check validations with calculations for multiple payments using card
			if (isset($data['payment_type']) && $data['payment_type'] == 'Card' && $data['refund_Type'] != "fareharbor" && $data['is_cash'] == '' && $paymentTransCountForBooking > 1 && (isset($data['checked_transactions']) && $data['checked_transactions'] != '')) {
				$refundTrans = $this->transaction::where('tour_booking_id', $bookingID)->where('transaction_number', $data['checked_transactions'])->where('status', 'Refund')->where(function ($query) {
					$query->whereNull('charge_type')->orWhere('charge_type', 'addons');
				})->get(['id', 'amount']);
				$paymentTrans = $this->transaction::where('tour_booking_id', $bookingID)->where('transaction_number', $data['checked_transactions'])->where('status', 'Completed')->where(function ($query) {
					$query->whereNull('charge_type')->orWhere('charge_type', 'addons');
				})->first(['id', 'amount']);
				$totalrefundedamount = 0;
				foreach ($refundTrans as $val) {
					$totalrefundedamount += $val->amount;
				}

				$amountCapturedStripe = 0;
				$amountRefundedStripe = 0;
				$paymentIntent = app(PaymentGatewayInterface::class)->retrievePayment($data['checked_transactions']);

				if (!empty($paymentIntent) && isset($paymentIntent->charges) && isset($paymentIntent->charges->data[0]) && !empty($paymentIntent->charges->data[0])) {
					$amountCapturedStripe = $paymentIntent->charges->data[0]->amount_captured;
					$amountRefundedStripe = ($paymentIntent->charges->data[0]->amount_refunded != '') ? $paymentIntent->charges->data[0]->amount_refunded : 0;
				}

				//Validation check if payment transactions fully refunded or not
				if ($paymentTrans->amount - $totalrefundedamount <= 0) {
					throw new Exception('Unable to refund booking. The chosen transaction has already been fully reimbursed. Please make a new selection.');
				}

				$totalAmountForValidation = 0;
				$totalFeeForValidation = 0;
				foreach ($rateGroupWisedeletedPeopleArray as $key => $value) {
					$tourBooking = $this->tourBooking::where('id', $bookingID)->where('status', 'Booked')->first();
					$customer = $this->customer::where('id', $tourBooking->customer_id)->first();

					$rateCheck = $this->bookingTransact::where('tour_package_rate_id', $key)->where('tour_booking_id', $bookingID)->where('deleted_by', 0)->first();
					$service_commission_percentage = $rateCheck->nat_fees_percentage;

					// Check if this rate group has any permit fee refund status (partial or full)
					if ($rateCheck->refund_permitfee_status != '') {
						// Calculate effective permit fee after partial refunds
						$effectivePermitFee = $rateCheck->permit_fee; // Default to original
						$refundStatus = json_decode($rateCheck->refund_permitfee_status);

						if (!empty($refundStatus)) {
							foreach ($refundStatus as $status) {
								if (isset($status->status) && $status->status == 'Y') {
									if (isset($status->new_permit_fee)) {
										$effectivePermitFee = $status->new_permit_fee; // Partial refund case
									} else {
										$effectivePermitFee = 0; // Full refund case
									}
									break;
								}
							}
						}

						$rate = $rateCheck->rate + $rateCheck->additional_charge + $effectivePermitFee + $rateCheck->partner_fees_amount;

						if ($data['payment_type'] === 'Card' || ($isCashFees == '1' && $data['payment_type'] === 'Cash')) {
							$per = $rate * ($rateCheck->additional_tax_percentage + $rateCheck->processing_charge_percentage) / 100;
						} else {
							$per = $rate * $rateCheck->additional_tax_percentage / 100;
						}

						$baseSubtotal = $rate + $per; // per person base cost

						// Per person subtotal (no refund)
						$personSubtotal = $baseSubtotal;

						// Commission fee calculation
						$personFee = roundout($personSubtotal * $service_commission_percentage / 100);

						// Calculate totals for all people (using same effective permit fee)
						$totalFee = $personFee * $value;
						$totalSubtotal = $personSubtotal * $value;

						// Format if you need final display
						$subtotal = round($totalSubtotal, 2);
						$totalFeeAmount = round($totalFee, 2);
					} else {
						$rate = $rateCheck->rate + $rateCheck->additional_charge + $rateCheck->permit_fee;
						if ($data['payment_type'] === 'Card' || ($isCashFees == '1' && $data['payment_type'] === 'Cash')) {
							$per = $rate * ($rateCheck->additional_tax_percentage + $rateCheck->processing_charge_percentage) / 100;
						} else {
							$per = $rate * $rateCheck->additional_tax_percentage / 100;
						}

						$subtotal = ($rate + $per);
						$totalFeeAmount = (roundout(($subtotal * $service_commission_percentage) / 100, 2)) * $value;
						$subtotal = number_format((float)$subtotal * $value, 2, '.', '');
					}

					$totalAmountForValidation += $subtotal;
					$totalFeeForValidation += $totalFeeAmount;
				}

				// Remove unpaid pax cost from the Stripe-based validation totals —
				// Stripe was never charged for them so the transaction cannot cover their cost.
				if (!empty($unpaidCountByRateGroupId)) {
					$unpaidValidationDeduction = PaymentLinkService::computeMixedPathUnpaidCostCorrection(
						$unpaidCountByRateGroupId,
						$rateGroupWisedeletedPeopleArray,
						$bookingID
					);
					$totalAmountForValidation = max(0.0, round($totalAmountForValidation - $unpaidValidationDeduction, 2));
					$totalFeeForValidation    = max(0.0, round($totalFeeForValidation - round($unpaidValidationDeduction * ($service_commission_percentage ?? 0) / 100, 2), 2));
				}

				if ($data['refund_Type'] == "partial_refund") {
					$feeAmount = 0;
					if ($data['payment_type'] === 'Card') {
						$feeAmount = ($totalAmountForValidation * $service_commission_percentage) / 100;
					}
					$netAmountForValidationPartialRefund = round($totalAmountForValidation + $feeAmount, 2);
					if ($data['partial_Refund_value'] > $netAmountForValidationPartialRefund) {
						throw new Exception('Unable to refund booking. Please enter amount less than total.');
					}
				}

				if ($data['refund_Type'] != "dont_refund" && $amountCapturedStripe > 0) {
					$remainingAmountStripe = $amountCapturedStripe / 100 - $amountRefundedStripe / 100;
					if ($totalAmountForValidation > $remainingAmountStripe) {
						throw new Exception('Unable to refund booking. For the chosen transaction, the refund amount is greater than the unrefunded amount. Please choose another transaction.');
					}
				}

				//Validation check for 100% refund when deleting persons
				if ($data['refund_Type']  == "100_refund" && ($totalAmountForValidation > 0)) {
					$set_fee_amount = $totalFeeForValidation;
					$Refund100 = $totalAmountForValidation + $set_fee_amount;
					$Refund100 = round($Refund100, 2);
					$rounded = round($paymentTrans->amount - $totalrefundedamount - $Refund100, 2);
					if ($rounded < -0.05) {
						throw new Exception('Unable to refund booking. Please choose a valid transaction or person to refund.');
					}
				}

				//Validation check for full refund minus fees when deleting persons
				if ($data['refund_Type'] == "full_refund" && ($totalAmountForValidation > 0)) {
					$Refund100MinusFees = round($totalAmountForValidation, 2);
					if (($paymentTrans->amount - $totalrefundedamount - $Refund100MinusFees) < -0.05) {
						throw new Exception('Unable to refund booking. Please choose a valid transaction or person to refund.');
					}
				}
			}

			//Updating checkins json
			if (!empty($updatedCheckIns)) {
				foreach ($updatedCheckIns as $key => $value) {
					if (!empty($value)) {
						$this->bookingTransact::where('tour_booking_id', $bookingID)->where('tour_package_rate_id', $key)->where('deleted_by', 0)
							->update([
								'check_in_status' => (!empty($value)) ? json_encode((array_values($value))) : ''
							]);
					}
				}
			}

			//Updating redeem ticket json
			if (!empty($updatedRedeemTickets)) {
				foreach ($updatedRedeemTickets as $key => $value) {
					if (!empty($value)) {
						$this->bookingTransact::where('tour_booking_id', $bookingID)->where('tour_package_rate_id', $key)->where('deleted_by', 0)
							->update([
								'redeem_ticket' => (!empty($value)) ? json_encode((array_values($value))) : ''
							]);
					}
				}
			}

			//Updating refunded permit fee json
			if (!empty($updatedRefundedPermitfees)) {
				foreach ($updatedRefundedPermitfees as $key => $value) {
					if (!empty($value)) {
						$this->bookingTransact::where('tour_booking_id', $bookingID)->where('tour_package_rate_id', $key)->where('deleted_by', 0)
							->update([
								'refund_permitfee_status' => (!empty($value)) ? json_encode(array_values($value)) : '',
							]);
					}
				}
			}

			$total = 0;
			$totalFees = 0;
			foreach ($rateGroupWisedeletedPeopleArray as $keyl => $value) {
				$transaction = $this->transaction::where('tour_booking_id', $bookingID)->where('status', 'Completed')->whereNull('charge_type')->first();
				$tourBooking = $this->tourBooking::where('id', $bookingID)->where('status', 'Booked')->first();
				$customer = $this->customer::where('id', $tourBooking->customer_id)->first();
				$rateCheckname = $this->tourPackageRate::where('id', $keyl)->withTrashed()->first();
				$rateCheck = $this->bookingTransact::where('tour_package_rate_id', $keyl)->where('tour_booking_id', $bookingID)->where('deleted_by', 0)->first();

				if ($customer->is_affiliate == 'Yes') {
					$service_commission_percentage = $rateCheck->nat_fees_percentage;
				} else {
					$service_commission_percentage = $rateCheck->nat_fees_percentage;
				}

				if ($rateCheck->refund_permitfee_status != '' && isset($refundedpermitarray) && !empty($refundedpermitarray) && isset($refundedpermitarray[$keyl])) {
					// Calculate effective permit fee after partial refunds
					$effectivePermitFee = $rateCheck->permit_fee; // Default to original
					$refundStatus = json_decode($rateCheck->refund_permitfee_status);

					if (!empty($refundStatus)) {
						foreach ($refundStatus as $status) {
							if (isset($status->status) && $status->status == 'Y') {
								if (isset($status->new_permit_fee)) {
									$effectivePermitFee = $status->new_permit_fee; // Partial refund case
								} else {
									$effectivePermitFee = 0; // Full refund case
								}
								break;
							}
						}
					}

					$rate = $rateCheck->rate + $rateCheck->additional_charge + $effectivePermitFee + $rateCheck->partner_fees_amount;

					if ($data['payment_type'] === 'Card' || ($isCashFees == '1' && $data['payment_type'] === 'Cash')) {
						$per = $rate * ($rateCheck->additional_tax_percentage + $rateCheck->processing_charge_percentage) / 100;
					} else {
						$per = $rate * $rateCheck->additional_tax_percentage / 100;
					}

					$baseSubtotal = $rate + $per; // per person base cost

					// Per person subtotal (no refund)
					$personSubtotal = $baseSubtotal;

					// Commission fee calculation
					$personFee = roundout($personSubtotal * $service_commission_percentage / 100);

					// Calculate totals for all people (using same effective permit fee)
					$totalFee = $personFee * $value;
					$totalSubtotal = $personSubtotal * $value;

					// Format final values
					$subtotal = round($totalSubtotal, 2);
					$totalFeeAmount = round($totalFee, 2);
				} else {
					$rate = $rateCheck->rate + $rateCheck->additional_charge + $rateCheck->permit_fee + $rateCheck->partner_fees_amount;
					if (isset($data['payment_type']) && ($data['payment_type'] === 'Card' || ($isCashFees == '1' && $data['payment_type'] === 'Cash'))) {
						$per = $rate * ($rateCheck->additional_tax_percentage + $rateCheck->processing_charge_percentage) / 100;
					} else {
						$per = $rate * $rateCheck->additional_tax_percentage / 100;
					}

					$subtotal = ($rate + $per);
					$totalFeeAmount = (roundout(($subtotal * $service_commission_percentage) / 100, 2)) * $value;
					$subtotal = number_format((float)$subtotal * $value, 2, '.', '');
				}

				$total += $subtotal;
				$totalFees += $totalFeeAmount;
			}

			$totalTicketCost = $total;
			//Validationds for delete people with split payments for unpaid paxes
			$btvtotal = 0;
			$btv = $this->tourBooking::where('id', $bookingID)->first();
			$btvtotal = $btv->total;
			$btvtotal =  (float)$btvtotal;
			$total =  (float)$total;
			$nan = 0;

			$tsm = $this->transaction::where('tour_booking_id', $bookingID)->where('status', 'Completed')->whereNull('charge_type')->orderBy('id', 'DESC')->first();

			if (!empty($tsm) && $tsm->payment_type == 1 && $data['refund_Type'] == "dont_refund") {
				$paymentOnlyCheck = 0;
				$paymentOnly = $this->tourBookingHistory::where('tour_booking_id', $bookingID)->where('operation', 'Payment')->get();

				foreach ($paymentOnly as $value) {
					$details = json_decode($value->details);
					$paymentOnlyCheck += $details->amount;
				}

				$pendingAmount = $btv->total - $paymentOnlyCheck;
				$pendingAmount = round($pendingAmount);
				$deleteRequestAmount = 0;

				$deleteRequestAmount = $this->splitPaymentCheckBeforeDelete($rateGroupWisedeletedPeopleArray, $bookingID, $data['payment_type']);

				$deleteRequestAmount = round($deleteRequestAmount);
				if ($deleteRequestAmount > $pendingAmount) {
					throw new Exception('Unable to delete booking. Please delete unpaid pax first.');
				}
			}

			if ($data['refund_Type'] == "partial_refund") {
				if ($data['partial_Refund_value'] == "NaN") {
					$nan = 0;
				} else {
					$nan = $data['partial_Refund_value'];
				}
				$feeAmount = 0;
				if ($data['payment_type'] === 'Card') {
					$feeAmount = ($total * $service_commission_percentage) / 100;
				}
				$netAmountForValidationPartialRefund = round($total + $feeAmount, 2);
				if (($nan > $netAmountForValidationPartialRefund) || ($nan > $btvtotal)) {
					throw new Exception('Unable to refund booking. Please enter amount less than total.');
				}
			}

			if (($total > $btvtotal)  && ($data['partial_Refund_value'] == "NaN") && ($data['refund_Type'] != "dont_refund")) {
				throw new Exception('Unable to refund booking. Please enter amount less than total.');
			}

			$rateChecknameForPartialRefund = [];
			$tourBookingTotalForPayLater = 0;
			$partnerFeesRefundForPartialRefund = 0;
			$totalDeletedPax = 0;

			// Build rate-group → unpaid-pax-count map for dont_refund so refund_keep_us
			// can be scaled to paid pax only (unpaid pax were never charged).
			$unpaidCountByRateGroupForDontRefund = ($data['refund_Type'] === 'dont_refund')
				? PaymentLinkService::unpaidCountByRateGroupFromFormIds(
					$data['pending_item_ids'] ?? null,
					$data['pending_history_ids'] ?? null
				)
				: [];

			foreach ($rateGroupWisedeletedPeopleArray as $key => $value) {
				$transaction = $this->transaction::where('tour_booking_id', $bookingID)
					->where('status', 'Completed')
					->whereNull('charge_type')
					->first();

				$tourBooking = $this->tourBooking::find($bookingID);
				$customer = $this->customer::find($tourBooking->customer_id);

				// Per-rate-group unpaid pax count (dont_refund path only).
				$unpaidPaxCount = min((int)$value, $unpaidCountByRateGroupForDontRefund[$key] ?? 0);
				$paidPaxValue   = (int)$value - $unpaidPaxCount;

				$rateCheckname = $this->tourPackageRate::where('id', $key)->first();
				$rateChecknameForPartialRefund[] = $rateCheckname->rate_for . ' person ' . $value;

				$rateCheck = $this->bookingTransact::where('tour_package_rate_id', $key)
					->where('tour_booking_id', $bookingID)
					->where('deleted_by', 0)
					->first();
				$totalDeletedPax += ($rateCheck->infants == 0) ? $value : 0;
				// guard
				if (!$rateCheck) {
					continue; // skip if no booking transact for this rate
				}

				$stripe_fees_percentage = $rateCheck->stripe_fees_percentage;
				// service_commission_percentage set same for both cases in original code - kept as-is
				$service_commission_percentage = $rateCheck->nat_fees_percentage;

				$partnerFees = ($isPartnerBooking == 1) ? ($rateCheck->partner_fees_amount * $value) : 0;

				// initialize per-rate totals
				$subtotal = 0.0;
				$totalFeeAmount = 0.0;

				// Check if this rate group has any permit fee refund status (partial or full)
				if ($rateCheck->refund_permitfee_status != '') {
					// Calculate effective permit fee after partial refunds
					$effectivePermitFee = $rateCheck->permit_fee; // Default to original
					$refundStatus = json_decode($rateCheck->refund_permitfee_status);

					if (!empty($refundStatus)) {
						foreach ($refundStatus as $status) {
							if (isset($status->status) && $status->status == 'Y') {
								if (isset($status->new_permit_fee)) {
									$effectivePermitFee = $status->new_permit_fee; // Partial refund case
								} else {
									$effectivePermitFee = 0; // Full refund case
								}
								break;
							}
						}
					}

					// per person rate components
					$rate = $rateCheck->rate + $rateCheck->additional_charge + $effectivePermitFee + $rateCheck->partner_fees_amount;

					if (isset($data['payment_type']) && ($data['payment_type'] === 'Card' || ($isCashFees == '1' && $data['payment_type'] === 'Cash'))) {
						$per = $rate * ($rateCheck->additional_tax_percentage + $rateCheck->processing_charge_percentage) / 100;
					} else {
						$per = $rate * $rateCheck->additional_tax_percentage / 100;
					}

					$baseSubtotal = $rate + $per; // per person base cost

					// Per person subtotal (no permit refund)
					$personSubtotal = $baseSubtotal;

					// Commission fee for each type (use roundout helper)
					$personFee = roundout($personSubtotal * $service_commission_percentage / 100);

					// For partial refunds, all people use same effective permit fee
					// No need to split between normal and refunded people
					$totalFee = $personFee * $value;
					$totalSubtotal = $personSubtotal * $value;

					// Format if you need final display
					$subtotal = (float) round($totalSubtotal, 2);
					$totalFeeAmount = (float) round($totalFee, 2);
				} else {
					// standard case (no permit refund situation)
					$rate = $rateCheck->rate + $rateCheck->additional_charge + $rateCheck->permit_fee + $rateCheck->partner_fees_amount;

					if (isset($data['payment_type']) && ($data['payment_type'] === 'Card' || ($isCashFees == '1' && $data['payment_type'] === 'Cash'))) {
						$per = $rate * ($rateCheck->additional_tax_percentage + $rateCheck->processing_charge_percentage) / 100;
					} else {
						$per = $rate * $rateCheck->additional_tax_percentage / 100;
					}

					$perPersonSubtotal = $rate + $per;
					// total for this rate group (value pax)
					$subtotal = (float) round($perPersonSubtotal * $value, 2);

					// commission total for this group
					$totalFeeAmount = (float) roundout(($perPersonSubtotal * $service_commission_percentage) / 100, 2) * $value;
				}

				// ensure base variables used later are set as floats
				$total = (float) $subtotal;                // per-rate-group total (money)
				$totalFees = (float) $totalFeeAmount;      // per-rate-group fee total
				$totalTicketCost = (float) ($subtotal - $partnerFees); // ticket cost used in partner reversal logic
				$ticketCost = $totalTicketCost; // keep original name too

				// Scale refund amounts to paid-pax only — unpaid pax were never charged to Stripe
				$unpaidInGroup  = min((int)$value, $unpaidCountByRateGroupId[$key] ?? 0);
				$paidInGroup    = max(0, (int)$value - $unpaidInGroup);
				$paidFraction   = ((int)$value > 0) ? ($paidInGroup / (int)$value) : 1.0;
				$stripeRefundTotal = round($total * $paidFraction, 2);
				$stripeRefundFees  = round($totalFees * $paidFraction, 2);

				$bt = $this->bookingTransact::where('tour_booking_id', $bookingID)
					->where('tour_package_rate_id', $key)
					->first();

				if ($bt) {
					$setTotal = (float) $bt->total - $total;
					$setTourist = ($bt->is_infant_rate != 1) ? (int) $bt->tourists - $value : (int) $bt->tourists;
					$setInfant = ($bt->is_infant_rate == 1) ?  (int) $bt->infants - $value : (int) $bt->infants;
				} else {
					$setTotal = 0;
					$setTourist = 0;
					$setInfant = 0;
				}

				$total_fee_amount = 0.0;
				if (!empty($transaction) && ($transaction->via == "Card" || ($isCashFees == '1' && $transaction->via == "Cash"))) {
					$total_fee_amount = (float) number_format($totalFees, 2, '.', '');
				}

				$set_fee_amount = 0.0;
				$partnerFeesAmount = 0.0;
				if ($transaction) {
					$set_fee_amount = (float) $tourBooking->service_commission - (float)$total_fee_amount;
					$set_fee_amount = (float) number_format($set_fee_amount, 2, '.', '');
				}

				// update booking transact row for this rate
				if ($bt) {
					if ($setTourist == 0 && $setInfant == 0) {
						$this->bookingTransact::where('tour_booking_id', $bookingID)
							->where('tour_package_rate_id', $key)
							->update([
								'total' => $setTotal,
								'tourists' => $setTourist,
								'infants' => $setInfant,
								'check_in_status' => '',
								'redeem_ticket' => null,
								'refund_permitfee_status' => ''
							]);
					} else {
						$this->bookingTransact::where('tour_booking_id', $bookingID)
							->where('tour_package_rate_id', $key)
							->update([
								'total' => $setTotal,
								'tourists' => $setTourist,
								'infants' => $setInfant
							]);
					}
				}

				// update main tour booking totals
				if (!empty($transaction)) {
					$tourBooking_set_total = (float) $tourBooking->total - $total;
					$tourBookingSetTourist = ($bt->is_infant_rate != 1) ? (int) $tourBooking->tourists - $value : $tourBooking->tourists;
					$tourBookingSetInfant = ($bt->is_infant_rate == 1) ? (int) $tourBooking->infants - $value : $tourBooking->infants;

					if ($transaction->via == "Card" && $data['refund_Type'] != "fareharbor") {
						// set_fee_amount re-calculation uses totalFees variable (per-rate)
						$set_fee_amount = (float) number_format($totalFees, 2, '.', '');
						if ($data['refund_Type'] == "dont_refund") {
							$tourBooking_set_total = (float) $tourBooking->total - ($total + $set_fee_amount);
							$permitFeeUpdate = ($tourBooking_set_total * $stripe_fees_percentage) / 100;
							$permitFeeUpdate = (float) number_format($permitFeeUpdate, 2, '.', '');

							// check payment_type on transaction model (original code used $transK->payment_type - replaced with $transaction)
							if (isset($transaction->payment_type) && $transaction->payment_type == 1) {
								$tourBooking->update([
									'booking_total' => $tourBooking_set_total,
									'service_commission' => $permitFeeUpdate,
								]);
								DB::commit();
							}
						}

						if ($data['refund_Type'] == "100_refund" || $data['refund_Type'] == "full_refund") {
							$tourBooking_set_total = (float) $tourBooking->total - ($total + $set_fee_amount);
						}

						$tourBooking_set_total = (float) number_format($tourBooking_set_total, 2, '.', '');

						if ($data['refund_Type'] != "partial_refund") {
							$tourBooking->update([
								'total' => $tourBooking_set_total,
								'tourists' => $tourBookingSetTourist,
								'infants' => $tourBookingSetInfant
							]);
							DB::commit();
						}
					} else {
						if ($data['refund_Type'] != "partial_refund") {
							$tourBooking->update([
								'total' => $tourBooking_set_total,
								'tourists' => $tourBookingSetTourist,
								'infants' => $tourBookingSetInfant
							]);
							DB::commit();
						}
					}
				} else {
					// No transaction (pay later / cash, or card paid via payment link).
					// For card bookings, total includes platform fee — subtract ticket+fee.
					// For cash/pay-later, subtract ticket only.
					// booking_total holds the original booking amount and must not change.
					if (isset($data['payment_type']) && $data['payment_type'] === 'Card') {
						$tourBooking_set_total = (float) $tourBooking->total - ($total + $totalFees);
					} else {
						$tourBooking_set_total = (float) $tourBooking->total - $total;
					}
					$tourBookingTotalForPayLater += $total;
					$tourBookingSetTourist = ($bt->is_infant_rate != 1) ? (int) $tourBooking->tourists - $value : $tourBooking->tourists;
					$tourBookingSetInfant = ($bt->is_infant_rate == 1) ? (int) $tourBooking->infants - $value : $tourBooking->infants;

					if ($data['refund_Type'] != "partial_refund") {
						$tourBooking->update([
							'total'    => $tourBooking_set_total,
							'tourists' => $tourBookingSetTourist,
							'infants'  => $tourBookingSetInfant
						]);
						DB::commit();
					}
				}

				// Switch to paid-pax-only amounts for history/transaction/refund branches.
				// The master booking and transact DB updates above already used the full $total.
				$total     = $stripeRefundTotal;
				$totalFees = $stripeRefundFees;

				// Stripe reversals & refunds (card)
				if ($data['payment_type'] == 'Card' && $data['refund_Type'] != "fareharbor" && ($data['is_cash'] == '')) {
					//Fetching transaction id for transfer reversal in stripe
					if (isset($data['checked_transactions']) && $data['checked_transactions'] != '') {
						$checkedTrans = $this->transaction::where('tour_booking_id', $bookingID)
							->where('transaction_number', $data['checked_transactions'])
							->where('status', 'Completed')
							->first(['id', 'payment_mode']);
						$transId = $checkedTrans ? $checkedTrans->id : ($transaction ? $transaction->id : null);
					} else {
						$transId = $transaction ? $transaction->id : null;
					}

					//Reverse transfer for partner package (ticket cost)
					if ($isPartnerBooking == 1 && $ticketCost > 0 && $data['refund_Type'] != "dont_refund" && $data['refund_Type'] != "partial_refund") {
						ThreeWayPaymentService::reverseTransfer($bookingID, $transId, $ticketCost);
					}

					// Full refund (paid-pax portion only — unpaid pax were never charged to Stripe)
					if ($data['refund_Type'] == "full_refund" && ($stripeRefundTotal > 0)) {
						if (isset($data['checked_transactions']) && $data['checked_transactions'] != '') {
							$refundParams = [
								'payment_intent' => $data['checked_transactions'],
								'amount' => (int) round($stripeRefundTotal * 100),
								'reverse_transfer' => true,
							];
							// Same fallback chain as $transId above: the checked_transactions value may
							// not resolve to a row, in which case $transaction (if present) is the next
							// best source of truth for the mode this exact charge actually used.
							app(PaymentGatewayInterface::class)->refundPayment($refundParams, $checkedTrans ? $checkedTrans->payment_mode : $transaction->payment_mode);
						} elseif ($transaction) {
							$refundParams = [
								'payment_intent' => $transaction->transaction_number,
								'amount' => (int) round($stripeRefundTotal * 100),
								'reverse_transfer' => true,
							];
							app(PaymentGatewayInterface::class)->refundPayment($refundParams, $transaction->payment_mode);
						}
						DB::commit();
					}

					// 100% refund (including fees and application fee)
					if ($data['refund_Type'] == "100_refund" && ($stripeRefundTotal + $stripeRefundFees > 0)) {
						$Refund100 = $stripeRefundTotal + $stripeRefundFees;
						$Refund100 = (float) round($Refund100, 2);

						if (isset($data['checked_transactions']) && $data['checked_transactions'] != '') {
							$refundTrans = $this->transaction::where('tour_booking_id', $bookingID)
								->where('transaction_number', $data['checked_transactions'])
								->where('status', 'Refund')
								->where(function ($query) {
									$query->whereNull('charge_type')->orWhere('charge_type', 'addons');
								})
								->get(['id', 'amount']);
							$paymentTrans = $this->transaction::where('tour_booking_id', $bookingID)
								->where('transaction_number', $data['checked_transactions'])
								->where('status', 'Completed')
								->where(function ($query) {
									$query->whereNull('charge_type')->orWhere('charge_type', 'addons');
								})
								->first(['id', 'amount', 'payment_mode']);

							$totalrefundedamount = 0;
							foreach ($refundTrans as $ky => $val) {
								$totalrefundedamount += $val->amount;
							}

							if ($paymentTrans) {
								$rounded = round($paymentTrans->amount - $totalrefundedamount - $Refund100, 2);

								if ($rounded <= -0.01) {
									$refundParams = [
										'payment_intent' => $data['checked_transactions'],
										'amount' => (int) round(($Refund100 + $rounded) * 100),
										'reverse_transfer' => true,
										'refund_application_fee' => true,
									];
									app(PaymentGatewayInterface::class)->refundPayment($refundParams, $paymentTrans->payment_mode);
								} else {
									$refundParams = [
										'payment_intent' => $data['checked_transactions'],
										'amount' => (int) round($Refund100 * 100),
										'reverse_transfer' => true,
										'refund_application_fee' => true,
									];
									app(PaymentGatewayInterface::class)->refundPayment($refundParams, $paymentTrans->payment_mode);
								}
							}
						} elseif ($transaction) {
							$refundParams = [
								'payment_intent' => $transaction->transaction_number,
								'amount' => (int) round($Refund100 * 100),
								'reverse_transfer' => true,
								'refund_application_fee' => true,
							];
							app(PaymentGatewayInterface::class)->refundPayment($refundParams, $transaction->payment_mode);
						}
					}
				}

				// Now decide refund types, refund_keep_us etc.
				$deletedPeople = $value;

				// initialize these so they exist
				$refund_keep_us = 0.0;
				$fee_amount = 0.0;
				$refundPartnerFeesKeepUs = 0.0;
				$refund_type = '';

				if ($data['refund_Type'] == "dont_refund") {
					if (($data['payment_type'] == 'Card' || ($isCashFees == '1' && $data['payment_type'] === 'Cash')) && $data['refund_Type'] != "fareharbor") {
						$fee_amount = (float) $totalFees;
						$fee_amount = (float) number_format($fee_amount, 2, '.', '');
						$total = $total + $fee_amount;
						$refund_keep_us = $total;
					} else {
						$refund_keep_us = $total;
					}

					// Nothing paid yet: the removed pax were never charged, so nothing is kept.
					if (empty($transaction)) {
						$total = 0;
						$refund_keep_us = 0;
						$refundPartnerFeesKeepUs = 0;
					}
					// Unpaid pax were never charged — NAT keeps nothing for them.
					// Scale refund_keep_us to the paid-pax fraction only.
					if (isset($unpaidPaxCount) && $unpaidPaxCount > 0 && (int)$value > 0) {
						$paidFrac       = $paidPaxValue / (int)$value;
						$refund_keep_us = round($refund_keep_us * $paidFrac, 2);
					}

					$fee_amount = 0;
					$refund_type = "Don't Refund";
				}

				if ($data['refund_Type'] == "partial_refund") {
					// Check ticket cost vs partial refund for partner package
					if (!empty($transaction) && $isPartnerBooking == 1 && $data['partial_Refund_value'] != "NaN") {
						if ((float)$data['partial_Refund_value'] < (float)$totalTicketCost) {
							$total = $subtotal - $partnerFees;
							$ticketCost = $total;
						} else {
							$total = $subtotal;
							$partnerFeesRefundForPartialRefund += $partnerFees;
						}
					}

					if (($data['payment_type'] == 'Card' || ($isCashFees == '1' && $data['payment_type'] === 'Cash')) && $data['refund_Type'] != "fareharbor") {
						$fee_amount = (float) $totalFees;
						$fee_amount = (float) number_format($fee_amount, 2, '.', '');
						$total = $total + $fee_amount;
						$refund_keep_us = $total - (float)$data['partial_Refund_value'];
						$refund_keep_us = (float) number_format((float)$refund_keep_us, 2, '.', '');
						$fee_amount = 0;
					} else {
						$refund_keep_us = $total - (float)$data['partial_Refund_value'];
						$refund_keep_us = (float) number_format((float)$refund_keep_us, 2, '.', '');
					}

					if (empty($transaction)) {
						$total = 0;
					}

					$total = (float) number_format((float)$data['partial_Refund_value'], 2, '.', '');
					$refund_type = "Partial Refund";
				}

				if ($data['refund_Type'] == "full_refund") {
					if (($data['payment_type'] == 'Card' || ($isCashFees == '1' && $data['payment_type'] === 'Cash')) && $data['refund_Type'] != "fareharbor") {
						$fee_amount = (float) $totalFees;
						$fee_amount = (float) number_format($fee_amount, 2, '.', '');
						$refund_keep_us = $fee_amount;
						$fee_amount = 0;
					} else {
						$refund_keep_us = 0;
					}
					if (empty($transaction)) {
						$total = 0;
					}
					$partnerFeesAmount = (!empty($transaction)) ? $partnerFees : 0;
					$refund_type = "Full Refund minus Fees";
				}

				if ($data['refund_Type'] == "fareharbor") {
					$refund_keep_us = $total;
					$refund_type = "Fareharbor";
				}

				if ($data['refund_Type'] == "100_refund") {
					if (($data['payment_type'] == 'Card' || ($isCashFees == '1' && $data['payment_type'] === 'Cash')) && $data['refund_Type'] != "fareharbor") {
						$fee_amount = (float) $totalFees;
						$fee_amount = (float) roundout($fee_amount, 2);
						$total = $total + $fee_amount;
						$refund_keep_us = 0;
					} else {
						$refund_keep_us = 0;
					}
					if (empty($transaction)) {
						$total = 0;
					}
					$partnerFeesAmount = (!empty($transaction)) ? $partnerFees : 0;
					$refund_type = "100 % Refund";
				}

				if (isset($data['is_cash']) && $data['is_cash'] != '') {
					if ($data['is_cash'] == 'Cash') {
						$refundVia = 'Cash';
					} elseif ($data['is_cash'] == 'Wire Transfer') {
						$refundVia = 'Check/Wire';
					} else {
						$refundVia = $data['payment_type'];
					}
				} else {
					$refundVia = $data['payment_type'];
				}

				$bookingInfo = $this->tourBooking::find($bookingID);
				if ($data['refund_Type'] != "partial_refund") {
					$historyId = HistoryService::storeRefundDataInHistory(
						$bookingID,
						$bookingInfo->tourists + $bookingInfo->infants,
						$created_by_with_name,
						null, /* $comment */
						$refund_type,
						null,
						$total,
						null, /* $cardNumber */
						[], /* $cardsArray */
						[], /* $partialAmountArray */
						$refundVia,
						null, /* $paymentTotal */
						null, /* $refundTotal */
						$refund_keep_us,
						$rateCheckname->rate_for . ' person ' . $value, /* $deleted */
						isset($fee_amount) ? $fee_amount : 0,
						null,
						$partnerFeesAmount,
						$refundPartnerFeesKeepUs ?? 0
					);
					// Remove contacts if booking package has contacts
					if ($packageHasContacts->has_contacts == 1) {
						if (isset($data['contacts']) && !empty($data['contacts'])) {
							try {
								PackageHasContactsService::deleteContacts($data['contacts']);
							} catch (Exception $ex) {
								Log::error($ex->getMessage());
							}
						}
					}
				}

				$paymentOnly = $this->tourBookingHistory::where('tour_booking_id', $bookingID)->where('operation', 'Payment')->get();
				$paymentOnlyCheck = 0;
				foreach ($paymentOnly as $value) {
					$details = json_decode($value->details);
					$paymentOnlyCheck += $details->amount;
				}

				$bok = round($bookingInfo->booking_total);
				$pay = round($paymentOnlyCheck);
				$firstTransaction = $this->transaction::where('tour_booking_id', $bookingID)->where('status', 'Completed')->whereNull('charge_type')->orderBy('id', 'DESC')->first();
				if (!empty($transaction) && $data['payment_type'] == 'Card' && $data['refund_Type'] != "fareharbor" && $data['refund_Type'] != "partial_refund") {
					if (isset($data['is_cash']) && $data['is_cash'] != '') {
						if ($data['is_cash'] == 'Cash') {
							$refundVia = 'Cash';
						} else if ($data['is_cash'] == 'Wire Transfer') {
							$refundVia = 'Check/Wire';
						}
					} else {
						$refundVia = $data['payment_type'];
					}
					if ($firstTransaction->payment_type == 0) {
						if (isset($data['checked_transactions']) && $data['checked_transactions'] != '') {
							$selectedTransaction = $this->transaction::where('tour_booking_id', $bookingID)->where('transaction_number', $data['checked_transactions'])->where('status', 'Completed')->where(function ($query) {
								$query->whereNull('charge_type')->orWhere('charge_type', 'addons');
							})->first();
							if ($data['refund_Type'] == "dont_refund") {
								$refundAmount = 0.00;
							} else {
								$refundAmount = $total;
							}
							if ($data['refund_Type'] == "100_refund") {
								$feeAmount = round($totalFees, 2);
							} else {
								$feeAmount = 0.00;
							}
							// $refundVia is 'Cash'/'Check/Wire' when is_cash overrode a Card booking to
							// a manual reimbursement — no real Stripe operation backs this refund
							// row, so it must not carry a real PaymentIntent/fee id.
							$refundTransId = TransactionService::storeRefundInTransaction($bookingID, $refundAmount, $feeAmount, $refundVia, ($refundVia == "Card") ? $selectedTransaction->transaction_number : null, ($refundVia == "Card") ? $selectedTransaction->application_fee_id : null, mode: $selectedTransaction->payment_mode);
						} else {
							if ($data['refund_Type'] == "dont_refund") {
								$refundAmount = 0.00;
							} else {
								$refundAmount = $total;
							}
							if ($data['refund_Type'] == "100_refund") {
								$feeAmount =  round($totalFees, 2);
							} else {
								$feeAmount = 0.00;
							}
							$refundTransId = TransactionService::storeRefundInTransaction($bookingID, $refundAmount, $feeAmount, $refundVia, ($refundVia == "Card") ? $firstTransaction->transaction_number : null, ($refundVia == "Card") ? $firstTransaction->application_fee_id : null, mode: $firstTransaction->payment_mode);
						}
						//Store reverse transfer in payout for partner package
						if ($isPartnerBooking == 1 && $ticketCost > 0  && $data['refund_Type'] != "dont_refund") {
							$transactionId = (isset($data['checked_transactions']) && $data['checked_transactions'] != '') ? $selectedTransaction->id :  $firstTransaction->id;
							ThreeWayPaymentService::storeReverseTransferInPayout($bookingID, $transactionId, $refundTransId ?? null, $ticketCost, $partnerFeesAmount);
						}
					}

					if ($pay >= $bok) {
						$firstTransaction->payment_type = 0;
						$firstTransaction->save();
					}
				} elseif (!empty($transaction) && $data['payment_type'] == 'Cash' && $data['refund_Type'] != "partial_refund") {
					if (isset($data['is_cash']) && $data['is_cash'] != '') {
						if ($data['is_cash'] == 'Cash') {
							$refundVia = 'Cash';
						} elseif ($data['is_cash'] == 'Wire Transfer') {
							$refundVia = 'Check/Wire';
						}
					} else {
						$refundVia = $data['payment_type'];
					}

					if ($data['refund_Type'] == "dont_refund") {
						$refundAmount = 0.00;
					} else {
						$refundAmount = $total;
					}
					if ($isCashFees == 1) {
						if ($data['refund_Type'] == "100_refund") {
							$feeAmount = round($totalFees, 2);
						} else {
							$feeAmount = 0.00;
						}
					} else {
						$feeAmount = 0.00;
					}
					$refundTransId = TransactionService::storeRefundInTransaction($bookingID, $refundAmount, $feeAmount, $refundVia, null, null);

					//Store reverse transfer in payout for partner package
					if ($isPartnerBooking == 1 && $ticketCost > 0  && $data['refund_Type'] != "dont_refund") {
						ThreeWayPaymentService::storeReverseTransferInPayout($bookingID, $firstTransaction->id, $refundTransId ?? null, $ticketCost, $partnerFeesAmount);
					}

					DB::commit();
				} elseif (!empty($transaction) && $data['refund_Type'] == "fareharbor" && $data['refund_Type'] != "partial_refund") {
					if (isset($data['is_cash']) && $data['is_cash'] != '') {
						if ($data['is_cash'] == 'Cash') {
							$refundVia = 'Cash';
						} elseif ($data['is_cash'] == 'Wire Transfer') {
							$refundVia = 'Check/Wire';
						}
					} else {
						$refundVia = $data['payment_type'];
					}
					if ($data['refund_Type'] == "dont_refund") {
						$refundAmount = 0.00;
					} else {
						$refundAmount = $total;
					}
					$refundTransId = TransactionService::storeRefundInTransaction($bookingID, $refundAmount, 0, $refundVia, null, null, mode: $transaction->payment_mode);
					DB::commit();
				} elseif (!empty($transaction) && $data['refund_Type'] != "partial_refund") {
					// Handle third-party platforms (TripAdvisor, GetYourGuide, Headout, etc.)
					if (isset($data['is_cash']) && $data['is_cash'] != '') {
						if ($data['is_cash'] == 'Cash') {
							$refundVia = 'Cash';
						} elseif ($data['is_cash'] == 'Wire Transfer') {
							$refundVia = 'Check/Wire';
						}
					} else {
						$refundVia = $data['payment_type'];
					}
					if ($data['refund_Type'] == "dont_refund") {
						$refundAmount = 0.00;
					} else {
						$refundAmount = $total;
					}
					$refundTransId = TransactionService::storeRefundInTransaction($bookingID, $refundAmount, 0, $refundVia, null, null, mode: $transaction->payment_mode);
					DB::commit();
				}

				// Refund priced add-ons attached to the pax being removed FROM THIS RATE GROUP
				// (identified by pax_id = this rate group's tour_bookings_transact.id). Runs AFTER
				// the tour-side ledger row above (storeRefundInTransaction) so the `transactions`
				// table gets the tour entry first, then the add-on entry — same order as the charge
				// side. This is its own separate Stripe refund + ledger/history row —
				// deletePeopleChangePeople() has no single combined operation to piggyback on,
				// unlike the main change-people flow.
				// dont_refund/partial_refund/fareharbor all settle as 'dont_refund': dont_refund
				// means no money moves for either side; partial_refund is a manually-typed dollar
				// amount with no reliable way to know how much of it the admin intended for
				// add-ons (same "Partial Refund never touches add-ons" convention the direct Edit
				// Booking delete flow's editBooking() already uses); fareharbor is an
				// external-platform refund handled outside Stripe.
				$addonRefundTypeForGroup = match ($data['refund_Type']) {
					'100_refund' => 'full_refund',    // refund price + fee
					'full_refund' => 'ticket_refund',  // ("Full Refund minus Fees") price only, keep fee
					default => 'dont_refund',
				};
				// Still call settleFromDelta() below even when $addonRefundTypeForGroup is
				// 'dont_refund' — removePaxAddons() (called earlier, before deletePeopleChangePeople())
				// already hard-deleted the field row and its own TourBookingAddonTransaction charge
				// row with zero history entry of its own. Skipping this call entirely for
				// dont_refund/partial_refund (the previous behavior) meant the add-on's removal left
				// NO audit trail whatsoever — not even a "Don't Refund" line — exactly the gap
				// TourBookingAddonRepository::deletePaxAddons() already had to fix for the direct
				// delete flow (see its own $notRefundedFields history block). settleAddonTransactions()
				// already handles refund_type='dont_refund' safely on its own: it skips the real
				// Stripe call (gated on `$refundType !== 'dont_refund'`) and instead writes a
				// "Don't Refund" ledger/history row — and mapRefundItemsToOriginalCharge() already
				// uses withTrashed() specifically so it can still find that soft-deleted original
				// charge row after removePaxAddons() ran.
				if (!empty($addonRefundDelta['refundItems'])) {
					$addonItemsForGroup = array_values(array_filter(
						$addonRefundDelta['refundItems'],
						fn($item) => ($item['pax_id'] ?? null) == $rateCheck->id
					));

					if (!empty($addonItemsForGroup)) {
						// True Pay Later: $transaction (this rate group's loop-scoped lookup of a
						// 'Completed', charge_type-null transaction, same one the tour-side ticket
						// refund above checks via `empty($transaction) -> $total = 0`) is empty
						// because NOTHING has ever actually been captured for this booking — the
						// add-on was only ever recorded as an open/unsettled field row (see
						// changePeopleBooking()'s own "no-payment bypass" branch for adding a Pay
						// Later add-on: it deliberately skips settleFromDelta() and writes a plain
						// $0 history entry instead). Calling settleFromDelta() here regardless of
						// that would create a `TourBookingAddonTransaction` "refund" row with no
						// matching "charge" row to net against (none was ever written), plus — for
						// any refund type other than dont_refund — a real `transactions` ledger row
						// and "X.XX Refund" history entry for money that was never collected.
						// That's exactly the reported bug: a Pay Later pax removal showing a real
						// "-$15.00 Refund" and dragging Payment Total/Add-ons negative for an
						// add-on nobody ever paid for. Mirror the add-side bypass instead: skip
						// settlement entirely and log a plain $0, blank-payment-method "Don't
						// Refund" entry so the removal still has an audit trail.
						if (empty($transaction)) {
							try {
								$removedHistoryItems = array_map(function ($item) {
									return [
										'name' => $item['label'] ?? 'Add-on',
										'price' => $item['price'] ?? 0,
										'fee' => $item['fee'] ?? 0,
										'payment_method' => '',
										'status' => "Don't Refund",
									];
								}, $addonItemsForGroup);

								HistoryService::storeAddonsRefundInHistory(
									$tourBooking,
									(object) ['payment_method' => ''],
									['price' => 0, 'fee' => 0, 'transaction_id' => null, 'application_fee_id' => null],
									$removedHistoryItems,
									'removed',
									Constants::ADDONS_DONT_REFUND,
									null,
									(object) ['description' => null]
								);
							} catch (Exception $ex) {
								Log::error('ChangePeopleAddonService error (Pay Later addon-removal history in deletePeopleChangePeople): ' . $ex->getMessage());
							}
						} else {
							// Partition into what actually gets refunded vs. what only gets a "Don't
							// Refund" audit entry — this can no longer be a single filter-then-call
							// (the previous shape: filter down to the selected subset, then call
							// settleFromDelta() ONCE for just that subset, or not at all if it ended up
							// empty). That silently dropped the audit trail for every deselected/
							// unrefunded item, and for $addonRefundTypeForGroup === 'dont_refund' —
							// which covers partial_refund/dont_refund/fareharbor (see the match() above)
							// — it dropped EVERY item's audit trail, because Partial Refund's checkboxes
							// are force-disabled in the "Update Booking" modal (see
							// delete-booking-refund.js's recalcDeleteBookingBreakdown()), so
							// selected_addon_field_ids always arrives as the literal "[]" for that
							// refund type — not a real choice, just the forced default — leaving
							// $addonItemsForGroup empty and settleFromDelta() never called at all.
							$refundedItems = [];
							$notRefundedItems = $addonItemsForGroup;

							// Only a real refund type (100% Refund / Full Refund minus Fees) ever lets
							// the admin choose specific items via selected_addon_field_ids — for
							// 'dont_refund' every item in scope settles as "Don't Refund" uniformly,
							// regardless of whatever that field happens to contain.
							if ($addonRefundTypeForGroup !== 'dont_refund') {
								// The admin can deselect specific add-on line items in the "Update
								// Booking" modal so only the CHOSEN ones get refunded — a deselected
								// add-on is still removed (which pax/add-ons are in scope is decided
								// independently, upstream), just without moving money back for that
								// specific selection; it still gets its own "Don't Refund" entry below
								// instead of vanishing with no record. A missing or empty-string
								// selected_addon_field_ids (e.g. a single-PaymentIntent booking, where
								// the modal never renders the add-ons block/checkboxes at all) means no
								// selection was ever made — fall back to refunding everything tied to
								// this pax, matching pre-existing behavior, rather than silently
								// refunding nothing.
								if (!empty($data['selected_addon_field_ids'])) {
									$selectedAddonFieldIds = is_array($data['selected_addon_field_ids'])
										? $data['selected_addon_field_ids']
										: (json_decode($data['selected_addon_field_ids'], true) ?? []);
									$selectedAddonFieldIds = array_map('intval', $selectedAddonFieldIds);
									$refundedItems = array_values(array_filter(
										$addonItemsForGroup,
										fn($item) => in_array((int) ($item['db_id'] ?? 0), $selectedAddonFieldIds, true)
									));
									$notRefundedItems = array_values(array_filter(
										$addonItemsForGroup,
										fn($item) => !in_array((int) ($item['db_id'] ?? 0), $selectedAddonFieldIds, true)
									));
								} else {
									$refundedItems = $addonItemsForGroup;
									$notRefundedItems = [];
								}
							}

							$addonStripeTransactionNumber = (isset($data['checked_transactions']) && $data['checked_transactions'] != '')
								? $data['checked_transactions']
								: ($transaction->transaction_number ?? null);

							// One call per bucket (each with its own uniform refund_type) instead of
							// one call for the whole group — settleFromDelta()/settleAddonTransactions()
							// only ever applies a single refund_type per call.
							$settleGroupAddons = function (array $items, string $itemsRefundType) use ($bookingID, $keyl, $refundVia, $addonStripeTransactionNumber) {
								if (empty($items)) {
									return;
								}
								try {
									ChangePeopleAddonService::settleFromDelta(
										['chargeItems' => [], 'refundItems' => $items],
										[
											'action' => 'refund',
											// $refundVia (not $data['payment_type']) — it already carries the
											// admin's Cash/Check-Wire override from the refund modal's "is_cash"
											// choice above (same variable the tour-side storeRefundInTransaction()
											// call just above this uses). Passing the booking's raw original
											// payment_type here ignored that override, so a Card booking's add-on
											// kept getting refunded straight back to the card even when the admin
											// explicitly chose to reimburse it as Cash/Check-Wire instead.
											'payment_method' => $refundVia,
											'transaction_id' => $addonStripeTransactionNumber,
											'refund_type' => $itemsRefundType,
											'execute_stripe_refund' => true,
										],
										$bookingID
									);
								} catch (Exception $ex) {
									Log::error('ChangePeopleAddonService: addon refund settlement failed in deletePeopleChangePeople', [
										'booking_id' => $bookingID,
										'rate_group_id' => $keyl,
										'error' => $ex->getMessage(),
									]);
								}
							};

							$settleGroupAddons($refundedItems, $addonRefundTypeForGroup);
							$settleGroupAddons($notRefundedItems, 'dont_refund');
						}
					}
				}

				// Below line is for to update tour booking history table
				if ($data['refund_Type'] != "partial_refund") {
					$this->handleDeletePersonHistoryUpdateJobs($tourBooking, $historyId, $data, $refundVia, $refundTransId ?? null);
				}
			}

			// Cancel pending remaining_payment link items for deleted unpaid pax.
			// The loop above already deducted the full pax cost (paid + unpaid) from
			// tour_bookings_master.total, so skipTotalUpdate=true prevents a double-deduction
			// on total. booking_total is NOT skipped (4th arg omitted/false): the loop above
			// never touches booking_total for an unpaid pax (old assumption it's never bumped —
			// it is, together with total, when the Payment-Link item was first created), so it
			// must be corrected here or it drifts permanently stale/overstated.
			PaymentLinkService::cancelPendingChangePeopleItems(
				$data['pending_item_ids'] ?? null,
				$data['pending_history_ids'] ?? null,
				true
			);
			// Also cancel any pending addon payment-link items for the same booking.
			PaymentLinkService::cancelPendingAddonLinkItemsForBooking((int) $bookingID);

			/* Remove contacts if booking package has contacts feature enabled */
			$getBooking = $this->tourBooking::findOrFail($bookingID);
			$packageHasContacts = $this->tourPackage::find($getBooking->tour_package_id);

			if ($packageHasContacts->has_contacts == 1) {
				if (isset($data['contacts'])) {
					try {
						PackageHasContactsService::deleteContacts($data['contacts']);
					} catch (Exception $ex) {
						Log::error($ex->getMessage());
					}
				}
			}

			// Partial Refund edit booking
			if ($data['refund_Type'] == "partial_refund") {
				$totalc = $this->tourBooking::where('id', $bookingID)->first();
				DB::beginTransaction();
				if (isset($data['checked_transactions']) && $data['checked_transactions'] != '') {
					$transac = $this->transaction::where('tour_booking_id', $bookingID)->where('transaction_number', $data['checked_transactions'])->where('status', 'Completed')->where(function ($query) {
						$query->whereNull('charge_type')->orWhere('charge_type', 'addons');
					})->first();
				} else {
					$transac = $this->transaction::where('tour_booking_id', $bookingID)->where('status', 'Completed')->whereNull('charge_type')->first();
				}

				$transactionFirst = $this->transaction::where('tour_booking_id', $bookingID)->whereNull('charge_type')->first();
				$refundAmountFromConnectedAccountForTrans = 0;

				if ($refundVia == "Card") {
					$netPartnerAmountsForTrans = ($isPartnerBooking == 1) ? ThreeWayPaymentService::getNetPartnerAmountsForTransaction($bookingID, $transac->transaction_number) : 0;  //Get net ticket cost without partner fees
					$netTicketCostForTrans = $netPartnerAmountsForTrans['netTicketCost'] ?? 0;

					//Below line is for to check if the partial refund value is greater than net ticket cost and refund from partner fees amount for selected transaction
					$refundAmountFromConnectedAccountForTrans = 0;
					if ($isPartnerBooking == 1 && $netTicketCostForTrans > 0) {
						if ($netTicketCostForTrans < $data['partial_Refund_value']) {
							$refundAmountFromConnectedAccountForTrans = $netTicketCostForTrans;
						} else {
							$refundAmountFromConnectedAccountForTrans = $data['partial_Refund_value'];
						}
					}
					if ($data['partial_Refund_value'] > 0) {
						//Reverse transfer for partner package (ticket cost)
						if ($isPartnerBooking == 1 && $refundAmountFromConnectedAccountForTrans > 0) {
							ThreeWayPaymentService::reverseTransfer($bookingID, $transac->id, $refundAmountFromConnectedAccountForTrans);
						}
						$refundParams = [
							'payment_intent' => $transac->transaction_number,
							'amount' => $data['partial_Refund_value'] * 100,
							'reverse_transfer' => true,
							'refund_application_fee' => true,
						];
						$refund = app(PaymentGatewayInterface::class)->refundPayment($refundParams, $transac->payment_mode);
					}
				}

				$btp = $this->bookingTransact::where('tour_booking_id', $bookingID)->where('deleted_by', 0)->get();
				$tcount = 0;
				$infantCount = 0;
				foreach ($btp as $value) {
					$tcount += $value->tourists;
					$infantCount += $value->infants;
				}

				if (!empty($transactionFirst)) {
					$ptotal = $totalc->total - $data['partial_Refund_value'];
					$tourBooking->update([
						'total' => $ptotal,
						'tourists' => $tcount,
						'infants' => $infantCount
					]);
				} else {
					$tourBooking->update([
						'total' => $totalc->total - $tourBookingTotalForPayLater,
						'booking_total' => $totalc->booking_total - $tourBookingTotalForPayLater,
						'tourists' => $tcount,
						'infants' => $infantCount
					]);
				}
				DB::commit();

				if (!empty($transactionFirst)) {
					$partialValue = $data['partial_Refund_value'];
				} else {
					$partialValue = 0;
					$refund_keep_us = 0;
				}

				$historyId = HistoryService::storeRefundDataInHistory(
					$bookingID,
					$tcount + $infantCount,
					$created_by_with_name,
					null, /* $comment */
					$refund_type,
					null, /* $transaction */
					$partialValue,
					null, /* $cardNumber */
					[], /* $cardsArray */
					[], /* $partialAmountArray */
					$refundVia,
					null, /* $paymentTotal */
					null, /* $refundTotal */
					$refund_keep_us,
					$rateChecknameForPartialRefund, /* $deleted */
					0,
					null,
					$partnerFeesRefundForPartialRefund
				);

				// Remove contacts if booking package has contacts
				if ($packageHasContacts->has_contacts == 1) {
					if (isset($data['contacts']) && !empty($data['contacts'])) {
						try {
							PackageHasContactsService::deleteContacts($data['contacts']);
						} catch (Exception $ex) {
							Log::error($ex->getMessage());
						}
					}
				}

				if (!empty($transactionFirst)) {
					$refundTransId = TransactionService::storeRefundInTransaction(
						$bookingID,
						$data['partial_Refund_value'],
						0,
						$refundVia,
						($refundVia == "Card") ? $transac->transaction_number : null,
						'',
						mode: ($refundVia == "Card") ? $transac->payment_mode : PaymentModeResolver::DESTINATION
					);
					if ($refundVia != "Card") {
						$refundAmountFromConnectedAccountForTrans = $data['partial_Refund_value'];
					}
					//Store reverse transfer in payout for partner package
					if ($isPartnerBooking == 1 && $refundAmountFromConnectedAccountForTrans > 0) {
						ThreeWayPaymentService::storeReverseTransferInPayout($bookingID, $transac->id, $refundTransId ?? null, $refundAmountFromConnectedAccountForTrans, $partnerFeesRefundForPartialRefund, 'partial_refund');
					}
					$this->handleDeletePersonHistoryUpdateJobs($tourBooking, $historyId, $data, $refundVia, $refundTransId ?? null);
				}
				DB::commit();
			}
			// Update slot summary
			$seatsDiff = - ($totalDeletedPax);
			TimeSlotAvailabilityService::updateSlotSummary($tourBooking->tour_slot_id, $seatsDiff);
			DB::commit();
			$info = DB::table('tour_slot_times AS tst')
				->join('tour_bookings_master as bm', 'bm.tour_slot_id', '=', 'tst.id')
				->join('tour_slot_dates AS tsd', 'tsd.id', '=', 'tst.tour_slot_id')
				->join('tour_packages AS tp', 'tp.id', '=', 'tsd.tour_package_id')
				->join('tour_operators AS t_o', 't_o.id', '=', 'tp.tour_operator_id')
				->join('cities AS ct', 'ct.id', '=', 't_o.city_id')
				->join('states AS st', 'st.id', '=', 'ct.state_id')
				->where('bm.id', $bookingID)
				->select([
					'tst.time_from',
					'tsd.date',
					'tst.time_slot_seats as seats',
					'tp.tour_operator_id',
					'tsd.tour_package_id',
					'tp.name AS package_name',
					'tp.important_notes',
					'tp.things_to_bring',
					'ct.state_id',
					'st.permit_fee',
					't_o.name AS tour_operator',
					't_o.email AS tour_op_email',
					't_o.phone_number AS tour_op_phone',
					't_o.website AS tour_op_website',
					't_o.logo AS tour_op_logo',
					't_o.cancellation_policy',
					'tp.service_commission_percentage',
					'tp.stripe_commission_percentage',
					't_o.tenant_id',
					'bm.name As custname',
					'bm.email As custemail',
					'bm.phone_number As phone_number',
					'tp.email as packageEmail',
					'tp.from_name as packageFromName',
					'tp.from_email as packageFromEmail',
					'tp.api_key as packageApiKey',
					DB::raw("(SELECT SUM(tbm.tourists)
                            FROM tour_bookings_master AS tbm
                            WHERE tbm.tour_slot_id = tst.id
                                AND tbm.status != 'Cancelled'
                            GROUP BY tbm.tour_slot_id) AS booked_seats")
				])
				->first();


			// Payment link query start — remaining_payment links are managed separately
			$tourBookingPaymentLink = TourBookingPaymentLink::where('order_id', $tourBooking->group_id)
				->where('status', 'Unpaid')
				->where(function ($q) { $q->whereNull('section')->orWhere('section', '!=', 'remaining_payment'); })
				->first();

			if ($tourBookingPaymentLink) {
				$tourBookingTransaction = $this->bookingTransact::where('tour_booking_id', $bookingID)->where('deleted_by', 0)->first();
				// $tourBookingTotalForPayLater is pax-ticket-only — the removed pax's OWN priced
				// add-ons ($addonRefundDelta) never factor in. paymentLinkUpdate()'s "Delete People"
				// branch subtracts this amount (plus its own fee) from the link, so folding in the
				// addon delta here too (net_price is negative for a net removal, so subtracting it
				// ADDS to the amount being taken off the link) keeps the link from staying
				// overstated by exactly the removed pax's add-on worth.
				$addonNetPriceForPayLink = (float) ($addonRefundDelta['net_price'] ?? 0);
				$dataPaymentLink = [
					'amount' => $tourBookingTotalForPayLater - $addonNetPriceForPayLink,
					'natFeesPercentage' => $tourBookingTransaction->nat_fees_percentage ?? 0
				];
				PaymentLinkService::paymentLinkUpdate($dataPaymentLink, $info, $tourBooking, $tourBookingPaymentLink, 'Delete People');
			}
			// Payment link query end

			$deletedPeople = $this->tourBookingHistory::where('tour_booking_id', $bookingID)->where('operation', 'Refund')->get();

			$arEmailData = [
				'tour_d_t' => $info->date . ' ' . $info->time_from,
				'bookingId' => $bookingID,
				'custName' => $info->custname,
				'custEmail' => $info->custemail,
				'custPhone' => $info->phone_number ?? '',
				'deletedPeople' => $deletedPeople
			];

			if (in_array(Auth::user()->email, config('constants.prevent_sending_emails')) == false) {
				EmailService::sendPeopleRemovedEmail($info, $arEmailData);
			}
			return [
				'booking_id' => $bookingID,
				'success' => true,
				'message' => 'Booking has been updated' . ($data['refund_Type'] != "dont_refund" ? ' and refund has been initiated.' : '.')
			];
		} catch (Exception $exception) {
			DB::rollBack();
			Log::error($exception);
			throw new GeneralCoreException($exception);
		}
	}

	/**
	 * Create (or append to) a remaining-payment link item for priced add-ons that were
	 * added during a Change People edit paid via Payment Link.
	 *
	 * Extracted from changePeopleBooking() so the logic lives in one place and can be
	 * unit-tested independently.
	 */
	private function upsertChangePeopleAddonPaymentLink(
		array   $addonDelta,
		object  $checkaffiliate,
		int     $oldBookingID,
		object  $request,
		float   $natFeesPercentage,
		object  $tourBooking,
		array   $addonProcessResult,
		string  $createdByWithName,
		\Carbon\Carbon $slotDateTime,
		object  $info
	): void {
		$addonNetPrice = (float) ($addonDelta['net_price'] ?? 0);

		// A net REMOVAL/downgrade (e.g. toggling an existing add-on option back off) never
		// reaches the "add a new/bigger pending item" logic below at all — it must instead
		// shrink (or cancel) whatever pending 'addon' item already covers the field, or that
		// item silently stays at its old, now-too-high amount forever. Matched via db_id
		// (calculatePricedAddonDelta()'s refundItems always carry it, for both a plain removal
		// and a downgrade), same field-resolution convention as PaymentLinkService's own
		// pending-addon-item helpers.
		//
		// A field whose OLD selection is itself still pending on the link is charged its full
		// new price (or the part above what was actually paid) by this same edit, so that old
		// pending line must go FIRST, exactly like the Card/Invoiced branches of
		// changePeopleBooking() do, or the same field ends up on the link twice (booking #41960:
		// two $17.57 lines for a single $16 lunch). This applies even when the edit nets to
		// <= $0 and nothing new is added to the link (an upgrade offset by a bigger downgrade
		// elsewhere) -- the superseded line is still no longer owed.
		$supersededFieldIds = array_column(
			array_filter($addonDelta['chargeItems'] ?? [], fn ($item) => !empty($item['supersedes_pending_link'])),
			'db_id'
		);
		$hasSupersededLines = !empty($supersededFieldIds);

		if ($addonNetPrice < 0 && !empty($addonDelta['refundItems'])) {
			if ($hasSupersededLines) {
				PaymentLinkService::syncPendingAddonLinkItemsForUpdatedFields($tourBooking->id, $supersededFieldIds, $supersededFieldIds, false);
			}
			// Re-sums the link once for both changes (forced when only the sync above touched it).
			$this->reduceChangePeopleAddonPaymentLink($addonDelta['refundItems'], $tourBooking, $hasSupersededLines);
			return;
		}

		if ($addonNetPrice <= 0 || empty($addonDelta['chargeItems'])) {
			if ($hasSupersededLines) {
				PaymentLinkService::syncPendingAddonLinkItemsForUpdatedFields($tourBooking->id, $supersededFieldIds, $supersededFieldIds, true);
			}
			return;
		}

		// Reuse the SAME fee calculatePricedAddonDelta() already computed for these chargeItems
		// (summed per-component: each item's field_fee + option_fee, independently rounded)
		// instead of re-deriving it here from the combined net price — the two methods can land
		// on opposite sides of a rounding boundary for the exact same charge (e.g. a $25 addon
		// @ 9.82%: $25 * 0.0982 = $2.455 rounds to $2.46 combined, but $1.47 + $0.98 = $2.45
		// summed per-component), silently making the pending Payment Link amount shown to the
		// customer 1 cent higher than what actually gets collected when they pay (confirmed on
		// booking #348666, tenant kens: link showed $210.42, Stripe actually charged $210.41).
		// Using the exact same number here that settles the real charge later means the two can
		// never disagree. The old-booking 6% override and the affiliate zero-fee case are
		// unrelated to this rounding mismatch (calculatePricedAddonDelta() doesn't apply either
		// rule) — left as their own independent computations, unchanged.
		if ($checkaffiliate->is_affiliate === 'No') {
			$addonLinkFees = ($request->bookingID < $oldBookingID)
				? roundout($addonNetPrice * 6 / 100, 2)
				: (float) ($addonDelta['net_fee'] ?? 0);
		} elseif ($checkaffiliate->is_affiliate === 'Yes' && $request->bookingID > $oldBookingID) {
			$addonLinkFees = (float) ($addonDelta['net_fee'] ?? 0);
		} else {
			$addonLinkFees = 0;
		}
		$addonLinkAmount = round($addonNetPrice + $addonLinkFees, 2);

		// Drop the superseded pending lines (see above) before the new item is added.
		// recalculate=false: upsertRemainingPaymentLink() below re-sums the link.
		if ($hasSupersededLines) {
			PaymentLinkService::syncPendingAddonLinkItemsForUpdatedFields(
				$tourBooking->id,
				$supersededFieldIds,
				$supersededFieldIds,
				false
			);
		}

		// Map chargeItems into the format AddonItemHandler::finalize() expects.
		// calculatePricedAddonDelta() uses 'price' for the per-item total;
		// processAddonFinancialTransactions reads 'charge_amount' — map accordingly.
		$addonChargeItems = [];
		foreach ($addonDelta['chargeItems'] as $ci) {
			$fieldPrice  = (float) ($ci['field_price']  ?? 0);
			$optionPrice = (float) ($ci['option_price'] ?? 0);
			$addonChargeItems[] = [
				'field_id'             => $ci['field_id'],
				'pax_index'            => $ci['pax_index'] ?? null,
				'old_db_id'            => $ci['db_id'] ?? null,
				'charge_amount'        => (float) ($ci['price'] ?? ($fieldPrice + $optionPrice)),
				'field_price'          => $fieldPrice,
				'option_price'         => $optionPrice,
				'field_fee'            => (float) ($ci['field_fee']  ?? 0),
				'option_fee'           => (float) ($ci['option_fee'] ?? 0),
				'label'                => $ci['label'] ?? null,
				'field_additional_fee' => $ci['field_additional_fee']  ?? false,
				'option_additional_fee'=> $ci['option_additional_fee'] ?? false,
			];
		}

		PaymentLinkService::upsertRemainingPaymentLink(
			$tourBooking->group_id,
			[
				'type'         => 'addon',
				'reference_id' => null,
				'amount'       => $addonLinkAmount,
				'reason'       => 'Payment for add-ons on your booking',
				'details'      => [
					'booking_id'           => $tourBooking->id,
					'form_id'              => $request->addons_form_id ?? null,
					'financial'            => [
						'action'     => 'charge',
						'net_amount' => $addonNetPrice,
						'to_charge'  => $addonChargeItems,
						'to_refund'  => [],
					],
					'field_to_db'          => $addonProcessResult['field_db_id_map'] ?? [],
					'platform_fees'        => $addonLinkFees,
					'added'                => [],
					'updated'              => [],
					'pax'                  => [],
					'created_by_with_name' => $createdByWithName,
				],
			],
			$tourBooking,
			$slotDateTime,
			$info
		);
	}

	/**
	 * Companion to upsertChangePeopleAddonPaymentLink() — shrinks (or cancels) whatever
	 * pending, Unpaid 'addon' remaining_payment link item(s) already cover the removed/
	 * downgraded fields in $refundItems, instead of leaving them stuck at their old, now
	 * too-high amount. A single item can bundle multiple fields together, so only the
	 * specific matched to_charge entries are dropped — the item's total is recomputed from
	 * whatever entries remain, and it's only cancelled outright once nothing does.
	 *
	 * @param array  $refundItems calculatePricedAddonDelta()'s refundItems — each carries the
	 *        field's real tour_booking_addon_fields.id as 'db_id'.
	 * @param object $tourBooking
	 * @param bool   $forceRecalculate re-sum the link even if no item here changed (the caller
	 *        already changed an item without recalculating)
	 */
	private function reduceChangePeopleAddonPaymentLink(array $refundItems, object $tourBooking, bool $forceRecalculate = false): void
	{
		$removedFieldIds = array_values(array_unique(array_filter(array_map(
			fn ($item) => (int) ($item['db_id'] ?? 0),
			$refundItems
		))));
		if (empty($removedFieldIds)) {
			return;
		}

		$oldLink = TourBookingPaymentLink::where('order_id', $tourBooking->group_id)
			->where('section', 'remaining_payment')
			->where('status', 'Unpaid')
			->first();
		if (!$oldLink) {
			return;
		}

		$items = TourBookingPaymentLinkItem::where('payment_link_id', $oldLink->id)
			->where('type', 'addon')
			->where('status', 'Unpaid')
			->get();

		$userType = function_exists('userType') ? userType() : 'Admin';
		// recalculateRemainingPaymentLink() re-derives the WHOLE link (several queries: group
		// bookings, custom-charge lookups, item creation) — a single Change People edit can touch
		// more than one pending addon item here (e.g. two pax bundled onto the same item, or two
		// separate items), so calling it once per matching item repeats that full recalculation
		// redundantly. It only ever needs to run once, after every item in this call has settled.
		$linkChanged = false;

		foreach ($items as $item) {
			$details   = is_array($item->details) ? $item->details : (json_decode($item->details ?? '[]', true) ?? []);
			$financial = $details['financial'] ?? [];
			$fieldToDb = $details['field_to_db'] ?? [];

			$resolveFieldId = function (array $lineItem) use ($fieldToDb): ?int {
				if (!empty($lineItem['old_db_id'])) {
					return (int) $lineItem['old_db_id'];
				}
				$lookupKey = ($lineItem['field_id'] ?? '') . '_' . ($lineItem['pax_index'] ?? '');
				return isset($fieldToDb[$lookupKey]) ? (int) $fieldToDb[$lookupKey] : null;
			};

			$toCharge   = $financial['to_charge'] ?? [];
			$keptCharge = [];
			$removedAmount = 0.0;
			foreach ($toCharge as $lineItem) {
				$fid = $resolveFieldId($lineItem);
				if ($fid !== null && in_array($fid, $removedFieldIds, true)) {
					$removedAmount += (float) ($lineItem['charge_amount'] ?? 0);
					continue;
				}
				$keptCharge[] = $lineItem;
			}

			if ($removedAmount <= 0) {
				continue; // nothing in this item belongs to the removed/downgraded fields
			}

			$existingNet = (float) ($financial['net_amount'] ?? 0);
			$existingFee = (float) ($financial['fee_amount'] ?? $details['platform_fees'] ?? 0);
			$removedFeeShare = ($existingNet > 0 && $existingFee > 0)
				? round($existingFee * ($removedAmount / $existingNet), 2)
				: 0.0;
			$newNet    = round($existingNet - $removedAmount, 2);
			$newFee    = round($existingFee - $removedFeeShare, 2);
			$newAmount = round($newNet + $newFee, 2);

			if ($newAmount <= 0 || empty($keptCharge)) {
				$item->status               = 'Cancelled';
				$item->updated_by           = Auth::id();
				$item->updated_by_user_type = $userType;
				$item->save();
			} else {
				$financial['to_charge']   = array_values($keptCharge);
				$financial['net_amount']  = $newNet;
				$details['financial']     = $financial;
				$details['platform_fees'] = $newFee;

				$item->amount               = $newAmount;
				$item->details              = json_encode($details, JSON_NUMERIC_CHECK);
				$item->updated_by           = Auth::id();
				$item->updated_by_user_type = $userType;
				$item->save();
			}

			$linkChanged = true;
		}

		if ($linkChanged || $forceRecalculate) {
			PaymentLinkService::recalculateRemainingPaymentLink($oldLink->id);
		}
	}

	/**
	 * Switch package in the existing booking
	 *
	 * @param object $request
	 * @return mixed
	 *
	 * @version 1.0.0
	 */
	public function switchPackageBooking($request)
	{
		DB::beginTransaction();
		try {
			$trans = $this->transaction::where('tour_booking_id', $request->bookingID)
				->where('status', 'Completed')
				->orderBy('id', 'DESC')
				->first();

			$data = DB::table('tour_bookings_master as tbm')
				->join('tour_slot_times as tst', 'tst.id', '=', 'tbm.tour_slot_id')
				->where('tbm.id', $request->bookingID)
				->first(['tst.time_from', 'tst.date']);

			$paymentMethod = $trans ? $trans->via : '';

			$paymentIntentId = ($request->is('api/*')) ? $request->paymentIntentId : $request->payment_intent_id;

			// Admin selected "Pay with Link" in the Make Payment modal: send a payment link
			// for the remaining balance instead of collecting payment immediately.
			if ($request->payment_method === 'Payment Link') {
				$switchTourPackage = SwitchTourPackagePaymentLinkService::run($request);
			} else {
				switch ($paymentMethod) {
					case 'Cash':
						$switchTourPackage = SwitchTourPackageCashService::run($request);
						break;
					case 'Invoiced':
						$switchTourPackage = SwitchTourPackageInvoicedService::run($request);
						break;
					case 'Card':
						$switchTourPackage = SwitchTourPackageCardService::run($request);
						break;
					default:
						$switchTourPackage = SwitchTourPackagePayLaterService::run($request);
						break;
				}
			}

			// Save the card details
			HistoryService::getSavedCardFromPaymentIntent($paymentIntentId, $request->bookingID, "BACKEND");

			//Unassign booking from board station
			BoardService::boardBookingUnassign($request->bookingID, $data->date, $data->time_from);
			return $switchTourPackage;
		} catch (Exception $exception) {
			DB::rollBack();
			Log::error($exception);
			throw new GeneralCoreException($exception);
		}
	}

	public static function saveCardPermitFeeJson($updatesTransact, $tbTransactexist, $tbltrans, $tourPackageRateGroup)
	{
		if ($tbTransactexist->refund_permitfee_status != '') {
			$statusInfo = json_decode($tbTransactexist->refund_permitfee_status);
			for ($b = $tbTransactexist->tourists; $b < ($tbTransactexist->tourists + $tbltrans['tourists']); $b++) {
				if ($tbltrans['permit_fee']) {
					$statusInfo[$b] = new \stdClass;
					$statusInfo[$b]->status = 'N';
					$statusInfo[$b]->is_pax_added = true;
				} elseif ($tbltrans['permit_fee'] == 0 && $tourPackageRateGroup->permit_fee == 0) {
					$statusInfo[$b] = new \stdClass;
					$statusInfo[$b]->status = 'Y';
					$statusInfo[$b]->amount = $tbTransactexist->permit_fee;
					$statusInfo[$b]->processing_fees = '0.00';
					$statusInfo[$b]->is_pax_added = true;
					$statusInfo[$b]->dateTime = mysqlDT();
				} else {
					$statusInfo[$b] = new \stdClass;
					$statusInfo[$b]->status = 'Y';
					$statusInfo[$b]->amount = $tbTransactexist->permit_fee;
					$statusInfo[$b]->processing_fees = $tbTransactexist->permit_fee * $tbltrans['processing_charge_percentage'] / 100;
					$statusInfo[$b]->is_pax_added = true;
					$statusInfo[$b]->dateTime = mysqlDT();
				}
			}

			$updatesTransact['refund_permitfee_status'] = (!empty($statusInfo)) ? json_encode((array_values($statusInfo))) : '';

			return $updatesTransact;
		} elseif ($tbTransactexist->permit_fee == 0) {
			for ($b = 0; $b < ($tbltrans['tourists'] + $tbTransactexist->tourists); $b++) {
				$overrideStatusInfo = 0;
				if (!isset($statusInfo[$b])) {
					$statusInfo[$b] = new \stdClass;
					$statusInfo[$b]->status = 'N';
					$statusInfo[$b]->is_pax_added = true;
					$overrideStatusInfo = 1;
				}
				if ($overrideStatusInfo && $tbltrans['permit_fee'] == 0 && $tbTransactexist->tourists > $b) {
					$statusInfo[$b] = new \stdClass;
					$statusInfo[$b]->status = 'Y';
					$statusInfo[$b]->amount = $tbTransactexist->permit_fee;
					$statusInfo[$b]->processing_fees = $tbTransactexist->tourists > $b ? 0 : ($tbTransactexist->permit_fee * $tbltrans['processing_charge_percentage'] / 100);
					$statusInfo[$b]->is_pax_added = true;
					$statusInfo[$b]->dateTime = mysqlDT();
				}
				if ($overrideStatusInfo && $tbltrans['permit_fee'] != 0 && $tbTransactexist->tourists > $b) {
					$statusInfo[$b] = new \stdClass;
					$statusInfo[$b]->status = 'Y';
					$statusInfo[$b]->amount = $tbTransactexist->permit_fee;
					$statusInfo[$b]->processing_fees = $tbTransactexist->permit_fee * $tbltrans['processing_charge_percentage'] / 100;
					$statusInfo[$b]->is_pax_added = true;
					$statusInfo[$b]->dateTime = mysqlDT();
				}
			}
			if ($tbTransactexist->rate == 0) {
				$updatesTransact['refund_permitfee_status'] = '';
			} else {
				$updatesTransact['refund_permitfee_status'] = (!empty($statusInfo)) ? json_encode((array_values($statusInfo))) : '';
			}


			return $updatesTransact;
		} elseif ($tbTransactexist->permit_fee != 0) {
			for ($b = 0; $b < ($tbltrans['tourists'] + $tbTransactexist->tourists); $b++) {
				$overrideStatusInfo = 0;
				if (!isset($statusInfo[$b])) {
					$statusInfo[$b] = new \stdClass;
					$statusInfo[$b]->status = 'N';
					// Only newly added pax (index >= existing count) are unpaid/added;
					// do NOT stamp is_pax_added on the original paid pax.
					if ($b >= $tbTransactexist->tourists) {
						$statusInfo[$b]->is_pax_added = true;
					}
					$overrideStatusInfo = 1;
				}
				if ($overrideStatusInfo && $tbltrans['permit_fee'] == 0 && $tbTransactexist->tourists <= $b) {
					$statusInfo[$b] = new \stdClass;
					$statusInfo[$b]->status = 'Y';
					$statusInfo[$b]->amount = $tbTransactexist->permit_fee;
					$statusInfo[$b]->processing_fees = $tbTransactexist->permit_fee * $tbltrans['processing_charge_percentage'] / 100;
					$statusInfo[$b]->is_pax_added = true;
					$statusInfo[$b]->dateTime = mysqlDT();
				}
			}

			$updatesTransact['refund_permitfee_status'] = (!empty($statusInfo)) ? json_encode((array_values($statusInfo))) : '';

			return $updatesTransact;
		}
	}

