	 * @param object $request
	 * @return mixed
	 * 
	 * @version 1.0.0
	 */
	public function smsSend($request)
	{
		try {
			$message = "Message From: " . strtoupper(tenancy()->tenant->id) . "\n";
			$message .= $request->message;
