	/**
	 * Add Time Slot From Calendar Page
	 *
	 * @param object $request
	 * @return array
	 * @throws GeneralCoreException
	 *
	 * @version 1.0.0
	 */
	public function addTimeSlot(Request $request)
	{
		DB::beginTransaction();
		try {
			$userType = userType();
			$formattedDate = Carbon::parse($request->date)->toDateString();

			// Check if the time slot already exists
			$timeSlotExists = $this->tourSlotTime::where([
				'tour_package_id' => $request->tour_package_id,
				'date' => $formattedDate,
				'time_from' => $request->from_time,
				'time_to' => $request->to_time
			])->exists();

			if ($timeSlotExists) {
				throw new Exception('Time slot already exists!!');
			}

			// Fetch the tour slot date
			$dateSlot = $this->tourDateSlot::where([
				'tour_package_id' => $request->tour_package_id,
				'date' => $formattedDate
			])->select('id')->firstOrFail();

			// Save time slot using Eloquent
			$timeSlot = $this->tourSlotTime::create([
				'tour_slot_id' => $dateSlot->id,
				'tour_package_id' => $request->tour_package_id,
				'time_slot_seats' => $request->seats,
				'date' => $formattedDate,
				'time_from' => $request->from_time,
				'time_to' => $request->to_time,
				'bookable_status' => $request->status,
				'hide_slot' => $request->hide_time_slot,
				'created_by' => Auth::id(),
				'created_by_user_type' => $userType
			]);

			DB::commit();

			return response()->json([
				'time_slot_id' => $timeSlot->id,
				'seats' => $request->seats,
				'from_time' => $request->from_time,
				'to_time' => $request->to_time,
				'status' => $request->status,
				'hide_slot' => (int)$request->hide_time_slot,
			]);
		} catch (Exception $e) {
			DB::rollback();
			Log::error($e);
			throw new GeneralCoreException($e);
		}
	}

	/**
	 * Bulk Update Time Slot Bookable Status [Open|Only by Phone|Closed]
	 *
	 * @param object $request
	 * @return array
	 * @throws GeneralCoreException
	 * 
	 * @version 1.0.0
	 */
	public function bulkUpdateSlotBookableStatus($request)
	{
		DB::beginTransaction();
		try {
			foreach ($request->slotIds as $slotId) {
				// Fetch time slot with required details
				$timeSlot = $this->tourSlotTime::findOrFail($slotId);

				$updateDT = mysqlDT();
				$oldValues = [];
				$newValues = ['bookable_status' => $request->status];


				// Track changes for history
				diffRecord(['bookable_status'], 'u', (array) $timeSlot, $newValues, $oldValues, $newValues);

				// Insert change record into history table
				DB::table('records_history')->insert([
					'record_id_1' => $timeSlot->id,
					'record_id_2' => $timeSlot->tour_package_id,
					'operation_type' => 'u',
					'table_name' => 'tour_slot_times',
					'entity_info' => "{$timeSlot->date} {$timeSlot->time_from}",
					'old_values' => json_encode($oldValues),
					'new_values' => json_encode($newValues),
					'operation_at' => $updateDT,
					'operation_by' => Auth::id(),
					'operation_by_user_type' => session('userType'),
				]);

				// Update the record
				DB::table('tour_slot_times')
					->where('id', $slotId)
					->update(array_merge($newValues, [
						'updated_at' => $updateDT,
						'updated_by' => Auth::id(),
						'updated_by_user_type' => session('userType')
					]));
			}
			DB::commit();
			// Assign class based on status
			$statusClasses = [
				'Open' => 'bookable',
				'Only by Phone' => 'callback',
				'Closed' => ''
			];
			$class = $statusClasses[$request->status] ?? '';

			return [
				'status' => $request->status,
				'class' => $class
			];
		} catch (Exception $exception) {
			DB::rollback();
			Log::error($exception);
			throw new GeneralCoreException($exception);
		}
	}

	/**
	 * Create Payment Link From Booking Information Page
	 *
	 * @param object $request
	 * 
	 * @return mixed
	 * 
	 */
	public function createPaymentLink(Request $request)
	{
		DB::beginTransaction();
		try {
			$userType = userType();
			$isPaymentLinkEnabled = hasSetting('PAYMENT_LINK');

			// Find the booking early to use in multiple places
			$tourBooking = $this->tourBooking::findOrFail($request->booking_id);

			// Prepare payment link data
			$paymentLinkData = [
				'amount'             => $request->amount,
				'reason_of_payment'  => $request->reason_of_payment,
				'customer_email'     => $request->customer_email,
				'customer_phone_no'  => $request->customer_phone_no,
			];
			$paymentLinkDataJson = json_encode($paymentLinkData);

			// Get slot datetime info
			$slotTime = TourPackageService::getTourSlotInfo($request->tour_slot_id, $userType);

			if (!$slotTime) {
				throw new Exception('Unable to found tour package.');
			}

			$slotDateTime = Carbon::parse("{$slotTime->date} {$slotTime->time_from}");

			// Get past transactions
			$transactions = $this->transaction::with('bookingHistory')
				->where('tour_booking_id', $request->booking_id)
				->whereIn('status', ['Completed', 'Failed', 'Refund'])
				->where(function ($query) {
					$query->whereNull('charge_type')
						->orWhere('charge_type', 'discount');
				})
				->orderByDesc('id')
				->get();

			// Get first completed transaction (if any)
			$completedTransaction = $transactions->firstWhere('status', 'Completed');

			// Store the payment link
			$paymentLink = PaymentLinkService::storeTourBookingPaymentLink($tourBooking->group_id, $paymentLinkDataJson, $slotDateTime);
			$info = TourPackageService::getTourSlotInfo($tourBooking->tour_slot_id, $userType);
			// Send payment link email if no completed transaction and payment link setting is enabled
			if (!$completedTransaction && $isPaymentLinkEnabled) {
				EmailService::sendPaymentLinkEmail($info, $tourBooking, $paymentLink);
			}

			return true;
		} catch (Exception $e) {
			DB::rollback();
			Log::error($e);
			throw new GeneralCoreException($e);
		}
	}

	/**
	 * Execute to get reason of payment to create payment link
	 *
	 * @param object $request
	 * 
	 * @return mixed
	 * 
	 */
	public function getPaymentLinkReason($request)
	{
		try {
			$userType = userType();
			$cart = session()->get('cart');
			$amount = $request->amount;
			$paymentLinkDays = getSettingsByKey('PAYMENT_LINK_DAYS');
			$daysPaymentLink = (int) $paymentLinkDays->value;

			$content = config('constants.payment_link_reasons');

			if ($request->order_id) {
				$totalAmount = 0;
				$slotTimeArray = [];

				$tourBookings = TourBooking::where('group_id', $request->order_id)->get();

				foreach ($tourBookings as $tourBooking) {
					$slotTime = TourPackageService::getTourSlotInfo($tourBooking->tour_slot_id, $userType);
					$slotTimeArray[] = $slotTime->date . ' ' . $slotTime->time_from;

					$transactions = Transaction::with('bookingHistory')
						->where('tour_booking_id', $tourBooking->id)
						->whereIn('status', ['Completed', 'Failed', 'Refund'])
						->where(function ($query) {
							$query->whereNull('charge_type')->orWhere('charge_type', 'discount');
						})
						->orderByDesc('id')
						->get();

					$trans     = Transaction::where('tour_booking_id', $tourBooking->id)->first();
					$bookingT  = BookingTransact::where('tour_booking_id', $tourBooking->id)->where('deleted_by', 0)->first();

					$customChargePrice = CustomChargeBookingService::customChargePrice($tourBooking->id, $transactions);
					$payLaterAddons    = BookingService::fetchPayLaterAddonsWithPrice($tourBooking->id, $bookingT->nat_fees_percentage, $trans);

					$totalFee = ($tourBooking->total * $bookingT->nat_fees_percentage) / 100;
					$totalAmount += roundout(
						$tourBooking->total + $totalFee + $payLaterAddons['addons_total'] + $customChargePrice['overall_custom_charge'],
						2
					);
				}

				$reasonOfPaymentText = $content['create_combo_booking'];
				$earliestSlot = Carbon::parse(min($slotTimeArray));
				$expiredDateTime = $earliestSlot->subDays($daysPaymentLink);

				$placeholders = [
					'{amount}'           => currencyFormation(code: false, symbol: true) . $totalAmount,
					'{expiration_date}'  => $expiredDateTime->format('F j, Y'),
					'{expiration_time}'  => $expiredDateTime->format('g:i A'),
				];

				$finalMessage = strtr($reasonOfPaymentText, $placeholders);
			} elseif (!empty($cart)) {
				foreach ($cart['tour_packages'] as &$tourPackage) {
					$ageGroupCount = PaymentLinkService::ageGroupCount($tourPackage['tourist_groups']);
					$tourPackage['touristAgeGroup'] = [];

					foreach ($tourPackage['tourists'] as $tourist) {
						$tourPackage['touristAgeGroup'][] = $ageGroupCount . ' ' . $tourist;
					}
				}
				unset($tourPackage); // avoid side effects

				$sortedDataArray = PaymentLinkService::sortedDataArray($cart['tour_packages'], $userType);
				$reasonOfPaymentText = $content['create_combo_booking'];
				$finalMessage = '';

				foreach ($sortedDataArray as $data) {
					$placeholders = [
						'{tour_name}'       => $data['tour_package_name'],
						'{pax_details}'     => trim($data['touristAgeGroup']),
						'{amount}'          => currencyFormation(code: false, symbol: true) . $amount,
						'{expiration_date}' => $data['expiredDate'],
						'{expiration_time}' => $data['expiredTime'],
					];
					$finalMessage = strtr($reasonOfPaymentText, $placeholders);
				}
			} else {
				$slotTime = TourPackageService::getTourSlotInfo($request->slot_time, $userType);

				if (!$slotTime) {
					throw new Exception('Unable to book the tour package.');
				}

				$slotDateTime = Carbon::parse($slotTime->date . ' ' . $slotTime->time_from);
				$expiredDateTime = $slotDateTime->subDays($daysPaymentLink);

				$reasonOfPaymentText = $content[$request->page];

				$placeholders = [
					'{customer_name}'    => $request->customer_name,
					'{tour_name}'        => $request->package_name,
					'{pax_details}'      => $request->pax_details,
					'{amount}'           => currencyFormation(code: false, symbol: true) . $request->amount,
					'{expiration_date}'  => $expiredDateTime->format('F j, Y'),
					'{expiration_time}'  => $expiredDateTime->format('g:i A'),
				];

				$finalMessage = strtr($reasonOfPaymentText, $placeholders);
			}

			if ($request->order_id) {
				$data = ['finalMessage' => $finalMessage, 'totalAmount' => $totalAmount];
				return $data;
			} else {
				return $finalMessage;
			}
		} catch (Exception $exception) {
			DB::rollback();
			Log::error($exception);
			throw new GeneralCoreException($exception);
		}
	}

	/**
	 * Expiry date override function
	 *
	 * @param object $request
	 * 
	 * @return string
	 */

	public function expiryDateOverride($request)
	{
		try {
			$userType = userType();
			$cart = session('cart');
			$data = 0;
			$daysPaymentLink = (int) getSettingsByKey('PAYMENT_LINK_DAYS')->value;
			$today = Carbon::today();

			if ($request->cartView == 1 && !empty($cart)) {
				$dates = array_column($cart['tour_packages'], 'date');
				if (!empty($dates)) {
					$earliestDate = Carbon::parse(min($dates))->subDays($daysPaymentLink);
					if ($today->gt($earliestDate)) {
						$data = 1;
					}
				}
			} elseif (!empty($request->date)) {
				$bookingDate = Carbon::parse($request->date)->subDays($daysPaymentLink);
				if ($today->gt($bookingDate)) {
					$data = 1;
				}
			} elseif (isset($request->type)) {
				if ($request->order_id == '') {
					$data = 1;
				}
				$tourBookings = TourBooking::where('group_id', $request->order_id)->pluck('tour_slot_id');
				$now = Carbon::today();

				$slotTimes = $tourBookings
					->map(fn($slotId) => TourPackageService::getTourSlotInfo($slotId, $userType))
					->filter() // Remove nulls if any slot info is not found
					->map(fn($slot) => Carbon::parse("{$slot->date} {$slot->time_from}"));

				if (count($slotTimes) && !empty($slotTimes)) {
					$earliest = $slotTimes->min();
					if ($today->gt($earliest)) {
						$data = 1; // Past booking — tour already happened
					} else {
						$data = $today->gt($earliest->copy()->subDays($daysPaymentLink)) ? 1 : 0;
					}
				}
			}
			session()->put('overrideExpiryDate', $data);
			return $data;
		} catch (Exception $exception) {
			Log::error($exception);
			throw new GeneralCoreException($exception);
		}
	}

	/**
	 * Active payment link
	 *
	 * @param object $request
	 * 
	 * @return string
	 */

	public function activePaymentLink($request)
	{
		try {
			$data = TourBookingPaymentLink::where('order_id', $request->order_id)
				->where('status', 'Unpaid');

			return Datatables::of($data)
				->addIndexColumn()
				->editColumn('expiry_date', function ($query) {
					return date('D, M d Y', strtotime($query->expired_at));
				})
				->editColumn('updated_at', function ($query) {
					return date('D, M d Y', strtotime($query->updated_at));
				})
				->editColumn('created_by', function ($query) {
					if ($query->created_by_user_type == "Admin") {
						$user = Admin::find($query->created_by);
						$created_by_with_name = $user->name . ': (' . "Admin" . ')';
					} elseif ($query->created_by_user_type == "Tour Operator") {
						$user = Staff::find($query->created_by);
						$created_by_with_name = $user->name . ': (' . "Tour Operator" . ')';
					} elseif ($query->created_by_user_type == "Affiliate") {
						$user = Customer::find($query->created_by);
						$created_by_with_name = $user->name . ': (' . "Affiliate" . ')';
					}
					return $created_by_with_name;
				})
				->editColumn('action', function ($query) {
					return '<a data-id="' . $query->id . '" data-type="cancel" class="btn btn-danger link-action btn-sm me-2">Cancel</a>';
				})
				->rawColumns(['action'])
				->make(true);
		} catch (Exception $exception) {
			Log::error($exception);
			throw new GeneralCoreException($exception);
		}
	}

