	/**
	 * Execute to get assigned guides for specific booking
	 *
	 * @param integer|string $bookingId
	 * 
	 * @return array
	 * 
	 * @version 1.0.0
	 */

	public function getAssignedGuides($bookingId)
	{
		try {
			/* -------------------------------------------------
	         | BOOKING INFO
	         -------------------------------------------------*/
			$bookingInfo = DB::table('tour_bookings_master AS tbm')
				->join('tour_packages AS tp', 'tp.id', '=', 'tbm.tour_package_id')
				->join('tour_slot_times AS tst', 'tst.id', '=', 'tbm.tour_slot_id')
				->join('tour_slot_dates AS tsd', 'tsd.id', '=', 'tst.tour_slot_id')
				->where('tbm.id', $bookingId)
				->select(
					'tbm.id',
					'tbm.id as bookingId',
					'tbm.tour_package_id',
					'tbm.name AS customer_name',
					'tbm.tourists',
					'tbm.infants',
					'tp.name as package_name',
					'tsd.date',
					'tst.time_from',
					'tst.time_to',
					'tp.include_in_operation_board'
				)
				->first();

			if (!$bookingInfo) {
				throw new Exception("Booking not found for ID: {$bookingId}");
			}

			/* -------------------------------------------------
	         | CHECK-IN ADJUSTMENT (TOURISTS)
	         -------------------------------------------------*/
			$checkInsTourists = BoardService::checkInStatus($bookingInfo);
			$bookingInfo->checkInsCount = $checkInsTourists->checkInsCount
				?? ['1' => 0, '2' => 0, 'A' => 0];

			$absentTourists = $bookingInfo->checkInsCount['A'] ?? 0;
			$bookingInfo->tourists = max(0, $bookingInfo->tourists - $absentTourists);

			/* -------------------------------------------------
	         | CHECK-IN ADJUSTMENT (INFANTS)
	         -------------------------------------------------*/
			$checkInsInfants = BoardService::checkInInfantsStatus($bookingInfo);
			$bookingInfo->checkInsInfantsCount = $checkInsInfants->checkInsCount
				?? ['1' => 0, '2' => 0, 'A' => 0];

			$absentInfants = $bookingInfo->checkInsInfantsCount['A'] ?? 0;
			$bookingInfo->infants = max(0, ($bookingInfo->infants ?? 0) - $absentInfants);

			/* -------------------------------------------------
	         | PREFIX
	         -------------------------------------------------*/
			$bookingPrefix = bookingPrefixSetting();
			$bookingInfo->bookingId = $bookingPrefix . $bookingInfo->bookingId;

			$authId   = Auth::id();
			$userType = Auth::user()->type ?? null;

			/* -------------------------------------------------
	         | BASE GUIDE QUERY
	         -------------------------------------------------*/
			$guidesQuery = DB::table('tour_operator_staff AS tos')
				->join('model_has_roles AS mhr', 'mhr.model_id', '=', 'tos.id')
				->join('roles AS r', 'r.id', '=', 'mhr.role_id')
				->leftJoin('guide_specific_capacity as gsc', function ($join) use ($bookingInfo) {
					$join->on('gsc.guide_id', '=', 'tos.id')
						->where('gsc.date', '=', $bookingInfo->date)
						->where('gsc.time_from', '=', $bookingInfo->time_from);
				})
				->where('tos.status', 'Active')
				->where('r.name', 'tour-guide');

			if ($bookingInfo->include_in_operation_board == 1) {
				$guidesQuery->where('tos.guide_status', 'Active');
			}

			/* -------------------------------------------------
	         | EXCLUDE BUSY GUIDES
	         -------------------------------------------------*/
			$guidesQuery->whereNotExists(function ($query) use ($bookingInfo) {
				$query->select(DB::raw(1))
					->from('guide_next_timeslot_block AS gntb')
					->whereColumn('gntb.guide_id', 'tos.id')
					->where('gntb.date', $bookingInfo->date)
					->where(function ($q) use ($bookingInfo) {
						$q->where(function ($f) use ($bookingInfo) {
							$f->where('gntb.time_from', '<', $bookingInfo->time_from)
								->where('gntb.time_to',   '>', $bookingInfo->time_from);
						});
					});
			});

			$guides = $guidesQuery->get([
				'tos.id',
				DB::raw("CONCAT(tos.first_name, ' ', tos.last_name) AS guide_name"),
				DB::raw('COALESCE(gsc.capacity, tos.capacity) AS capacity')
			]);

			// --- Get guide assignments for current slot ---
			$bookingGuidesQuery = DB::table('booking_tour_guides as btg')
				->leftJoin('stations as s', 's.id', '=', 'btg.station_id')

				// station name override
				->leftJoin('board_station_specific_name as bssn', function ($join) use ($bookingInfo) {
					$join->on('bssn.station_id', '=', 'btg.station_id')
						->where('bssn.date', '=', $bookingInfo->date)
						->where('bssn.time_from', '=', $bookingInfo->time_from);
				})

				// station package override
				->leftJoin('board_station_specific_packages as bssp', function ($join) use ($bookingInfo) {
					$join->on('bssp.station_id', '=', 'btg.station_id')
						->where('bssp.date', '=', $bookingInfo->date)
						->where('bssp.time_from', '=', $bookingInfo->time_from);
				})

				->where('btg.time_from', $bookingInfo->time_from)
				->where('btg.date', $bookingInfo->date);

			if ($userType === 'Tour Operator') {
				$bookingGuidesQuery->whereIn('guide_id', $guides->pluck('id')->toArray());
			}

			$bookingGuides = $bookingGuidesQuery->get([
				'btg.guide_id',
				'btg.booking_id',
				'btg.tourists',
				'btg.station_id',

				// station name override > default
				DB::raw('COALESCE(bssn.name, s.name) as name'),

				// station package override > default
				DB::raw('COALESCE(bssp.packages, s.tour_packages) as tour_packages'),
			]);

			$busyGuideIds = $bookingGuides->pluck('guide_id')->unique()->toArray();

			/* -------------------------------------------------
	         | MAP GUIDE → BOOKINGS
	         -------------------------------------------------*/
			$guideBookingMap = [];
			$guideStationMap = [];

			foreach ($bookingGuides as $entry) {
				if ($entry->booking_id) {
					$guideBookingMap[$entry->guide_id][$entry->booking_id] = $entry->tourists;
				}

				if (!empty($entry->name)) {
					$guideStationMap[$entry->guide_id]['station'] = $entry->name;
					$guideStationMap[$entry->guide_id]['tour_packages'] = $entry->tour_packages;
				}
			}

			$allBookingIds = collect($guideBookingMap)->flatten()->unique()->toArray();

			/* -------------------------------------------------
	         | FETCH BOOKING COUNTS (TOURISTS + INFANTS)
	         -------------------------------------------------*/
			$bookingCounts = DB::table('tour_bookings_master')
				->whereIn('id', $allBookingIds)
				->get(['id', 'tourists', 'infants'])
				->keyBy('id');

			/* -------------------------------------------------
	         | ENRICH GUIDES
	         -------------------------------------------------*/
			$guides = $guides->map(function ($guide) use (
				$busyGuideIds,
				$guideBookingMap,
				$bookingCounts,
				$guideStationMap
			) {
				$guide->busy = in_array($guide->id, $busyGuideIds);

				$guide->tourists_assigned = 0;
				$guide->tourists_total   = 0;
				$guide->infants_total    = 0;
				$guide->total_assigned_bookings = 0;

				$guide->station_name = $guideStationMap[$guide->id]['station'] ?? null;
				$guide->tour_packages = $guideStationMap[$guide->id]['tour_packages'] ?? null;

				if (isset($guideBookingMap[$guide->id])) {
					foreach ($guideBookingMap[$guide->id] as $bookingId => $assigned) {

						$guide->tourists_assigned += max(0, $assigned ?? 0);

						if (isset($bookingCounts[$bookingId])) {
							$guide->tourists_total += max(0, $bookingCounts[$bookingId]->tourists ?? 0);
							$guide->infants_total  += max(0, $bookingCounts[$bookingId]->infants ?? 0);
						}
					}
					$guide->total_assigned_bookings = count($guideBookingMap[$guide->id]);
				}

				return $guide;
			})
				->sortBy([
					['busy', 'asc'],
					['total_assigned_bookings', 'asc'],
				])
				->values();

			// --- Return data ---
			return [
				'bookingInfo'     => $bookingInfo,
				'assignedGuides'  => TipService::getBookingAssignedGuides($bookingId, $bookingInfo->date, $bookingInfo->time_from),
				'guides'          => $guides
			];
		} catch (Exception $exception) {
			Log::error($exception);
			throw new GeneralCoreException($exception);
		}
	}

	/**
	 * Check if any rate group has people with different permit fees
	 * This is used to determine if change people functionality should be disabled
	 *
	 * @param int $bookingId
	 * @return bool
	 */
	public function hasRateGroupWithDifferentPermitFees($bookingId)
	{
		try {
			// Get all booking transactions for this booking
			$bookingTransacts = $this->bookingTransact::where('tour_booking_id', $bookingId)
				->where('deleted_by', 0)
				->get(['tour_package_rate_id', 'refund_permitfee_status', 'permit_fee', 'tourists']);

			foreach ($bookingTransacts as $transact) {
				// Skip if no tourists in this rate group
				if ($transact->tourists <= 1) {
					continue;
				}

				// If there's no refund permit fee status, all people have the same permit fee
				if (empty($transact->refund_permitfee_status)) {
					continue;
				}

				// Parse the refund permit fee status
				$refundStatus = json_decode($transact->refund_permitfee_status, true);
				if (empty($refundStatus)) {
					continue;
				}

				// Calculate current permit fees for each person in this rate group
				$permitFees = [];
				foreach ($refundStatus as $index => $status) {
					if (isset($status['status']) && $status['status'] == 'Y') {
						// Person has refund status
						if (isset($status['new_permit_fee'])) {
							$permitFees[] = floatval($status['new_permit_fee']);
						} else {
							$permitFees[] = 0; // Full refund
						}
					} else {
						// Person has no refund, use original permit fee
						$permitFees[] = floatval($transact->permit_fee);
					}
				}

				// Check if all permit fees are the same
				$uniquePermitFees = array_unique($permitFees);
				if (count($uniquePermitFees) > 1) {
					// Found a rate group with different permit fees
					return true;
				}
			}

			return false;
		} catch (Exception $exception) {
			Log::error($exception);
			return false; // Default to allowing change people if there's an error
		}
	}

	/**
	 * Booking agenda check-ins overview
	 *
	 * @param $request
	 * @return array
	 * 
	 * @version 3.0.0
	 */
	public function agendaCheckinOverview($request)
	{
		$vars = $this->dayTimeSlots(
			$request,
			$request->date ?? 0,
			$request->tourPackagesId ?? '',
			$request->paymentStatus ?? 0,
			$request->slotId ?? ''
		);

		return $vars;
	}

	/**
	 * Return all waiver entries from liability_waiver_signing, newest first.
	 * Supports both formats:
	 *   - Direct waiver (3 elements): [name, age, datetime]
	 *   - School waiver (5 elements): [name, age, datetime, parent_email, reference_id]
	 */
	private function getSchoolWaiverEntries(int $id): array
	{
		$raw = DB::table('tour_bookings_master')->where('id', $id)->value('liability_waiver_signing');
		$all = (!empty($raw)) ? json_decode($raw, true) : [];
		return array_reverse(array_values($all));
	}

	/**
	 * Build a transact_id → unpaid-pax-count map from pending payment link items / history records.
	 * Used to exclude never-charged pax from Stripe refund validation and from actual refund amounts.
	 *
	 * @param mixed $request  Must have bookingID + optionally pending_item_ids / pending_history_ids
	 * @return array<int, int>  [transact_id => unpaid_count]
	 */
	private function buildUnpaidPaxCountByTransactId($request): array
	{
		$map = [];

		// ── New flow: IDs are TourBookingPaymentLinkItem IDs ──
		if ($request->filled('pending_item_ids')) {
			foreach (array_filter(array_map('intval', explode(',', $request->pending_item_ids))) as $piId) {
				$plItem  = TourBookingPaymentLinkItem::find($piId);
				$details = $plItem
					? (is_array($plItem->details) ? $plItem->details : (json_decode($plItem->details ?? '[]', true) ?? []))
					: [];
				foreach ($details['added_transact_data'] ?? [] as $td) {
					$map[$td['transact_id']] = ($map[$td['transact_id']] ?? 0) + (int)$td['added_count'];
				}
			}
		}

		// ── Legacy flow: IDs are tour_booking_history record IDs ──
		if ($request->filled('pending_history_ids')) {
			foreach (array_filter(array_map('intval', explode(',', $request->pending_history_ids))) as $phId) {
				$phRecord  = DB::table('tour_booking_history')->where('id', $phId)->value('details');
				$phDetails = $phRecord ? json_decode($phRecord, true) : [];
				if (!empty($phDetails['added_transact_data'])) {
					foreach ($phDetails['added_transact_data'] as $td) {
						$map[$td['transact_id']] = ($map[$td['transact_id']] ?? 0) + (int)$td['added_count'];
					}
				} else {
					$companion  = DB::table('tour_booking_history')
						->where('tour_booking_id', $request->bookingID)
						->where('operation', 'Update')
						->whereRaw("JSON_EXTRACT(details, '$.txnhistoryid') = ?", [$phId])
						->value('details');
					$addedCount = $companion ? intval(json_decode($companion, true)['addedTourists'] ?? 0) : 0;
					if ($addedCount > 0) {
						$tRows     = DB::table('tour_bookings_transact')
							->where('tour_booking_id', $request->bookingID)
							->where('deleted_by', 0)
							->select(['id', 'tourists'])
							->get();
						$remaining = $addedCount;
						foreach ($tRows->reverse() as $tRow) {
							if ($remaining <= 0) break;
							$markCount = min($remaining, $tRow->tourists);
							$map[$tRow->id] = ($map[$tRow->id] ?? 0) + $markCount;
							$remaining -= $markCount;
						}
					}
				}
			}
		}

		return $map;
	}
}
